export default {"24-1": {"decisionQ": "중앙회와 자체 이기종 시스템 간 야간 DB 동기화 구간에 평문 전송 없이 전용회선·VPN 및 강력한 암호화가 적용되어 있습니까?", "verify": ["중앙회 연계 이기종 DB 동기화 구간의 네트워크 구성도와 암호화 적용 설정 화면을 보여주시겠습니까?", "동기화 수행 시 실제 흐르는 패킷을 스니핑한 결과나 평문 전송 여부 점검 보고서를 제시해 주시겠습니까?", "VPN 또는 전용회선에 적용된 암호화 알고리즘(AES-256 등) 및 암호화 키 갱신 이력 관리 대장을 보여주시겠습니까?"], "verifyEnd": "동기화 구간에 VPN/전용회선 기반의 강력한 암호화가 적용되어 있고 패킷 점검 결과 평문 노출이 없으며 키 관리 이력이 확인되면 양호로 확정합니다.", "partial": ["전용회선이나 VPN은 사용 중이나 동기화 애플리케이션/DB 자체 암호화가 누락되어 있거나, 키 갱신 주기가 준수되지 않는 부분이 있습니까?", "동기화 데이터 중 개인신용정보 일부 항목만 암호화되고 일부는 평문 전송되는 구간이 존재합니까?", "이러한 미흡 사항이 발생한 원인과 완전 암호화 전환을 위한 개선 계획은 무엇입니까?"], "partialEnd": "일부 구간 또는 항목의 암호화 누락을 특정하여 개선 계획을 요청하고, 전수 암호화 완료 시까지 보완 조치를 이행하도록 합니다.", "rootcause": ["동기화 구간에 암호화가 전혀 적용되지 않고 평문 전송되는 이유는 무엇입니까?", "구간 암호화 미적용 위험을 인지하고도 조치하지 않은 경위와 담당자/승인자는 누구입니까?", "즉시 동기화 채널을 암호화 조치하거나 회선을 차단할 수 있는 긴급 대책이 있습니까?"], "rootcauseEnd": "개인신용정보 유출 위험이 매우 높은 결함으로 확정하고, 즉시 암호화 적용 및 회선 통제 개선계획서를 서면 제출하도록 요구합니다.", "na": ["중앙회와 연계된 별도의 자체 이기종 DB나 동기화 채널 자체가 존재하지 않습니까?", "모든 데이터 처리가 중앙회 단일 시스템 내에서만 완결되는 구조임을 증명할 시스템 구성도를 제시할 수 있습니까?"], "naEnd": "이기종 DB 동기화 채널이 아예 존재하지 않음이 시스템 구성도로 확인되면 N/A로 판정합니다."}, "24-2": {"decisionQ": "주민등록번호·계좌번호·신용점수 등 개인신용정보가 업무 화면, 인쇄물, 화면 캡처 시 업무 필요 최소 범위로 마스킹 처리되어 있습니까?", "verify": ["여신·수신 주요 업무 화면을 직접 열어 주민번호와 계좌번호 마스킹 처리 상태를 보여주시겠습니까?", "동일한 조회 화면에서 권한이 다른 계정(예: 일반 영업점원 vs 관리자)으로 로그인했을 때 마스킹 범위가 차등 적용되는지 비교해 주시겠습니까?", "해당 화면을 인쇄하거나 캡처 프로그램 실행 시 마스킹 상태가 그대로 유지되는지 시연해 주시겠습니까?", "마스킹 해제(원문 조회)가 필요한 경우 사전 승인 절차 및 그 승인 이력을 보여주시겠습니까?"], "verifyEnd": "모든 업무 화면, 인쇄, 캡처 시 마스킹이 정상 작동하고 권한별 차등 설정 및 예외 승인 절차가 철저히 관리됨이 확인되면 양호로 확정합니다.", "partial": ["화면 조회 시에는 마스킹이 적용되나, 인쇄나 화면 캡처 시 마스킹이 해제되어 출력되는 화면이 일부 존재합니까?", "직급이나 업무 목적과 상관없이 전 임직원에게 동일한 수준의 마스킹 해제 권한이 부여되어 있습니까?", "마스킹 예외 승인 절차는 있으나 사후 이력 검토가 이루어지지 않는 이유는 무엇입니까?"], "partialEnd": "마스킹 적용 취약 구간(인쇄/캡처/권한설정)을 특정하고 기술적 통제 보완 및 권한 재조정 계획을 요구합니다.", "rootcause": ["주요 업무 화면에서 주민등록번호나 계좌번호가 전혀 마스킹되지 않고 평문 노출되는 원인은 무엇입니까?", "화면 마스킹 정책이 수립되지 않았거나 시스템 개발 시 반영되지 않은 경위는 무엇입니까?", "마스킹 미적용 화면을 통해 개인신용정보가 대량 유출될 위험에 대해 내부 보고가 이루어진 적이 있습니까?"], "rootcauseEnd": "개인신용정보 보호법령 위반 결함으로 확정하고, 전 시스템 마스킹 적용 개발 및 즉시 조치 계획 작성을 요구합니다.", "na": ["임직원이 개인신용정보를 화면에서 직접 조회하거나 출력하는 업무 기능이 전혀 없는 시스템입니까?"], "naEnd": "개인신용정보 화면 노출 기능이 전혀 없는 단방향 처리 시스템임이 확인되면 N/A로 판정합니다."}, "24-3": {"decisionQ": "개발 및 QA/테스트 환경에서 운영 실 개인신용정보를 전면 배제하고, 가명처리 또는 합성데이터만을 사용하고 있습니까?", "verify": ["현재 개발 및 QA 데이터베이스에 접속하여 주요 테이블의 주민번호, 성명, 계좌번호 데이터가 가명처리되었거나 합성데이터인지 직접 조회해 주시겠습니까?", "운영 DB의 데이터를 테스트 환경으로 이관할 때 적용하는 가명처리/변환 스크립트 및 익명화 도구 실행 결과를 보여주시겠습니까?", "개발 환경 DB 접속 가능 계정 목록을 조회하여 외주개발자 계정이 운영 실데이터에 접근 불가능하도록 차단되어 있는지 보여주시겠습니까?", "전 임직원 및 외주인력 대상 '테스트 환경 실데이터 사용 금지' 보안 교육 실시 이력을 제시해 주시겠습니까?"], "verifyEnd": "테스트 DB에 실데이터가 존재하지 않고, 가명/합성데이터 변환 절차가 적정하며 외주인력 통제가 확인되면 양호로 확정합니다.", "partial": ["주요 개인신용정보(주민번호)는 가명처리하였으나, 기타 정보(성명, 연락처, 계좌번호 등)가 실데이터 상태로 남아있는 테이블이 존재합니까?", "가명처리 변환 도구를 사용 중이나 재식별 가능한 유일키가 테스트 환경에 그대로 잔존해 있습니까?", "개발 환경에서 실데이터 사용 시 사전 파기 및 통제 절차가 부분적으로만 이행되는 원인은 무엇입니까?"], "partialEnd": "미변환된 잔여 실데이터의 완전 가명처리 및 삭제를 명령하고, 변환 스크립트 자동화 개선 계획을 요구합니다.", "rootcause": ["개발/테스트 DB에 운영 실 개인신용정보가 이관되어 변환 없이 그대로 사용되고 있는 이유는 무엇입니까?", "실데이터 변환 조치 없이 테스트를 진행하도록 승인한 책임자는 누구입니까?", "개발 DB에 존재하는 실데이터를 즉시 삭제하고 가명데이터로 교체할 수 있는 조치 계획은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 및 신용정보법 중대 위반 결함으로 확정하고, 개발 DB 내 실데이터 즉시 삭제 및 원인 규명보고서를 요구합니다.", "na": ["자체적인 개발/QA 환경을 운용하지 않으며, 모든 개발 업무를 외부 검증된 표준 패키지로만 도입하여 테스트 DB 구축 자체가 없는 구조입니까?"], "naEnd": "개발/테스트 DB 환경 자체가 존재하지 않음이 확인되면 N/A로 판정합니다."}, "24-4": {"decisionQ": "단일 계정의 단위 시간당 개인신용정보 조회 임계치 설정 및 야간·휴일 대량 다운로드에 대한 탐지·경보 시스템이 정상 작동하고 있습니까?", "verify": ["모니터링 시스템(SIEM 또는 통합로그)에서 단일 계정 개인신용정보 대량 조회 임계치 설정 화면을 보여주시겠습니까?", "야간 및 휴일에 발생한 대량 조회·다운로드 이벤트 탐지 및 담당자 자동 경보(SMS/메일/슬랙 등) 발송 설정 상태를 시연해 주시겠습니까?", "최근 6개월 동안 발생한 대량 조회 경보 이벤트 발생 내역과 이에 대한 소명·조치 이력 대장을 보여주시겠습니까?", "조회 임계치 설정값의 적정성에 대해 연 1회 이상 정기 검토를 실시한 보고서를 제시해 주시겠습니까?"], "verifyEnd": "임계치 및 야간/휴일 경보 설정이 유효하고, 탐지 이벤트에 대한 처리 이력 및 연간 정기 검토 보고서가 확인되면 양호로 확정합니다.", "partial": ["임계치는 설정되어 있으나 야간·휴일 특화 탐지 룰이 미비하거나 경보 발송이 담당자에게 실시간 전달되지 않는 상태입니까?", "대량 조회 탐지 경보는 발생하나 이에 대한 사후 소명 확인 조치가 누락되거나 지연 처리되는 사례가 존재합니까?", "임계치 적정성 정기 검토를 실시하지 않고 최초 설정값을 수년간 유지하고 있는 이유는 무엇입니까?"], "partialEnd": "탐지 룰 실시간성 강화, 소명 프로세스 정립 및 임계치 재검토 수행을 지적 조치사항으로 요구합니다.", "rootcause": ["단일 계정의 대량 개인신용정보 조회를 탐지하는 임계치 설정 및 모니터링 체계가 전혀 존재하지 않는 이유는 무엇입니까?", "야간·휴일 대량 다운로드에 따른 유출 시도를 탐지하지 못해 발생할 수 있는 사고 위험을 방치한 경위는 무엇입니까?", "즉시 임계치를 설정하고 모니터링 및 경보 체계를 구축할 수 있는 조치 일정은 무엇입니까?"], "rootcauseEnd": "대량 유출 탐지 부실 결함으로 확정하고, 대량조회 탐지 룰 즉시 반영 및 보안 모니터링 강화 계획 제출을 요구합니다.", "na": ["시스템 구조상 임직원이 개인신용정보를 대량으로 조회하거나 파일로 다운로드하는 기능 자체가 전무한 경우입니까?"], "naEnd": "대량 조회 및 다운로드 기능이 구조적으로 불가능함이 확인되면 N/A로 판정합니다."}, "24-5": {"decisionQ": "상주 외주개발자의 운영 DB 직접 접근이 완전히 차단되어 있으며, 개발·스테이징·운영 환경 분리 및 NDA/보안서약서 관리가 적정하게 이행되고 있습니까?", "verify": ["DB 접근통제 솔루션(DBSAFER 등)에서 외주개발자 계정 그룹의 운영 DB 접근 차단 룰 설정을 직접 보여주시겠습니까?", "개발, 스테이징, 운영 환경 간 네트워크 망분리 구성도 및 방화벽 정책 설정 화면을 보여주시겠습니까?", "현재 상주 중인 외주개발자 전원의 NDA(비밀유지계약서) 및 개인정보보호 보안서약서 징구 대장을 보여주시겠습니까?", "최근 6개월 내 퇴직 또는 철수한 외주개발자의 DB 접근 권한 및 내부계정 즉시 회수 이력을 제시해 주시겠습니까?"], "verifyEnd": "외주개발자의 운영 DB 접근이 완벽히 차단되어 있고 망분리, 서약서 징구, 권한 적기 회수가 확인되면 양호로 확정합니다.", "partial": ["외주개발자의 운영 DB 직접 접속은 차단되어 있으나, 예외 계정을 통해 일시적으로 직접 접속한 후 권한 회수가 지연된 사례가 있습니까?", "개발 환경과 운영 환경이 물리적/논리적으로 분리되어 있으나 일부 점검용 포트가 상시 열려 있습니까?", "외주개발자 교체 시 보안서약서 징구가 누락되거나 사후에 지연 징구된 경위는 무엇입니까?"], "partialEnd": "예외 접속 통제 강화, 방화벽 개방 포트 즉시 닫기 및 서약서 즉시 보완을 지적하여 개선토록 합니다.", "rootcause": ["상주 외주개발자에게 운영 DB 직접 접근 권한(쿼리 실행 등)이 부여되어 있는 이유는 무엇입니까?", "개발 환경과 운영 환경을 분리하지 않고 동일 네트워크에서 운영 DB를 직접 참조하도록 방치한 경위는 무엇입니까?", "외주인력 관리에 관한 전자금융감독규정 위반 상태를 해결하기 위한 즉시 권한 차단 계획은 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 위반 중대 결함으로 확정하고, 외주자 운영 DB 접근 권한 즉시 박탈 및 통제 강화 보고를 요구합니다.", "na": ["상주 또는 비상주를 포함하여 용역·단가를 수행하는 외주개발자 활용이 전혀 없는 100% 자체 개발/운영 조직입니까?"], "naEnd": "외주개발자 활용 자체가 전무함이 계약 대장 등을 통해 확인되면 N/A로 판정합니다."}, "24-6": {"decisionQ": "DBA 및 특권계정을 포함한 개인신용정보 DB 접근 로그가 90일 이상 보존되고, 별도 분리하여 월 1회 이상 이상징후를 정기 분석하고 있습니까?", "verify": ["DB 접근통제 솔루션의 로그 보존 기간 설정 화면(90일 이상 지정)을 직접 보여주시겠습니까?", "DBA 및 최고권한(root/sa) 계정의 접근 로그가 일반 사용자 로그와 별도로 분리되어 보관되는 저장소 현황을 보여주시겠습니까?", "최근 3개월간 수행한 'DBA/특권계정 접근 로그 정기 분석 보고서' 및 결재 문서를 제시해 주시겠습니까?", "이상징후(예: 대량 조회, 비업무시간 접속) 발생 시 에스컬레이션 절차 및 실제 처리 이력 로그를 보여주시겠습니까?"], "verifyEnd": "로그 90일 이상 보존, 특권계정 로그 분리 보관, 월 1회 이상 정기 분석 및 이상징후 에스컬레이션 처리가 확인되면 양호로 확정합니다.", "partial": ["DB 접근 로그는 90일 이상 보존되나, DBA/특권계정 로그가 분리되지 않고 일반 로그와 혼재되어 있습니까?", "특권계정 로그 분석을 실시하고 있으나 주기가 월 1회를 초과하거나, 분석 항목이 단순 접속 여부에만 치중되어 있습니까?", "이상징후 발견 시 보고 절차는 있으나 소명서 수령 등 후속 조치가 일부 누락된 원인은 무엇입니까?"], "partialEnd": "특권계정 로그 분리 저장 및 분석 항목 구체화, 사후 조치 절차 강화를 개선 사항으로 요구합니다.", "rootcause": ["DB 접근 로그 보존 기간이 90일 미만이거나 저장 공간 부족을 이유로 삭제되고 있는 원인은 무엇입니까?", "DBA 등 특권계정에 대한 접근 로그 분석을 전혀 수행하지 않아 내부자에 의한 오남용 통제가 안 되는 이유는 무엇입니까?", "특권계정 로그 분석 체계를 즉시 수립하고 미비된 로그를 복구/보존할 대책은 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 위반 결함으로 확정하고, 로그 저장공간 확보 및 DBA 로그 정기분석 체계 마련을 요구합니다.", "na": ["개인신용정보를 저장·처리하는 DB가 존재하지 않는 구조입니까?"], "naEnd": "개인신용정보 DB 자체가 존재하지 않음이 확인되면 N/A로 판정합니다."}, "24-7": {"decisionQ": "이메일, 웹, USB, 인쇄 출력 등 주요 유출 채널에 DLP 솔루션이 적용되어 개인신용정보 유출이 차단되며, 예외 승인 및 차단 패턴 최신화가 관리되고 있습니까?", "verify": ["DLP 솔루션 관리자 콘솔에서 이메일, 웹(게시판/클라우드), USB, 인쇄 통제 정책 적용 현황을 보여주시겠습니까?", "실제 개인신용정보(테스트용 주민번호/계좌번호)를 이메일 또는 USB로 반출 시도하여 DLP 차단 알림이 뜨는 것을 시연해 주시겠습니까?", "최근 3개월간 DLP 예외 승인(반출 허용) 신청서, 사유, 승인자 결재 이력 및 사후 삭제 검증 로그를 제시해 주시겠습니까?", "DLP의 개인신용정보 탐지 패턴(주민번호, 계좌번호, 카드번호 룰)이 최신 정책으로 반영된 설정 화면을 보여주시겠습니까?"], "verifyEnd": "전 채널 DLP 유출 차단 시연 성공, 예외 승인 절차 준수, 차단 패턴 최신화가 확인되면 양호로 확정합니다.", "partial": ["이메일과 USB는 차단되나, 웹 업로드나 인쇄 출력 채널에 대한 DLP 차단 정책이 미비한 상태입니까?", "DLP가 유출을 탐지하여 '경고'만 발생시키고 실제 차단(Block) 조치가 이루어지지 않는 채널이 있습니까?", "DLP 예외 승인 건에 대해 승인 기간 종료 후 권한 회수가 수동으로 처리되어 지연되는 이유는 무엇입니까?"], "partialEnd": "미비 채널 차단 정책 반영, 경고 모드의 차단 모드 전환, 예외 권한 자동 회수 시스템 보완을 요구합니다.", "rootcause": ["DLP 솔루션이 도입되지 않았거나, 도입되어 있음에도 agent가 PC에 정상 작동하지 않는 원인은 무엇입니까?", "DLP 차단 정책을 무력화하거나 예외 승인 없이 임의로 반출할 수 있는 보안 구멍이 방치된 경위는 무엇입니까?", "DLP 차단 룰을 정비하고 매체 유출 통제를 강화하기 위한 개선 조치 계획은 무엇입니까?"], "rootcauseEnd": "개인신용정보 유출 방지 조치 위반 결함으로 확정하고, DLP 전사 적용 및 차단 정책 재정비 보고를 요구합니다.", "na": ["모든 업무 PC가 인터넷과 완전히 물리적으로 차단되어 있고, USB 포트가 물리적으로 봉인되어 있으며 출력이 불가능한 환경입니까?"], "naEnd": "매체/네트워크 유출 채널 자체가 물리적으로 완전 차단되어 있음이 확인되면 N/A로 판정합니다."}, "24-8": {"decisionQ": "개인신용정보 유출 사고 인지 시 72시간 이내 개인정보보호위원회 신고 및 금융위원회 즉시 통지 절차가 최신 대응 매뉴얼에 반영되어 있고 담당자가 숙지하고 있습니까?", "verify": ["최신으로 개정된 '개인신용정보 유출 사고 대응 매뉴얼/절차서'를 제시해 주시겠습니까?", "매뉴얼 내에 개정 개인정보보호법에 따른 '72시간 이내 보호위 신고' 및 신용정보법에 따른 '금융위 즉시 통지' 양식과 절차가 명시되어 있는지 보여주시겠습니까?", "유출 사고 통지·신고 담당자의 지정 현황 및 해당 담당자가 신고 수단(포털 등)과 절차를 숙지하고 있는지 설명해 주시겠습니까?", "과거 유출 사고(또는 유사 사고) 발생 시 실제 보고/신고를 이행한 증빙 기록을 보여주시겠습니까? (사고가 없었던 경우 N/A 검증 질문으로 대체)"], "verifyEnd": "신고 절차서 최신화, 72시간 및 즉시 보고 규정 명시, 담당자 숙지 상태가 검증되면 양호로 확정합니다.", "partial": ["유출 사고 대응 매뉴얼은 있으나 과거 법령 기준(예: 24시간 또는 5일 등)으로 되어 있어 72시간/즉시 통지 기준 개정이 누락되어 있습니까?", "보고 절차는 수립되어 있으나 주관 부서 및 담당자 변경 사항이 반영되지 않아 비상 연락 체계가 구형입니까?", "절차서 개정이 지연되고 있는 원인과 즉시 개정 반영 계획은 무엇입니까?"], "partialEnd": "개정 법령 기준(보호위 72h, 금융위 즉시)을 반영한 절차서 즉시 개정 및 담당자 재교육을 지적합니다.", "rootcause": ["개인신용정보 유출 사고 시 법정 신고 시한을 준수하기 위한 내부 절차서 자체가 부재한 이유는 무엇입니까?", "유출 사고 발생 시 금융위 및 보호위 신고 의무 자체를 인지하지 못하고 있는 경위는 무엇입니까?", "유출 사고 발생 시 법정 시한 초과로 인한 과태료/제재 위험을 방지하기 위한 긴급 절차 정비 대책은 무엇입니까?"], "rootcauseEnd": "법정 유출 신고 체계 미비 결함으로 확정하고, 유출 대응 절차서 제정 및 경영진 보고를 요구합니다.", "na": ["과거 유출 사고 이력 유무를 질문하는 항목의 경우, 설립 이후 현재까지 개인신용정보 유출 사고가 단 한 건도 발생하지 않았음을 증명하는 경우 (단, 매뉴얼 보유 여부는 점검 대상임)"], "naEnd": "사고 이력 부분에 한해 사고 무발생 사실이 확인되면 이력 검증은 N/A 처리하되 매뉴얼 적정성은 평가합니다."}, "24-9": {"decisionQ": "전자금융사고 발생 시 3시간 이내에 금융감독원에 보고하기 위한 전담 절차서, 최신 비상연락망 및 보고 체계가 수립되어 있습니까?", "verify": ["전자금융사고 발생 시 '3시간 이내 금감원 보고' 절차가 규정된 전자금융사고 대응 매뉴얼을 보여주시겠습니까?", "금융감독원 담당 부서 및 담당자 비상연락망이 최근 기준(최근 3개월 이내)으로 최신화된 대장을 보여주시겠습니까?", "전자금융사고 발생 상황을 가정한 보고 서식 작성 및 금감원 보고 채널(POSS 등) 송신 준비 상태를 시연해 주시겠습니까?", "과거 전자금융사고 발생 시 실제 3시간 이내 보고가 이뤄진 보고서 및 접수 이력을 보여주시겠습니까?"], "verifyEnd": "3시간 보고 절차 명시, 비상연락망 최신화, 보고 채널 준비 및 과거 보고 이행이 확인되면 양호로 확정합니다.", "partial": ["3시간 보고 절차는 수립되어 있으나, 금감원 담당자 비상연락망의 인사이동 내용이 반영되지 않아 구형 정보가 방치되어 있습니까?", "야간이나 휴일 사고 발생 시 3시간 이내 보고를 위한 당직자/비상대기자보고 체계가 불명확한 부분이 있습니까?", "비상연락망 미갱신 및 야간 보고 체계 미비의 원인은 무엇입니까?"], "partialEnd": "금감원 비상연락망 즉시 갱신 및 야간/휴일 3시간 내 보고 비상 대응 체계 보완을 지적합니다.", "rootcause": ["전자금융사고 발생 시 금감원 3시간 이내 보고 의무를 규정한 매뉴얼 자체가 없는 이유는 무엇입니까?", "사고 발생 후 3시간이라는 엄격한 기한 내 보고를 위한 보고 라인이 구축되지 않은 경위는 무엇입니까?", "전자금융거래법 위반을 방지하기 위해 3시간 보고 절차를 즉시 제정하고 비상연락 체계를 구축할 계획은 무엇입니까?"], "rootcauseEnd": "전자금융거래법 위반 결함으로 확정하고, 3시간 보고 매뉴얼 제정 및 비상연락망 정비를 서면 요구합니다.", "na": ["저축은행법상 전자금융업자/전자금융보조업자에 해당하지 않거나 전자금융거래 서비스를 전혀 제공하지 않는 특수 기관인 경우"], "naEnd": "전자금융거래 서비스를 전혀 제공하지 않는 기관임이 확인되면 N/A로 판정합니다."}, "24-10": {"decisionQ": "연 1회 이상 개인신용정보 유출 시나리오에 기반한 모의훈련을 계획·실시하고, 그 결과를 경영진에 보고하여 유출 대응 절차에 반영하고 있습니까?", "verify": ["당해 연도(또는 전년도) 개인신용정보 유출 대응 모의훈련 종합 계획서 및 결과 보고서를 보여주시겠습니까?", "훈련 시나리오에 '유출 인지 -> 초기 통제 -> 정부기관(보호위/금융위) 보고 -> 정보주체 통지' 전 과정이 포함되어 있는지 시나리오 문서를 제시해 주시겠습니까?", "임직원 및 관련 부서의 훈련 참석 명단과 불참자에 대한 사후 조치(재교육 등) 이력을 보여주시겠습니까?", "모의훈련 결과 도출된 개선 필요사항이 실제 유출 대응 절차서 개정에 반영된 이력을 제시해 주시겠습니까?"], "verifyEnd": "연 1회 모의훈련 실시, 전 과정 시나리오 포함, 높은 참석률 및 훈련 결과를 통한 절차 개선이 확인되면 양호로 확정합니다.", "partial": ["모의훈련을 실시하였으나, 정부기관 보고나 정보주체 통지 단계가 제외된 단순 기술적 해킹 대응 위주로 진행되었습니까?", "훈련 불참자에 대한 추가 훈련이나 사후 조치가 이행되지 않고 방치된 비율이 높습니까?", "훈련 결과 보고서상 도출된 지적사항에 대해 실제 절차서 개정 등 후속 조치가 미진한 원인은 무엇입니까?"], "partialEnd": "훈련 시나리오에 보고/통지 절차 포함, 불참자 재훈련 실시 및 개선사항의 절차서 즉시 반영을 지적합니다.", "rootcause": ["최근 1년 이상 개인신용정보 유출 대응 모의훈련을 전혀 실시하지 않은 이유는 무엇입니까?", "모의훈련의 중요성을 인지하지 못하거나 전담 인력 부족을 이유로 훈련을 방치한 경위는 무엇입니까?", "유출 대응 역량을 강화하기 위해 빠른 시일 내 모의훈련을 계획하고 실시할 대책은 무엇입니까?"], "rootcauseEnd": "유출 대응 훈련 미실시 결함으로 확정하고, 유출 모의훈련 계획 수립 및 조속한 실시를 요구합니다.", "na": ["당해 연도 신규 설립된 저축은행으로 아직 첫 번째 모의훈련 수립 주기가 도래하지 않은 경우 (단, 연간 훈련 계획서는 작성되어 있어야 함)"], "naEnd": "신설 기관으로서 훈련 계획서가 수립되어 있고 주기가 도래하지 않았음이 확인되면 N/A로 판정합니다."}, "24-11": {"decisionQ": "유출 사고 발생 시 정보주체에게 통지할 통지 수단(이메일·문자·서면) 및 핵심 기재사항이 포함된 서식이 준비되어 있으며 공지 대체 절차가 수립되어 있습니까?", "verify": ["정보주체 유출 통지용 표준 서식(유출 항목, 시점, 원인, 정보주체 대처방법, 피해보상 절차 등 포함)을 보여주시겠습니까?", "대량 발송을 위한 문자(SMS/LMS) 발송 시스템 및 이메일 발송 연동 체계 준비 상태를 보여주시겠습니까?", "연락처 불상 등으로 개별 통지가 불가능한 경우를 대비한 홈페이지 공지 대체 절차서 및 서식을 보여주시겠습니까?", "과거 유출 통지 수행 이력이 있는 경우, 통지 완료 내역 및 수신여부 관리 대장을 제시해 주시겠습니까?"], "verifyEnd": "통지 수단 및 구체적 서식 구비, 홈페이지 공지 대체 절정 수립, 통지 이력 관리가 확인되면 양호로 확정합니다.", "partial": ["개별 통지 서식은 구비되어 있으나, 법정 필수 기재 항목(예: 피해접수 담당부서 및 연락처) 일부가 누락되어 있습니까?", "문자나 이메일 발송 체계는 구축되어 있으나, 시스템 장애나 대량 발송 제한으로 즉시 발송이 어려운 상태입니까?", "홈페이지 공지 대체 조건(예: 1만건 이상 유출 등) 및 게시 기간 규정이 명확하지 않은 원인은 무엇입니까?"], "partialEnd": "통지 서식 내 법정 필수 항목 보완 및 대량 발송 채널 점검, 공지 대체 기준 명확화를 요구합니다.", "rootcause": ["유출 발생 시 정보주체에게 통지하기 위한 시스템이나 사전 양식 자체가 준비되어 있지 않은 이유는 무엇입니까?", "정보주체 통지 의무를 인지하지 못했거나 통지 서식을 구비하지 않아 발생할 대 혼란을 방치한 경위는 무엇입니까?", "개인정보보호법상 통지 의무 준수를 위해 표준 통지 양식 및 대량 발송 체계를 즉시 구축할 계획은 무엇입니까?"], "rootcauseEnd": "정보주체 통지 체계 미비 결함으로 확정하고, 정보주체 통지 서식 제정 및 발송 체계 정비를 서면 요구합니다.", "na": ["개인신용정보를 직접 보유하지 않거나, 개인정보 처리를 위탁받아 단순히 처리만 수행하여 직접 통지 의무 주체가 아닌 특수 법인인 경우"], "naEnd": "정보주체 직접 통지 의무가 없는 위탁 기관임이 증명되면 N/A로 판정합니다."}, "24-12": {"decisionQ": "형상관리 시스템의 접근 권한이 최소화되어 있고, 외주개발자의 소스코드 무단 반출이 DLP로 통제되며 퇴직·계약만료 시 권한이 즉시 회수되고 있습니까?", "verify": ["형상관리 시스템(Git, SVN 등)의 계정별/프로젝트별 접근 권한 설정 목록을 직접 보여주시겠습니까?", "외주개발자가 소스코드를 로컬 PC 외부로 반출하거나 이메일/USB로 유출하려 할 때 DLP에서 차단하는 정책 설정을 보여주시겠습니까?", "소스코드를 정당한 사유로 외부 반출할 때의 사전 승인 결재 문서 및 반출 이력 대장을 보여주시겠습니까?", "최근 퇴직한 내부 개발자 및 계약 만료된 외주개발자의 형상관리 시스템 권한 회수 타임라인 로그를 제시해 주시겠습니까?"], "verifyEnd": "형상관리 권한 최소화, DLP 소스코드 차단, 반출 사전 승인, 퇴직자 권한 즉시 회수가 확인되면 양호로 확정합니다.", "partial": ["형상관리 권한은 통제되나 프로젝트 전체에 대해 개발자들에게 과도한 읽기/쓰기 통통권한이 부여되어 있습니까?", "DLP로 텍스트 소스코드는 차단되나 압축 파일이나 암호화 파일 형태의 소스코드 반출 차단 정책이 미흡합니까?", "퇴직자 계정 회수가 퇴직일 이후 수일간 지연 처리된 경위는 무엇입니까?"], "partialEnd": "형상관리 권한 세분화, DLP 압축파일 반출 탐지 강화, 퇴직자 계정 자동 회수 연동 조치를 지적합니다.", "rootcause": ["형상관리 시스템 접근 권한이 모든 개발자 및 외주자에게 일률적으로 풀 권한으로 부여된 이유는 무엇입니까?", "소스코드 반출을 통제하는 DLP 정책이 없거나 외주개발자가 제한 없이 소스코드를 유출할 수 있게 방치된 경위는 무엇입니까?", "소스코드 자산 유출 위험을 차단하기 위한 형상관리 통제 및 DLP 연계 강화 계획은 무엇입니까?"], "rootcauseEnd": "소스코드 자산 통제 부실 결함으로 확정하고, 형상관리 권한 재조정 및 소스코드 반출 차단 정책 즉시 적용을 요구합니다.", "na": ["자체 소스코드 개발이나 수정 업무가 전혀 없으며 전적으로 외부 완전 완제품(COTS)만을 사용하고 개발 조직이 없는 경우"], "naEnd": "자체 개발 및 소스코드 관리가 전혀 수행되지 않는 조직임이 증명되면 N/A로 판정합니다."}, "23-1": {"decisionQ": "전자금융거래 기능별 강화인증(OTP·생체) 적용, 비밀번호 복잡도, 5회 실패 시 계정 잠금 정책이 실제 시스템 서버 설정에 반영되어 운영 중인지 바로 확인해 주시겠습니까?", "verify": ["인증서버의 비밀번호 정책 설정 화면에서 최소 길이(영문·숫자·특수문자 조합)와 5회 이상 실패 시 잠금 옵션이 활성화되어 있는지 보여주시겠습니까?", "이체 및 주요 정보 변경 등 고위험 거래 발생 시 OTP 또는 생체인증이 필수 호출되도록 설정된 거래별 인증 매핑 정책을 보여주시겠습니까?", "임시 비밀번호 발급 후 사용자 첫 로그인 시 비밀번호 변경 화면으로 즉시 이동하도록 강제 설정된 소스코드 또는 시스템 정책을 시연해 주시겠습니까?", "최근 1개월 내 비밀번호 5회 오류로 계정이 잠긴 실제 고객 로그를 감사역이 지정하는 시점으로 조회해 주시겠습니까?"], "verifyEnd": "제시된 인증 서버 설정, 거래별 강화인증 매핑 내역, 계정 잠금 실적 로그가 규정(전자금융감독규정 §15)과 일치함을 확인하여 양호로 판정합니다.", "partial": ["비밀번호 복잡도나 실패 잠금은 설정되어 있으나, 일부 간편뱅킹 서비스나 모바일 앱 거래에서 OTP·생체인증 등 강화인증이 누락된 구간이 있습니까?", "임시 비밀번호 발급 후 변경을 강제하지 않고 기존 임시 비밀번호로 연속 거래가 가능하도록 허용된 예외 채널이 존재합니까?", "이러한 미흡 구간이 발생한 사유와, 규정 수준으로 강화하기 위한 개선 계획 및 이행 시점은 언제입니까?"], "partialEnd": "일부 거래 채널의 강화인증 적용 누락 등 경계성 미흡을 확인하여 부분이행으로 기록하고, 즉시 보안 정책 반영 및 완료 기한 제출을 서면으로 요청합니다.", "rootcause": ["로그인 실패 5회 이상에도 계정이 잠기지 않거나 OTP 요구가 완전히 누락된 채 서비스가 제공되는 원인은 무엇입니까?", "비밀번호 정책 변경이나 시스템 개편 시 관련 보안 설정 검증 절차를 거치지 않았습니까?", "이러한 통제 부재 상태를 언제부터 인지하고 있었으며, 상급자나 정보보호최고책임자(CISO)에게 보고된 적이 있습니까?", "취약한 인증 체계로 인해 발생할 수 있는 부정 로그인 예방을 위한 즉시 조치 계획은 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제15조 위반에 해당하는 핵심 통제 결함으로 판정하고, 즉시 설정 변경 명령 및 취약점 개선계획서 수립을 요청합니다.", "na": ["해당 웹/앱 서비스에서 금융거래, 회원가입, 로그인 등 본인 확인이 필요한 기능이 전혀 존재하지 않는 단순 안내용 페이지입니까?", "안내용 서비스에서 향후 본인인증이 필요한 기능(상담 신청, 대출 조회 등)이 추가될 계획이 없는지 확인해 주시겠습니까?"], "naEnd": "금융거래 및 사용자 인증 기능이 전혀 없는 완전 안내형 시스템임을 확인하여 해당없음으로 처리합니다."}, "23-2": {"decisionQ": "웹·모바일 세션의 비활성 자동 종료(10분), 쿠키 Secure/HttpOnly 속성, 동시 로그인 제한 및 서버 측 세션 파기 정책이 실제 반영되어 있습니까?", "verify": ["웹서버/WAS의 세션 타임아웃 설정 파일(web.xml 등)에서 타임아웃 값이 10분(600초) 이하로 설정되어 있는지 보여주시겠습니까?", "감사역이 지정하는 웹 페이지 접속 상태에서 브라우저 개발자 도구(F12)를 열어 세션 쿠키의 HttpOnly 및 Secure 플래그 적용 여부를 보여주시겠습니까?", "동일 계정으로 PC와 모바일 앱에서 동시에 로그인을 시도할 때 기존 세션이 차단되거나 중복 로그인이 통제되는지 시연해 주시겠습니까?", "로그아웃 버튼 클릭 시 서버 DB/메모리 상에서 해당 세션 토큰이 완벽히 삭제되어 이전 토큰 재사용이 불가능한지 검증해 주시겠습니까?"], "verifyEnd": "세션 타임아웃 설정, 쿠키 보안 속성, 중복 로그인 통제 및 로그아웃 시 서버 세션 완벽 파기가 확인되어 양호로 판정합니다.", "partial": ["세션 타임아웃은 10분으로 설정되어 있으나, 특정 쿠키에 Secure 또는 HttpOnly 속성이 누락되어 있습니까?", "웹 상에서는 동시 로그인이 차단되나 모바일 앱과 웹 간 크로스 채널 동시 로그인은 허용되고 있습니까?", "로그아웃 시 클라이언트 쿠키만 삭제되고 서버 세션은 일정 시간 유지되는 문제에 대한 개선 계획은 무엇입니까?"], "partialEnd": "일부 쿠키 보안 속성 누락 및 채널 간 동시 로그인 통제 미비가 확인되어 부분이행으로 처리하고 보완 조치를 요구합니다.", "rootcause": ["세션 타임아웃이 10분을 초과하거나(예: 30분 이상) 비활성 세션 종료 기능 자체가 구현되어 있지 않은 원인은 무엇입니까?", "쿠키를 통한 Session Hijacking 공격 방지 대책(HttpOnly, Secure)을 개발 가이드라인에 반영하지 않은 이유는 무엇입니까?", "서버 측 세션 파기 미흡으로 인한 세션 재사용 위험에 대해 정보보호 점검이나 개발 검수를 진행하지 않았습니까?"], "rootcauseEnd": "전자금융감독규정 §15 위반 및 세션 탈취 위험 존재로 미흡(결함) 판정하며, 세션 관리 로직 재개발을 명합니다.", "na": ["로그인 기능이 전혀 없고 세션을 생성하거나 유지하지 않는 무상태(Stateless) 단방향 정보 제공 서비스입니까?"], "naEnd": "사용자 세션을 수립하지 않는 완전한 무상태 안내 서비스임을 확인하여 해당없음 처리합니다."}, "23-3": {"decisionQ": "모바일 앱 및 API 게이트웨이의 Access/Refresh 토큰 유효기간 정책, 미인증 엔드포인트 존재 여부, API 인가 통제가 올바르게 설정되어 있습니까?", "verify": ["API 게이트웨이 또는 인증서버 설정에서 Access Token(예: JWT)과 Refresh Token의 유효기간 설정값을 보여주시겠습니까?", "전체 API 엔드포인트 목록 중 인증이 필요 없는 Unauthenticated API 명세를 보여주시고, 본인인증/금융거래 API가 포함되어 있지 않음을 확인해 주시겠습니까?", "AccessToken 만료 시 Refresh Token을 통한 재발급 절차 및 만료된 Refresh Token 사용 시 즉시 차단되는 정책을 보여주시겠습니까?", "감사역이 지정한 사용자 A의 토큰으로 사용자 B의 계좌 정보 API를 호출했을 때, 권한 없음(403 Forbidden)으로 정상 차단되는지 시연해 주시겠습니까?"], "verifyEnd": "적정한 토큰 유효기간, 미인증 API 통제, API 수준의 인가(Authorization) 처리가 철저히 검증되어 양호로 판정합니다.", "partial": ["Access Token의 유효기간은 적정하나 Refresh Token의 유효기간이 과도하게 길거나(예: 6개월 이상) 무제한 갱신이 허용되어 있습니까?", "로그인 및 거래 API는 인가 통제가 되나, 조회성 일부 API에서 사용자 간 권한 검증(IDOR 취약점)이 부분적으로 누락되어 있습니까?", "미인증 API 엔드포인트 중 불필요하게 노출된 내부 개발용 API에 대한 제거 및 개선 계획은 무엇입니까?"], "partialEnd": "Refresh Token 갱신 정책 미흡 및 일부 조회 API 인가 통제 누락을 부분이행으로 기록하고 즉시 수정 개발을 요구합니다.", "rootcause": ["인증 토큰의 유효기간이 설정되어 있지 않거나, Access Token이 만료되지 않는 구조로 개발된 원인은 무엇입니까?", "API 게이트웨이 도입 시 전체 API에 대한 인가 정책을 수립하지 않거나 개발자 임의로 미인증 API를 개설하도록 방치한 이유는 무엇입니까?", "타인의 토큰으로 타인 정보 조회가 가능한 객체 수준 인가 통제 실패(BOLA/IDOR) 현상을 사전 보안 점검에서 발견하지 못한 경위는 무엇입니까?"], "rootcauseEnd": "API 보안 통제 체계 심각 결함으로 판정하며, 미인증 API 즉시 차단 및 API 게이트웨이 인가 재설정을 요구합니다.", "na": ["모바일 앱 전용 API 게이트웨이를 운용하지 않으며, 외부 연계 및 앱-서버 간 API 통신 구조 자체가 전혀 존재하지 않는 시스템입니까?"], "naEnd": "API 통신 기반의 서비스 구조가 없음을 확인하여 해당없음으로 처리합니다."}, "23-4": {"decisionQ": "비정상 IP, 신규 기기, 자격증명 스터핑(Credential Stuffing) 탐지 룰을 운영 중이며 의심 로그인 발생 시 이용자 알림 및 차단이 실시간 수행되고 있습니까?", "verify": ["FDS(이상금융거래탐지시스템) 또는 WAF/SIEM에서 자격증명 스터핑 및 무차별 대입 공격 탐지 임계치(예: 동일 IP당 분당 30회 이상 실패 등) 설정 화면을 보여주시겠습니까?", "해외 IP 접속 차단 정책 및 미등록 신규 기기 접속 시 추가 인증(MFA)을 요구하는 탐지 룰 설정 내역을 확인해 주시겠습니까?", "실제 비정상 로그인 탐지 이벤트 발생 시 해당 고객에게 발송된 알림(SMS, PUSH, 알림톡) 이력을 최근 1주일 내 건으로 조회해 주시겠습니까?", "탐지된 비정상 IP/기기에 대해 자동 차단(IP Block / Device Ban) 처리된 실제 차단 리스트 및 대응 이력 로그를 보여주시겠습니까?"], "verifyEnd": "ATO 탐지 룰 정상 운영, 의심 접속 시 실시간 알림 발송, 차단 조치 이력이 완벽히 입증되어 양호로 판정합니다.", "partial": ["자격증명 스터핑 탐지 룰은 설정되어 있으나 임계치가 너무 높게 설정되어 실제 소량 분산 공격을 탐지하지 못합니까?", "의심 로그인 탐지 시 차단 및 모니터링은 이루어지나 이용자에 대한 실시간 알림 발송 연동이 누락되어 있습니까?", "ATO 탐지 시스템의 미흡한 룰을 보완하고 알림 체계를 일치시키기 위한 향후 계획은 무엇입니까?"], "partialEnd": "탐지 임계치 과다 또는 실시간 알림 누락 등 부분적 통제 미비가 확인되어 탐지 룰 정밀화 및 알림 연동 개선을 요청합니다.", "rootcause": ["계정 탈취 시도(ATO)를 탐지할 수 있는 탐지 룰이나 모니터링 체계 자체가 구축되지 않은 원인은 무엇입니까?", "대량의 로그인 실패 패턴이나 해외 IP를 통한 무차별 접속 시도를 방치하여 발생할 수 있는 피해 위험을 사전에 검토하지 않았습니까?", "ATO 모니터링을 위한 전담 운영 인력 또는 보안관제 연동 체계가 부재한 이유와 개선 계획은 무엇입니까?"], "rootcauseEnd": "금융IT안전성강화가이드 미준수 및 ATO 공격 무방비 상태로 결함 판정하며, ATO 탐지 룰 즉시 신설 및 차단 체계 구축을 명합니다.", "na": ["해당 웹/앱 서비스가 회원가입 및 로그인 절차가 존재하지 않는 단순 조회용 서비스여서 계정 개념 자체가 없습니까?"], "naEnd": "계정 로그인 기능이 전혀 존재하지 않는 서비스임을 확인하여 해당없음 처리합니다."}, "23-5": {"decisionQ": "웹·모바일 앱의 모든 전송 구간에 TLS 1.2 이상이 적용되어 있고, 취약한 암호 스위트 제거 및 HSTS 헤더가 설정되어 있습니까?", "verify": ["웹서버(Nginx, Apache 등) SSL/TLS 설정 파일에서 Protocols 설정이 TLSv1.2, TLSv1.3만 허용되고 TLS 1.0/1.1이 비활성화되어 있음을 보여주시겠습니까?", "취약한 암호 스위트(RC4, DES, 3DES, EXPORT, NULL)가 SSLCipherSuite 설정에서 완전히 exclusion(-) 처리되어 있는지 보여주시겠습니까?", "브라우저 또는 SSL 점검 도구를 통해 응답 헤더에 'Strict-Transport-Security(HSTS)' 헤더가 정상 출력되는지 보여주시겠습니까?", "현재 사용 중인 SSL/TLS 인증서의 유효기간 및 갱신 관리 이력(만료 30일 전 알림 설정 등)을 확인해 주시겠습니까?"], "verifyEnd": "TLS 1.2 이상 적용, 취약 Cipher Suite 완전 제거, HSTS 설정 및 인증서 유효기간 관리가 입증되어 양호로 판정합니다.", "partial": ["메인 서비스는 TLS 1.2 이상이 적용되어 있으나 일부 정적 자원 서버나 구버전 모바일 앱 연계 서버에 TLS 1.0/1.1이 허용되어 있습니까?", "TLS 1.2 이상을 사용 중이나 HSTS(Strict-Transport-Security) 헤더가 누락되어 HTTP 도청/스푸핑 공격에 노출될 가능성이 있습니까?", "취약한 TLS 버전을 아직 거두지 못하는 불가피한 사유와, 해당 구간 폐기/업그레이드 완료 예정일은 언제입니까?"], "partialEnd": "일부 서버의 하위 TLS 버전 허용 또는 HSTS 미설정을 확인하여 부분이행으로 기록하고 보안 강화 조치를 요구합니다.", "rootcause": ["TLS 1.0/1.1 등 구버전 프로토콜이나 RC4, 3DES 등 취약한 암호 스위트를 여전히 활성화해 둔 원인은 무엇입니까?", "전송 구간 암호화 미흡으로 인한 중간자 공격(MITM) 및 데이터 도청 위험에 대해 보안 점검을 실시하지 않았습니까?", "SSL/TLS 설정 가이드라인을 작성하여 웹서버 관리자에게 전달하고 이행 여부를 검수하는 절차가 부재한 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제17조 위반 및 암호화 통제 미흡으로 결함 판정하며, 취약 프로토콜 즉시 비활성화를 요구합니다.", "na": ["내부망 전용 단순 안내용 웹으로, 전자금융거래나 개인정보 전송이 전혀 발생하지 않으며 외부 인터넷망에 노출되지 않는 서비스입니까?"], "naEnd": "외부 노출 및 금융정보 전송이 없는 완전 내부망 전용 시스템임을 확인하여 해당없음 처리합니다."}, "23-6": {"decisionQ": "웹방화벽(WAF)의 탐지 룰이 월 1회 이상 정기 업데이트되고 있으며, SQL인젝션·XSS 차단 이력 및 예외 정책 승인 절차가 엄격히 관리되고 있습니까?", "verify": ["WAF 관리 콘솔에서 최근 6개월간 최신 공격 룰셋(Rule Set) 업데이트 수행 이력 로그를 보여주시겠습니까?", "최근 1개월간 WAF에서 차단한 SQL 인젝션, XSS, CSRF 공격 차단 로그 및 통계 리포트를 현장에서 조회해 주시겠습니까?", "WAF 차단 정책 예외(Bypass/Allow)로 등록된 IP 또는 URL 목록을 보여주시고, 각 예외 건별 결재된 '예외 승인 문서'를 보여주시겠습니까?", "WAF 운영 현황에 대해 월 1회 이상 정보보호최고책임자(CISO) 또는 담당 부서장이 검토하고 서명한 월간 보고서를 확인해 주시겠습니까?"], "verifyEnd": "WAF 룰 최신화(월1회 이상), 차단 로그 입증, 예외 정책 문서화 결재, 월간 보고서 검토가 완벽히 입증되어 양호로 판정합니다.", "partial": ["WAF 룰 업데이트가 이루어지고 있으나 정기적(월 1회)으로 시행되지 않고 분기/반기 단위로 지연되었습니까?", "WAF 예외 정책이 설정되어 있으나 결재 문서가 누락되거나 구두 요청으로 등록된 건이 일부 포함되어 있습니까?", "미흡한 예외 정책을 정비하고 결재 프로세스를 규정화하기 위한 개선 이행 계획은 무엇입니까?"], "partialEnd": "룰 업데이트 주기 지연 및 예외 승인 절차 일부 미흡을 부분이행으로 기록하고 절차 정비를 권고합니다.", "rootcause": ["WAF 탐지 룰 업데이트가 장기간(6개월 이상) 중단된 채 방치된 원인은 무엇입니까?", "WAF를 차단 모드(Block)가 아닌 단순 탐지 모드(Monitor)로만 운용하여 실제 공격을 차단하지 못하고 있는 이유는 무엇입니까?", "임의로 WAF 예외 등록을 수행하여 특정 IP나 URL에 대한 웹 공격 통제를 완전히 무력화한 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §18 위반 및 WAF 무력화운영 결함으로 판정하며, WAF 룰 즉시 업데이트 및 예외 전수 재검토를 명합니다.", "na": ["외부 연결이 완전히 차단되어 웹 공격 가능성이 없는 폐쇄망 내부 시스템이거나, 상위 기관 WAF에서 전적으로 일괄 통제하는 구조입니까?"], "naEnd": "상위 기관 통합 WAF 적용 또는 완벽 폐쇄망으로 자체 WAF 운영 대상이 아님을 확인하여 해당없음 처리합니다."}, "23-7": {"decisionQ": "연 1회 이상 정기 모의해킹(OWASP Top10 기준)을 수행하고 있으며, 발굴된 고위험 취약점을 30일 이내에 완벽히 조치하였습니까?", "verify": ["최근 1년 이내 수행된 모의해킹 결과 보고서를 제출받아, 점검 항목에 OWASP Top 10 주요 취약점이 포함되어 있는지 확인해 주시겠습니까?", "보고서 상에 발견된 '고위험(High)' 등급 취약점 항목과, 해당 항목의 '조치 완료 보고서(재점검 결과서)'를 대조해 주시겠습니까?", "고위험 취약점의 '발견일(보고서 확정일)'부터 '조치 완료일'까지의 소요 일수가 30일 이내인지 일자를 확인해 주시겠습니까?", "모의해킹을 수행한 외부 전문업체의 계약서 상 보안조항(비밀유지협약, 결과물 보안 관리)이 포함되어 있는지 확인해 주시겠습니까?"], "verifyEnd": "연 1회 모의해킹 실시, OWASP Top10 기준 점검, 고위험 취약점 30일 내 조치 완료가 확인되어 양호로 판정합니다.", "partial": ["모의해킹은 연 1회 실시하였으나, 고위험 취약점 조치가 30일을 초과하여(예: 45일 소요) 지연 조치된 이력이 있습니까?", "OWASP 항목 중 일부(예: API 취약점, CSRF 등)가 점검 대상에서 누락된 상태로 축소 수행되었습니까?", "조치 지연 원인과 향후 취약점 조치 SLA(30일)를 준수하기 위한 프로세스 개선안은 무엇입니까?"], "partialEnd": "모의해킹은 수행했으나 고위험 취약점 조치 기한(30일) 준수 지연을 부분이행으로 기록하고 개선을 요구합니다.", "rootcause": ["최근 1년 이상 홈페이지 및 모바일 앱에 대한 모의해킹을 전혀 실시하지 않은 원인은 무엇입니까?", "모의해킹 결과 보고서에서 지적된 고위험 취약점에 대해 감사 시점까지 조치하지 않고 방치한 사유는 무엇입니까?", "취약점 점검 결과를 경영진이나 CISO에게 보고하지 않거나 조치 예산을 확보하지 않은 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §18 위반 및 고위험 보안 취약점 방치로 결함 판정하며, 즉시 모의해킹 수립 및 미조치 항목 긴급 패치를 명합니다.", "na": ["신규 구축 후 서비스 오픈 전이거나, 당해 연도 구축되어 아직 정기 모의해킹 주기(연 1회)가 도래하지 않은 신규 서비스입니까? (단, 오픈 전 모의해킹 수행 여부 확인 필요)"], "naEnd": "오픈 전 모의해킹을 이미 완료했거나 주기 미도래 타당성이 입증된 경우 해당없음(또는 이행 완료)으로 정리합니다."}, "23-8": {"decisionQ": "모바일 앱에 루팅·탈옥 탐지, 소스코드 난독화, 앱 위변조 방지 솔루션이 적용되어 실제로 실행 시 차단 동작을 합니까?", "verify": ["모바일 앱 빌드 설정 또는 보안 솔루션(위변조방지/난독화) 적용 확인서를 보여주실 수 있습니까?", "루팅 또는 탈옥 처리된 테스트 단말기에서 자사 모바일 앱을 실행했을 때, '루팅 환경 탐지' 메시지와 함께 앱이 자동 종료되는지 현장에서 시연해 주시겠습니까?", "APK/IPA 파일의 소스코드를 디컴파일(Decompile)했을 때 핵심 클래스와 메서드가 의미 없는 문자(a, b, c)로 난독화되어 있는지 보여주시겠습니까?", "앱 해시(Hash)값 무결성 검증을 통해 앱 소스코드 위변조 시 서버 통신이 즉시 차단되는 대응 체계 로그를 확인해 주시겠습니까?"], "verifyEnd": "루팅/탈옥 차단 시연, 코드 난독화 확인, 위변조 차단 무결성 검증이 현장에서 입증되어 양호로 판정합니다.", "partial": ["Android 앱에는 난독화 및 루팅 탐지가 적용되어 있으나 iOS 앱에는 일부 통제(예: 탈옥 탐지)가 누락되어 있습니까?", "루팅 탐지 시 경고 문구만 출력되고 앱이 강제 종료되지 않아 우회 접속이 가능한 상태입니까?", "누락된 OS 채널에 대한 앱 보안 솔루션 적용 및 즉시 종료 로직 보완 계획은 무엇입니까?"], "partialEnd": "OS 채널 간 보안 통제 불균형 및 단순 경고 처리 등 경계성 결함을 부분이행으로 기록하고 강제 종료 및 솔루션 확대를 요구합니다.", "rootcause": ["모바일 앱에 난독화, 위변조 방지, 루팅 탐지 등 필수 앱 보안 솔루션을 적용하지 않고 앱을 배포한 원인은 무엇입니까?", "앱 위변조로 인한 금융 사기(가짜 앱, 악성 앱) 위험에 대해 모바일 앱 보안 검수를 수행하지 않은 경위는 무엇입니까?", "보안 솔루션 미적용 상태에서 모바일 금융 서비스를 제공한 조치에 대해 경영진에 보고되었습니까?"], "rootcauseEnd": "전자금융감독규정 §15 및 앱 보안 지침 위반으로 결함 판정하며, 앱 보안 솔루션 적용 및 즉시 업데이트 배포를 명합니다.", "na": ["저축은행에서 모바일 앱(Android/iOS)을 전혀 제공하지 않으며, 오직 PC/모바일 웹 브라우저 기반 서비스만 운영합니까?"], "naEnd": "모바일 앱 서비스를 운용하지 않음을 확인하여 해당없음 처리합니다."}, "23-9": {"decisionQ": "정적 분석(SAST) 고위험 취약점이 해결 상태인지, 배포 전 동적 분석(DAST)이 수행되고 고위험 미해결 시 배포가 자동 차단되고 있습니까?", "verify": ["최근 운영 환경 배포 건에 대해 정적 분석(SAST) 도구(Fortify, SonarQube 등)에서 출력된 '고위험(Critical/High) 취약점 잔여 현황'을 보여주시겠습니까?", "배포 전 동적 분석(DAST) 수행 결과 보고서 및 DAST에서 발굴된 취약점 조치 이력서를 확인해 주시겠습니까?", "형상관리/CI-CD 파이프라인(Jenkins 등) 상에서 SAST/DAST 고위험 취약점이 미해결 상태일 때 배포를 자동으로 빌드 차단(Block)하는 정책 설정을 보여주시겠습니까?", "고위험 취약점에도 불구하고 예외적으로 배포해야 했던 건에 대해 CISO의 '위험 수용 결재 문서'가 존재하는지 확인해 주시겠습니까?"], "verifyEnd": "SAST/DAST 점검 수행, 고위험 취약점 완비 조치, 빌드 파이프라인 상의 배포 차단 정책이 확인되어 양호로 판정합니다.", "partial": ["SAST(정적 분석)는 매 배포마다 수행하나 DAST(동적 분석)는 정기적으로 수행하지 않고 연 1~2회에 그치고 있습니까?", "고위험 취약점이 남아 있음에도 예외 배포 절차(CISO 승인) 없이 개발팀 판단하에 배포된 건이 포함되어 있습니까?", "DAST 수행 체계 수립 및 고위험 미해결 건 배포 차단 통제를 강화하기 위한 일정은 언제입니까?"], "partialEnd": "DAST 주기 미흡 및 예외 배포 승인 절차 결미를 부분이행으로 기록하고 즉시 CI/CD 파이프라인 통제 강화를 요청합니다.", "rootcause": ["소스코드 보안약점 진단(SAST) 및 동적 분석(DAST)을 운영 배포 전 수행하지 않는 원인은 무엇입니까?", "SAST/DAST 도구에서 고위험 취약점이 다수 발견되었음에도 조치하지 않고 운영 환경에 지속 배포한 이유는 무엇입니까?", "보안 약점 진단 결과를 개발팀이 인지하지 못하거나 조치 이행 여부를 점검하는 보안 주관 부서의 검수 절차가 부재한 이유는 무엇입니까?"], "rootcauseEnd": "프로그램 통제 지침 위반 및 고위험 보안약점 운영 환경 유입으로 결함 판정하며, 미조치 고위험 항목 즉시 수정 및 DAST 필수화를 명합니다.", "na": ["자체 개발이나 소스코드 변경이 전혀 없는 단순 패키지 도입 형태이며, 소스코드 접근 및 빌드 권한이 전혀 없는 외부 완제품 서비스입니까?"], "naEnd": "자체 소스코드 변경이 불가능한 외부 완제품 서비스임을 확인하여 해당없음 처리합니다."}, "23-10": {"decisionQ": "홈페이지·앱에 사용된 오픈소스 구성요소 목록(SBOM)을 관리 중이며, CVE 취약점 모니터링 및 패치 SLA(30일)를 준수하고 있습니까?", "verify": ["홈페이지 및 모바일 앱 서비스에 포함된 오픈소스 라이브러리 목록(SBOM : 소프트웨어 자재명세서 - 라이브러리명, 버전, 라이선스) 문서나 도구를 보여주시겠습니까?", "CVE 및 KrCERT 등의 취약점 DB와 연동하여 사용 중인 오픈소스의 신규 취약점을 자동/수동으로 모니터링하는 현황을 보여주시겠습니까?", "최근 1년 이내 고위험 CVE(CVSS 7.0 이상)가 발표된 오픈소스 라이브러리에 대해 30일 이내 패치/업그레이드를 완료한 이력 로그를 보여주시겠습니까?", "개발이 중단되거나(Deprecated) 보안 지원이 종료된 오픈소스 라이브러리를 서비스에서 제거하거나 대체한 이력을 확인해 주시겠습니까?"], "verifyEnd": "SBOM 작성 관리, CVE 정기 모니터링, 취약 오픈소스 30일 내 패치 SLA 준수, 단종 라이브러리 정리가 입증되어 양호로 판정합니다.", "partial": ["SBOM 목록은 보유하고 있으나 수동으로 관리되어 최근 추가된 일부 라이브러리의 버전 정보가 누락되어 있습니까?", "CVE 모니터링은 수행하나 패치 조치 기간이 SLA 30일을 초과하여(예: 60일 이상) 이행된 사례가 존재합니까?", "SBOM 관리 자동화 도구 도입 및 패치 SLA 엄수를 위한 프로세스 개선 계획은 무엇입니까?"], "partialEnd": "SBOM 현황 최신화 누락 및 패치 SLA 지연을 부분이행으로 기록하고 오픈소스 관리 체계 정비를 촉구합니다.", "rootcause": ["사용 중인 오픈소스 라이브러리 목록(SBOM) 자체가 전혀 작성되거나 관리되지 않는 원인은 무엇입니까?", "알려진 고위험 CVE 취약점이 존재하는 오픈소스를 패치하지 않고 오랫동안 운영 시스템에 방치한 이유는 무엇입니까?", "오픈소스 구성요소의 공급망 보안 위협에 대한 점검 가이드 및 담당자 지정이 부재한 경위는 무엇입니까?"], "rootcauseEnd": "오픈소스 공급망 보안 관리 미흡으로 결함(미흡) 판정하며, SBOM 전수 조사 작성 및 취약 라이브러리 긴급 패치를 요청합니다.", "na": ["홈페이지 및 앱 개발에 오픈소스 라이브러리를 전혀 사용하지 않으며, 100% 자체 개발 코드 또는 프레임워크로만 구성되어 있습니까? (실제 입증 필요)"], "naEnd": "오픈소스 라이브러리를 일절 사용하지 않는 서비스임을 확인하여 해당없음 처리합니다."}, "23-11": {"decisionQ": "외부 JS 및 SDK(광고/분석 등) 목록을 관리 중이며, 정기 취약점 점검(반기 1회) 및 공급망 변조(CDN 탈취) 대응 방안이 수립되어 있습니까?", "verify": ["홈페이지 및 앱에 삽입된 제3자(Third-party) 외부 스크립트 및 SDK 전체 목록 현황을 보여주시겠습니까?", "외부 스크립트에 대해 반기 1회 이상 정기적으로 수행한 취약점 점검 결과 보고서 및 미사용/단종 스크립트 제거 이력을 보여주시겠습니까?", "외부 CDN을 통해 로딩되는 스크립트의 위변조 방지를 위해 SRI(Subresource Integrity - hash 검증) 속성을 적용한 소스코드를 보여주시겠습니까?", "외부 스크립트 제공업체 변경이나 공급망 공격 발생 시 실시간으로 스크립트 호출을 차단할 수 있는 비상 대응 절차서를 확인해 주시겠습니까?"], "verifyEnd": "제3자 스크립트/SDK 목록화, 반기 점검 이행, SRI 적용 등 공급망 위변조 방지 통제가 입증되어 양호로 판정합니다.", "partial": ["외부 스크립트 목록은 관리되고 있으나, 정기 점검 주기가 반기 1회를 초과하여 연 1회 수준으로 지연되었습니까?", "외부 스크립트는 사용 중이나 SRI(서브리소스 무결성) 검증 속성이 일부 중요 페이지(로그인/금융거래 등)에서 누락되어 있습니까?", "외부 스크립트 보안 점검 주기를 준수하고 SRI 적용 범위를 확대하기 위한 개선 계획은 무엇입니까?"], "partialEnd": "점검 주기 지연 및 SRI 속성 일부 누락을 부분이행으로 기록하고 보안 강화 조치를 권고합니다.", "rootcause": ["홈페이지에 삽입된 외부 광고/분석 스크립트 현황을 파악조차 하지 못하고 방치한 원인은 무엇입니까?", "제3자 외부 스크립트 변조(Magecart 등 웹 스키밍 공격)로 인한 이용자 개인정보/금융정보 유출 위험 대책을 수립하지 않은 경위는 무엇입니까?", "미사용되거나 단종된 제3자 SDK를 제거하지 않고 소스코드에 남겨둔 이유는 무엇입니까?"], "rootcauseEnd": "제3자 스크립트 관리 미흡 및 공급망 보안 무방비 상태로 결함(미흡) 판정하며, 제3자 스크립트 전수 점검 및 미사용 스크립트 즉시 제거를 명합니다.", "na": ["홈페이지 및 모바일 앱에 제3자(Third-party) 외부 JS, SDK, 외부 분석 도구를 일절 사용하지 않으며, 100% 자체 내부 자원만 호출합니까?"], "naEnd": "제3자 외부 스크립트 및 SDK를 전혀 사용하지 않는 순수 자체 서비스임을 확인하여 해당없음 처리합니다."}, "22-1": {"decisionQ": "클라우드 서비스 도입 전 금감원 사전 신고·승인 절차, 내부 IT운영위원회 의사결정, 그리고 위험평가를 모두 이행하고 현황을 관리하고 계십니까?", "verify": ["현재 운영 중인 클라우드 서비스 목록에서 가장 최근 도입된 서비스의 금감원 사전 신고 접수증 또는 승인 공문을 지금 화면으로 보여주시겠습니까?", "해당 클라우드 도입 건에 대한 IT운영위원회(또는 최고 의사결정기구) 회의록 및 위험평가 결과보고서를 함께 제시해 주시겠습니까?", "클라우드 서비스 이용 현황 관리 대장의 최신 업데이트 날짜와 실제 콘솔상 운영 중인 리소스 목록이 일치하는지 재확인해 주시겠습니까?"], "verifyEnd": "금감원 신고·승인 공문, 내부 의사결정 회의록, 위험평가서가 모두 확인되고, 클라우드 이용 현황 목록이 실제 콘솔 리소스와 일치하면 양호로 확정합니다.", "partial": ["내부 위험평가나 IT운영위원회 승인은 거쳤으나, 금감원 사전 신고 절차가 누락되거나 지연된 사유가 있습니까?", "클라우드 이용 현황 대장에 일부 테스트용/개발용 클라우드 리소스가 누락되어 있는 이유는 무엇입니까?", "미비된 신고 절차나 현황 대장 최신화 계획은 언제까지 완료할 예정입니까?"], "partialEnd": "일부 절차 누락 또는 현황 관리 불일치가 확인되었으므로 개선계획 작성을 요청하고 조치 기한을 부여합니다.", "rootcause": ["금감원 사전 신고·승인 없이 클라우드 서비스를 운용하게 된 경위와 의사결정 주체는 누구입니까?", "사전 위험평가 절차를 거치지 않고 실운영 환경에 반영된 사유는 무엇입니까?", "이러한 승인 절차 회피를 방지하기 위한 통제 장치가 내부 규정에 부재했던 것입니까?"], "rootcauseEnd": "전자금융감독규정 및 금융분야 클라우드 가이드 위반으로 결함 확정하며, 서면 개선계획서 및 관련자 경위서 제출을 요구합니다.", "na": ["당 저축은행에서 온프레미스 외에 외부 클라우드 서비스(IaaS, PaaS, SaaS 포함)를 일절 이용하지 않고 계신 것이 맞습니까?", "SaaS 형태의 외부 업무용 소프트웨어(예: 그룹웨어, 전자결재, 보안 S/W 등)도 전혀 사용하지 않는지 재확인해 주시겠습니까?"], "naEnd": "클라우드 서비스 이용 사실이 완전히 없음이 증명되면 N/A로 판정합니다."}, "22-2": {"decisionQ": "도입된 CSP에 대한 안전성 평가 및 정기 재평가(연 1회 이상)를 수립된 기준과 금융보안원 평가 결과를 반영하여 이행하고 계십니까?", "verify": ["현재 이용 중인 CSP의 보안 인증서(ISO 27001, SOC2 등)와 금융보안원 CSP 안전성 평가 보고서 활용 내역을 보여주시겠습니까?", "당 저축은행에서 수립한 'CSP 보안 평가 기준'과 이에 따라 실시한 최근 1년 이내의 정기 재평가 결과보고서를 제시해 주시겠습니까?", "평가 결과 지적된 보안 취약점이나 개선 요구사항에 대해 CSP 측에 이행을 요청하고 확인한 이력 화면을 보여주시겠습니까?"], "verifyEnd": "CSP에 대한 평가 기준, 금융보안원 결과 반영, 최근 1년 이내 정기 재평가서 및 조치 이력이 입증되면 양호로 확정합니다.", "partial": ["최초 선정 시에만 안전성 평가를 수행하고, 연 1회 정기 재평가가 지연되거나 누락된 사유는 무엇입니까?", "금융보안원 CSP 안전성 평가 결과를 확인했으나, 당행 자체 추가 평가 기준 적용이 미흡했던 이유는 무엇입니까?", "지연된 정기 재평가를 언제까지 완료하여 보고서를 제출하시겠습니까?"], "partialEnd": "정기 재평가 주기 준수 미흡 등에 대해 개선 권고 조치를 내리고 재평가 완료 결과를 제출받도록 합니다.", "rootcause": ["CSP에 대한 보안 평가 기준 자체가 없거나, 금융보안원/자체 안전성 평가를 전혀 거치지 않고 계약을 체결한 경위는 무엇입니까?", "CSP 보안 평가를 수행하지 않아 발생할 수 있는 공급망 보안 위험을 어떻게 관리하려 했습니까?"], "rootcauseEnd": "금융분야 클라우드 가이드 위반으로 결정적 결함으로 확정하고 즉시 안전성 평가 수행을 지시합니다.", "na": ["클라우드 서비스(IaaS, PaaS, SaaS)를 전혀 이용하지 않아 평가 대상 CSP가 존재하지 않는 것이 맞습니까?"], "naEnd": "클라우드 서비스 이용 사실이 없어 평가 대상 CSP가 없음이 확인되면 N/A로 처리합니다."}, "22-3": {"decisionQ": "클라우드 서비스 유형별 책임 분담 모델을 명확히 정의하고, 보안 요구사항·장애 대응·개인정보 위탁 계약이 포함된 SLA를 적정하게 관리하고 계십니까?", "verify": ["이용 중인 클라우드 서비스(IaaS/PaaS/SaaS)별 '책임 분담 모델(Shared Responsibility Model)' 정의 문서를 보여주시겠습니까?", "CSP와 체결한 SLA 계약서 내에 보안 요구사항, 장애 시 침해사고 통지 시한, 보상 기준이 명시되어 있는지 해당 조항을 화면으로 보여주시겠습니까?", "개인정보 처리 업무가 포함된 경우, 개인정보보호법 제26조에 따른 '개인정보 처리위탁 계약서' 및 관리·감독 점검 이력을 제시해 주시겠습니까?", "최근 6개월간 SLA 이행 현황 모니터링 보고서 및 SLA 미달 시 조치 이력을 보여주시겠습니까?"], "verifyEnd": "책임 분담 모델 명시, SLA 계약 내 보안/장애 조항 확보, 개인정보 위탁계약 체결 및 SLA 모니터링 이력이 모두 확인되면 양호로 확정합니다.", "partial": ["SLA 계약은 체결되어 있으나, 장애 발생 시 통지 시간이나 보안 침해 대응에 대한 구체적 기준이 누락된 사유는 무엇입니까?", "개인정보 위탁 계약은 체결했으나, 연간 관리·감독 점검 이력이 미비한 이유는 무엇입니까?", "누락된 SLA 항목 재계약 및 관리감독 점검 이행 계획을 제시해 주시겠습니까?"], "partialEnd": "계약서상 보완 조치 및 관리감독 이행을 보완하도록 조치 요구합니다.", "rootcause": ["클라우드 계약 시 표준 SLA를 그대로 수용하고 당행 보안 요구사항이나 개인정보 위탁 조항을 누락한 경위는 무엇입니까?", "책임 분담 모델을 정의하지 않아 클라우드 장애/보안 사고 발생 시 책임 소재가 불명확한 상태로 운영된 사유는 무엇입니까?"], "rootcauseEnd": "계약 및 위험관리 미흡으로 결함 확정하며 계약 조항 변경 및 보완을 요구합니다.", "na": ["외부 클라우드 서비스 이용이 전혀 없어 SLA 및 위탁 계약 체결 대상이 아닌 것이 맞습니까?"], "naEnd": "클라우드 서비스 미이용이 입증되면 N/A로 판정합니다."}, "22-4": {"decisionQ": "클라우드 IAM에 최소 권한 원칙을 적용하고, 관리자 계정에 MFA를 강제화하며, 권한을 주기적(분기 1회 이상)으로 검토·회수하고 계십니까?", "verify": ["클라우드 관리 콘솔(AWS, Azure, NCP 등)에 최고관리자 및 운영자 계정 로그인 시 MFA(다중인증) 설정이 활성화된 화면을 실시간으로 보여주시겠습니까?", "클라우드 IAM 사용자/역할(Role) 목록 및 부여된 정책(Policy) 화면에서 최소 권한(AdministratorAccess 과도 부여 여부) 적용 상태를 보여주시겠습니까?", "가장 최근 수행한 '클라우드 IAM 권한 주기적 정기 검토(최근 분기)' 결재 문서와 불필요 계정/과도 권한 회수 이력 대장을 보여주시겠습니까?", "원격에서 클라우드 관리 콘솔 또는 리소스에 접근할 때 상급자/정보보안담당자 사전 승인을 받은 신청서 및 접속 로그를 대조해 주시겠습니까?"], "verifyEnd": "관리자 MFA 적용, 최소 권한 설정, 분기별 권한 검토 및 회수 이력, 원격접속 승인 절차가 실시간 화면 및 증빙으로 확인되면 양호로 확정합니다.", "partial": ["일부 관리자 계정이나 개발 환경 콘솔에 MFA가 적용되어 있지 않은 사유는 무엇입니까?", "권한 검토는 수행하고 있으나 주기(분기 1회)를 초과하여 반기/연간 단위로 지연되어 진행된 이유는 무엇입니까?", "MFA 미설정 계정에 대한 즉시 조치 및 분기별 권한 검토 수립 계획을 제시해 주시겠습니까?"], "partialEnd": "미설정 계정 즉시 차단/MFA 강제 적용 및 검토 주기 준수를 조건으로 개선 조치를 요구합니다.", "rootcause": ["관리자 계정에 MFA를 적용하지 않거나 root/admin 계정을 공용으로 공유하여 사용해 온 경위는 무엇입니까?", "퇴직자 또는 직무 이동자의 클라우드 IAM 계정이 즉시 삭제/권한 회수되지 않고 방치된 이유는 무엇입니까?"], "rootcauseEnd": "접근통제 및 IAM 보안 관리 심각한 미흡으로 결함 확정하며 계정 일제 정비 및 권한 회수를 지시합니다.", "na": ["클라우드 인프라 및 SaaS 관리를 일절 수행하지 않는 환경입니까?"], "naEnd": "클라우드 계정이 존재하지 않음이 확인되면 N/A 처리합니다."}, "22-5": {"decisionQ": "클라우드 내 저장·전송 데이터를 암호화하고, 암호키를 CSP와 분리하여 안전하게 관리하며 데이터 위치를 통제하고 계십니까?", "verify": ["클라우드 스토리지(S3, Blob 등) 및 DB의 저장 데이터(At-Rest) 암호화 설정 화면(KMS/KMS 고객위임키 적용 등)을 실시간으로 보여주시겠습니까?", "클라우드 웹 서비스 및 API 통신 설정에서 TLS 1.2 이상 버전만 허용되고 비암호화 통신(HTTP)이 차단된 설정 화면을 보여주시겠습니까?", "클라우드 암호 키 관리 서비스(KMS) 설정에서 암호 키 생명주기 통제 및 CSP 외부 분리/고객 관리 키(CMAK/BYOK) 적용 현황을 제시해 주시겠습니까?", "당 저축은행 데이터가 저장·복제되는 클라우드 리전(Region) 및 데이터센터의 물리적 위치 관리 현황표를 보여주시겠습니까?"], "verifyEnd": "저장/전송 암호화 적용(TLS 1.2↑), 암호키 분리/독자 관리, 국내 리전 등 데이터 위치 통제 현황이 확인되면 양호로 확정합니다.", "partial": ["저장 데이터 암호화는 적용되어 있으나 일부 백업 데이터나 로그 스토리지의 암호화 설정이 누락된 이유는 무엇입니까?", "TLS 1.0/1.1 등 구버전 프로토콜이 일부 레거시 연동을 위해 예외적으로 허용되어 있는 사유와 향후 개선 계획은 무엇입니까?", "암호화 누락 항목에 대한 즉시 설정 반영 계획을 제시해 주시겠습니까?"], "partialEnd": "암호화 미적용 영역 및 TLS 구버전 허용에 대해 즉시 시정 조치를 요구합니다.", "rootcause": ["클라우드 내 고객 개인정보 또는 중요 데이터가 평문으로 저장되거나 통신 과정에서 암호화되지 않은 경위는 무엇입니까?", "암호 키 관리 주체를 CSP에게 전적으로 위임하여 키 통제권을 확보하지 못한 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 및 개인정보보호법 위반으로 심각한 결함으로 확정하며 중대 시정 요구를 발송합니다.", "na": ["클라우드 환경에 데이터를 전혀 저장하지 않고, 단순히 통과형 처리만 수행하거나 클라우드를 이용하지 않는 것이 맞습니까?"], "naEnd": "클라우드 데이터 저장 및 전송이 없음이 확인되면 N/A로 처리합니다."}, "22-6": {"decisionQ": "클라우드 VPC 및 서브넷을 용도별로 분리하고, 보안그룹/방화벽에 최소 허용 원칙을 적용하며 최신 구성도를 유지하고 계십니까?", "verify": ["클라우드 VPC/서브넷 설정 화면에서 DMZ, Private(WAS/DB), 관리망 간의 네트워크 분리 구성 상태를 보여주시겠습니까?", "보안그룹(Security Group) 및 Network ACL 설정에서 Any Open(`0.0.0.0/0`) 설정이 존재하는지 검색/조회 화면을 보여주시겠습니까?", "클라우드 외부 노출 서비스(Public IP 보유 리소스)에 대한 불필요 포트(예: 22, 3389, 8080 등) 차단 및 주기적 점검 결과를 보여주시겠습니까?", "현재 최신화된 '클라우드 네트워크 구성도'를 제시하고, 실제 콘솔의 Routing Table 및 Peering 설정과 일치하는지 대조해 주시겠습니까?"], "verifyEnd": "VPC 망분리, 보안그룹 내 Any open 제거, 불필요 포트 차단, 최신 네트워크 구성도 일치가 확인되면 양호로 확정합니다.", "partial": ["개발/테스트 VPC 내 일부 보안그룹에 22/3389 포트 Any open(`0.0.0.0/0`) 설정이 일시적으로 남아있는 사유는 무엇입니까?", "네트워크 구성도에 최근 추가된 서브넷이나 VPC Peering 변경 사항이 즉시 반영되지 않고 지연된 이유는 무엇입니까?", "지적된 보안그룹 즉시 삭제 및 구성도 최신화 완료 계획을 제시해 주시겠습니까?"], "partialEnd": "과도하게 허용된 보안그룹 룰 즉시 삭제 조치 및 네트워크 구성도 최신화를 조건으로 권고합니다.", "rootcause": ["실운영 클라우드 환경의 보안그룹에 `0.0.0.0/0` 전체 허용 룰을 상시 설정하여 운용한 경위는 무엇입니까?", "DMZ망과 내부 DB망 간 직접 통신을 허용하거나 네트워크 분리 없이 단일 서브넷에 혼재시킨 사유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 망분리 및 네트워크 통제 위반으로 결함 확정하며 네트워크 전면 재설정을 요구합니다.", "na": ["IaaS/PaaS 등 네트워크(VPC/보안그룹)를 직접 구성하고 통제할 수 있는 클라우드 서비스를 이용하지 않는 것이 맞습니까?"], "naEnd": "네트워크 구성 통제 권한이 없는 단순 SaaS만 이용 시 N/A 처리합니다."}, "22-7": {"decisionQ": "클라우드 내 보안 이벤트 로그를 수집·보존하고, CSPM·SIEM 등을 활용하여 이상행위를 모니터링하며 경보 발생 시 정해진 절차대로 대응하고 계십니까?", "verify": ["클라우드 보안 로그(CloudTrail, VPC Flow Logs, GuardDuty 등) 수집 활성화 설정 화면 및 로그 보존 기간(1년 이상) 설정 상태를 보여주시겠습니까?", "CSPM(클라우드 보안 포스처 관리) 또는 SIEM 솔루션을 통해 취약한 설정, 비인가 접근 등 이상행위를 탐지하고 있는 실시간 모니터링 대시보드를 보여주시겠습니까?", "최근 6개월간 발생한 클라우드 보안 경보(Alert) 이력 대장과 이에 따른 보안 담당자의 실제 조사 및 조치 결과 보고서를 보여주시겠습니까?", "CSPM을 통해 수행한 최근 클라우드 컴플라이언스/취약 설정 점검 결과 및 미흡 항목에 대한 시정 이력을 제시해 주시겠습니까?"], "verifyEnd": "로그 수집/보존(1년↑), 이상행위 탐지 체계(CSPM/SIEM) 가동, 경보 대응 이력 및 CSPM 점검 실적이 확인되면 양호로 확정합니다.", "partial": ["클라우드 로그 수집은 되고 있으나, 일부 리전이나 신규 생성된 계정의 로그 수집이 비활성화되어 있는 이유는 무엇입니까?", "로그 보존 기간이 내부 규정(1년 이상)에 미달(예: 3개월/6개월)하게 설정된 사유와 개선 계획은 무엇입니까?", "CSPM 점검 결과 지적된 취약 설정에 대해 이행 조치가 지연되고 있는 사유를 설명해 주시겠습니까?"], "partialEnd": "로그 보존기간 연장 및 미수집 계정 즉시 설정, CSPM 지적사항 조치를 이행토록 요구합니다.", "rootcause": ["CloudTrail 등 클라우드 감사 로그 수집 기능 자체가 비활성화되어 있어 이상행위 추적이 불가능한 상태로 운용한 경위는 무엇입니까?", "보안 경보가 발생했음에도 담당자가 이를 인지하지 못하거나 조치 없이 방치한 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 로그 및 모니터링 의무 위반으로 결함 확정하며 로그 수집 강제화 및 대응 체계 재정비를 지시합니다.", "na": ["로그 수집 및 이상행위 모니터링 통제 권한이 전혀 없는 외부 SaaS 서비스만 단순 이용하는 경우입니까?"], "naEnd": "모니터링 대상 인프라/로그가 없는 구조임이 증명되면 N/A로 처리합니다."}, "22-8": {"decisionQ": "클라우드 인프라·컨테이너·오픈소스에 대한 취약점 점검을 정기적으로(반기 1회 이상) 실시하고, 보안 패치적용 및 결과를 경영진에 보고하고 계십니까?", "verify": ["최근 1년 이내(반기 1회 이상) 수행한 '클라우드 인프라 및 컨테이너/이미지 취약점 점검 결과 보고서'를 보여주시겠습니까?", "클라우드 서버(VM) 및 컨테이너 이미지 보안 패치 절차서와 최근 수행한 패치 적용 수행 이력 대장을 보여주시겠습니까?", "클라우드 애플리케이션에서 사용 중인 오픈소스 라이브러리 취약점(SCA 점검 등) 관리 현황 및 조치 내역을 보여주시겠습니까?", "취약점 점검 및 패치 결과가 포함된 IT운영위원회 또는 CISO/경영진 보고서 결재 문서를 보여주시겠습니까?"], "verifyEnd": "반기 1회 이상 취약점 점검, 패치 및 오픈소스 관리 이력, 경영진 보고서 결재가 모두 입증되면 양호로 확정합니다.", "partial": ["취약점 점검은 실시했으나, 발굴된 고위험 취약점에 대한 패치 적용이 지정된 기한을 초과하여 지연된 이유는 무엇입니까?", "VM 인프라 점검은 이루어졌으나, 컨테이너 이미지나 오픈소스 라이브러리에 대한 취약점 점검이 누락된 사유는 무엇입니까?", "미조치된 고위험 취약점에 대한 패치 적용 완료 예정일 및 보고 계획을 제시해 주시겠습니까?"], "partialEnd": "지연된 고위험 취약점 패치 조치를 즉시 지시하고 개선 결과를 제출받도록 합니다.", "rootcause": ["클라우드 환경에 대한 취약점 점검을 최근 1년간 단 한 번도 수행하지 않고 방치한 경위는 무엇입니까?", "심각한 보안 취약점(CVE High/Critical)이 보고되었음에도 이를 패치하지 않고 실운영 환경에 상시 노출시킨 사유는 무엇입니까?"], "rootcauseEnd": "보안 패치 및 취약점 관리 소홀로 결함 확정하며 즉시 긴급 점검 및 패치 적용을 명령합니다.", "na": ["인프라, 컨테이너, OS 패치 관리 권한이 전혀 없는 완전 관리형 SaaS만을 이용하는 환경입니까?"], "naEnd": "패치 및 취약점 점검 대상 인프라가 존재하지 않음이 확인되면 N/A로 처리합니다."}, "22-9": {"decisionQ": "클라우드 서비스에 대한 RTO·RPO 목표를 설정하여 SLA에 반영하고, 재해복구 절차 수립, 백업 이행, 연간 복구훈련을 수행하고 계십니까?", "verify": ["클라우드 업무별 RTO(복구목표시간)·RPO(복구시점목표)가 정의된 BCP 규정 및 CSP SLA 반영 문서를 보여주시겠습니까?", "클라우드 장애 및 재해 발생 시 대응하기 위한 '클라우드 재해복구(DR) 절차서' 및 대체 수단 운영 가이드를 제시해 주시겠습니까?", "클라우드 백업 정책(자동 백업 주기, 보존 기간) 설정 화면 및 최근 백업 데이터 복구 테스트 이력 대장을 보여주시겠습니까?", "최근 1년 이내 실시한 '클라우드 재해복구(DR) 훈련 결과 보고서'와 IT운영위원회/경영진 보고 문서를 제시해 주시겠습니까?"], "verifyEnd": "RTO/RPO 설정, DR 절차서, 백업/복구 테스트 이력, 연간 DR 훈련 보고서가 모두 입증되면 양호로 확정합니다.", "partial": ["백업은 정상 수행 중이나 백업 데이터에 대한 실제 복구 테스트(Data Restore Test)를 수행하지 않은 사유는 무엇입니까?", "DR 훈련은 실시했으나 온프레미스만 대상에 포함되고 클라우드 시스템이 일부 누락된 사유와 향후 개선 대책은 무엇입니까?", "누락된 클라우드 DR 훈련 계획 및 복구 테스트 수립 일정을 제시해 주시겠습니까?"], "partialEnd": "클라우드 대상 백업 복구 테스트 및 DR 훈련 범위 확대를 조건으로 개선 조치를 요구합니다.", "rootcause": ["클라우드 시스템에 대한 백업 정책이 미수정되거나 DR 비상대책 자체가 수립되지 않은 경위는 무엇입니까?", "연간 재해복구 훈련을 실시하지 않아 장애 발생 시 서비스 불능 위험을 방치한 사유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 및 비상대책 가이드라인 위반으로 결함 확정하며 DR 체계 재정비를 명령합니다.", "na": ["저축은행의 업무에 영향이 전혀 없는 단순 열람용 서비스이며 비상대책 적용 대상이 아닌 클라우드 서비스입니까?"], "naEnd": "업무 연계성이 없는 경미한 클라우드 이용으로 비상대책 대상 제외가 타당할 경우 N/A 처리합니다."}, "22-10": {"decisionQ": "클라우드 이용 종료 시 데이터 회수 및 완전 파기 절차를 수립하고, CSP 잔여 데이터 파기 확인서 수급 및 이력을 관리하고 계십니까?", "verify": ["클라우드 서비스 계약 해지 또는 종료 시 적용되는 '클라우드 데이터 회수 및 파기 절차서'를 보여주시겠습니까?", "최근 이용 종료된 클라우드 서비스(SaaS 또는 IaaS 테넌트 해지 등)가 있다면, 해당 CSP로부터 수급한 '잔여 데이터 파기 확인서'를 제시해 주시겠습니까?", "CSP 계약서 내 서비스 종료 후 데이터 회수 기간 및 이전을 지원하는 SLA 조항을 화면으로 명시해 주시겠습니까?", "클라우드 데이터 파기 관리 대장에 파기 일자, 담당자, 파기 방법이 적정하게 기록되어 있는지 보여주시겠습니까?"], "verifyEnd": "종료 절차서, SLA 내 회수 조항, 잔여 데이터 파기 확인서 및 파기 대장 기록이 입증되면 양호로 확정합니다.", "partial": ["계약 종료 후 데이터 회수는 완료했으나, CSP로부터 잔여 데이터(백업 포함) 파기 확인서를 수급하지 못하고 지연된 사유는 무엇입니까?", "데이터 파기 대장 기록이 일부 누락되거나 최신화되지 않은 사유 및 즉시 보완 계획은 무엇입니까?", "CSP 측에 잔여 데이터 완전 파기 확약서를 언제까지 제출받아 보고하시겠습니까?"], "partialEnd": "CSP 잔여 데이터 파기 확인서 제출 조치 요구 및 대장 작성을 지시합니다.", "rootcause": ["클라우드 이용 종료 후 데이터 회수 절차 없이 사업을 중단하거나 잔여 데이터를 CSP 서버에 방치한 경위는 무엇입니까?", "개인정보보호법에 따른 데이터 파기 의무를 이행하지 않고 파기 이력을 관리하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 및 금융 가이드 위반으로 결함 확정하며 잔여 데이터 완전 파기 및 확인서 제출을 강제합니다.", "na": ["저축은행 창립 이래 계약 종료, 해지, 이관된 클라우드 서비스가 전혀 없고 현재 이용 중인 서비스만 존재하는 경우입니까?"], "naEnd": "서비스 종료 사례가 단 한 건도 없음이 확인될 경우 '종료 절차 수립 여부'만 검토 후 파기 실적 부분은 N/A로 처리합니다."}, "21-1": {"decisionQ": "당행의 AI 서비스 도입 및 운영과 관련된 정보보호 관리체계 문서와 CISO 지정 결재문서, 최근 경영진 보고 실적을 현장에서 제시해 주시겠습니까?", "verify": ["AI 정보보호 관리체계 및 보안 정책에 CISO 및 최고경영진(CEO/이사회) 결재가 반영된 원본 문서를 보여주시겠습니까?", "CISO의 관장 업무 범위에 'AI 보안'이 명시적으로 포함된 업무분장서 또는 지정 문서 결재건을 보여주시겠습니까?", "최근 1년 이내 AI 보안 정책 제·개정 시 관련 법률 및 가이드라인(금융분야 AI 보안 가이드라인 등)을 검토한 이사회 또는 정보보호위원회 보고 안건을 조회해 주시겠습니까?", "금년도 AI 보안 예산 및 전담/겸임 인력 배정 현황이 포함된 예산 확정 문서를 보여주시겠습니까?"], "verifyEnd": "경영진 승인 정책, CISO의 AI 보안 관장 권한, 최신 가이드라인 반영 보고서 및 예산/인력 배정 증빙이 모두 확인되면 양호로 확정합니다.", "partial": ["CISO 지정 문서는 존재하나 AI 보안 관련 정책 규정이 명확히 수립되지 않았거나 결재가 누락된 이유는 무엇입니까?", "경영진 보고는 이루어졌으나 AI 관련 예산 및 인력 지원이 구체적으로 확정되지 않은 이유는 무엇입니까?", "개선 계획이 수립되어 있다면 언제까지 정책 수립 및 예산 확보를 완료할 예정입니까?"], "partialEnd": "정책 미비 또는 예산/인력 미확보 등 부분 미흡 사항에 대해 정식 개선계획서를 제출받고 차기 점검 시 재확인합니다.", "rootcause": ["AI 보안 관련 거버넌스 규정이나 책임자 지정이 전혀 이루어지지 않은 경위는 무엇입니까?", "AI 서비스 도입 시 기존 IT보안 정책만을 적용하고 AI 특화 위험을 고려하지 않은 이유는 무엇입니까?", "이 문제를 인지하고도 경영진에 보고하지 않은 이유나 이사회/CEO보고가 차단된 내부 사유가 있습니까?"], "rootcauseEnd": "AI 보안 거버넌스 부재로 결함 확정하며, CISO 및 경영진 보고를 통한 종합 개선 대책 마련을 서면 요구합니다.", "na": ["당행에서 내부 업무용 포함 AI 서비스(생성형 AI, ML 모델, 외부 AI API 등)를 전혀 도입하거나 활용하지 않고 있습니까?", "향후 1년 이내 AI 관련 시스템 도입 계획이나 PoC 진행 계획이 완전히 부재함을 증명할 사업계획서 조회가 가능합니까?"], "naEnd": "AI 미도입 및 도입 계획 없음이 확인되면 해당없음으로 판정합니다."}, "21-2": {"decisionQ": "AI 핵심자산(학습데이터·모델·API 등) 관리대장과 연 1회 이상 실시한 AI 위험평가 결과 보고서를 시스템에서 직접 제시해 주시겠습니까?", "verify": ["등록된 AI 자산목록(학습데이터, 알고리즘, 모델, 연동 API)의 최신 갱신 일자와 실물 보유 현황을 대조해 주시겠습니까?", "AI 특화 위협(모델 오염, 적대적 공격, 데이터 유출 등) 평가 항목이 포함된 위험평가 방법론 문서 및 결과 보고서를 보여주시겠습니까?", "위험평가 결과 도출된 위험 개선과제의 보호대책 이행계획서 및 조치 완료 증빙을 보여주시겠습니까?", "해당 위험평가 결과가 CISO 및 경영진에게 보고된 결재 문서 원본을 조회해 주시겠습니까?"], "verifyEnd": "AI 자산 식별, AI 특화 위험평가 연 1회 이행, 보호대책 이행 완료 및 경영진 보고가 확인되면 양호로 확정합니다.", "partial": ["일반 IT 위험평가는 실시했으나 AI 특화 위험(데이터 편향, 적대적 공격 등)에 대한 평가 항목이 누락된 이유는 무엇입니까?", "위험평가는 완료했으나 도출된 위험 요소에 대한 보호대책 이행이 지연되고 있는 사유는 무엇입니까?"], "partialEnd": "AI 특화 평가 항목 보완 및 지연된 보호대책 이행 완료 기한을 명시한 개선계획서를 제출받습니다.", "rootcause": ["AI 서비스에 대한 위험평가를 전혀 실시하지 않은 이유는 무엇입니까?", "핵심자산(모델, 학습데이터 등)이 관리대장에 누락된 채 운영되고 있는 경위는 무엇입니까?"], "rootcauseEnd": "AI 위험관리체계 미운영으로 결함 처리하며, 자산 전수조사 및 위험평가 즉시 실시를 권고합니다.", "na": ["당행에서 운영 중이거나 개발 중인 AI 모델 및 AI 연동 서비스가 전혀 없습니까?", "외부 상용 AI 단순 단순 조회형 서비스 외에 내부 자산이나 데이터를 사용하는 AI 서비스가 부재합니까?"], "naEnd": "AI 자산 및 서비스 부재가 확인되면 해당없음으로 판정합니다."}, "21-3": {"decisionQ": "AI 모델 취약점(적대적 공격, 모델 오염, 역공학 등) 점검 방법론 문서와 반기 1회 이상 실시한 취약점 점검 결과 보고서를 제시해 주시겠습니까?", "verify": ["AI 모델에 대한 보안 요구사항 정의서(데이터 훼손, 프롬프트 인젝션, 적대적 예제 대응 등)를 보여주시겠습니까?", "최근 반기 이내에 수행된 AI 모델 취약점 점검 수행 결과 보고서 및 수행자 자격 증빙을 보여주시겠습니까?", "CVE 또는 최신 AI 보안 트렌드(OWASP Top 10 for LLM 등)를 수집 및 모니터링한 이력 대장을 조회해 주시겠습니까?", "취약점 점검 결과 발굴된 미흡사항에 대한 조치 이행 확인서와 경영진 보고 결재건을 보여주시겠습니까?"], "verifyEnd": "AI 보안요구사항 정립, 반기 1회 이상 취약점 점검 이행, 최신 동향 모니터링 및 조치/보고 이력이 확인되면 양호로 확정합니다.", "partial": ["점검은 실시했으나 수행 주기가 반기를 초과했거나 점검 범위에서 일부 AI 모델이 누락된 이유는 무엇입니까?", "취약점이 발견되었으나 조치 기한이 경과하도록 조치가 완결되지 않은 사유는 무엇입니까?"], "partialEnd": "누락된 모델에 대한 추가 점검 실시 및 미조치 취약점에 대한 즉시 조치 계획서를 요청합니다.", "rootcause": ["AI 모델 취약점 점검을 전혀 실시하지 않은 이유는 무엇입니까?", "AI 최신 취약점에 대한 모니터링 체계가 전혀 구축되지 않은 경위는 무엇입니까?"], "rootcauseEnd": "취약점 관리 체계 부재로 결정적 결함 처리하며, 점검 도구 도입 및 외부 전문기관 점검을 권고합니다.", "na": ["자체 AI 모델을 보유하거나 튜닝하지 않고, 보안이 검증된 대외기관 표준 패키지만을 수정 없이 단순 이용합니까?", "AI 모델 구성요소에 접근 권한이 없거나 내부 데이터/모델 연동이 전혀 없는 구조입니까?"], "naEnd": "직접 관질 대상 AI 모델이 없음이 검증되면 해당없음 처리합니다."}, "21-4": {"decisionQ": "AI 학습 데이터의 출처 관리 대장과 개발/학습 환경 및 운영 환경의 분리 상태를 증명할 구성도를 보여주시겠습니까?", "verify": ["학습 데이터 수집 시 출처 검증, 수집 경로, 적법성 점검 이력이 포함된 학습 데이터 출처 대장을 보여주시겠습니까?", "AI 학습/테스트 서버와 실제 운영 DB 서버 간 물리적·논리적 접근통제 설정 화면(방화벽 정책 등)을 조회해 주시겠습니까?", "AI 모델 시험 및 학습 시 실제 운영 개인정보를 마스킹/가명 처리하여 사용했거나 변환된 데이터만을 사용했음을 보여주는 데이터 변환 로그를 제시해 주시겠습니까?", "학습 데이터에 대한 보관 기간 지정 및 만료 데이터 삭제 실행 결과서를 보여주시겠습니까?"], "verifyEnd": "출처 관리, 학습/운영 환경 분리, 시험 데이터 내 개인정보 미사용, 보관/파기 기준 준수가 확인되면 양호로 확정합니다.", "partial": ["학습 데이터 출처 대장은 존재하나 일부 외부 수집 데이터의 출처 검증 항목이 누락된 이유는 무엇입니까?", "시험 환경에 운영 데이터가 일부 사용되었으나 익명화가 불완전하게 적용된 사유는 무엇입니까?"], "partialEnd": "불완전한 학습 데이터 출처 재검증 및 시험 데이터의 완전 익명화 조치를 즉시 이행하도록 요구합니다.", "rootcause": ["AI 학습 시 실제 운영 개인정보를 아무런 통제 없이 그대로 복사하여 사용한 경위는 무엇입니까?", "학습 환경과 운영 환경이 분리되어 있지 않고 동일 네트워크에서 운영되는 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 및 망분리 통제 위반으로 중대 결함 처리하며, 개인정보 즉시 파기 및 환경 분리를 요구합니다.", "na": ["내부 데이터를 활용한 AI 학습을 전혀 수행하지 않고, 완전히 사전 학습된(Pre-trained) 외부 API만 호출하여 사용하는 구조입니까?"], "naEnd": "내부 학습 데이터 및 학습 환경 생성이 전무함이 검증되면 해당없음 판정합니다."}, "21-5": {"decisionQ": "AI 관련 시스템 및 자율 에이전트(Agent)의 권한 부여 현황 매트릭스와 강화된 인증(MFA) 적용 설정을 현장 시스템에서 보여주시겠습니까?", "verify": ["AI 관련 DB, 서버, 에이전트에 부여된 계정 목록 및 '최소 권한 원칙'이 적용된 권한 설정 화면을 조회해 주시겠습니까?", "AI 주요 개발자 및 관리자 계정에 대해 주기적(반기/분기)으로 권한 타당성을 검토한 결재 문서를 보여주시겠습니까?", "AI 관리자 콘솔 및 중요 AI 서버 접속 시 OTP 또는 MFA(다중인증)가 강제 적용된 서버 설정 화면을 보여주시겠습니까?", "비인가 IP 또는 미등록 에이전트의 AI 서비스 접속 차단 정책이 반영된 접근통제 솔루션(DBSAFER 등) 설정 내역을 조회해 주시겠습니까?"], "verifyEnd": "최소 권한 부여, 권한 재검토 실적, 관리자 MFA 적용, 접근통제 정책 설정이 확인되면 양호로 확정합니다.", "partial": ["인간 사용자에게는 MFA가 적용되었으나, AI 자율 에이전트 서비스 계정(Service Account)의 권한 통제나 인증이 미흡한 이유는 무엇입니까?", "권한 재검토는 실시했으나 퇴사자/보직이동자의 계정 삭제가 일부 지연된 사유는 무엇입니까?"], "partialEnd": "에이전트 계정 통제 강화 및 지연된 권한 회수를 즉시 완료하도록 권고합니다.", "rootcause": ["AI 관리자 계정에 공용 계정을 사용하거나 MFA 없이 단일 비밀번호로 접속하고 있는 경위는 무엇입니까?", "AI 에이전트에게 DB에 대한 과도한 관리자(DBA) 권한이 부여되어 있는 이유는 무엇입니까?"], "rootcauseEnd": "접근통제 심각 결함으로 결정하고, 계정 권한 즉시 축소 및 MFA 강제 적용을 명령합니다.", "na": ["AI 관련 별도 관리자 화면이나 자체 구동 시스템이 전혀 없고 외부 완제품 SW만 이용합니까?"], "naEnd": "독립된 AI 계정/시스템이 존재하지 않음이 입증되면 해당없음 처리합니다."}, "21-6": {"decisionQ": "외부 AI 서비스(OpenAI, Claude 등) 연동 API 키의 안전한 보관 관리 상태와 정보유출 방지 통제(DLP) 설정을 시스템에서 직접 보여주시겠습니까?", "verify": ["외부 AI API 키가 소스코드 내 하드코딩되지 않고 Key Vault/암호화 관리 모듈에 보관되어 있음을 코드/설정 화면으로 확인해 주시겠습니까?", "AI 개발 도구(GitHub Copilot 등) 또는 클라우드 AI 서비스 이용 시 개인정보·주요 금융정보의 입력/유출을 차단하는 DLP/프록시 설정 내역을 제시해 주시겠습니까?", "외부 API 호출 시 부여된 계정 권한이 해당 기능 수행에 필요한 최소 범위로 제한되어 있음을 연동 명세서로 조회해 주시겠습니까?", "외부 API 키의 주기적 변경(Rotation) 이력 대장을 제시해 주시겠습니까?"], "verifyEnd": "API 키 볼트 보관, 소스코드 내 하드코딩 부재, DLP 차단 정책 적용, Key 로테이션 준수가 확인되면 양호 확정합니다.", "partial": ["API 키는 Key Vault에 보관되나 주기적 로테이션(변경) 절차가 이행되지 않는 이유는 무엇입니까?", "DLP 차단 정책이 적용되어 있으나 예외 처리 IP/계정이 과도하게 설정된 사유는 무엇입니까?"], "partialEnd": "API 키 로테이션 주기 설정 및 DLP 예외 계정 즉시 정리를 요구합니다.", "rootcause": ["외부 AI API 키가 개발자 PC 또는 형상관리 소스코드(Git)에 평문으로 하드코딩되어 발견된 경위는 무엇입니까?", "내부 중요 데이터나 소스코드가 외부 AI 서비스로 프롬프트 형태로 통제 없이 전송되고 있는 사유는 무엇입니까?"], "rootcauseEnd": "API 키 유출 위험 및 데이터 유출 통제 미흡으로 중대 결함 처리하며, API 키 즉시 폐기/재발급을 명령합니다.", "na": ["외부 AI 서비스, 외부 API 연동, 클라우드 기반 AI 코딩 도구를 일체 사용하지 않는 완전 폐쇄망 온프레미스 AI 구조입니까?"], "naEnd": "외부 API 연동이 전혀 없음이 네트워크 구성도상 입증되면 해당없음 처리합니다."}, "21-7": {"decisionQ": "AI 시스템 도입·개발 시 작성한 보안 요구사항 정의서 및 오픈소스 라이브러리 공급망 취약점 점검 내역을 보여주시겠습니까?", "verify": ["AI 시스템 개발 단계별 보안 요구사항 검토서 및 승인 문서 원본을 보여주시겠습니까?", "AI 모델 구축에 사용된 오픈소스/라이브러리 목록(BOM)과 이에 대한 점검(SCA 도구 등) 및 패치 이력을 조회해 주시겠습니까?", "AI 소스코드 및 학습 데이터의 변경 이력이 형상관리 시스템(Git 등)에 기록되고 무단 변경이 통제되고 있음을 시연해 주시겠습니까?", "오픈소스 버전 관리 정책 및 보안 취약점 발견 시 패치 기준서가 정립되어 있습니까?"], "verifyEnd": "개발 보안 요구사항 정의, 오픈소스 SBOM 및 취약점 점검, 소스/데이터 형상 통제가 확인되면 양호 확정합니다.", "partial": ["개발 보안 요구사항은 수립되었으나 공급망 취약점(오픈소스)에 대한 점검 도구 미비로 일부 라이브러리 점검이 누락된 사유는 무엇입니까?", "형상관리는 수행 중이나 학습 데이터 버전 변경에 대한 승인 절차가 구두로 진행된 사유는 무엇입니까?"], "partialEnd": "오픈소스 점검 체계 강화 및 학습 데이터 변경 승인 절차의 서면화/시스템화를 명시한 개선계획서를 받습니다.", "rootcause": ["AI 개발 시 보안 요구사항 검토 없이 개발이 완료 및 배포된 경위는 무엇입니까?", "오픈소스 라이브러리의 취약점을 점검하거나 패치하는 기준이 전혀 없는 이유는 무엇입니까?"], "rootcauseEnd": "개발 보안 및 공급망 관리 부재로 결함 확정하며, 개발 보안 가이드라인 제정 및 소스 전수점검을 권고합니다.", "na": ["자체 개발이나 오픈소스 활용이 전혀 없으며, 100% 외산/대외검증 완제 상용 AI 소프트웨어를 단순 도입하여 사용합니까?"], "naEnd": "소프트웨어 자체 개발 및 오픈소스 활용이 없음이 검증되면 해당없음 처리합니다."}, "21-8": {"decisionQ": "AI 개발·시험 환경과 운영 환경의 분리 상태 및 운영 환경 이관 시 수행하는 접근통제 및 예외 처리·복구 절차서를 보여주시겠습니까?", "verify": ["AI 개발, 시험, 운영 서버 간 접근이 논리적/물리적으로 차단되어 있음을 네트워크 구성도 및 서버 접근 통제 설정으로 증명해 주시겠습니까?", "AI 모델 및 소스코드를 운영 환경으로 이관 시 이관 승인 결재 및 검증 절차서가 이행된 이력을 보여주시겠습니까?", "AI 모델의 이상 동작, 적대적 입력, 시스템 오류 시 작동하는 예외 처리(Fallback) 및 복구 매뉴얼을 제시해 주시겠습니까?", "클라우드 기반 AI 이용 시 당행과 클라우드 사업자(CSP) 간 책임분담모델(RACI) 명시 문서 및 SLA 협약서를 조회해 주시겠습니까?"], "verifyEnd": "개발/시험/운영 환경 분리, 이관 통제 절차, 예외 처리/복구 매뉴얼, 클라우드 책임분담 명확화가 확인되면 양호 확정합니다.", "partial": ["환경은 분리되어 있으나 개발자가 긴급 조치를 이유로 운영 환경에 직접 접속할 수 있는 예외 계정이 존재하는 사유는 무엇입니까?", "예외 처리 절차는 존재 하나 모델 오류 시 구체적인 복구 테스트 실적이 누락된 사유는 무엇입니까?"], "partialEnd": "운영 직접 접속 예외 계정 회수 및 복구 훈련 실시를 요구합니다.", "rootcause": ["AI 개발/시험 환경과 운영 환경을 동일 서버/네트워크에서 혼용하여 사용하는 경위는 무엇입니까?", "클라우드 AI 서비스 이용 시 보안 관리 책임 범위를 미정립한 채 운영하는 이유는 무엇입니까?"], "rootcauseEnd": "환경 분리 위반 및 이관 통제 부재로 결함 처리하고 물리적/논리적 분리를 명령합니다.", "na": ["별도의 개발/시험 단계 없이 완제품 서비스 형태의 SaaS AI만 단순 계약하여 사용하는 구조입니까?"], "naEnd": "자체 운영 환경 이관이 없는 SaaS 형태임이 확인되면 해당없음 처리합니다."}, "21-9": {"decisionQ": "AI 서비스의 성능 및 이상행위(프롬프트 오용, 자동화 공격, 편향 출력 등)를 실시간 모니터링하는 화면 및 최근 점검 이력을 보여주시겠습니까?", "verify": ["AI 서비스 장애 및 성능 지표(응답속도, 정확도 등 SLA)를 모니터링하는 관제 대시보드를 직접 보여주시겠습니까?", "AI 모델 모듈에 대한 이상 접근, 비인가 호출, 자동화 공격(Bot 등) 탐지 정책이 적용된 통합관제/보안 솔루션 화면을 제시해 주시겠습니까?", "AI 출력 결과물에 대한 중요정보 노출, 편향성, 유해성 여부를 주기적으로 점검한 점검 결과 보고서를 조회해 주시겠습니까?", "SLA 미달 또는 이상행위 탐지 시 담당자에게 즉시 통보되는 경보(Alert) 설정 상태를 시연해 주시겠습니까?"], "verifyEnd": "성능/장애 관제, 이상행위 탐지 체계, 출력물 주기적 점검, 자동 경보 체계가 증명되면 양호 확정합니다.", "partial": ["성능 관제는 이루어지고 있으나 AI 특화 이상행위(프롬프트 주입 공격 탐지 등)에 대한 통제 정책이 미비한 이유는 무엇입니까?", "출력물 점검은 실시하나 점검 주기가 불규칙하거나 결과 조치가 지연되는 사유는 무엇입니까?"], "partialEnd": "AI 특화 탐지 룰셋 추가 및 출력물 정기 점검 주강화를 명시한 계획서를 요청합니다.", "rootcause": ["AI 서비스 모니터링 체계가 전혀 구축되지 않아 이상 동작이나 장애 발생을 인지하지 못하는 경위는 무엇입니까?", "AI 서비스 결과물에 대한 편향성/중요정보 노출 점검을 단 한 차례도 수행하지 않은 이유는 무엇입니까?"], "rootcauseEnd": "모니터링 체계 미비로 결함 확정하며, 이상행위 탐지 모듈 구축 및 출력물 필터링 강화를 요구합니다.", "na": ["내부/대고객용 AI 서비스가 존재하지 않거나 단순 테스트 목적으로만 운영되는 시스템입니까?"], "naEnd": "운영 중인 AI 서비스 부재가 입증되면 해당없음 처리합니다."}, "21-10": {"decisionQ": "AI 시스템의 로그 관리 기준서와 로그 모니터링 절차서, 그리고 실제 로그 무결성 보호 설정 화면을 보여주시겠습니까?", "verify": ["AI 프롬프트, 모델 응답, 학습 이력, API 호출 로그의 수집 기준 및 보존 기간(예: 1년 이상)이 명시된 규정 문서를 보여주시겠습니까?", "생성된 AI 관련 로그에 대한 정기적 검토/분석 이력 대장 및 이상징후 경보 발생 내역을 조회해 주시겠습니까?", "AI 로그가 저장되는 로그 전용 서버의 접근 권한 및 위·변조 방지(WORM, Hash, 암호화 등) 적용 설정 화면을 보여주시겠습니까?", "이상징후 탐지 시 관련 담당자에게 비상 경보가 발송된 대응 이력서를 보여주시겠습니까?"], "verifyEnd": "로그 수집/보존 기준 준수, 정기 모니터링 이력, 위변조 방지 조치, 경보대응 이력이 입증되면 양호 확정합니다.", "partial": ["로그는 수집·보존되고 있으나 로그 검토 주기가 불규칙하거나 수동 검토에만 의존하는 이유는 무엇입니까?", "로그 위·변조 방지 조치가 일부 시스템에만 적용되어 있는 사유는 무엇입니까?"], "partialEnd": "자동화된 로그 분석 체계 수립 및 전 시스템 로그 위변조 방지 적용을 명령합니다.", "rootcause": ["AI 관련 중요 로그(입출력, 모델 변경 등)를 전혀 남기지 않거나 보존 기간이 현저히 짧은 경위는 무엇입니까?", "로그 관리자 권한 통제가 안 되어 로그 삭제/수정이 자유롭게 가능한 상태인 이유는 무엇입니까?"], "rootcauseEnd": "로그 관리 및 무결성 통제 부재로 중대 결함 처리하며, 로그 저장소 즉시 격리 및 무결성 통제 구현을 권고합니다.", "na": ["AI 기능을 직접 운영하지 않고 로그 생성이 불가능한 구조입니까?"], "naEnd": "로그 수집 대상 AI 시스템이 없음이 증명되면 해당없음 판정합니다."}, "21-11": {"decisionQ": "AI 학습 및 서비스 과정에서 개인정보 처리를 최소화하기 위해 수립한 가명처리 기준서 및 실제 가명처리 이행 결과서를 제시해 주시겠습니까?", "verify": ["AI 학습 데이터셋에서 개인정보 처리 최소화(필수 항목 외 삭제/마스킹) 조치 내역 대장을 보여주시겠습니까?", "비정형 데이터(음성 상담록, 이미지 문서 등)에 적용된 가명처리/재식별 방지 솔루션 설정 및 처리 전후 비교 샘플을 제시해 주시겠습니까?", "AI 서비스가 민감정보나 고유식별정보를 추론하거나 재조합하여 출력하지 않도록 조치한 프롬프트/필터링 설정 내역을 조회해 주시겠습니까?", "AI 학습 데이터 파기 정책 및 만료된 개인정보 데이터셋 파기 집행 결과서를 제시해 주시겠습니까?"], "verifyEnd": "개인정보 최소화, 비정형 가명처리, 민감정보 추론 방지 통제, 데이터 파기 이행이 검증되면 양호 확정합니다.", "partial": ["정형 데이터는 가명처리가 양호하나 비정형 데이터(텍스트/음성) 내 비정식 표기 개인정보의 마스킹이 일부 누락된 사유는 무엇입니까?", "추론 방지 통제는 수립되었으나 사전 테스트가 일부 시나리오에 한정된 이유는 무엇입니까?"], "partialEnd": "비정형 가명처리 솔루션 고도화 및 민감정보 추론 방지 테스트 시나리오 확대를 요구합니다.", "rootcause": ["AI 학습 데이터에 가명처리나 마스킹 조치 없이 주민등록번호 등 고유식별정보가 평문으로 포함되어 사용된 경위는 무엇입니까?", "개인정보 적법성 검토 없이 개인정보가 포함된 대량의 데이터를 AI 모델에 무단 학습시킨 사유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 중대 위반으로 결함 처리하며, 개인정보보호위 보고 및 학습 데이터 즉시 파기를 권고합니다.", "na": ["AI 모델 학습 및 프롬프트 처리에 개인정보가 전혀 포함되지 않고 완전히 익명화된 금융 통계/기술 데이터만 활용합니까?"], "naEnd": "개인정보 처리 사실이 완전히 부재함이 증명되면 해당없음 처리합니다."}, "21-12": {"decisionQ": "AI 개인정보처리방침 공개 현황과 자동화된 결정에 대한 정보주체 권리행사(거버넌스/설명요구) 처리 시스템 및 절차서를 보여주시겠습니까?", "verify": ["당행 홈페이지/앱에 AI 서비스의 개인정보 처리 및 자동화된 결정에 대한 내용이 포함된 개인정보처리방침 최신 게시 화면을 보여주시겠습니까?", "정보주체가 자동화된 결정에 대해 거부하거나 설명을 요구할 수 있는 수단을 마련하고 실제 처리한 접수/이행 대장을 조회해 주시겠습니까?", "AI 학습 및 활용 목적에 대해 정보주체로부터 적법하게 동의를 받거나 법적 근거를 갖춘 동의서 양식을 보여주시겠습니까?", "AI 관련 데이터의 국외 이전(외부 AI 클라우드 호출 등) 발생 여부를 식별하고 법적 요건(동의, 고지 등)을 준수한 증빙을 제시해 주시겠습니까?"], "verifyEnd": "처리방침 공개, 설명/거부 요구 처리 절차, 동의 적법성, 국외이전 요건 준수가 입증되면 양호 확정합니다.", "partial": ["개인정보처리방침에 AI 관련 내용이 명시되었으나 자동화된 결정 거부/설명요구 신청 접수 채널이 일원화되지 않은 사유는 무엇입니까?", "국외이전 식별은 되었으나 고지 항목 중 일부 내용이 미비한 이유는 무엇입니까?"], "partialEnd": "권리행사 접수 채널 일원화 및 국외이전 고지사항 보완을 명시한 개선계획서를 요구합니다.", "rootcause": ["자동화된 결정에 대한 정보주체의 권리행사(설명 요구, 거부) 처리 절차 및 시스템이 전혀 구축되지 않은 경위는 무엇입니까?", "정보주체 고지 없이 개인정보를 국외 AI 클라우드 서버로 무단 전송한 사유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 정보주체 권리 보장 위반으로 중대 결함 처리하며, 권리행사 절차 신설 및 국외이전 중단을 명령합니다.", "na": ["당행 AI 서비스가 정보주체의 개인정보를 전혀 처리하지 않거나 개인에게 영향을 미치는 자동화된 결정을 내리지 않는 시스템입니까?"], "naEnd": "자동화된 결정 및 개인정보 처리가 없음이 입증되면 해당없음 처리합니다."}, "19-1": {"decisionQ": "전자금융거래 안전성을 위한 FDS(이상거래탐지시스템)가 정상 작동하고 있으며, 탐지 룰 모니터링 및 주기적 업데이트가 이행되고 있습니까? 현장 화면 및 보고서로 확인 부탁드립니다.", "verify": ["현재 FDS 탐지 엔진 운영 화면과 설정된 탐지 룰 목록(버전/적용일 포함)을 화면으로 즉시 보여주실 수 있습니까?", "최근 1년 동안 분기별 1회 이상 탐지 룰을 신규 제정하거나 업데이트한 결재문서와 룰 적용 이력을 제시해 주시겠습니까?", "오탐·누탐 발생에 대한 정기 분석 보고서와, 이에 따라 룰을 조정한 조치 내역을 보여주시겠습니까?", "FDS 탐지 이벤트 발생 시 담당자 알림 및 처리 SLA 기준이 지정되어 있는지, 실제 실시간 미처리건 유무를 조회해 주시겠습니까?"], "verifyEnd": "FDS가 실시간 가동 중이고 분기별 룰 업데이트 이력이 확인되며, 오탐·누탐 분석 보고서 및 SLA 이행 이력이 검증되면 '양호'로 판정합니다.", "partial": ["FDS 운영 및 룰 적용은 되고 있으나, 분기 1회 이상 룰 업데이트 주기나 오탐/누탐 분석 보고 절차가 일부 누락된 사유는 무엇입니까?", "SLA 초과 처리건이 일부 존재하는 경우, 처리 지연의 원인 및 관리 방안이 마련되어 있습니까?"], "partialEnd": "FDS 기본 기능은 가동 중이나 룰 업데이트/분석 절차가 미비한 경우 '부분이행'으로 판정하고 룰 정비 및 정기 분석 체계 개선을 권고합니다.", "rootcause": ["FDS를 아예 도입하지 않았거나 탐지 룰을 최초 구축 이후 전혀 업데이트하지 않은 사유는 무엇입니까?", "이상거래 발생 시 이에 대한 탐지 및 차단 실패에 대해 알고 계셨음에도 조치를 취하지 않은 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §38 위반으로 '미흡' 판정하며, FDS 구축 및 탐지 룰 즉시 업데이트, 이상거래 모니터링 체계 재수립 조치요구서를 발급합니다.", "na": ["조직이 전자금융거래법상 대고객 전자금융서비스를 제공하지 않거나 전용 단말 기반의 예외 대상인지 증빙할 수 있습니까?"], "naEnd": "대고객 전자금융거래가 전혀 존재하지 않음이 객적으로 입증되는 경우에 한해 'N/A' 처리합니다."}, "19-2": {"decisionQ": "전자금융거래 시 사용되는 인증수단(간편인증, 금융인증서 등)의 안전성 기준이 준수되고 있으며, 인증 실패 제한 및 우회 통제가 설정되어 있습니까?", "verify": ["전자금융 인증수단별 안전성 적합성 검토 보고서 및 금융보안원 보안성 심의 결과를 제시해 주시겠습니까?", "인증서 발급·재발급·폐기 처리 로그 및 관련 내부 승인 절차를 보여주실 수 있습니까?", "운영 중인 뱅킹 앱/웹의 인증 실패 제한 설정(예: 5회 실패 시 차단) 화면을 직접 보여주시겠습니까?", "인증 수단 우회 공격 방지를 위한 앱 패키징, 모바일 백신, 핀테크 API 인증 검증 테스트 결과를 제시해 주시겠습니까?"], "verifyEnd": "인증수단 안전성 기준 적합성, 인증서 관리 절차, 실패 횟수 제한 설정 및 우회 점검 결과가 모두 확인되면 '양호'로 판정합니다.", "partial": ["인증 실패 횟수 제한은 적용되어 있으나 일부 간편인증 수단에 대해 별도의 안전성 적합성 검토서가 누락된 이유는 무엇입니까?", "우회 경로 점검이 정기적으로 이루어지지 않고 최초 구축 시에만 시행된 경위가 있습니까?"], "partialEnd": "인증 기본 통제는 적용 중이나 일부 인증수단 관리 및 취약점 점검이 부분 누락된 경우 '부분이행' 판정 후 개선을 권고합니다.", "rootcause": ["인증 실패 횟수 제한 설정이 누락되어 무제한 시도가 가능한 상태로 운영된 원인은 무엇입니까?", "인증서 폐기 처리 프로세스가 연동되지 않거나 인증 우회 통제가 전혀 이루어지지 않은 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §21 위반으로 '미흡' 판정하며, 인증 실패 제한 및 우회 방지 로직 즉시 적용을 지시합니다.", "na": ["본 저축은행이 고객 인증이 필요한 전자금융거래 서비스를 일체 제공하지 않는 특수 기관인지 확인 가능합니까?"], "naEnd": "인증이 필요한 전자금융서비스가 전혀 존재하지 않는 경우 'N/A' 판정합니다."}, "19-3": {"decisionQ": "전자금융거래 내부통제 기준이 문서화되어 시행 중이며, 전체 임직원 대상 준수 교육 및 위반 시 처리 절차가 적정하게 관리되고 있습니까?", "verify": ["현재 제정·시행 중인 '전자금융거래 내부통제 기준' 문서와 이사회/경영진 승인 문서 결재를 보여주시겠습니까?", "최근 1년 내 전체 임직원 및 IT/전자금융 담당자 대상으로 실시한 내부통제 교육 이수 내역(수료율 포함)을 제출해 주시겠습니까?", "내부통제 기준 위반 사례 발생 시 모니터링 이력 및 인사 조치·경고 등 처리 결과 보고서를 제시해 주시겠습니까?", "관련 법령(전자금융거래법 등) 개정에 따라 내부통제 기준을 최신화한 최근 개정 이력을 보여주시겠습니까?"], "verifyEnd": "내부통제 기준 승인 문서, 교육 이수율, 위반 조치 이력 및 법령 개정 반영 이력이 모두 검증되면 '양호'로 판정합니다.", "partial": ["내부통제 기준은 존재 하나, 전 임직원 교육 수료율이 저조하거나 일부 신규 입사자에 대한 교육이 누락된 사유는 무엇입니까?", "최신 법령 개정 사항이 내부통제 기준에 제때 반영되지 않고 지연 반영된 이유가 있습니까?"], "partialEnd": "내부통제 기준은 수립되어 있으나 교육 실시 및 기준 최신화가 일부 미흡한 경우 '부분이행'으로 판정합니다.", "rootcause": ["전자금융거래 내부통제 기준 자체를 수립하지 않았거나, 제정 후 수년간 방치하여 규정이 유명무실한 경위는 무엇입니까?", "내부통제 위반 사항이 발생했음에도 은폐하거나 정상적인 처리를 하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "전자금융거래법 §21의2 위반으로 '미흡' 판정하며, 내부통제 기준 재정비 및 전 임직원 교육 실시를 이행 요구합니다.", "na": ["전자금융거래법 제21조의2 적용 대상에서 제외되는 특수 목적 법인이거나 해당 업무가 전혀 없는지 입증 가능합니까?"], "naEnd": "법적 기준상 내부통제 기준 수립 의무가 제외되는 기관임이 입증되면 'N/A' 판정합니다."}, "19-4": {"decisionQ": "전자금융사고 발생 시 3시간 이내 금융감독원 보고 절차서가 수립되어 있으며, 비상연락망 및 사고 보고 이력이 적정하게 관리되고 있습니까?", "verify": ["전자금융사고 발생 시 '3시간 이내 금감원 보고' 단계별 매뉴얼 및 보고 절차서를 제시해 주시겠습니까?", "보고 매뉴얼 내 금감원 담당부서 및 기관 내부 비상연락망이 최근(1~2개월 내) 갱신되었는지 현장 확인해 주시겠습니까?", "사고 유형별(장애, 침해사고 등) 최종 보고서 제출 기한(예: 2주 내) 준수를 위한 관리 대장을 보여주시겠습니까?", "최근 3년간 발생한 전자금융사고(또는 장애) 발생 시 금감원에 실제 제출된 초보(3시간 내) 및 확정 보고서 접수증을 제시해 주시겠습니까?"], "verifyEnd": "3시간 이내 보고 절차서, 최신 비상연락망, 최종 보고 기한 관리 대장 및 실제 사고 보고 이행 이력이 검증되면 '양호'로 판정합니다.", "partial": ["사고 보고 절차는 존재하나, 금감원 담당자 연락망 최신화가 수개월간 누락되어 있었던 사유는 무엇입니까?", "과거 사고 보고 시 3시간 초보 보고는 이행했으나 최종 보고서 제출이 일주일가량 지연되었던 경위가 있습니까?"], "partialEnd": "보고 절차 및 실적은 있으나 연락망 미비 또는 최종 보고 지연 등이 확인된 경우 '부분이행'으로 판정하고 정비를 요구합니다.", "rootcause": ["전자금융사고 발생 시 금감원 보고 절차서 자체가 마련되어 있지 않은 사유는 무엇입니까?", "전자금융사고가 발생했음에도 금감원 보고를 누락하거나 은폐한 사실이 있습니까? 그 경위를 설명해 주십시오."], "rootcauseEnd": "전자금융거래법 §21의3 및 감독규정 §40 위반으로 '미흡' 판정하며, 사고 보고 체계 즉시 재수립 및 은폐 건 조사를 진행합니다.", "na": ["해당 기관이 전자금융거래법상 전자금융업자 또는 금융회사에 해당하지 않아 보고 의무가 없는지 입증할 수 있습니까?"], "naEnd": "법적 보고 의무 대상 기관이 아님이 확인된 경우에 한해 'N/A' 판정합니다."}, "19-5": {"decisionQ": "금융감독원 IT 실태평가 대비 자가진단을 정기적으로 수행하고 있으며, 전년도 지적·미흡 사항에 대한 개선 이행을 완료했습니까?", "verify": ["가장 최근 실시한 'IT 실태평가 자가진단 결과 보고서'와 각 항목별 점수/평가표를 제시해 주시겠습니까?", "전년도 금감원 IT 실태평가(또는 자체 자가진단)에서 지적된 미흡 항목에 대한 개선 이행 관리 대장 및 완료 증빙을 보여주시겠습니까?", "자가진단 결과 및 미흡 항목 개선 계획에 대해 대표이사/이사회 등 경영진에 보고한 결재문서를 제시해 주시겠습니까?", "개선 이행이 진행 중인 항목에 대해 예정된 기한 내 완료 가능한 일정표가 관리되고 있습니까?"], "verifyEnd": "자가진단 수행 보고서, 전년도 미흡 항목 개선 완료 증빙, 경영진 보고 문서가 모두 검증되면 '양호'로 판정합니다.", "partial": ["자가진단은 수행했으나 경영진 보고가 누락되었거나 결재 절차가 지연된 사유는 무엇입니까?", "전년도 지적사항 중 일부 항목의 개선 완료 예정일이 지연되었으나 조치 계획 정비가 미흡한 상태인 이유는 무엇입니까?"], "partialEnd": "자가진단은 시행 중이나 일부 미흡 항목의 개선 지연 또는 보고 절차 누락이 확인된 경우 '부분이행' 판정합니다.", "rootcause": ["금감원 IT 실태평가 자가진단을 수년간 전혀 수행하지 않은 경위는 무엇입니까?", "금감원 실태평가 지적사항에 대해 개선 조치를 이행하지 않고 방치한 원인은 무엇입니까?"], "rootcauseEnd": "IT 실태평가 관리 체계 미비로 '미흡' 판정하며, 즉시 자가진단 실시 및 미흡 항목 개선 이행 계획 제출을 요구합니다.", "na": ["금감원 IT 실태평가 대상에 포함되지 않는 특수 기관임을 입증할 증빙이 있습니까?"], "naEnd": "IT 실태평가 적용 예외 기관임이 법적/제도적으로 확인되면 'N/A' 처리합니다."}, "19-6": {"decisionQ": "연간 정보기술부문 실태보고서를 감독당국 제출 기한 내에 정확하게 작성하여 제출하고 계십니까?", "verify": ["최근 제출한 '정보기술부문 실태보고서' 원본 및 금감원 접수 확인증(접수번호/일자)을 보여주시겠습니까?", "실태보고서 기재 데이터(IT 인력, 예산, 시스템 현황 등)와 실제 내부 관리 대장 간 데이터 일치 여부를 대조해 주시겠습니까?", "보고서 제출 전 CIO/CISO 승인 및 내부 검증 절차 결재문서를 제시해 주시겠습니까?", "과거 3년간 제출 기한 연장이나 지연 제출 없이 정해진 기한(예: 매년 2월 말 등) 내 제출되었는지 확인 가능합니까?"], "verifyEnd": "실태보고서 원본, 금감원 접수증, 수치 대조 일치, 제출 기한 준수가 검증되면 '양호'로 판정합니다.", "partial": ["보고서는 기한 내 제출했으나 보고서 기재 일부 데이터(예: IT 외주인력 수, 예산 세부항목)의 오기가 있어 사후 수정 제출한 적이 있습니까?", "제출 접수증 보관이 누락되어 팩스/전자문서 송신 로그로 대체 확인해야 하는 상황입니까?"], "partialEnd": "기한 내 제출은 되었으나 기재 수치의 경미한 오기나 증빙 관리 미흡이 확인된 경우 '부분이행' 판정합니다.", "rootcause": ["정보기술부문 실태보고서를 기한 내 제출하지 못하고 누락하거나 수개월 지연 제출한 사유는 무엇입니까?", "실태보고서의 핵심 통계 수치를 허위로 기재하여 제출한 경위가 있습니까?"], "rootcauseEnd": "전자금융거래법 §22의3 위반으로 '미흡' 판정하며, 정정 보고서 제출 및 보고 체계 정비 조치를 지시합니다.", "na": ["전자금융거래법상 정보기술부문 실태보고서 제출 의무 대상 기관에서 제외되는 사유가 있습니까?"], "naEnd": "법적 제출 의무가 면제되는 기관임이 확인되면 'N/A' 판정합니다."}, "19-7": {"decisionQ": "전자금융사고로 인한 소비자 피해보상 기준 및 절차가 마련되어 있으며, 보상 기준의 이사회 승인 및 공시가 적정하게 이행되고 있습니까?", "verify": ["현재 제정되어 있는 '전자금융사고 소비자 피해보상 지침(절차서)' 및 이사회 승인 결재 문서를 제출해 주시겠습니까?", "소비자가 피해보상 신청 시 처리되는 절차 및 보상 여부 심의위원회 운영 기록을 보여주실 수 있습니까?", "공식 홈페이지 또는 앱 내에 금융소비자용 '전자금융사고 피해보상 절차 및 기준'이 공시되어 있는 화면을 보여주시겠습니까?", "최근 발생한 전자금융 피해보상 신청 건에 대한 손해배상 지급 내역 및 보상 처리 대장을 제시해 주시겠습니까?"], "verifyEnd": "피해보상 지침, 이사회 승인 문서, 홈페이지 공시 화면 및 피해보상 처리 대장이 모두 검증되면 '양호'로 판정합니다.", "partial": ["피해보상 기준은 수립되어 있으나 홈페이지 공시 내용이 이전 규정 기준으로 최신화되지 않은 사유는 무엇입니까?", "보상 처리 절차는 가동 중이나 보상 심의위원회 의록 작성이 일부 누락된 경위가 있습니까?"], "partialEnd": "보상 기준 및 처리는 이루어지나 공시 최신화나 서류 관리가 미흡한 경우 '부분이행'으로 판정합니다.", "rootcause": ["전자금융사고에 따른 소비자 피해보상 기준 및 절차 자체를 수립하지 않은 사유는 무엇입니까?", "전자금융사고 발생 시 고객의 보상 요구를 합당한 이유 없이 거부하거나 규정과 다르게 처리한 경위가 있습니까?"], "rootcauseEnd": "전자금융거래법 §9·10 위반으로 '미흡' 판정하며, 피해보상 기준 즉시 제정 및 이사회 승인, 고객 피해 재조치를 요구합니다.", "na": ["대고객 전자금융거래를 제공하지 않아 소비자 피해보상 이슈가 구조적으로 발생할 수 없음을 증명할 수 있습니까?"], "naEnd": "대고객 금융거래가 존재하지 않음이 확인되면 'N/A' 판정합니다."}, "19-8": {"decisionQ": "DDoS(디도스) 공격 대응 계획이 수립되어 있고, 방어 시스템 운영, ISP 연계 대피소 체계 및 정기 모의훈련이 적정하게 수행되고 있습니까?", "verify": ["최신 'DDoS 공격 대응 비상계획서' 및 비상대응조직도(연락망 포함)를 보여주시겠습니까?", "Anti-DDoS 전용 장비의 차단 정책 설정 화면과 회선 대역폭 임계치 설정 상태를 모니터링 화면으로 보여주실 수 있습니까?", "KT/SKB/LG U+ 등 통신사업자(ISP) 또는 금융보안원 사이버비상대응센터(DDoS 대피소) 연계 계약서 및 서비스 활성화 상태를 제시해 주시겠습니까?", "최근 1년 이내 실시한 'DDoS 모의훈련 결과 보고서'(훈련 시나리오, 응답시간, 차단 성공률 포함)를 제시해 주시겠습니까?"], "verifyEnd": "DDoS 대응 계획, Anti-DDoS 장비 설정, ISP 대피소 계약, DDoS 훈련 결과 보고서가 모두 검증되면 '양호'로 판정합니다.", "partial": ["DDoS 방어 장비 및 ISP 연계는 되어 있으나, 연 1회 수행해야 하는 DDoS 모의훈련이 연장되어 미실시 상태인 사유는 무엇입니까?", "대응 매뉴얼 내 비상연락망에 퇴사자나 보직 변경자가 포함되어 최신화가 지연된 경위가 있습니까?"], "partialEnd": "방어 시스템은 작동하나 훈련 미실시 또는 매뉴얼 최신화 지연이 확인되면 '부분이행' 판정 후 개선을 조치합니다.", "rootcause": ["Anti-DDoS 방어 장비를 도입하지 않았거나 ISP DDoS 대피소 연계 서비스가 계약되어 있지 않은 원인은 무엇입니까?", "DDoS 공격으로 인한 대고객 서비스 차단 발생 시 비상 대응 절차가 전혀 작동하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §18 위반으로 '미흡' 판정하며, Anti-DDoS 체계 구축 및 차단 훈련 즉시 실시를 지시합니다.", "na": ["외부 인터넷과 완전히 단절된 폐쇄망만 운영하여 DDoS 공격 위협이 완전히 배제되는 환경인지 증빙할 수 있습니까?"], "naEnd": "외부 접점이 없는 완전 폐쇄망 구조임이 입증되면 'N/A' 판정합니다."}, "19-9": {"decisionQ": "외부 보안 연구자 또는 금융소비자로부터의 정보기술 부문 취약점 신고 접수 채널을 운영하고 있으며, 신고 처리 절차 및 보상 정책이 관리되고 있습니까?", "verify": ["홈페이지/앱 상에 공개된 '금융보안 취약점 신고 채널(이메일, 웹페이지 등)' 안내 화면을 보여주시겠습니까?", "외부 취약점 신고 접수 시 담당자 지정, 위험도 평가, 조치 기한(예: 30일 내)이 명시된 '취약점 신고 처리 절차서'를 제출해 주시겠습니까?", "최근 접수된 외부 취약점 신고 이력 및 해당 취약점에 대한 패치/조치 완료 내역서를 보여주실 수 있습니까?", "취약점 신고자에 대한 포상금 지급 또는 감사 표창 등 보상 정책 운영 규정 및 지급 이력을 제시해 주시겠습니까?"], "verifyEnd": "취약점 신고 채널, 처리 절차서, 최근 접수·조치 내역, 보상 정책이 확인되면 '양호'로 판정합니다.", "partial": ["신고 채널 및 처리 절차는 존재하나 신고 포상 정책이 수립되어 있지 않거나 운영 실적이 없는 사유는 무엇입니까?", "외부 취약점 접수 후 패치 조치가 기한을 초과하여 처리된건에 대한 관리 이력이 미흡한 이유가 있습니까?"], "partialEnd": "신고 접수 및 조치 체계는 존재하나 보상 정책 부재 또는 조치 기한 지연이 발견된 경우 '부분이행' 판정합니다.", "rootcause": ["외부 취약점 제보 접수 채널을 운영하지 않거나 제보된 취약점을 조치하지 않고 방치한 원인은 무엇입니까?", "외부 취약점 제보자에 대해 공식적인 절차 없이 무응답으로 일관하거나 무시한 경위가 있습니까?"], "rootcauseEnd": "취약점 관리 체계 미비로 '미흡' 판정하며, 신고 채널 개설 및 조치 절차 수립을 지시합니다.", "na": ["외부 인터넷 접점이 전혀 없거나 대외 서비스를 단 하나도 제공하지 않아 외부 취약점 제보가 불가능한 환경인지 입증할 수 있습니까?"], "naEnd": "대외 서비스 접점이 존재하지 않음이 확인되면 'N/A' 판정합니다."}, "20-1": {"decisionQ": "신용정보 수집·이용·제공 동의 징구 절차와 만료·철회 관리, 5년 이상 보존 통제가 시스템상 엄격히 이행되고 있습니까? 이를 시스템 화면과 데이터베이스로 보여주실 수 있습니까?", "verify": ["현재 사용 중인 대출 또는 수신 관련 '신용정보 수집·이용·제공 동의서' 서식과 동의 구분(필수/선택, 마케팅 목적 구분 등) 화면을 보여주시겠습니까?", "동의 만료(유효기간 도과) 대상 건을 시스템에서 어떻게 자동으로 식별하여 처리 중단 또는 파기 대상으로 분류하는지 설정 화면이나 로직을 보여주시겠습니까?", "최근 접수된 고객의 동의 철회 이력 1건을 지정할 테니, 해당 고객의 마케팅 전송 중단 처리 및 정보 제공 중단 등록 현황을 시스템에서 보여주시겠습니까?", "5년 이상 경과한 동의 기록(전자문서 또는 DB 이력)이 삭제되지 않고 보존되고 있는지 DB 조회나 보존 설정 정책 화면을 보여주시겠습니까?"], "verifyEnd": "동의 서식의 필수/선택 구분, 만료 관리 로직, 철회 즉시 처리 이력, 5년 이상 보존 설정이 모두 화면 및 DB 조회로 확인되면 양호로 확정합니다.", "partial": ["동의 징구 및 보존은 정상이나, 철회 요청 처리 시 시스템 자동 중단이 아닌 수동 반영 절차로 누락 위험이 존재합니까?", "동의 유효기간 관리가 시스템 자동 통제가 아닌 수기 액셀 형태로 관리되고 있는 이유는 무엇입니까?", "부분적 이행 상태의 원인과 개선 시점은 언제입니까?"], "partialEnd": "수동 관리 방식이나 일부 반영 누락 위험을 확인하고 미흡 항목을 명시하여 개선계획을 요청합니다.", "rootcause": ["동의 철회 처리 시 마케팅 시스템이나 제3자 제공 시스템으로 연동 통제가 이루어지지 않는 이유는 무엇입니까?", "동의 기록 보존 기간(5년) 미달 삭제나 유효기간 도과 건에 대한 자동 중단 로직 부재의 원인은 무엇입니까?", "관련 시스템 미비 조치에 대해 경영진에 보고되었거나 전산 개발 계획이 수립되어 있습니까?"], "rootcauseEnd": "신용정보법 §32 위반 가능성이 높으므로 결함으로 확정하고, 자동 통제 로직 구현 및 철회 절차 개선계획서 제출을 서면 요구합니다.", "na": ["신용정보를 직접 수집하지 않거나 완전 위탁 운영하여 동의 관리 주체가 아닌 근거가 있습니까?", "해당 업무 범위에 대한 법적 예외 규정 문서가 존재하는지 확인해 주시겠습니까?"], "naEnd": "해당없음 판단 근거(업무 미영위 등)를 확인하고 검증을 종료합니다."}, "20-2": {"decisionQ": "업무 목적 외 신용정보 조회 금지 통제, 조회 이력 로그 5년 보존, 비정상 조회 탐지 모니터링이 시스템상 자동 반영되어 있습니까?", "verify": ["직무별/부서별 신용정보 조회 권한 매트릭스 설정 화면을 보여주시겠습니까?", "감사역이 임의로 지정한 직원 1명의 최근 신용정보 조회 이력 로그를 조회하고, 로그 보존 기간이 5년 이상 설정된 정책 화면을 보여주시겠습니까?", "오남용 및 비정상 조회 탐지 패턴(예: 단시간 다량 조회, 본인/친인척 조회 등) 모니터링 규칙 설정 화면을 보여주시겠습니까?", "최근 발생한 비정상 조회 탐지 이벤트 처리 및 소명 확인 보고서 이력을 보여주시겠습니까?"], "verifyEnd": "조회 권한 분리, 로그 5년 보존 설정, 모니터링 탐지 룰 및 소명 처리 이력이 모두 현장 시연으로 확인되면 양호로 확정합니다.", "partial": ["조회 권한은 직무별로 구분되어 있으나 비정상 조회 탐지 모니터링 룰이 일부 수동 검증 방식에 의존하고 있습니까?", "조회 로그는 보존되고 있으나 일부 레거시 화면의 조회 이력이 파라미터 누락으로 저장되지 않는 경우가 있습니까?", "부분적 통제 누락 사유와 보완 계획은 무엇입니까?"], "partialEnd": "모니터링 룰 누락 또는 일부 화면 로그 누락 건을 명시하여 보완을 권고합니다.", "rootcause": ["신용정보 조회 로그의 보존 기간이 5년 미만으로 설정되어 있거나 삭제 배치가 잘못 동작한 이유는 무엇입니까?", "업무와 무관한 직원의 신용정보 조회 권한이 제한 없이 부여된 경위는 무엇입니까?", "비정상 조회 탐지 시스템이 아예 구축되지 않은 사유는 무엇입니까?"], "rootcauseEnd": "신용정보법 §22·38 위반으로 결함 확정하며, 조회 권한 회수 및 로그 보존 강화 조치 계획 제출을 요구합니다.", "na": ["당 저축은행 신용정보를 직접 조회하는 시스템 및 업무가 존재하지 않는 근거가 있습니까?"], "naEnd": "조회 업무 미영위 근거가 확인되면 해당없음으로 처리합니다."}, "20-3": {"decisionQ": "개인신용정보 저장 암호화, 접근 권한 최소화, 접근 로그 90일 이상 보존 및 취약점 점검이 법정 기준을 충족하고 있습니까?", "verify": ["DB 내 개인신용정보(주민등록번호, 계좌번호 등) 저장 암호화 적용 상태를 쿼리 결과(암호화된 문자열)로 보여주실 수 있습니까?", "신용정보 처리시스템(DB/Web/WAS 등)의 접근 권한 부여 현황 및 직무 분리 설정 화면을 보여주시겠습니까?", "개인신용정보 처리시스템 접근 로그 보존 설정이 90일 이상(또는 1년 이상)으로 되어 있음을 설정 파일이나 시스템 화면으로 보여주시겠습니까?", "최근 실시한 신용정보 처리시스템 보안 취약점 점검 결과 보고서 및 조치 완료 이력을 보여주시겠습니까?"], "verifyEnd": "저장 암호화, 접근 권한 최소화, 접근 로그 보존기간, 취약점 조치 완료가 현장 시연 및 문서로 확인되면 양호 확정합니다.", "partial": ["주민번호는 암호화되어 있으나 계좌번호 등 일부 고유식별/신용정보가 평문 저장되어 있습니까?", "접근 로그는 보존되나 로그 백업 장치로의 이관 및 위변조 방지 통제(WORM 또는 Sign)가 일부 누락되었습니까?", "부분적 통제 결함의 원인과 조치 예정일은 언제입니까?"], "partialEnd": "일부 암호화 미적용 대상 및 로그 보호 통제 미비 사항을 지적하여 개선을 요구합니다.", "rootcause": ["개인신용정보가 암호화되지 않고 평문으로 DB 또는 파일 서버에 저장된 원인은 무엇입니까?", "접근 로그 보존 기간 설정이 기준 미달이거나 접근 로그가 보존되지 않은 이유는 무엇입니까?", "보안 취약점 점검에서 발견된 고위험 항목이 장기간 조치되지 않은 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 및 신용정보법 위반으로 결함 확정하고, 즉시 암호화 적용 및 보안 조치 이행계획 수립을 명령합니다.", "na": ["개인신용정보를 직접 저장·처리하지 않는 완전 분리된 독립 시스템인 근거가 있습니까?"], "naEnd": "신용정보 미저장·미처리 근거가 명확하면 해당없음 처리합니다."}, "20-4": {"decisionQ": "법적 근거 없는 신용정보 제3자 제공을 통제하고, 마케팅 목적 사용 시 별도 동의 징구 및 제공 기록 5년 보존을 이행하고 있습니까?", "verify": ["현재 관리 중인 '신용정보 제3자 제공 현황 대장(제공처, 제공목적, 제공항목, 법적근거)'을 보여주시겠습니까?", "마케팅 활용 목적의 신용정보 제공 시, 동의서상 별도 동의(선택적 동의) 항목으로 분리하여 징구한 이력 화면을 보여주시겠습니까?", "제3자 제공 내역이 시스템에 자동으로 기록되고 있으며, 해당 기록이 5년간 보존되는지 DB 조회를 통해 보여주시겠습니까?", "법적 근거(법령상 의무, 고객 동의 등)가 없는 임의 제공을 차단하는 승인 통제 절차 문서 및 승인 결재 이력을 보여주시겠습니까?"], "verifyEnd": "제3자 제공 대장 관리, 마케팅 별도 동의, 제공 내역 자동 기록 및 5년 보존이 모두 검증되면 양호 확정합니다.", "partial": ["제3자 제공 내역은 기록되나 일부 파일 형태 제공(수기 추출 연동) 건에 대한 이력 관리가 누락되어 있습니까?", "마케팅 제공 동의는 받으나 동의 철회 시 제3자 제공처로의 실시간 철회 통보 연동이 지연되고 있습니까?", "부분적 통제 누락 사유 및 보완 계획을 설명해 주시겠습니까?"], "partialEnd": "수동 추출건 누락 및 철회 연동 지연에 대한 원인을 파악하고 보완대책 제출을 수립토록 합니다.", "rootcause": ["법적 근거나 정보주체 동의 없이 신용정보가 제3자에게 제공된 내역이 존재하는 이유는 무엇입니까?", "제3자 제공 기록이 5년 동안 보존되지 않고 삭제되거나 관리가 안 된 원인은 무엇입니까?", "마케팅 목적 이용 시 필수 동의와 선택 동의를 구분하지 않고 일괄 동의받은 이유는 무엇입니까?"], "rootcauseEnd": "신용정보법 §32·33 위반으로 결함 처리하고, 제3자 제공 즉시 중단 및 법적 처리 절차를 검토합니다.", "na": ["신용정보를 제3자에게 제공하거나 마케팅 목적으로 외부 활용하는 업무가 전혀 없는 근거가 있습니까?"], "naEnd": "제3자 제공 업무 전무함이 문서로 입증되면 해당없음 처리합니다."}, "20-5": {"decisionQ": "중앙회와의 DB 동기화 작업 후 건수 및 금액 합계 검증 절차와 불일치 발생 시 대응 프로세스가 자동으로 작동하고 있습니까?", "verify": ["익일 DB 동기화(저축은행중앙회 ↔ 당행 원장) 완료 후 자동 수행되는 건수·금액 합계 검증 배치는 어떻게 작동하는지 관련 스크립트나 모니터링 화면을 보여주시겠습니까?", "최근 1개월간 작성된 'DB 동기화 검증 이력 및 결과 보고서(또는 시스템 로그)'를 보여주시겠습니까?", "동기화 불일치 발생 시 담당자 알림(SMS/이메일), 원인 파악, 재동기화 및 보고 절차가 규정된 지침서를 보여주시겠습니까?", "가장 최근에 동기화 오류/불일치가 발생했던 사례 1건의 조치 완료보고서 및 원장 수정 이력을 보여주시겠습니까?"], "verifyEnd": "검증 배치 자동화, 매일 검증 이력 확인, 불일치 대응 절차서 및 실제 오류 조치 이력이 모두 확인되면 양호 확정합니다.", "partial": ["동기화 검증이 이루어지나 시스템 자동 검증이 아닌 담당자 수동 쿼리 수행 방식에 의존합니까?", "건수 검증은 자동화되어 있으나 금액 합계 검증 로직이 누락되어 있습니까?", "수동 작업에 따른 오류 위험 및 개선 일정은 어떻게 됩니까?"], "partialEnd": "수동 검증에 따른 무결성 검증 누락 위험을 지적하고 배치 자동화 구현을 권고합니다.", "rootcause": ["중앙회 DB 동기화 후 건수/금액 검증을 실시하지 않거나 검증 실패 알림을 무시한 이유는 무엇입니까?", "동기화 불일치 발생 시 표준 조치 절차 없이 임의로 원장을 수정해온 경위는 무엇입니까?", "동기화 검증 이력이 시스템에 기록 보존되지 않는 원인은 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §34 위반 및 데이터 무결성 훼손으로 결함 처리하며 자동 검증 로직 및 조치 절차 정비를 명령합니다.", "na": ["중앙회 코어뱅킹을 사용하지 않고 자체 단독 원장만을 사용하여 중앙회 간 DB 동기화 프로세스가 존재하지 않는 근거가 있습니까?"], "naEnd": "중앙회 동기화 대상 업무가 아님이 입증되면 해당없음 처리합니다."}, "20-6": {"decisionQ": "보유기간이 도과한 개인신용정보를 지체 없이 복구 불가능한 방법으로 파기하고 이력 대장을 통제하고 있습니까?", "verify": ["거래 종료 후 법정 보유기간(예: 5년)이 도과한 개인신용정보 대상자를 식별하여 자동 파기하는 배치 프로그램 및 파기 기준을 보여주시겠습니까?", "DB 레코드 덮어쓰기(Shredding) 또는 전자적 파일 복구 불가 파기 알고리즘이 적용되었음을 증명하는 기능 설명서나 스크립트를 보여주시겠습니까?", "최근 실시한 '개인신용정보 파기 이력 대장'을 보여주시고, 파기 일시, 건수, 파기 담당자, 승인자 내역을 확인해 주시겠습니까?", "파기 완료 후 해당 데이터가 실제 DB나 백업본에서 복구 불가능함을 검증한 테스트 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "자동 파기 로직, 복구 불가 파기 방식, 파기 대장 관리, 복구 불가 검증 보고서가 모두 확인되면 양호 확정합니다.", "partial": ["운영 DB의 신용정보는 파기되었으나, 백업 매체(테이프/DB 백업) 내 정보는 파기 주기 분리로 인해 잔존해 있습니까?", "파기는 진행되었으나 파기 대장의 필수 기재 사항이 일부 누락되었거나 승인 절차가 수동으로 수행됩니까?", "백업 매체 파기 방안 및 관리 절차 보완 계획은 무엇입니까?"], "partialEnd": "백업 매체 신용정보 파기 지연 및 대장 관리 수동화에 따른 미흡 사항을 지적하고 개선을 요청합니다.", "rootcause": ["보유기간 도과 신용정보가 파기되지 않고 운영 DB에 그대로 방치된 원인은 무엇입니까?", "파기 시 복구 가능한 단순 Delete 쿼리만 사용하거나, 파기 이력 대장 자체를 작성하지 않은 경위는 무엇입니까?", "신용정보 파기 업무 담당자 및 승인 절차가 지정되지 않은 이유는 무엇입니까?"], "rootcauseEnd": "신용정보법 §20의2 및 개인정보보호법 §21 위반으로 결함 확정하고, 즉시 파기 수행 및 복구 불가능 조치 결과를 서면 보고하도록 명령합니다.", "na": ["당 저축은행이 설립된 지 얼마 되지 않아 법정 보유기간(5년)이 경과한 신용정보가 단 1건도 존재하지 않는 근거가 있습니까?"], "naEnd": "보유기간 경과 데이터 미존재 근거 확인 시 해당없음 처리합니다."}, "20-7": {"decisionQ": "신용정보 유출·분실 시 즉시 신고·통지 절차가 수립되어 있고, 사고 분석 및 재발방지대책, 모의훈련을 정기적으로 실시하고 있습니까?", "verify": ["신용정보 유출·분실 인지 시 즉시 보고, 금융위(금감원) 신고, 정보주체 통지 절차가 명시된 '사고 대응 매뉴얼'을 보여주시겠습니까?", "신용정보 유출 사고에 대비해 연 1회 이상 실시한 '신용정보 유출 대응 모의훈련 결과 보고서' 및 훈련 시연 증빙을 보여주시겠습니까?", "최근 유출·분실 사고(또는 의심 상황) 발생 시 금융위 신고서, 정보주체 통지문 발송 이력 및 사고 원인 분석 보고서를 보여주시겠습니까?", "유출 사고 원인 분석에 따른 재발 방지 대책 이행 완료 확인서를 보여주시겠습니까?"], "verifyEnd": "유출 대응 매뉴얼, 모의훈련 정기 실시 증빙, (사고 발생 시) 즉시 신고/통지 이력 및 재발방지 조치가 확인되면 양호 확정합니다.", "partial": ["유출 대응 매뉴얼과 신고 절차는 존재하나, 모의훈련이 문서상으로만 작성되고 실제 훈련 시연이 수행되지 않았습니까?", "정보주체 통지 양식 및 채널(SMS/이메일 등)은 준비되었으나 실제 발송 시스템 연동 테스트가 수행되지 않았습니까?", "모의훈련 미실시 원인 및 향후 실효성 확보 대책은 무엇입니까?"], "partialEnd": "모의훈련 실효성 부족 및 시스템 미비점을 지적하여 실제 훈련 수행을 권고합니다.", "rootcause": ["신용정보 유출 인지 시 금융위 및 정보주체 통지 법정 시한(즉시)을 지키지 못하도록 매뉴얼이 누락된 원인은 무엇입니까?", "유출 사고 발생에도 불구하고 원인 분석이나 재발 방지 대책 수립을 이행하지 않은 이유는 무엇입니까?", "유출 대응 모의훈련을 장기간(1년 이상) 전혀 실시하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "신용정보법 §39의4 위반으로 결함 처리하며, 유출 대응 절차 재정립 및 비상 모의훈련 즉시 실시를 명령합니다.", "na": ["신용정보를 보관·처리하지 않는 위탁기관으로서 유출 신고 대리 의무가 완전히 면제된 근거가 있습니까?"], "naEnd": "유출 신고 주체가 아님이 명확히 입증되면 해당없음 처리합니다."}, "16-1": {"decisionQ": "경영진 승인을 받은 최신 BCP/DRP 계획서와 연 1회 이상 검토·개정한 이력 및 담당자 배포 확인서명을 지금 바로 보여주실 수 있습니까?", "verify": ["경영진(CISO 또는 대표이사) 최종 결재가 완료된 BCP/DRP 최신 문서의 전자결재 이력을 화면으로 보여주시겠습니까?", "최근 1년 이내 조직 개편이나 신규 IT시스템 도입 사항이 BCP/DRP 개정 개정이력(Version History)에 정확히 반영되었는지 보여주시겠습니까?", "비상대책본부 구성원 및 핵심 업무 담당자들에게 최신 BCP/DRP 문서가 배포된 내역이나 서명부를 확인해주시겠습니까?", "계획서에 명시된 비상대책 실행 우선순위 및 조직별 역할 정의가 현재 부서 체계와 일치하는지 설명해주시겠습니까?"], "verifyEnd": "경영진 승인 문서, 연 1회 이상 개정이력, 조직·시스템 변경사항 반영, 담당자 배포·숙지 여부가 모두 입증되면 양호로 확정합니다.", "partial": ["BCP/DRP 계획서는 존재하고 경영진 승인도 받았으나, 최근 조직 변경이나 IT infrastructure 변경사항이 누락된 이유는 무엇입니까?", "연 1회 정기 검토는 이루어졌으나 실제 배포 및 담당자 확인 서명 절차가 일부 미흡한 상태입니까?", "개선 필요성을 인지하고도 개정 작업을 지연시킨 사유는 무엇이며, 미반영된 항목의 개정 완료 예정일은 언제입니까?"], "partialEnd": "계획서의 골격은 갖추어졌으나 최신성 유지나 배포 관리가 미흡하므로, 1개월 이내 보완 개정 및 배포를 조건으로 부분이행 판정합니다.", "rootcause": ["BCP/DRP 계획서 자체가 미수립되어 있거나, 경영진 승인 없이 방치된 규정 문서만 존재하는 원인은 무엇입니까?", "전자금융감독규정 제29조에 따른 비상대책 수립 의무를 담당 부서 및 경영진이 인지하고 있었습니까?", "계획서 미작성 또는 미갱신 상태에 대해 내부감사나 위험관리위원회에서 지적된 적이 있습니까?"], "rootcauseEnd": "BCP/DRP 미수립 또는 장기 미갱신은 중대한 통제 결함(NO)으로 확정하고, 즉시 계획 수립 및 경영진 보고를 서면 요청합니다.", "na": ["이 항목을 해당없음(N/A)으로 판단하신 개별 법적·운영적 근거가 있습니까? (저축은행업권 특성상 N/A 불인정 대상)", "IT업무 전체를 중앙회 등에 100% 위탁하여 자체 BCP 수립 의무가 제외된다고 판단하신 것입니까?"], "naEnd": "전자금융감독규정상 저축은행은 필수 적용 대상이므로, N/A 신청 타당성이 없음을 안내하고 통제 미흡(NO) 또는 평가 진행으로 전환합니다."}, "16-2": {"decisionQ": "핵심 업무시스템별로 설정된 RTO·RPO 목표 문서, 경영진 승인 결재서, 그리고 금감원 권고기준(RTO 3시간 등) 준수 현황표를 보여주실 수 있습니까?", "verify": ["핵심 업무(계정계, 여수신, 인터넷뱅킹 등)별 RTO·RPO가 명시된 표준 문서와 경영진 승인 결재 문서를 제시해주시겠습니까?", "금융감독원 가이드라인(예: 핵심 업무 RTO 3시간 이내 등) 대비 자사의 목표 설정치 비교표를 조회해주시겠습니까?", "최근 실시한 DR 훈련 결과 보고서에서 실제 측정된 복구시간이 설정된 RTO·RPO 목표치를 충족했는지 측정 데이터를 보여주시겠습니까?", "RTO/RPO 목표를 초과한 시스템이 존재할 경우, 이에 대한 원인 분석 및 기술적 개선 계획이 마련되어 있습니까?"], "verifyEnd": "경영진 승인 RTO/RPO 설정, 금감원 권고기준 부합, DR 훈련을 통한 실제 목표 달성이 증명되면 양호로 확정합니다.", "partial": ["업무별 RTO/RPO는 수립되어 있으나 일부 비핵심 시스템의 목표가 누락되었거나, 금감원 권고기준보다 현저히 길게 설정된 사유는 무엇입니까?", "훈련 결과 RTO 목표를 일부 초과했음에도 재설정이나 기술적 보완 작업이 지연되고 있는 이유는 무엇입니까?"], "partialEnd": "핵심 업무 RTO/RPO는 존재 하나, 일부 시스템 누락 또는 훈련 시 목표 미달성에 대한 보완조치가 미흡하여 부분이행 판정합니다.", "rootcause": ["핵심 업무시스템에 대한 RTO·RPO 목표 자체가 정의되지 않았거나 경영진 승인을 받지 않은 원인은 무엇입니까?", "RTO/RPO 개념이 IT 복구절차에 반영되지 않아 복구 우선순위 판단 기준이 부재한 상태입니까?"], "rootcauseEnd": "RTO/RPO 미설정은 재해 발생 시 복구 지연으로 인한 심각한 피해를 초래하므로 NO(미흡)로 확정하고 시정을 요구합니다.", "na": ["저축은행 주요 시스템 중 RTO·RPO 설정 대상에서 제외할 수 있는 업무가 있는지 법적/기술적 타당성을 제시할 수 있습니까?"], "naEnd": "전자금융감독규정 제30조에 따라 핵심 전자금융업무의 RTO/RPO 설정은 의무이므로 N/A를 불인정합니다."}, "16-3": {"decisionQ": "최근 수행한 업무영향분석(BIA) 보고서와 BIA 분석 결과(핵심 업무/재무·운영 영향)가 BCP 계획에 반영된 내역을 보여주실 수 있습니까?", "verify": ["가장 최근 정기 또는 수시로 수행된 BIA(Business Impact Analysis) 최종 보고서를 화면으로 제시해주시겠습니까?", "BIA 보고서 내에서 핵심 업무 프로세스와 연계 IT시스템, 중단 시 시간대별 재무적·법적·평판 손실 평가 내역을 보여주시겠습니까?", "BIA 분석 결과 도출된 핵심 업무 목록과 BCP 계획서상의 우선 복구 대상 업무 목록이 정확히 일치하는지 대조해주시겠습니까?", "신규 IT 서비스 구축이나 조직 변경 시 BIA를 재수행한 정기/수시 업데이트 개정이력을 보여주시겠습니까?"], "verifyEnd": "BIA 정기 수행, 영향 평가의 구체성, BIA 결과의 BCP 반영 및 정기 업데이트 이력이 확인되면 양호로 확정합니다.", "partial": ["BIA를 수행하였으나 재무적/운영적 영향 분석이 정량적으로 이루어지지 않고 형식적으로 작성된 이유는 무엇입니까?", "BIA 결과 도출된 핵심 업무 변경 사항이 BCP 계획서에 즉시 반영되지 않고 시차가 발생하는 이유는 무엇입니까?"], "partialEnd": "BIA 수행 실적은 있으나 분석 깊이가 미흡하거나 BCP와의 연계가 완벽하지 않아 부분이행 판정합니다.", "rootcause": ["BIA(업무영향분석)를 수행한 이력이 전혀 없거나, 과거 수년 간 정체되어 있는 원인은 무엇입니까?", "BIA 수행 없이 임의로 핵심 업무 및 복구 순서를 지정하여 발생할 수 있는 리스크를 알고 계십니까?"], "rootcauseEnd": "BIA 미수행은 비상대책 수립의 기초 통제 결함(NO)이므로, BIA 방법론 수립 및 즉시 수행을 요구합니다.", "na": ["저축은행 업무 중 BIA 대상에서 완전 제외할 수 있는 업무영역이 존재한다고 판단하는 근거가 있습니까?"], "naEnd": "ISMS-P 및 금융 보안 표준상 저축은행 전체 업무 대상 BIA 수행은 필수이므로 N/A를 인정하지 않습니다."}, "16-4": {"decisionQ": "주센터와 원격지 DR 사이트 간 계약서, 위치 독립성, 데이터 실시간 동기화 설정 화면 및 자동/수동 Failover 구성도를 보여주실 수 있습니까?", "verify": ["원격지 DR 사이트 임차 계약서 또는 자체 센터 보유 증빙을 통해 주센터와 소정 거리(예: 30km 이상) 이격된 물리적 위치를 확인해주시겠습니까?", "주센터 DB와 DR센터 DB 간 데이터 동기화 방식(Mirroring, CDC 등) 및 동기화 지연(Lag) 상태를 스토리지/DB 관리화면에서 실시간으로 보여주시겠습니까?", "네트워크 및 서버의 Failover(비상절체) 설정 및 자동/수동 절체 시나리오가 담긴 DR 구성도를 보여주시겠습니까?", "주센터 완파 시에도 DR 사이트에서 독자적으로 업무 처리가 가능한 HW/SW 인프라 및 전용회선 보유 현황을 입증해주시겠습니까?"], "verifyEnd": "DR 사이트 물리 이격, 실시간 데이터 동기화, Failover 구성 및 독자 운영 능력이 화면/서류로 입증되면 양호로 확정합니다.", "partial": ["DR 사이트는 확보되어 있으나 주센터와의 물리적 이격 거리가 지나치게 가깝거나 동일 지역 재해 위험에 노출된 이유는 무엇입니까?", "데이터 동기화가 실시간이 아닌 주기적 배치(Batch) 방식으로 운영되어 RPO 달성에 한계가 있는 상태입니까?", "일부 비핵심 모듈의 경우 DR 사이트 구성에서 제외되어 완전 독립 운영에 제약이 있습니까?"], "partialEnd": "DR 사이트는 구축되어 있으나 동기화 주기나 이격거리 등에서 일부분 미흡함이 존재하여 부분이행 판정합니다.", "rootcause": ["DR 사이트 자체가 구축되지 않았거나, 계약 종료 후 재계약이 이루어지지 않은 원인은 무엇입니까?", "전자금융감독규정 제30조에 따른 재해보복구센터 설치 의무를 준수하지 못한 재정적/기술적 사유는 무엇입니까?"], "rootcauseEnd": "DR 사이트 미비는 저축은행 IT 운영에 치명적인 중대 결함(NO)으로 확정하며 규정 준수를 위한 긴급 시정조치를 요구합니다.", "na": ["저축은행이 DR 사이트를 직접 구축하지 않아도 되는 법적 면제 조건에 해당한다고 판단하는 근거가 있습니까?"], "naEnd": "전자금융업자 및 저축은행은 DR 사이트 구축이 법적 의무 사항이므로 N/A 신청을 불인정합니다."}, "16-5": {"decisionQ": "연 1회 이상 실시한 DR 실전 훈련 계획서, 실제 절체 수행 결과 보고서(RTO·RPO 달성측정 포함), 그리고 외부 이해관계자(ITO·중앙회) 참여 증적을 보여주실 수 있습니까?", "verify": ["최근 1년 이내에 수행된 연간 DR 복구 훈련 계획서 및 경영진 승인문서를 제시해주시겠습니까?", "훈련 당시 주센터에서 DR센터로 실제 업무를 절체하여 수행한 시나리오 및 시간대별 훈련 타임라인 기록을 보여주시겠습니까?", "훈련 결과 보고서에 기록된 실제 복구 소요시간이 RTO·RPO 목표를 달성했는지, 미달 시 개선과제가 도출되었는지 보여주시겠습니까?", "IT 외주업체(ITO) 및 저축은행 중앙회 등 외부 연계기관이 훈련에 실제로 동참한 서명부 또는 훈련 공문을 확인해주시겠습니까?"], "verifyEnd": "연 1회 이상 실전 DR 훈련 실시, RTO/RPO 달성 검증, 도출된 개선사항 반영, 연계기관 참여 증적이 모두 확인되면 양호로 확정합니다.", "partial": ["DR 훈련은 실시하였으나 실제 시스템 절체 없이 서면/도상 훈련 방식으로 단순 대체된 이유는 무엇입니까?", "훈련 시 도출된 문제점 및 개선 요구사항에 대한 조치 이행 계획(CAPA) 수립이 지연되고 있습니까?", "중앙회나 외주 개발사 등 주요 연계기관이 훈련 대상에서 제외되어 모의 훈련만 진행되었습니까?"], "partialEnd": "훈련 실적은 있으나 서면 훈련에 치우쳐 있거나 도출된 문제점의 개선 조치가 완료되지 않아 부분이행 판정합니다.", "rootcause": ["최근 1년 이상 DR 복구 훈련을 전혀 실시하지 않은 원인은 무엇입니까?", "전자금융감독규정 제31조에 명시된 정기적 비상대책 훈련 의무 위반에 대한 사유와 책임 소재는 어떻게 됩니까?"], "rootcauseEnd": "연간 DR 훈련 미실시는 재해대응 통제의 중대한 결함(NO)으로 확정하고 사유서 제출 및 즉시 훈련 실시를 요구합니다.", "na": ["저축은행 IT 사정상 정기 DR 훈련을 면제받을 수 있는 정당한 법적 근거가 있습니까?"], "naEnd": "전자금융감독규정상 연 1회 이상 DR 훈련은 강제 규정이므로 N/A 처리가 불가합니다."}, "16-6": {"decisionQ": "임임직원·ITO·저축은행중앙회·금감원 등이 포함된 최신 비상연락망과 분기 1회 이상 실시한 연락망 유효성 점검(전화/문자 발송) 이력서를 보여주실 수 있습니까?", "verify": ["주요 비상 연락망(임직원, IT 외주업체, 저축은행중앙회, 금감원, 유지보수업체) 통합 최신 문서나 시스템 화면을 보여주시겠습니까?", "최근 1년 이내 분기별로 실시한 비상연락망 유효성 점검(실제 비상소집훈련, SMS 비상발송 테스트, 응답률 집계 등) 보고서를 제시해주시겠습니까?", "최근 인사이동이나 조직 개편 시 비상연락망이 즉시 업데이트된 변경 관리 이력(Version/Log)을 확인해주시겠습니까?", "비상연락망 문서가 개인정보보호 관리를 위해 권한자에게만 안전하게 보관·배포되고 있는지 통제 상태를 설명해주시겠습니까?"], "verifyEnd": "최신 비상연락망 완비, 분기 1회 이상 유효성 점검, 인사이동 즉시 반영, 개인정보 통제 관리가 입증되면 양호로 확정합니다.", "partial": ["비상연락망은 관리되고 있으나 중앙회나 금융당국 등 대외기관 비상연락처 누락 또는 전찬 변경이 지연된 이유는 무엇입니까?", "연락망 점검을 분기가 아닌 반기/연간 단위로 수행하거나 일부 부서의 응답 확인이 누락된 상태입니까?"], "partialEnd": "비상연락망은 존재하나 유효성 점검 주기가 길거나 일부 연락처의 최신성이 떨어져 부분이행 판정합니다.", "rootcause": ["비상연락망 자체가 수년 전 자료로 방치되어 있거나, 퇴사자/보직변경자가 그대로 남아있는 원인은 무엇입니까?", "비상 시 즉시 연락을 취할 수 있는 비상소집 및 통지 체계가 전무한 사유는 무엇입니까?"], "rootcauseEnd": "비상연락망 부실 및 점검 미실시는 비상 시 즉각 대응을 불가능하게 하므로 결함(NO)으로 확정합니다.", "na": ["비상연락망 관리 항목을 적용하지 않아도 되는 특수 상황이 존재합니까?"], "naEnd": "모든 금융기관에 필수적인 비상대책 기본 요소이므로 N/A를 불인정합니다."}, "16-7": {"decisionQ": "저축은행중앙회 계정계 시스템 장애 발생 시 적용되는 자체 비상처리 절차서, 데이터 재동기화 매뉴얼, 및 최근 연계 테스트 이력을 보여주실 수 있습니까?", "verify": ["중앙회 계정계 장애 시 당 저축은행 내부 수신/여신/창구 업무 처리용 자체 비상 대응 절차서(SOP)를 제시해주시겠습니까?", "중앙회 시스템 복구 후 비상 처리 기간 동안 발생한 수기/단독 타사 트랜잭션 데이터를 중앙회 원장과 재동기화(Reconciliation)하는 세부 매뉴얼을 보여주시겠습니까?", "중앙회 연계 장애 상황을 가정한 비상 대응 및 데이터 재동기화 훈련/테스트 수행 결과서를 보여주시겠습니까?", "중앙회 장애 발생 시 고객 안내 및 영업점 수기 집계 서식 보관 관리 체계가 정립되어 있습니까?"], "verifyEnd": "중앙회 장애 대비 자체 비상절차, 데이터 재동기화 절차 명확화, 정기 연계 테스트 결과가 확인되면 양호로 확정합니다.", "partial": ["중앙회 장애 대비 비상 절차서는 있으나, 복구 후 데이터 재동기화(원장 대조 및 맞춤) 절차가 모호하거나 수기 작업에 의존하여 리스크가 존재하는 사유는 무엇입니까?", "중앙회 비상 연계 테스트를 정기적으로 수행하지 않고 중앙회 통보에만 의존하여 자체 검증이 부족한 상태입니까?"], "partialEnd": "중앙회 비상절차는 존재하나 재동기화 절차가 미흡하거나 테스트 실적이 부족하여 부분이행 판정합니다.", "rootcause": ["중앙회 장애 시 당 저축은행의 업무 연속성을 유지하기 위한 비상절차서 자체가 수립되어 있지 않은 원인은 무엇입니까?", "중앙회 장애는 중앙회의 책임으로만 간주하여 자체 비상대책 수립을 도모하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "중앙회 연계 비상절차 미비는 중앙회 장애 시 영업 중단을 초래하므로 NO(미흡)로 확정하고 절차 수립을 요구합니다.", "na": ["저축은행이 중앙회 계정계를 이용하지 않고 100% 자체 계정계 시스템만 사용하고 있어 본 항목이 해당 없는지 증명할 수 있습니까?"], "naEnd": "자체 계정계를 완전 보유하여 중앙회 연계가 전혀 없는 저축은행의 경우에 한해 '해당없음(N/A)'으로 인정합니다."}, "16-8": {"decisionQ": "전력 이중화(UPS 및 자가발전기) 구성도, 통신 회선 물리적 이중화(다변화) 계약서, 단일장애점(SPOF) 식별 보고서 및 절체 테스트 결과를 보여주실 수 있습니까?", "verify": ["전산실 전력 공급용 UPS(무정전 전원장치) 이중화 및 비상 자가발전기 설비 명서와 용량 점검표를 제시해주시겠습니까?", "인터넷 및 전용 회선이 서로 다른 통신사업자(ISP) 또는 서로 다른 인입 관로를 통해 물리적으로 이중화되어 있음을 입증하는 계약서/구성도를 보여주시겠습니까?", "IT 인프라(서버, 스위치, 방화벽, 전력, 통신 등) 전체에 대한 단일장애점(SPOF) 식별 분석서와 점검 결과를 제시해주시겠습니까?", "최근 실시한 UPS 정전대비 절체 훈련 및 통신 회선 자동 절체(Failover) 테스트 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "전력/통신 물리적 이중화 완비, SPOF 제거, 정기적인 전력/통신 절체 테스트 결과가 입증되면 양호로 확정합니다.", "partial": ["통신 회선은 2개 회선을 사용 중이나 동일 통신사이거나 통신사 인입관로가 하나로 겹쳐 완벽한 물리적 이중화가 아닌 사유는 무엇입니까?", "UPS는 설치되어 있으나 비상발전기가 없거나, 발전기 유류 관리 및 정기 시동 점검이 일부 누락되어 있습니까?", "일부 상단 스위치나 보안 장비에 SPOF가 존재함에도 개선 예산 미반영으로 방치된 상태입니까?"], "partialEnd": "이중화 형태는 갖추었으나 동일 인입관로 사용, 비상발전기 용량 부족 등 부분적 SPOF가 존재하여 부분이행 판정합니다.", "rootcause": ["전력(UPS) 또는 인터넷/대외 통신회선이 단일 구성(Single Line)으로 운영되어 한 번의 장애로 전산실 전체가 마비될 위험에 노출된 원인은 무엇입니까?", "전자금융감독규정 제29조에 명시된 전력 및 통신회선 이중화 의무를 준수하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "전력·통신 단일점 장애(SPOF) 방치는 치명적 IT 통제 결함(NO)으로 확정하고 즉시 이중화 구축 계획을 요구합니다.", "na": ["저축은행 전산실의 전력/통신 이중화 의무를 면제받을 수 있는 법적 예외 조항이 존재합니까?"], "naEnd": "전자금융감독규정상 전력 및 통신회선 이중화는 필수 물리적 보안 요건이므로 N/A를 불인정합니다."}, "17-1": {"decisionQ": "수집하는 개인정보 항목별로 법적 근거(동의, 법령상 의무, 계약이행 등)를 정리한 '개인정보 수집 법적 근거 매핑표'와 이를 실제 수집하는 DB 테이블·화면 명세서를 지금 현장에서 대조해 보여주실 수 있습니까?", "verify": ["개인정보 처리 내역서 및 매핑표에서 법령상 의무 수집 항목(예: 금융실명법, 테러자금방지법 등)과 계약 이행 항목, 동의 필요 항목이 명확히 구분되어 있는지 확인해 주시겠습니까?", "감사역이 무작위로 지적하는 신규 여·수신 상품(또는 앱 화면 1개)의 실제 수집 입력 폼과 매핑표의 항목이 1:1로 일치하는지 화면으로 보여주시겠습니까?", "최근 1년 내 관계 법령 제·개정 시 수집 법적 근거를 재검토하고 매핑표 및 처리방침에 반영한 이력 문서를 제시해 주시겠습니까?"], "verifyEnd": "개인정보 수집 항목 전체에 대해 법적 근거가 1:1로 매핑되어 있고, 현장 무작위 대조 시 수집 폼과 일치하며, 법령 변경에 따른 재검토 절차가 작동함이 확인되면 양호로 판정합니다.", "partial": ["수집 항목에 대한 법적 근거 매핑표는 존재하나, 최근 신규 출시된 서비스나 앱 화면의 수집 항목이 누락되어 있는 이유는 무엇입니까?", "법령 의무 수집 항목과 일반 동의 수집 항목이 일부 혼재되어 구분 관리되지 않는 원인은 무엇입니까?", "누락되거나 미비한 항목에 대해 법적 근거 재검토 및 매핑표 현행화를 언제까지 완료할 계획입니까?"], "partialEnd": "일부 항목의 매핑 누락 또는 현행화 지연을 특정하여 보완을 권고하고, 매핑표 전수 재검토 계획 제출을 요청합니다.", "rootcause": ["법적 근거 없이 수집되고 있는 개인정보 항목이 존재하는 경위와 이유가 무엇입니까?", "신규 개발 및 서비스 출시 과정에서 개인정보 보호담당자(CPO)의 수집 법적 근거 사전 검토 절차가 누락된 이유는 무엇입니까?", "법적 근거 없는 수집 행위에 대해 상급자 보고나 자체 점검을 통한 개선 시도가 있었습니까?"], "rootcauseEnd": "법적 근거 없는 개인정보 수집은 개인정보보호법 제15조 위반으로 즉시 결함 처리하며, 불필요 수집 항목 파기 및 개발 통제 절과 개선계획 제출을 서면 요구합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거가 개인정보를 전혀 수집·처리하지 않는 시스템이기 때문입니까?", "해당 시스템이 신용정보 및 개인고객 정보와 완전히 분리되어 있음을 네트워크 구성도 및 DB 명세서로 증명할 수 있습니까?"], "naEnd": "고객 및 임직원의 개인정보 수집이 전혀 발생하지 않는 전용 시스템임이 증명되면 타당한 N/A로 인정합니다."}, "17-2": {"decisionQ": "전자금융 및 영업 창구에서 사용하는 개인정보 수집·이용 동의서에서 필수항목과 선택항목이 명확히 구분되어 있고, 동의 철회 기능이 시스템적으로 구현되어 있음을 시연해 주실 수 있습니까?", "verify": ["모바일·웹의 수집 동의 화면을 열어 필수 동의와 선택 동의가 별도 체크박스로 분리되어 있고 체크가 강제되지 않음을 보여주시겠습니까?", "선택 항목 동의를 거부하더라도 기본 서비스(대출/적금 가입 등) 제공이 정상 진행됨을 실제 시연해 주시겠습니까?", "고객이 모바일 앱 또는 원스톱 창구에서 직접 동의를 철회할 수 있는 화면과 철회 즉시 DB에 철회 로그가 남는 모습을 확인시켜 주시겠습니까?"], "verifyEnd": "필수/선택 구분, 거부 시 불이익 고지, 선택동의 거부 시 서비스 정상 제공, 철회 절차의 용이성 및 동의 이력 저장 로그가 모두 확인되면 양호로 확정합니다.", "partial": ["필수/선택 항목은 구분되어 있으나, 선택 동의 거부 시 특정 기본 기능 이용에 제한을 두는 오류가 발생하는 이유는 무엇입니까?", "동의 철회 기능은 존재하나 콜센터나 영업점 방문으로만 처리 가능하여 접수·처리 절차가 번거로운 이유는 무엇입니까?", "선택 동의 철회 건에 대한 마케팅 중단 조치가 완료되기까지 시차가 발생하는 원인과 개선 계획은 무엇입니까?"], "partialEnd": "동의 철회 채널의 제한성 및 처리 시차 발생 등 부분 미흡 사항을 지정하여 시스템 자동화 개선계획 제출을 요구합니다.", "rootcause": ["필수 항목과 선택 항목을 하나로 묶어서 일괄 동의를 받고 있는 이유가 무엇입니까?", "동의 거부 시 서비스 이용이 불가능하다는 사실과 상관없는 불이익 고지문이 포함되거나 아예 고지하지 않은 경위는 무엇입니까?", "동의 일시, 항목, 동의자 ID 등 법적 동의 기록이 DB에 누락되거나 변조 방지 조치가 안 된 원인은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제22조(동의를 받는 방법) 위반으로 결함 확정하며, 필수/선택 분리 화면 즉시 수정 및 동의 기록 로그 보강을 명령합니다.", "na": ["이 항목이 '해당없음'에 해당하는 시스템입니까? 동의 징구 주체가 타 법인이거나 내부 관리 전용 시스템입니까?", "정보주체(고객/임직원)로부터 직접 동의서를 받지 않는 시스템임을 증빙하는 업무 흐름도를 제시할 수 있습니까?"], "naEnd": "고객 접점이 전혀 없고 개인정보 동의 징구 행위 자체가 없는 내부 백엔드 시스템임이 확인되면 N/A 처리합니다."}, "17-3": {"decisionQ": "신용정보법에 따른 개인신용정보 조회·제공 동의 징구 체계와 유효기간 만료 관리 및 동의 철회 시 처리 중단(마케팅 등)이 자동 연동되어 있습니까?", "verify": ["신용정보 수집·이용·제공 동의서 서식에서 신용조회회사(CB사) 조회 동의, 제3자 제공 동의, 마케팅 이용 동의가 별도로 분리 징구됨을 확인해 주시겠습니까?", "동의 유효기간(예: 1년~5년 등)이 지난 고객 데이터를 자동 탐지하거나 유효기간 만료 시 재동의/파기하는 배치 프로그램 명세 및 수행 로그를 보여주시겠습니까?", "신용정보 동의 철회를 요청한 특정 고객 계정을 시스템에서 조회하여, 마케팅 발송 대상 및 제3자 제공 대상에서 즉시 제외 처리된 현황을 확인시켜 주시겠습니까?", "동의 기록 DB 테이블에서 5년 이상 안전하게 보존·관리되고 있음을 데이터 구조와 함께 보여주시겠습니까?"], "verifyEnd": "신용정보 동의서의 적법성, 유효기간 자동 통제, 철회 처리 중단 즉시 이행, 5년 이상 동의 기록 보존이 모두 확인되면 양호로 확정합니다.", "partial": ["신용정보 동의 철회 접수 후 실제 마케팅 대상 제외 및 조회 중단 처리까지 수동으로 개입하여 반영 지연이 발생하는 이유는 무엇입니까?", "동의 유효기간 만료 관리 정책은 수립되어 있으나, 관련 자동 배치 프로그램이 미작동하여 수동 추출에 의존하는 원인은 무엇입니까?", "철회 건의 처리 중단 프로세스 자동화 개선 일정을 제출할 수 있습니까?"], "partialEnd": "동의 철회 반영 지연 및 유효기간 관리 수동 운영 등 부분 미흡 사항을 지적하고 전산 자동화 조치 이행을 요구합니다.", "rootcause": ["동의 유효기간이 만료된 신용정보에 대해 조회나 이용을 지속하고 있는 경위는 무엇입니까?", "신용정보 동의 철회 요청이 접수되었음에도 타 부서나 제3자 제공업체로 신용정보가 계속 제공된 원인은 무엇입니까?", "신용정보 동의 기록이 5년이 채 되지 않아 삭제되거나 분실된 이유가 무엇입니까?"], "rootcauseEnd": "신용정보법 제32조 및 제33조 위반으로 즉시 결함 처리하며, 법적 권고사항 이행 및 책임자 조사, 관련 전산 로직 수정 조치를 요구합니다.", "na": ["개인신용정보를 취급하지 않거나 여·수신 등 금융거래 업무를 전혀 수행하지 않는 시스템입니까?", "신용정보업자 또는 여신금융기관으로서 신용정보 조회가 불가능한 독립 네트워크 환경임을 설명해 주시겠습니까?"], "naEnd": "신용정보 처리가 원천적으로 불가능한 시스템으로 증명되면 N/A로 종결합니다."}, "17-4": {"decisionQ": "저축은행 대표 홈페이지 첫 화면에 개인정보처리방침이 누구나 쉽게 찾을 수 있도록 공개되어 있으며, 내용 변경 시 30일 전 미리 공지한 내역과 현행화 검토 서류를 제시할 수 있습니까?", "verify": ["홈페이지 메인화면 하단(푸터 등)에서 글자 크기·색상 등을 통해 '개인정보처리방침'이 용이하게 식별 및 접근 가능한지 확인시켜 주시겠습니까?", "최근 개인정보처리방침 변경 이력(개정일자, 신구조문 대조표 등)과 개정 시 30일 전 홈페이지 공지사항에 사전 게시했던 화면 캡처 또는 관리 이력을 보여주시겠습니까?", "현재 게시된 처리방침 내용 중 수집 항목, 위탁업체, 제3자 제공처가 실제 IT 시스템 현황과 100% 일치하는지 CPO 현행화 점검 보고서를 제시해 주시겠습니까?"], "verifyEnd": "처리방침 접근 용이성, 변경 시 30일 전 사전 공지 이행, 개정이력 관리, 실제 처리 현황과의 현행화 일치가 확인되면 양호로 확정합니다.", "partial": ["개인정보처리방침은 게시되어 있으나, 변경 시 30일 전 사전 공지 기간을 지키지 못하고 변경 직전(예: 3~7일 전)에 공지한 사유는 무엇입니까?", "위탁업체나 수집 항목이 변경되었음에도 개인정보처리방침 반영이 1~2개월 지연되어 현행화가 즉시 이루어지지 않은 이유는 무엇입니까?", "개정 시 사전 공지 프로세스 개선 및 실시간 현행화 점검 계획을 말씀해 주시겠습니까?"], "partialEnd": "사전 공지 기간 미준수 및 현행화 지연을 부분 미흡으로 판정하고, 처리방침 개정 가이드라인 준수를 요청합니다.", "rootcause": ["홈페이지에 개인정보처리방침이 게시되지 않았거나, 연결 링크가 단락되어 접근이 불가능한 경위는 무엇입니까?", "실제 개인정보 위탁/제3자 제공 현황과 홈페이지 처리방침에 기재된 내용이 완전히 다르게 방치된 원인은 무엇입니까?", "처리방침 개정 시 사전 공지를 전혀 하지 않고 임의 변경 게시해온 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제30조 위반으로 결함 처리하며, 홈페이지 처리방침 즉시 정정 게시 및 공지 절차 이행을 촉구합니다.", "na": ["대고객 서비스를 전혀 제공하지 않고 인터넷 웹사이트를 운영하지 않는 내부 전용 시스템에 대한 평가입니까?", "해당 시스템이 일반 정보주체와 접점이 없는 완전히 독립된 폐쇄망 시스템임을 입증할 수 있습니까?"], "naEnd": "웹사이트 운영 및 일반 정보주입 접점이 없는 시스템인 경우 N/A 처리합니다."}, "17-5": {"decisionQ": "신규 서비스 기획이나 앱 개발 시 개인정보 최소수집 원칙을 검토하는 절차가 마련되어 있으며, 과도하게 수집되는 항목을 점검·삭제한 최신 검토 보고서를 보여주실 수 있습니까?", "verify": ["신규 여·수신 상품 출시 또는 모바일 앱 개편 시 작성된 '개인정보 수집 최소화 영향평가/검토서'를 제시해 주시겠습니까?", "앱에서 요구하는 권한(CCTV, 스마트폰 주소록, 위치정보, 사진 등) 중 서비스 제공에 불필요한 필수 권한이 제외되어 있음을 앱 설정 화면에서 시연해 주시겠습니까?", "기존 수집 항목 중 불필요하거나 과도하다고 판단되어 수집 중단 및 DB 컬럼 파기/정리 조치한 실적 자료를 보여주시겠습니까?"], "verifyEnd": "최소수집 사전 검토 절차 작동, 스마트폰 앱 과도 권한 미요구, 불필요 수집 항목 정기 점검 및 파기실적이 확인되면 양호로 확정합니다.", "partial": ["최소수집 원칙 검토 절차는 존재하나, 사후 점검 및 불필요 수집 항목 정리가 정기적으로 이루어지지 못하는 이유는 무엇입니까?", "스마트폰 앱에서 선택 권한으로 설정할 수 있는 항목을 필수 권한으로 설정해 놓은 사유는 무엇이며, 수정 일정은 어떻게 됩니까?", "불필요한 과다 수집 항목 재검토 및 앱 접근권한 최소화 조치 계획을 제출할 수 있습니까?"], "partialEnd": "앱 접근 권한 설정 과다 및 사후 점검 주기 미준수를 부분 미흡으로 지정하고 앱 권한 재설정 제출을 권고합니다.", "rootcause": ["서비스 제공과 무관한 개인정보(예: 결혼 여부, 가족관계, 기기식별값 등)를 관행적으로 수집해온 경위는 무엇입니까?", "신규 개발 시 최소수집 검토 없이 기획자/개발자 임의로 수집 항목을 추가할 수 있었던 통제 부재 원인은 무엇입니까?", "과도 수집 지적을 받은 이후에도 해당 DB 컬럼이나 입력 폼을 즉시 삭제하지 않은 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제16조(수집 제한) 위반으로 결함 처리하며, 과도 수집 항목 즉시 파기 및 개발 통제 프로세스 개편을 요구합니다.", "na": ["해당 시스템이 신규 수집을 전혀 하지 않고, 타 시스템으로부터 정제된 데이터만 제공받아 활용하는 시스템입니까?", "독립적인 수집 창구나 입력 폼이 전혀 존재하지 않는 시스템임을 입증할 수 있습니까?"], "naEnd": "직접적인 개인정보 수집 기능이 없는 백엔드 처리 전용 시스템인 경우 N/A로 판정합니다."}, "17-6": {"decisionQ": "외부 기관으로의 개인정보 제3자 제공 현황 관리 대장과 법적 근거(동의·법령)를 보여주시고, 제3자 제공 시 정보주체 알림 통지 이력을 현장에서 재조회해 주실 수 있습니까?", "verify": ["개인정보 제3자 제공 관리 현황 목록(제공받는 자, 제공 목적, 항목, 보유기간)을 제시해 주시겠습니까?", "목록에 등록된 제3자 제공건 중 1건을 지정할 테니, 해당 제공건의 명확한 법적 근거(별도 동의서 서식 또는 해당 법령 조항)를 확증해 주시겠습니까?", "제3자 제공 발생 시 정보주체(고객)에게 알림톡, SMS, 이메일 등으로 통지한 시스템 발송 로그 및 내역을 조회해 보여주시겠습니까?", "제3자 제공 계약서 상에 개인정보 보호 조치, 목적 외 이용 금지, 재제공 금지 조항이 명시되어 있는지 확인시켜 주시겠습니까?"], "verifyEnd": "제3자 제공 관리대장의 완전성, 법적 근거의 명확성, 정보주체 통지 이행, 제공 계약서의 적정성이 모두 확인되면 양호로 확정합니다.", "partial": ["제3자 제공 관리대장은 작성되어 있으나, 최근 추가된 제공 기관 1~2곳이 누락된 경위는 무엇입니까?", "법령에 의한 제3자 제공 발생 시 정보주체 통지 절차가 일부 지연되거나 사후 통지가 누락되는 사유는 무엇입니까?", "제3자 제공 관리대장 현행화 및 자동 통지 연동 시스템 개선 계획을 말씀해 주시겠습니까?"], "partialEnd": "제3자 제공 대장 누락 및 통지 지연을 부분 미흡으로 판정하고, 제3자 제공 전수 점검 및 통지 로직 강화를 요구합니다.", "rootcause": ["정보주체의 별도 동의나 명확한 법률 근거 없이 제3자(제휴사, 마케팅 업체 등)에게 개인정보를 제공한 사유는 무엇입니까?", "제3자 제공 내역에 대한 관리 대장 자체가 존재하지 않거나 무단으로 데이터가 제공된 경위는 무엇입니까?", "제3자 제공 통지 의무 대상임에도 통지를 전혀 실시하지 않은 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제17조 및 제18조 위반으로 즉시 결함 처리하며, 무단 제공 즉시 중단, 제공 데이터 회수/파기 및 법적 조치 이행을 요구합니다.", "na": ["어떠한 외부 기관, 제휴사, 관계사에도 개인정보를 제3자 제공하지 않는 시스템입니까?", "제3자 제공이 발생하지 않음을 입증할 수 있는 데이터 연동 네트워크 통제 정책 및 방화벽 설정 내역을 보여주시겠습니까?"], "naEnd": "외부 제3자 제공 연동이 전혀 없는 전용 내부 시스템임이 입증되면 N/A로 판정합니다."}, "17-7": {"decisionQ": "IT/전자금융 업무 관련 개인정보 처리 위탁 현황 목록과 표준 위탁계약서(법정 필수 조항 포함), 그리고 수탁자에 대한 정기 관리·감독(점검·교육) 이력 자료를 보여주시겠습니까?", "verify": ["개인정보 처리위탁 현황 대장에서 IT외주 개발사, 콜센터, IDC, 유지보수업체 등의 목록이 현행화되어 있는지 확인해 주시겠습니까?", "임의로 선택한 위탁업체 2곳의 위탁계약서를 열어 법 제26조에 따른 필수 6가지 조항(위탁업무 목적 외 금지, 기술적·관리적 보호조치, 재위탁 제한, 점검·감독, 손해배상 등)이 포함되어 있는지 확인시켜 주시겠습니까?", "최근 1년 이내 수행한 수탁자 실태 점검 결과 보고서 및 수탁자 대상 개인정보보호 교육 실시 증빙 자료를 보여주시겠습니까?", "수탁자가 재위탁을 실시한 경우, 당 저축은행의 사전 승인을 받은 서류가 존재하는지 보여주시겠습니까?"], "verifyEnd": "위탁 관리대장 현행화, 표준 위탁계약서 법정 필수 조항 반영, 정기 실태점검 및 교육 이행, 재위탁 사전승인 통제가 모두 확인되면 양호로 확정합니다.", "partial": ["위탁계약서는 체결되어 있으나, 일부 업체에 대해 연 1회 수탁자 정기 점검 또는 교육 실시 실적이 누락된 사유는 무엇입니까?", "수탁자의 재위탁 현황 파악이 다소 지연되거나 현황 대장의 업데이트가 적시에 이루어지지 않는 원인은 무엇입니까?", "미점검 수탁자에 대한 현장 실태점검 계획 및 수탁자 교육 보완 방안을 서면 제출할 수 있습니까?"], "partialEnd": "수탁자 점검·교육 이행 일부 누락을 부분 미흡으로 지정하고 수탁자 정기 실태점검 완수 계획 제출을 권고합니다.", "rootcause": ["개인정보 처리위탁 계약 체결 시 법정 필수 조항이 누락된 단순 용역 계약서 형태로 체결된 경위는 무엇입니까?", "수탁자에 대해 관리·감독(점검/교육)을 수년간 단 한 번도 실시하지 않고 방치한 이유는 무엇입니까?", "당 저축은행의 승인 없이 수탁자가 임의로 재위탁을 진행했음에도 이를 통제하지 못한 원인은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제26조(업무위탁에 따른 개인정보의 처리 제한) 위반으로 결함 처리하며, 위탁계약서 즉시 재체결 및 수탁자 특별점검 실시를 요구합니다.", "na": ["개인정보 처리를 외부에 위탁하는 업무가 전혀 없으며 100% 자체 인력 및 자체 시스템으로만 처리합니까?", "외부 외주업체, Maintenance 계약업체, 외부 SaaS 이용이 일체 없음을 입증할 수 있습니까?"], "naEnd": "개인정보 처리 위탁 관계가 완전히 부재한 조직/시스템임이 확인되면 N/A로 종결합니다."}, "17-8": {"decisionQ": "수집 목적 외 개인정보 이용을 금지하는 통제 정책 및 예외 발생 시 별도 동의/법적 근거 사전 승인 절차가 시스템 및 지침으로 구현되어 있음을 증명해 주실 수 있습니까?", "verify": ["목적 외 이용 처리 승인 지침과 예외적인 목적 외 이용 신청·승인 관리 대장(사유, 법적 근거, 승인자, 이용 범위 등)을 보여주시겠습니까?", "최근 1년 내 발생한 예외적 목적 외 이용 건에 대해 정보주체의 별도 동의를 받은 동의서 또는 법률상 의무 이행 근거 서류를 대조해 주시겠습니까?", "DB 접근통제 시스템 또는 개인정보 유출탐지 시스템에서 '원래 목적 외 대량 조회/추출 시도'를 탐지하여 차단하거나 경고하는 모니터링 룰을 보여주시겠습니까?", "임직원 대상 목적 외 이용 금지 및 위반 시 벌칙에 관한 연간 교육 이행 내역을 제시해 주시겠습니까?"], "verifyEnd": "목적 외 이용 예외 승인 절차 준수, 별도 동의/법적 근거 명확성, 모니터링 탐지 룰 가동, 임직원 교육 이행이 확인되면 양호로 확정합니다.", "partial": ["목적 외 이용 승인 절차는 존재하나, 사후 관리가 누락되거나 승인 관리 대장의 작성이 일부 지연되는 이유는 무엇입니까?", "목적 외 이용 모니터링 탐지 룰이 단순 조회 건수 기준으로만 설정되어 탐지의 정확도가 떨어지는 원인과 개선 방안은 무엇입니까?", "목적 외 이용 관리 대장 현행화 및 모니터링 임계치 고도화 계획 제출이 가능합니까?"], "partialEnd": "목적 외 이용 사후 관리 지연 및 모니터링 룰 미흡을 부분 미흡으로 지정하고 통제 프로세스 강화를 권고합니다.", "rootcause": ["수집 목적(예: 여신 심사)과 전혀 다른 목적(예: 타 상품 마케팅, 신규 사업 연구 등)으로 별도 동의 없이 개인정보를 무단 이용한 경위는 무엇입니까?", "개발, 테스트, 교육 등의 목적에 운영 DB의 실제 개인정보를 사전 승인이나 변환(마스킹/익명화) 없이 목적 외로 직접 사용한 이유는 무엇입니까?", "목적 외 이용 통제 정책을 회피하여 데이터를 임의 추출한 직원에 대한 통제 및 감사 기능이 작동하지 않은 원인은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제18조(개인정보의 이용·제공 제한) 위반으로 엄중 결함 처리하며, 목적 외 이용 데이터 즉시 삭제 및 관련자 경위 조사, 재발방지책 제출을 요구합니다.", "na": ["해당 시스템이 개인정보가 아닌 가명정보·익명정보만을 다루거나, 정보주체의 수집 목적 이외의 기능 자체가 제공되지 않는 단일 목적 전용 시스템입니까?", "목적 외 이용이 구조적으로 불가능한 시스템임을 입증하는 기능 명세서를 제시할 수 있습니까?"], "naEnd": "단일 목적 전용 시스템으로 목적 외 활용 가능성이 구조적으로 차단된 경우 N/A 판정합니다."}, "18-1": {"decisionQ": "안전성확보조치 기준(고시) 개정사항이 반영된 최신 이행 체크리스트와 함께, DB암호화·접속기록·보안프로그램의 실시간 적용 현황을 화면으로 시연해 주시겠습니까?", "verify": ["최근 1년 이내 개정된 안전성확보조치 기준 고시 반영 이력과 정기 자체점검 결과 보고서를 보여주시겠습니까?", "주요 개인정보처리시스템(여신·수신 원장 DB)의 고유식별정보 암호화 저장 및 구간 암호화 설정 화면을 보여주시겠습니까?", "개인정보취급자의 접속기록이 월 1회 이상 점검되고 있으며, 1년(또는 2년) 이상 안전하게 보관·백업되고 있는 로그 화면을 보여주시겠습니까?", "PC 및 서버의 백신 최신 업데이트 현황과 개인정보 탐지/출력 통제(DLP) 솔루션의 적용 현황을 시연해 주시겠습니까?"], "verifyEnd": "안전성확보조치 전 항목이 고시 기준에 맞게 반영되어 있고, 현장 시연을 통해 암호화·접속기록·보안프로그램이 정상 작동함이 확인되면 양호로 확정합니다.", "partial": ["안전성확보조치 항목 중 일부(예: 접속기록 점검 미흡, 일부 PC 보안프로그램 미설치 등)만 이행된 사유는 무엇입니까?", "미이행 또는 미흡 항목에 대해 수립된 보완 계획서와 현재까지의 이행 추진 실적을 제시해 주시겠습니까?", "개정된 고시 기준이 내부 지침이나 시스템에 제때 반영되지 않은 경위는 무엇입니까?"], "partialEnd": "미흡 항목에 대해 기 수립된 보완 계획의 타당성을 검토하고, 미이행 요소의 조속한 완료 조치 및 재점검을 요구합니다.", "rootcause": ["접속기록 미점검, 암호화 미적용 등 주요 안전조치가 누락된 근본적인 원인(예산, 인력, 시스템 제약 등)은 무엇입니까?", "이러한 미이행 상태를 내부 통제 절차에서 미리 인지하고 보고했었는지 확인해 주시겠습니까?", "법적 의무 사항 미준수로 인한 유출 위험에 대해 경영진에 보고된 내용이나 대책이 있습니까?"], "rootcauseEnd": "안전성확보조치 법적 의무 미준수로 결함 확정하고, 즉시 개선계획 수립 및 보안 조치를 서면 보고하도록 요청합니다.", "na": ["해당 시스템 또는 부서가 개인정보를 전혀 처리하지 않아 안전성확보조치 대상에서 제외되는 근거가 있습니까?", "개인정보 처리 위탁 등으로 인해 직접 조치 의무가 없다고 판단하신 공식적인 근거 문서를 보여주시겠습니까?"], "naEnd": "개인정보 미처리 또는 대상 제외 타당성이 입증되면 N/A로 처리합니다."}, "18-2": {"decisionQ": "개인정보 항목별 보유기간 정의서와 함께, 보유기간이 도과한 데이터의 자동 파기 설정 및 분리 보관 DB 구축 현황을 조회해 주시겠습니까?", "verify": ["수신·여신·신용정보 관련 개인정보 항목별 법정 보유기간이 명시된 규정/정의 목록을 제시해 주시겠습니까?", "계약 종료 후 법정 보유기간이 지난 개인정보가 배치(Batch) 작업 등을 통해 자동 파기되도록 구현된 원천 코드나 스케줄러 설정 화면을 보여주시겠습니까?", "법령에 의해 보존해야 하는 개인정보가 일반 거래 DB와 격리되어 접근 통제된 '분리 보관 DB'로 이관된 현황을 조회해 주시겠습니까?", "연 1회 이상 실시한 개인정보 보유기간 정기 검토 및 조치 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "보유기간 정의, 자동 파기/분리보관 로직, 정기 검토 이력이 모두 현장 시연 및 증빙으로 확인되면 양호로 확정합니다.", "partial": ["보유기간은 수립되어 있으나 일부 시스템에서 자동 파기 로직이 미구현되어 수동 파기를 진행하는 이유는 무엇입니까?", "분리 보관 조치는 되어 있으나, 일반 거래 DB와의 접근 통제나 권한 격리가 완벽하지 않은 사유는 무엇입니까?", "정기 검토 결과 발견된 보유기간 도과 데이터에 대해 즉시 파기 조치가 지연된 이유는 무엇입니까?"], "partialEnd": "수동 파기 또는 미완성 분리보관 조치에 따른 위험을 지적하고, 자동화 구현 및 권한 통제 강화 계획 수립을 요구합니다.", "rootcause": ["보유기간이 도과했음에도 파기나 분리 보관이 전혀 이루어지지 않고 DB에 방치된 원인은 무엇입니까?", "시스템 개발 시 보유기간 관리 기능이 반영되지 않은 이유와, 이를 검증하는 내부 절차가 없었던 경위는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제21조 위반(보유기간 도과 데이터 미파기/미분리)으로 결함 확정하고, 전수 조사 및 파기 이행을 요구합니다.", "na": ["당행에서 직접 보유·관리하는 개인정보가 전혀 존재하지 않음을 증명할 수 있는 근거가 있습니까?"], "naEnd": "해당 사안이 타당할 경우 N/A 판정합니다."}, "18-3": {"decisionQ": "DB·전자적 파일·출력물·기록매체에 대한 개인정보 파기 절차서와 함께, 복구 불가능한 방법으로 파기된 이력 대장 및 복구 불가 테스트 결과를 제시해 주시겠습니까?", "verify": ["최근 1년 이내 수행된 개인정보 파기 이력 대장(일시, 항목, 방법, 담당자, 승인자 명시)을 제시해 주시겠습니까?", "전자적 파일 및 DB 파기 시 '덮어쓰기(Zero Filling)' 또는 '완전삭제 솔루션'을 적용한 승인 문서와 기술 검증서를 보여주시겠습니까?", "서류, 디스크, 매체 파기 시 파쇄/천공/용해 등 물리적 파기 작업 현장 사진 또는 외부 전문 파기업체의 파기 완료 확인서를 제시해 주시겠습니까?", "파기 완료 후 데이터 복구가 불가능함을 직접 검증한 '복구 불가 테스트 결과 보고서'를 보여주시겠습니까?"], "verifyEnd": "매체별 복구 불가능한 파기 기법 적용, 승인된 파기 대장, 복구 불가 테스트 결과가 모두 확인되면 양호로 확정합니다.", "partial": ["DB 파기는 이행되고 있으나, 개인정보가 포함된 로컬 PC 파일이나 출력물의 파기 이력 관리가 일부 누락된 이유는 무엇입니까?", "파기 대장에 파기 일시 및 담당자 등 필수 기재 사항이 일부 누락되어 관리되는 경위는 무엇입니까?"], "partialEnd": "비전자식 문서 및 출력물 등에 대한 파기 관리 절차 보완과 대장 기재 항목 완전화를 요구합니다.", "rootcause": ["단순 삭제(Trash 삭제, DB Delete 문 실행) 등 복구 가능한 방법으로 파기한 근본적인 이유는 무엇입니까?", "파기 작업에 대한 승인 절차나 파기 후 복구 가능 여부를 검증하는 통제 장치가 전무한 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제21조 위반(완전파기 미이행)으로 결함 확정하고, 즉시 복구 불가능 파기 재실시를 요구합니다.", "na": ["최근 감사 대상 기간 동안 파기 대상 개인정보나 폐기 매체 발생 건이 전혀 없음을 증빙(시스템 로그 등)할 수 있습니까?"], "naEnd": "파기 대상 미발생 타당성이 증명되면 N/A로 확정합니다."}, "18-4": {"decisionQ": "최근 1년간 개인정보 개인정보처리시스템 구축/변경 시 작성된 개인정보 영향평가(PIA) 대상 선정 기준 및 영향평가 결과 보고서를 제시해 주시겠습니까?", "verify": ["법적 평가 대상(5만건 이상 민감/고유식별정보 처리 시스템 또는 50만건 이상 개인정보 시스템 구축/운영/변경 등) 적용 기준을 규정한 internal guideline을 제시해 주시겠습니까?", "최근 1년 내 진행된 PIA 수행 계획서 및 평가 결과 보고서(전문기관 수행 또는 자격 요건을 갖춘 자체 평가)를 보여주시겠습니까?", "PIA 결과 도출된 이행개선 권고사항에 대해 조치 계획을 수립하고, 실제 시스템에 반영한 '개선사항 이행확인서'를 보여주시겠습니까?"], "verifyEnd": "PIA 대상 선정 기준 준수, 평가 보고서의 타당성, 도출된 개선사항의 실제 시스템 반영 이력이 확인되면 양호로 확정합니다.", "partial": ["PIA는 수행되었으나, 도출된 위험 개선 조치가 일부 지연되거나 완료 예정일을 넘긴 사유는 무엇입니까?", "자체 영향평가 수행 시 평가 팀원의 전문성(자격증, 평가 경험 등) 요건이 일부 미흡했던 이유는 무엇입니까?"], "partialEnd": "미이행된 PIA 개선 조치 항목에 대해 즉시 이행 조치 요구 및 관리 강화를 권고합니다.", "rootcause": ["PIA 법적 대상 시스템임에도 불구하고 영향평가를 전혀 수행하지 않고 시스템을 오픈한 근본 원인은 무엇입니까?", "시스템 신규 구축/변경 시 PIA 수행 여부를 사전에 검토하는 IT개발 및 보안 협의 절차가 누락된 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제33조 위반(PIA 미수행)으로 결함 확정하고, 즉시 사후 영향평가 수행 및 지적사항 보고를 요구합니다.", "na": ["최근 1년 간 법정 PIA 대상 규모(5만건/50만건 등)에 해당하는 시스템 신규 구축, 연계, 또는 주요 변경 사항이 전혀 없음을 입증할 수 있습니까?"], "naEnd": "PIA 대상 구축/변경 사업이 없었음이 사업 목록으로 검증되면 N/A로 처리합니다."}, "18-5": {"decisionQ": "정보주체의 권리행사(열람·정정·삭제·처리정지) 접수 채널 운영 현황과 최근 1년 내 처리 이력 대장(10일 이내 통보 이행 여부)을 조회해 주시겠습니까?", "verify": ["홈페이지, 모바일 앱, 서면, 전화 등 고객이 권리행사를 할 수 있는 접수 창구 구축 화면을 시연해 주시겠습니까?", "권리행사 접수 후 10일 이내에 조치 결과 또는 처리 지연/불가 사유 통지서를 발송한 이력 대장을 제시해 주시겠습니까?", "실제 정정/삭제 요청 건에 대해 DB 원장 데이터가 정상적으로 수정되거나 삭제 처리된 시스템 변경 로그를 보여주시겠습니까?", "법령상 권리행사 거절(처리정지 예외 등) 사유 발생 시, 정보주체에게 합당한 법적 근거를 통지한 이력 문서를 보여주시겠습니까?"], "verifyEnd": "접수 채널 완비, 10일 이내 처리 통부율 100%, 원장 반영 및 거절 사유 통지의 적정성이 확인되면 양호로 확정합니다.", "partial": ["권리행사 요청은 처리되고 있으나, 일부 건에서 10일 이내 통지 기한을 소폭 초과(예: 11~12일차 통지)한 사유는 무엇입니까?", "접수 창구가 특정 채널(예: 영업점 서면 접수)로 제한되어 모바일 앱 등 온라인 접수가 불가능한 이유는 무엇입니까?"], "partialEnd": "처리 기한 엄수를 위한 프로세스 개선 및 다양한 요구 채널 확보 강화를 요구합니다.", "rootcause": ["정보주체의 열람·삭제·처리정지 요구를 담당자가 방치하거나 10일 이내 통지를 아예 누락한 근본 사유는 무엇입니까?", "권리행사 처리 이력 대장을 작성하지 않거나 처리 담당 부서 간 공조 프로세스가 부재한 이유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제35~37조 위반(권리행사 응대 미흡/기한 위반)으로 결함 확정하고, 전용 관리 시스템 구축 및 절차 재정비를 명령합니다.", "na": ["최근 감사 대상 기간 동안 정보주체의 열람/정정/삭제/처리정지 요구가 단 1건도 접수되지 않았음을 접수 대장 및 시스템으로 입증할 수 있습니까?"], "naEnd": "접수 내역 0건이 시스템상 증명되면 채널 구축 여부만 확인 후 N/A 처리합니다."}, "18-6": {"decisionQ": "개인정보 침해 손해배상 책임 이행을 위한 '보험 증권(또는 전용 준비금 적립 내역)'과 기준에 맞는 보상 한도액 산출 근거를 제시해 주시겠습니까?", "verify": ["현재 유효한 '개인정보보호 배상책임보험' 보험 증권 원본(또는 준비금 적립 통장/회계장부)을 보여주시겠습니까?", "저축은행의 매출액 및 개인정보 저장·보유 수(주민등록번호/고객 수)에 따른 법정 최저 가입 보상 한도액 산출표를 보여주시겠습니까?", "보험 증권상의 보상 한도액 및 가입 대상이 당행 산출액 이상이며, 특약 조건에 명시된 보장 범위가 적정한지 확인해 주시겠습니까?", "보험 만료에 따른 갱신 이력 및 연간 보험료 납입 영수증을 제시해 주시겠습니까?"], "verifyEnd": "법정 산출 기준 충족, 보험 유효기간 내 존재, 보상 한도 및 준비금의 적정성이 증권으로 확인되면 양호 확정합니다.", "partial": ["보험에는 가입되어 있으나, 최근 고객 수 증가 또는 매출액 변동으로 인해 가입 한도가 법정 최저 기준에 소폭 미달하는 사유는 무엇입니까?", "보험 만료 후 재갱신 과정에서 수일간의 가입 공백 기간이 발생했던 경위는 무엇입니까?"], "partialEnd": "변동된 매출액/고객 수 기준을 반영하여 보상 한도 증액 변경 계약 체결 및 공백 방지 절차 수립을 요구합니다.", "rootcause": ["개인정보 손해배상 책임 보험 미가입 또는 준비금 미적립 상태가 지속된 근본적인 원인은 무엇입니까?", "담당 부서의 법적 의무 사항 미숙지 또는 관련 예산 미편성 사유는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제39조의7 위반(손해배상책임 미이행)으로 결함 확정 및 즉시 보험 가입 조치를 서면 요구합니다.", "na": ["개인정보보호법상 손해배상 책임 보험 가입 의무 대상(저장·관리되는 개인정보 수가 1천명 미만 등)에서 제외되는 타당한 근거가 있습니까?"], "naEnd": "법적 면제 요건에 합당함이 증명되면 N/A로 판정합니다."}, "18-7": {"decisionQ": "개인정보 유출 사고 대응 매뉴얼(72시간 이내 신고·통지 절차 포함)과 최근 유출 발생 시 보호위원회 신고서 및 통지 내역을 보여주시겠습니까?", "verify": ["개인정보 유출 인지 시 '72시간 이내 개인정보보호위원회/KISA 신고' 및 '정보주체 통지' 절차가 명시된 유출 대응 매뉴얼을 제시해 주시겠습니까?", "유출 사고 발생 이력이 있는 경우, 72시간 이내에 작성·제출된 보호위원회 신고서 및 접수증을 보여주시겠습니까?", "정보주체에게 발송된 통지문(유출 항목, 시점, 대응 조치, 피해 접수 창구 포함) 및 발송 이력을 제시해 주시겠습니까?", "유출 사고 원인 분석 보고서 및 재발 방지 대책 이행 완료 확인서를 보여주시겠습니까?"], "verifyEnd": "매뉴얼 완비 및 사고 발생 시 72시간 이내 신고·통지 준수, 원인 분석과 재발 방지 조치가 증빙으로 확인되면 양호 확정합니다.", "partial": ["유출 신고 및 정보주체 통지는 완료되었으나, 통지 항목 중 일부(예: 피해 접수 창구, 대응 조치 등)가 누락된 채 발송된 사유는 무엇입니까?", "72시간 이내에 기본 신고는 이루어졌으나, 유출 원인 분석 보고서 제출이 부당하게 지연된 이유는 무엇입니까?"], "partialEnd": "유출 통지문 항목 표준화 및 사고 대응 프로세스의 일괄 신속화 개선 조치를 요구합니다.", "rootcause": ["유출 사실을 인지했음에도 보호위원회 신고 및 정보주체 통지를 72시간 내에 수행하지 않거나 은폐한 근본 사유는 무엇입니까?", "사고 발생 시 보고 체계가 제대로 작동하지 않거나 비상 연락망이 누락된 원인은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제34조 위반(유출 신고/통지 의무 위반)으로 결함 확정하고, 엄중 경고 및 재발방지책 수립을 즉시 명합니다.", "na": ["최근 감사 대상 기간 동안 개인정보 유출 사고 또는 유출 정황이 단 1건도 발생하지 않았음을 사고 접수 및 보안 모니터링 기록으로 증명할 수 있습니까?"], "naEnd": "유출 사고 미발생 사실이 확인되면 매뉴얼 작성 여부만 점검 후 N/A 판정합니다."}, "18-8": {"decisionQ": "만 14세 미만 아동의 개인정보 수집 여부 및 수집 시 법정대리인 동의 수렴/본인확인 인증 화면을 시연해 주시겠습니까?", "verify": ["모바일/웹 회원가입 또는 금융상품 신청 프로세스상에서 생년월일을 검증하여 만 14세 미만을 식별하는 로직을 시연해 주시겠습니까?", "만 14세 미만 아동인 경우, 법정대리인의 성명·휴대폰 인증 등을 통해 법정대리인 동의를 받아 저장하는 인증 처리 로그를 보여주시겠습니까?", "아동의 개인정보가 DB상에서 식별 관리되거나 법정대리인 정보와 매핑되어 관리되는 현황을 보여주시겠습니까?", "아동이 이해하기 쉬운 언어로 작성된 '아동용 개인정보 처리방침' 또는 별도 안내문이 게시된 화면을 시연해 주시겠습니까?"], "verifyEnd": "만 14세 미만 자동 판별, 법정대리인 동의 검증 로직, 아동 개인정보의 분리/매핑 관리가 시연으로 입증되면 양호로 확정합니다.", "partial": ["법정대리인의 동의는 수집하고 있으나, 법정대리인 본인 여부를 휴대폰/아이핀 등 객관적 매체로 검증하지 않는 사유는 무엇입니까?", "아동 개인정보 수집은 가능하나, 아동 눈높이에 맞춘 이해하기 쉬운 안내문 게시가 누락된 경위는 무엇입니까?"], "partialEnd": "법정대리인 본인 인증 절차의 즉시 추가 구현 및 아동용 개인정보 처리방침의 보완 게시를 권고합니다.", "rootcause": ["만 14세 미만 아동의 개인정보를 수집하면서 법정대리인의 동의 절차 자체를 미구현한 근본적인 원인은 무엇입니까?", "연령 확인 로직이 없어 아동이 연령을 허위 기재하더라도 검증 없이 수집되는 시스템적 결함의 경위는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 제22조의2 위반(법정대리인 동의 미수집)으로 결함 확정하고, 즉시 가입 프로세스 차단 및 개선을 명령합니다.", "na": ["당행의 서비스 이용 약관상 만 14세 미만 아동의 가입/거래를 절대 불허하며, 시스템적으로 만 14세 미만은 가입이 차단됨을 차단 화면 시연으로 증명할 수 있습니까?"], "naEnd": "시스템적으로 만 14세 미만 가입 및 거래가 완벽히 차단됨이 현장 시연으로 검증되면 N/A로 판정합니다."}, "14-1": {"decisionQ": "인프라 자산(서버, DB, 네트워크, 보안장비) 및 주요 응용시스템의 로그가 SIEM/통합로그관리시스템으로 누락 없이 수집되고 있는지 화면에서 직접 확인해 주시겠습니까?", "verify": ["SIEM 대시보드 또는 통합로그관리시스템의 자산 연동 현황 화면을 열어 전체 수집 대상 자산 리스트와 수집 상태(Normal)를 보여주시겠습니까?", "감사역이 지정하는 주요 DB 서버 1대와 핵심 응용프로그램 1건의 IP/시스템명을 시스템상에서 직접 검색하여, 최근 1시간 이내의 실시간 수집 로그를 조회해 주시겠습니까?", "전체 IT 자산 목록과 SIEM 수집 대상 자산 목록을 대조하여 작성된 '미수집 자산 목록 및 수집 계획서'를 제시해 주시겠습니까?", "로그 수집 에이전트 장애나 네트워크 단절로 인해 로그 수집이 중단되었을 때 담당자에게 SMS/메일로 즉시 발송되는 알림 설정 화면을 보여주시겠습니까?"], "verifyEnd": "SIEM 수집 자산과 전체 자산 목록이 일치하고, 임의 지정 자산의 실시간 로그 및 수집 장애 알림 설정이 확인되며 예외 미수집 자산에 대한 단계별 수집 계획이 타당하므로 양호로 확정합니다.", "partial": ["주요 서버 및 DB 로그는 수집 중이나, 응용시스템(AP) 로그나 특정 네트워크/보안장비 로그가 누락되어 있는 이유는 무엇입니까?", "미수집 자산에 대해 파악은 되었으나, 연동 추진 계획서나 완결 기한이 수립되지 않은 이유는 무엇입니까?", "로그 수집 실패 시 알림 통제는 있으나 즉시 알림이 아닌 일별 요약 보고 형태로만 운영되는 이유는 무엇입니까?"], "partialEnd": "일부 대상 시스템의 로그 수집 누락 또는 수집 장애 알림 체계의 지연이 확인되어 부분이행으로 판정하고, 미수집 자산 전체 연동 및 실시간 알림 조치 계획을 요청합니다.", "rootcause": ["SIEM 등 통합로그관리시스템이 미구축되어 있거나, 개별 서버/장비에만 로그가 산재되어 보관되는 근본 원인은 무엇입니까?", "로그 수집 대상 자산 식별 절차(IT자산관리 연계)가 아예 부재하여 미수집 자산의 규모조차 파악하지 못한 상태입니까?", "로그 수집 에이전트 정지나 통신 장애 발생 시 모니터링할 수 있는 알림 체계가 전혀 구현되어 있지 않은 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §22 및 ISMS-P 2.9.4 위반에 해당하는 미흡(결함)으로 확정하고, 통합로그관리시스템 구축 또는 수집 범위 확대 및 장애 경보 체계 마련을 위한 개선계획서를 요구합니다.", "na": ["모든 전산 자산이 클라우드 관리형 서비스(SaaS/PaaS)로 이전되어 자사 인프라 내 별도 수집 대상 로그 자산이 전혀 존재하지 않습니까?", "해당 사업장이 단순 연계 단말만 운영하고 독자적인 전산시스템, DB, 네트워크 장비를 일절 보유하지 않는 조직 구조입니까?"], "naEnd": "해당없음 타당성이 입증되었으나, 클라우드 또는 위탁 환경의 로그 관리 주체 및 접근 권한 관리 상태를 추가 검증합니다."}, "14-2": {"decisionQ": "전자금융거래 로그(5년), 보안 이벤트 로그(1년), 개인정보 접근 로그(1년/90일) 등 법적 보존 기간 기준에 맞게 로그 보존 정책이 설정 및 이행되고 있습니까?", "verify": ["SIEM 및 전자금융거래 시스템, 개인정보처리시스템의 백업/보존 정책 설정 화면(Log Retention Configuration)을 열어 보존 기간 수치를 확인해 주시겠습니까?", "5년 전 전자금융거래 로그 및 1년 전 보안 이벤트 로그가 스토리지 또는 코울드 백업 매체에서 실제 정상 조회가 가능한지 현장 시연해 주시겠습니까?", "보존 기간이 만료되어 파기되는 로그의 안전한 파기 절차 및 로그 파기 수행 기록을 제시해 주시겠습니까?", "전사 시스템을 대상으로 로그 보존 기간 준수 여부를 정기 점검한 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "각 로그 종류별 법적 보존 기간 설정이 보존 정책 화면에서 입증되고, 과거 백업 로그의 실제 재조회 및 정기 점검 이력이 확인되어 양호로 확정합니다.", "partial": ["전자금융거래 로그 5년, 보안 로그 1년 기준은 준수하나, 일부 개인정보 접근 로그의 보존 기간이 법적 최소 요건에 미달되어 있는 이유는 무엇입니까?", "보존 기간 설정은 되어 있으나 스토리지 용량 부족으로 인해 최신 로그만 남아있고 과거 백업 로그 조회가 지연되는 이유는 무엇입니까?"], "partialEnd": "일부 시스템의 로그 보존 기간 미달 또는 스토리지 용량 관리 미흡으로 인한 조회 불가가 확인되어 부분이행 처리하고 스토리지 증설 및 보존 정책 재설정을 요구합니다.", "rootcause": ["전자금융거래법 및 감독규정에서 정한 5년 이상 보존 규정을 인지하지 못하거나 보존 설정이 기본값(예: 30일/90일)으로 방치된 경위는 무엇입니까?", "디스크 용량 고갈 시 별도 백업 없이 로그가 자동 덮어쓰기(Overwrite)되거나 임의 삭제되도록 구성된 근본 원인은 무엇입니까?"], "rootcauseEnd": "전자금융거래법 §22의3 및 전자금융감독규정 §22 위반 사항으로 미흡(결함) 확정하고, 전사 로그 보존 정책 재정립 및 소급 백업 대책 마련을 요구합니다.", "na": ["당사가 전자금융업자 또는 금융회사에 해당하지 아니하여 전자금융거래법상 로그 보존 의무 적용 대상에서 완전히 제외되는 법적 근거가 있습니까?"], "naEnd": "저축은행 본업 특성상 전자금융거래 및 개인정보 처리가 필수적이므로 N/A 적용은 불가능함을 안내하고 평가를 진행합니다."}, "14-3": {"decisionQ": "로그 파일이 원본 서버와 분리된 별도 로그 서버에 보관되며, 위·변조 방지를 위한 암호화/Hash 검증 및 관리자 임의 삭제 통제가 적용되어 있습니까?", "verify": ["로그 수집 서버의 네트워크 구성도를 확인하고, 운영 서버와 물리적/논리적으로 분리된 별도 저장소로 원시간 송신되는 설정을 보여주시겠습니까?", "수집된 로그 파일에 대해 적용 중인 Hash 생성 및 무결성 검증 주기 설정(또는 암호화 저장 설정) 화면을 보여주시겠습니까?", "최고관리자(root/admin) 계정으로 로그 서버에 접속하였을 때, 보존 기간 내의 로그 파일 삭제 명령(rm 등)이 기술적으로 차단됨을 시연해 주시겠습니까?", "로그 무결성 검증 실패(위변조 감지) 시 경보가 발생한 이력이나 정기 무결성 점검 결과 보고서를 제시해 주시겠습니까?"], "verifyEnd": "로그의 별도 분리 저장, Hash/암호화를 통한 무결성 검증 통제, 관리자 삭제 권한 차단 시연 및 점검 이력이 입증되므로 양호로 확정합니다.", "partial": ["별도 로그 서버로 전송은 되나, 전송 구간 암호화가 누락되어 있거나 전송 중 간섭 가능성이 존재하는 이유는 무엇입니까?", "로그 무결성 Hash는 생성되나, 이를 주기적으로 검증하여 변경 여부를 감지하는 자동화 프로세스가 미비한 이유는 무엇입니까?"], "partialEnd": "로그 분리 보관은 이루어지나 무결성 검증 절차의 자동화 미비 또는 구간 암호화 누락으로 부분이행 판정하고 보완을 권고합니다.", "rootcause": ["로그가 원본 운영 서버 내에만 단일 보관되어, 서버 침해 시 로그 삭제/위변조 위험에 무방비로 노출되어 있는 경위는 무엇입니까?", "시스템 관리자나 DB 관리자가 자신의 작업 이력이 담긴 로그를 임의로 수정하거나 삭제할 수 있도록 권한이 방치된 이유는 무엇입니까?"], "rootcauseEnd": "ISMS-P 2.9.4 및 ISO 27001 기준 미달인 결함으로 확정하고, 로그 분리 저장 체계 구축 및 WORM 스토리지/권한 통제 적용 개선안을 요구합니다.", "na": ["위탁 운영 중인 외부 SaaS 환경으로, 서비스 제공자가 SOC2 등 국제 인증을 통해 무결성 보호 통제 입증 서류를 제공하고 있습니까?"], "naEnd": "위탁 검증 문서의 적정성을 평가하고, 당사의 직접적인 무결성 검증 가능 여부를 확인합니다."}, "14-4": {"decisionQ": "이상징후 탐지 룰(Rule)이 최신 위협을 반영하여 정기적으로 업데이트되고 있으며, 탐지-경보-대응 과정의 SLA 준수 관리 및 미처리 경보 조치가 이루어지고 있습니까?", "verify": ["SIEM 또는 이상징후 탐지시스템(FDS/SOC)에 등록된 탐지 룰 목록과 각 룰의 상세 정의 문서를 보여주시겠습니까?", "최근 1년 동안 이상징후 탐지 룰을 신규 제정하거나 변경/업데이트한 이력(Rule Change Log)을 시스템 화면 및 승인 문서로 보여주시겠습니까?", "탐지-경보-대응 단계별 타임라인과 SLA 기준(예: 초동대응 30분 내)이 명시된 대응 절차서 및 실제 이행 현황 보고서를 제시해 주시겠습니까?", "현재 시스템 내 미처리(Pending/Open) 상태로 남아있는 경보(Alert) 현황을 조회하고, 소명되지 않은 미처리건의 사유를 설명해 주시겠습니까?"], "verifyEnd": "탐지 룰 정의 문서의 구체성, 정기적 룰 업데이트 이력, SLA 기준에 따른 경보 대응 현황 및 미처리 경보의 정당한 사유가 확인되므로 양호로 확정합니다.", "partial": ["이상징후 탐지 룰은 운용 중이나, 환경 변화나 신규 위협 유형을 반영한 정기 업데이트 이력이 1년 이상 부재한 이유는 무엇입니까?", "경보 발생 후 대응은 이루어지나, 공식적인 SLA 기준시간 설정이 없거나 이행 시간을 측정·관리하지 않는 이유는 무엇입니까?"], "partialEnd": "탐지 룰 운영은 되고 있으나 정기 갱신 체계 미비 및 SLA 관리 미흡이 확인되어 부분이행 처리하고 룰 고도화 계획 제출을 요청합니다.", "rootcause": ["기본 벤더 제공 초기 룰 외에 저축은행 업무 특성을 반영한 이상징후 탐지 룰이 전혀 정의되어 있지 않은 이유는 무엇입니까?", "경보(Alert)가 다량 발생함에도 담당자 인력 부족 등의 이유로 미처리 경보가 조치 없이 다수 방치되고 있는 근본 원인은 무엇입니까?"], "rootcauseEnd": "금융IT안전성강화가이드 위반으로 미흡(결함) 판정하고, 탐지 룰 최적화(False Positive 감소) 및 경보 대응 체계 전면 재정비를 요구합니다.", "na": ["당사가 모든 이상징후 모니터링 업무를 전문 보안관제업체(MSSP)에 위탁하고, 위탁 계약 내에 동일한 SLA 및 룰 관리 조항이 포함되어 있습니까?"], "naEnd": "위탁 계약서 및 관제 보고서를 통해 탐지 룰 관리와 SLA 준수 여부를 대신 검증합니다."}, "14-5": {"decisionQ": "개인정보처리시스템에서 임직원의 업무 목적 외 대량 조회·다운로드 및 야간·휴일 이상 접근을 탐지하는 룰이 작동하고 모니터링 조치가 이행되고 있습니까?", "verify": ["개인정보접근통제(또는 DB접근제어) 시스템에서 '임계값 초과 대량 조회' 및 '야간/휴일 개인정보 접근' 탐지 룰 설정 화면을 보여주시겠습니까?", "최근 3개월 간 야간이나 휴일에 개인정보를 조회/다운로드하여 탐지된 이벤트 내역과 담당자의 소명 확인서 및 소명 처리 이력을 조회해 주시겠습니까?", "대량 다운로드 발생 시 해당 사용자의 다운로드를 즉시 차단하거나 승인자 결재를 요구하는 기술적 통제 화면을 시연해 주시겠습니까?", "개인정보 관리책임자(CPO) 또는 경영진에게 정기적으로 보고된 '개인정보 이상 접근 현황 보고서'를 제시해 주시겠습니까?"], "verifyEnd": "대량 조회/야간 접근 탐지 룰 정상 작동, 소명 처리 및 기술적 차단 시연, CPO 정기 보고 실적이 확인되므로 양호로 확정합니다.", "partial": ["대량 조회 탐지 룰은 운영되나, 야간·휴일 접근에 대한 별도의 모니터링 룰이나 모니터링 강화 통제가 누락된 이유는 무엇입니까?", "이상 접근 경보는 발생하나, 당사자에 대한 사후 소명 절차가 지연되거나 소명서 보관이 누락되어 있는 이유는 무엇입니까?"], "partialEnd": "일부 탐지 패턴 누락 또는 사후 소명 관리의 미비가 확인되어 부분이행 처리하고, 야간/휴일 룰 추가 및 소명 프로세스 강화를 권고합니다.", "rootcause": ["개인정보보호법 및 감독규정에서 요구하는 개인정보 이상 접근 탐지 룰(대량 조회/휴일 접근)을 시스템에 아예 설정하지 않은 이유는 무엇입니까?", "이상 접근 경보가 발생했음에도 소명 절차 없이 전건 '정상 업무'로 일괄 무마하거나 모니터링 담당자가 확인을 누락한 근본 원인은 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §35 및 개인정보보호법 §29 위반 사항으로 미흡(결함) 확정하고, 개인정보 이상접근 모니터링 체계 전면 재구축을 요구합니다.", "na": ["당해 시스템이 개인정보(고객 및 임직원 식별정보)를 전혀 취급하지 아니하는 순수 인프라/네트워크 전용 장비에 해당합니까?"], "naEnd": "해당 시스템의 개인정보 포함 여부를 데이터베이스 테이블 명세서를 통해 검증한 후 N/A 처리 여부를 결정합니다."}, "14-6": {"decisionQ": "주요 전산 자산의 성능 요소(CPU, 메모리, 디스크, 네트워크)에 대한 임계값 경보가 설정되어 있고, 경보 발생 시 대응 절차 준수 및 주기적 적정성 검토가 수행되고 있습니까?", "verify": ["SMS/NMS 시스템 관제 화면에서 주요 서버/네트워크 장비의 CPU(예: 80% 이상), 메모리, 디스크(예: 85% 이상) 임계값 경보(Threshold Alert) 설정 화면을 보여주시겠습니까?", "임계값 초과 경보 발생 시 담당자에게 자동 통보되는 알림 설정 및 '성능 장애 대응 표준 절차서(SOP)'를 제시해 주시겠습니까?", "최근 3개월 간 발생한 성능 임계값 초과 이력 및 이에 따른 조치 결과(디스크 정합성 정리, 메모리 증설, 프로세스 재시작 등) 이력 내역을 보여주시겠습니까?", "시스템 용량 증설 및 업무량 변화를 반영하여 성능 임계값 설정 수치를 정기적으로 재검토한 보고서를 제시해 주시겠습니까?"], "verifyEnd": "성능 임계값 설정, 경보 알림 및 대응 절차서, 최근 조치 이력, 임계값 적정성 정기 검토 실적이 확인되므로 양호로 확정합니다.", "partial": ["CPU, 메모리, 디스크 임계값은 설정되어 있으나, 네트워크 트래픽/대역폭 임계값 경보 설정이 누락되어 있는 이유는 무엇입니까?", "임계값 경보는 정상 통보되나, 장애 발생 후 조치 결과에 대한 보고서 작성이 일부 누락되거나 지연되는 이유는 무엇입니까?"], "partialEnd": "성능 임계값 통제는 작동하나 네트워크 자원 누락 또는 조치 기록 관리 미비로 부분이행 판정하고 보완을 권고합니다.", "rootcause": ["주요 서버 및 DB 디스크 용량이 90% 이상 차오름에도 사전 경보 설정이 없어 장애 발생 직전까지 인지하지 못하는 경위는 무엇입니까?", "성능 임계값 경보가 수시로 발생함에도 단순 오경보(False Alarm)로 치부하여 조치 절차 없이 알림을 무시/임의 OFF 처리한 근본 원인은 무엇입니까?"], "rootcauseEnd": "전산시스템성능관리가이드 미준수로 미흡(결함) 처리하고, 자원 모니터링 임계값 재설정 및 장애 예방 대응 체계 수립을 요구합니다.", "na": ["해당 장비가 단순 소모품 또는 가상화 클러스터 내 자동 스케일아웃(Auto-Scaling)되는 환경으로 개별 성능 경보 설정 대상에서 제외되는 타당한 이유가 있습니까?"], "naEnd": "오토스케일링 정책 및 클러스터 전체 성능 관제 화면을 검증하여 해당없음 타당성을 판단합니다."}, "14-7": {"decisionQ": "CVE 및 KrCERT 등 보안 취약점 정보 수집 채널을 운영하고, 취약점 수신 시 영향 자산 파악 및 패치 SLA 준수 관리가 이루어지고 있습니까?", "verify": ["KrCERT, KISA, 벤더 보안 권고문 등 취약점 정보 구독/수신 채널 메일함이나 관리 시스템 화면을 보여주시겠습니까?", "최신 CVE 취약점(예: 최근 발령된 고위험 CVE) 수신 후, 당사 대상 자산 해당 여부를 분석한 '취약점 영향도 분석 보고서'를 제시해 주시겠습니까?", "보안 패치 적용 절차서 상의 SLA 기준(예: 긴급 7일, 일반 30일 이내)과 최근 적용된 패치 작업 내역을 대조하여 준수 여부를 보여주시겠습니까?", "전사 취약점 모니터링 및 패치 이행을 담당하는 보안 담당자 지정 문서(R&R)를 제시해 주시겠습니까?"], "verifyEnd": "취약점 구독 채널, 영향 자산 분석 실적, 패치 SLA 준수 내역 및 담당자 지정이 입증되므로 양호로 확정합니다.", "partial": ["취약점 정보는 수신하고 있으나, 당사 보유 자산 목록(자산 DB)과의 연동이 미비하여 영향 자산 파악에 지연이 발생하는 이유는 무엇입니까?", "패치 SLA 기준은 있으나, 현업 서비스 영향도 등을 이유로 승인 없이 패치 적용이 SLA 기한을 상습적으로 초과하는 이유는 무엇입니까?"], "partialEnd": "취약점 수집은 이루어지나 영향 분석 지연 또는 패치 SLA 지연이 확인되어 부분이행 처리하고 자산 연계 및 패치 프로세스 개선을 권고합니다.", "rootcause": ["KrCERT 등 공공/외부 취약점 정보 수신 채널이 전혀 지정되어 있지 않아 신규 zero-day 취약점 발생을 인지하지 못하는 경위는 무엇입니까?", "취약점 모니터링 담당자가 지정되지 않아 수신된 보안 권고문이 조치 없이 방치되고 패치가 이루어지지 않는 근본 원인은 무엇입니까?"], "rootcauseEnd": "금융IT안전성강화가이드 및 ISMS-P 2.10.5 미준수로 미흡(결함) 확정하고, 취약점 모니터링 담당자 지정 및 패치 관리 절차 수립을 요구합니다.", "na": ["모든 인프라 및 소프트웨어 운영을 외부 MSP/클라우드 사업자가 완제형 서비스 형태로 제공하여 당사가 패치 권한을 보유하지 않는 영역입니까?"], "naEnd": "MSP와의 위탁 계약서 상 취약점 모니터링 및 패치 책임 분계점을 검증하여 N/A 타당성을 검토합니다."}, "15-1": {"decisionQ": "침해사고 예방 및 대응을 위한 사고 대응 계획(IRP)과 CSIRT 구성 명단, 최근 1년 이내의 검토·갱신 이력을 지금 바로 화면에 띄워 확인해 주시겠습니까?", "verify": ["최신으로 개정된 침해사고 대응 계획서(IRP)의 최종 결재 문서와 개정 이력표를 보여주시겠습니까?", "비상연락망 및 CSIRT 조직도에 명시된 주요 보직자(대응팀장, 현장조사자, 금감원 보고 담당자 등)가 현재 실제 근무 중인 인력과 일치하는지 인사발령 시스템과 비교해 주시겠습니까?", "악성코드, DDoS, 정보유출 등 주요 침해사고 유형별로 대응 절차 및 유형별 판단 기준이 문서화되어 있는지 열람해 주시겠습니까?", "최근 1년 내 수행된 IRP 검토 또는 갱신 관련 보고서(또는 결재문서)를 조회해 주시겠습니까?"], "verifyEnd": "제시된 IRP 문서의 결재 이력, 실제 현직 인원과의 CSIRT 조직도 일치 여부, 유형별 대응 절차 및 1년 이내 검토·갱신 이력이 모두 확인되면 양호로 확정합니다. 현직 명부와 CSIRT 명단이 불일치하거나 단순 연례 문서로만 방치된 경우는 미흡 조치합니다.", "partial": ["IRP 문서나 CSIRT 조직도는 존재하나, 최근 1년 내 검토·갱신 이력이 없거나 일부 인사이동 내역이 반영되지 않은 이유는 무엇입니까?", "유형별 대응 절차 중 일부 최신 공격 기법(예: 랜섬웨어 등)에 대한 절차가 누락된 구체적 경위는 무엇입니까?", "언제까지 해당 누락 사항 및 연락망을 최신화하여 재결재를 받으실 예정입니까?"], "partialEnd": "개정 절차 이행 및 조직도 반영을 위한 개선계획을 요청하고, 차기 점검 시 갱신 완료 여부를 확인합니다.", "rootcause": ["현재 침해사고 대응 계획(IRP) 자체가 미수립되었거나, 구체적인 대응 절차 및 CSIRT 구성이 전혀 없는 사유는 무엇입니까?", "IRP 미수립 상태를 언제부터 인지하고 계셨으며, 이에 대해 경영진 보고나 예산/인력 요청 조치가 있었습니까?", "사고 발생 시 실무 부서에서는 규정된 매뉴얼 없이 어떤 방식으로 대응할 계획이었습니까?", "IRP 작성 및 CSIRT 구성을 위한 즉시 조치 계획 및 완료 예정일은 언제입니까?"], "rootcauseEnd": "보안사고 예방/대응 역량의 근본적 결함으로 확정하고, 즉시 IRP 작성 및 비상대응체계 구축 명령을 포함한 개선계획서를 제출받습니다.", "na": ["이 항목을 '해당없음'으로 응답하신 근거는 무엇입니까?", "저축은행업권 보안지침 및 전자금융감독규정에 따라 IRP 수립은 필수 의무사항인데, 이를 수립하지 않아도 되는 특수 사유가 있습니까?"], "naEnd": "IRP 수립은 전 금융기관 필수 의무 항목이므로 N/A 판정은 불가하며, 즉시 평가 대상으로 전환합니다."}, "15-2": {"decisionQ": "최근 1년 이내 실시한 침해사고 모의훈련 계획서, 결과 보고서, 그리고 개선 조치 내역을 지금 그룹웨어나 통합관리시스템에서 조회해 주시겠습니까?", "verify": ["최근 1년 내 수행된 훈련의 종합 결과 보고서 및 경영진(또는 CISO) 결재 내역을 열람해 주시겠습니까?", "훈련 시나리오에 기술적 대응(또는 Table-top 도식) 요소와 실제 상황을 반영한 구체적 절차가 포함되어 있는지 보여주시겠습니까?", "훈련 참가 대상자 명단과 실제 참석율 통계, 미참석자에 대한 조치(추가 교육 등) 이력을 조회해 주시겠습니까?", "훈련 도중 발굴된 개선 필요사항이 실제 보안시스템 설정 변경이나 절차 개정으로 반영된 증빙을 제시해 주시겠습니까?"], "verifyEnd": "연간 훈련 계획에 따른 실제 훈련 수행, 결재 보고서, 미참석자 관리, 도출된 개선점의 실제 이행 내역이 확인되면 양호로 확정합니다. 훈련을 서류로만 대체하였거나 피드백 조치가 없는 경우 미흡 처리합니다.", "partial": ["모의훈련은 실시했으나, 도출된 개선사항에 대한 이행 완료 확인이 누락되었거나 결과 보고 결재가 지연된 이유는 무엇입니까?", "훈련 참가 대상자 중 미참석자에 대한 사후 조치가 이루어지지 않은 경위는 무엇입니까?", "언제까지 미완료된 개선 조치를 완료하고 보완 훈련을 수행할 예정입니까?"], "partialEnd": "개선사항 미이행 건에 대한 조치기한을 설정하도록 요구하고 차기 점검 시 반영 여부를 확인합니다.", "rootcause": ["최근 1년간 침해대응 모의훈련을 단 한 차례도 실시하지 않은 사유는 무엇입니까?", "훈련 미실시에 대해 내부 위험평가나 경영진보고 시 지적된 바가 있습니까?", "실제 침해사고 발생 시 훈련되지 않은 대응팀이 정상적으로 작동할 수 있다고 판단하십니까?", "향후 모의훈련 수행을 위한 구체적인 시나리오 수립 및 훈련 일정 계획은 무엇입니까?"], "rootcauseEnd": "침해대응 모의훈련 미실시 결함으로 확정하고, 조속한 시일 내 모의훈련 계획 수립 및 이행을 요구합니다.", "na": ["이 항목을 '해당없음'으로 평가한 사유는 무엇입니까?", "모든 금융회사는 연 1회 이상 침해대응 모의훈련이 필수인데, 적용 대상에서 제외된다고 판단한 근거가 있습니까?"], "naEnd": "해당 규정은 금융회사 공통 필수사항이므로 N/A 판정을 철회하고 감사 점검을 진행합니다."}, "15-3": {"decisionQ": "전자금융사고 발생 시 3시간 이내 금융감독원 보고 절차서와 최신화된 금감원 보고 비상연락망을 화면으로 확인해 주시겠습니까?", "verify": ["전자금융사고 발생 시 '3시간 이내 금감원 보고' 규정이 명시된 내규 또는 업무 매뉴얼을 열람해 주시겠습니까?", "비상연락망 상의 금융감독원 담당 부서, 담당자 전화번호, 전자보고 시스템 계정이 최신으로 유지되고 있는지 직접 보여주시겠습니까?", "최근 3년간 발생한 전자금융사고(중단, 지연, 침해 등)에 대해 금감원 보고서 및 접수증(또는 보고 시스템 전송 이력)을 조회해 주시겠습니까?", "과거 사고 중 보고 시한(3시간)을 초과한 건이 있었다면 원인 분석서 및 보완책 결재문서를 확인해 주시겠습니까?"], "verifyEnd": "3시간 이내 보고 절차 명시, 최신 연락망 확인, 과거 사고에 대한 기한 내 보고 이력(또는 지연 건 발생 시 명확한 사유 분석)이 입증되면 양호로 확정합니다.", "partial": ["보고 절차서는 있으나 비상연락망의 금감원 담당자 정보가 과거 인원으로 방치되어 있는 사유는 무엇입니까?", "과거 보고 건 중 일부 보고 시한을 경과했으나 원인 분석 보고서 작성이 누락된 경위는 무엇입니까?", "비상연락망 즉시 현행화 및 보고 프로세스 재점검을 언제까지 완료하시겠습니까?"], "partialEnd": "연락망 즉시 현행화를 지시하고 보고 시한 준수를 위한 체크리스트 제출을 요구합니다.", "rootcause": ["전자금융사고 3시간 이내 보고 의무 절차 자체가 수립되어 있지 않은 사유는 무엇입니까?", "전자금융감독규정 제40조 보고 의무를 인지하지 못했거나 절차 제정을 누락한 책임은 누구에게 있습니까?", "실제 장애/사고 발생 시 금감원 보고 누락으로 인한 행정처분 위험을 어떻게 관리하고 있었습니까?", "즉시 보고 절차를 신설하고 담당자를 지정하기 위한 구체적 계획은 무엇입니까?"], "rootcauseEnd": "법적 보고 의무 절차 미비에 따른 고위험 결함으로 확정하고, 즉시 매뉴얼 제정 및 비상연락망 정비를 요구합니다.", "na": ["이 항목을 '해당없음'으로 판단한 사유는 무엇입니까? (예: 최근 3년간 보고 대상 사고가 단 한 건도 없었음)", "과거 사고가 없었더라도 보고 '절차'와 '연락망' 자체가 없어도 된다는 의미입니까?"], "naEnd": "사고 발생 이력이 없더라도 '보고 절차 및 연락망 구축'은 필수이므로, 절차 부재 시 미흡으로 판정합니다."}, "15-4": {"decisionQ": "개인정보 누출·침해 발생 시 72시간 이내 개인정보보호위원회(또는 KISA) 신고 및 정보주체 통지 매뉴얼을 지금 시스템에서 열람해 주시겠습니까?", "verify": ["개인정보보호법에 따른 '72시간 이내 신고 및 정보주체 통지' 절차가 정의된 매뉴얼을 열람해 주시겠습니까?", "신고 대상 기관(개인정보위, KISA, 금융위 등)별 신고 서식 및 담당 접수 창구 연락망이 최신으로 유지되어 있는지 확인해 주시겠습니까?", "최근 개인정보 유출/침해 사례 발생 건에 대해 72시간 내 기관 신고 접수증 및 통지문 발송 이력을 조회해 주시겠습니까?", "유출 통지 시 포함해야 할 필수 항목(유출 항목, 시점, 이용자 조치사항, 대응창구 등)이 규정 및 실제 통지문에 적정하게 포함되었는지 보여주시겠습니까?"], "verifyEnd": "72시간 내 신고/통지 절차 완비, 필수 항목을 포함한 통지 양식, 실제 유출 건 발생 시 법정 기한 내 신고 및 통지 이력이 검증되면 양호로 확정합니다.", "partial": ["기관 신고 절차(72시간)는 수립되어 있으나, 정보주체 통지 서식이나 구체적 통지 방법(SMS, 이메일 등)이 매뉴얼에서 누락된 사유는 무엇입니까?", "유출 사고 발생 시 통지유예 대상 판단 기준이 불명확하게 작성된 경위는 무엇입니까?", "누락된 통지 절차 및 양식을 언제까지 보완하여 제정하시겠습니까?"], "partialEnd": "정보주체 통지 세부 절차 보완을 지시하고 개정된 매뉴얼을 제출받아 확인합니다.", "rootcause": ["개인정보 침해 시 72시간 내 신고 및 통지 절차 자체가 전혀 마련되지 않은 원인은 무엇입니까?", "개인정보보호법 제34조 개정 내용(72시간 기준 등)을 내규에 반영하지 않고 방치한 이유는 무엇입니까?", "실제 개인정보 유출 시 법정 통지 의무 위반에 따른 과징금/과태료 위험을 인식하고 계셨습니까?", "관련 절차 수립 및 통지 시스템 연동을 위한 개선 계획은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 준수 체계 결함으로 확정하고, 즉시 유출 대응 절차 제정 및 서식 마련을 요구합니다.", "na": ["이 항목에 대해 '해당없음'으로 처리한 사유는 무엇입니까?", "저축은행이 고객 개인신용정보 및 개인정보를 처리함에도 침해 신고 절차가 해당없다고 판단한 법적 근거가 있습니까?"], "naEnd": "개인정보 처리기관으로서 침해 신고 절차는 필수이므로 N/A를 취소하고 검증을 계속합니다."}, "15-5": {"decisionQ": "과거 발생한 보안사고 및 장애에 대한 근본 원인 분석(RCA) 보고서와 재발 방지 대책 이행 내역을 조회해 주시겠습니까?", "verify": ["최근 발생한 침해사고 또는 주요 보안장애 건에 대해 작성된 RCA(Root Cause Analysis) 보고서를 보여주시겠습니까?", "RCA 보고서 내에 단순 인적 실수나 표면적 원인을 넘어 기술적·관리적 근본 원인이 도출되어 있는지 확인해 주시겠습니까?", "도출된 재발 방지 대책의 실제 이행 완료 증빙자료(시스템 개선, 결재문서, 설비 교체 등)를 재조회해 주시겠습니까?", "해당 사고 사례 및 재발 방지 대책이 임직원 교육이나 내부 공문 등을 통해 공유되었는지 내역을 보여주시겠습니까?"], "verifyEnd": "근본 원인 분석 수행, 재발 방지 대책의 실제 이행 완료 증빙, 전사 또는 관련 부서 사례 공유 이력이 모두 확인되면 양호로 확정합니다.", "partial": ["원인 분석은 이루어졌으나, 재발 방지 대책 중 일부 미이행 건에 대한 기한 연장이 반복되고 있는 이유는 무엇입니까?", "유사 사례 공유가 일부 IT 부서에만 국한되고 전사적 교육이나 안내로 이어지지 않은 경위는 무엇입니까?", "지연된 재발 방지 대책을 언제까지 최종 완결지을 예정입니까?"], "partialEnd": "미이행 재발방지책에 대한 일정을 재설정하도록 하고 개선 완료 시 증빙 제출을 요구합니다.", "rootcause": ["사고 발생 후 공식적인 근본 원인 분석(RCA) 절차를 거치지 않고 봉합한 사유는 무엇입니까?", "동일하거나 유사한 유형의 보안사고가 반복해서 발생하는 근본적인 이유는 무엇입니까?", "재발 방지 대책 수립 및 이행을 검증하는 내부 통제 체계가 작동하지 않는 이유는 무엇입니까?", "향후 사고 발생 시 RCA 보고서 작성 법제화 및 재발방지 이행 강화를 위한 개선안은 무엇입니까?"], "rootcauseEnd": "사후 관리 및 재발 방지 체계 결함으로 확정하고, 사고 사후관리 프로세스 재정비를 지시합니다.", "na": ["이 항목을 '해당없음'으로 처리한 사유가 최근 보안사고 발생 이력이 전혀 없기 때문입니까?", "과거 사고가 없었더라도 사고 발생 시 적용할 RCA 수행 절차 및 양식은 준비되어 있습니까?"], "naEnd": "과거 사고가 없더라도 RCA 절차서가 존재하면 양호/해당없음 처리하되, 절차 자체가 없으면 미흡 처리합니다."}, "15-6": {"decisionQ": "디지털 포렌식 및 증거 보전 절차서와 실제 증거 수집 시 작성하는 '증거 연계성 유지(Chain of Custody)' 양식을 보여주시겠습니까?", "verify": ["디지털 포렌식 및 증거 수집 절차가 규정된 '증거 보전 절차서'를 열람해 주시겠습니까?", "증거 수집 시 해시(Hash)값 추출, 디스크 이미징, 방수/방자 봉인 봉투 사용 등 무결성 확보 절차가 명시되어 있는지 확인해 주시겠습니까?", "증거 제출 및 이송 이력을 기록하는 'Chain of Custody(증거 연계성 양식)' 서식과 실제 작성 이력을 보여주시겠습니까?", "외부 디지털 포렌식 전문업체와의 협력 체계(MOU, 전문업체 계약서, 비상연락망 등)가 구축되어 있는지 조회해 주시겠습니까?"], "verifyEnd": "증거 보전 절차서 완비, 무결성 검증 방안(해시 등), Chain of Custody 서식 구비, 외부 전문기관 협력 계약이 확인되면 양호로 확정합니다.", "partial": ["증거 보전 절차는 있으나, 해시값 검증이나 Chain of Custody 서식 관리 등이 일부분 누락되어 있는 사유는 무엇입니까?", "외부 전문기관 협력 계약이 만료된 후 재계약이 지연되고 있는 경위는 무엇입니까?", "누락된 서식 보완 및 외부 협력 체계 재정비를 언제까지 완료하시겠습니까?"], "partialEnd": "증거 수집 양식 보완 및 외부 전문업체 계약 갱신을 요청하고 완료 보고서를 확인합니다.", "rootcause": ["디지털 포렌식 및 증거 보전 절차가 전혀 수립되어 있지 않은 사유는 무엇입니까?", "사고 발생 시 증거 훼손이나 무결성 입증 실패로 인한 법적 침해 대응 불능 위험을 고려해 보셨습니까?", "전문 도구나 인력이 없는 상태에서 증거 보전을 위해 어떤 대책을 가지고 계셨습니까?", "포렌식 절차 제정 및 전문업체 연계 체계 구축을 위한 구체적 향후 일정은 무엇입니까?"], "rootcauseEnd": "사고 증거 보전 및 포렌식 체계 부재로 결함 처리하고, 절차 수립 및 외부 협력 체계 조속 구축을 요구합니다.", "na": ["이 항목을 '해당없음'으로 응답한 사유는 무엇입니까?", "금융사고 시 법적 증빙 제출이 요구되는데 포렌식 절차가 해당없다고 본 근거가 있습니까?"], "naEnd": "금융기관 침해대응의 필수 요소이므로 N/A를 인정하지 않고 점검을 계속합니다."}, "15-7": {"decisionQ": "전사 보안사고 이력 관리 대장과 최근 작성된 연간 보안사고 통계 분석 및 예방 보고서를 시스템에서 확인해 주시겠습니까?", "verify": ["보안사고 발생 이력(일시, 유형, 피해 규모, 조치 내용 등)이 등록된 '보안사고 이력 대장'을 조회해 주시겠습니까?", "최근 1년 동안 발생한 사고/장애 건에 대해 유형별·원인별 통계 분석을 수행한 보고서를 보여주시겠습니까?", "통계 분석 결과 반복적으로 발생하는 사고 유형에 대해 수립한 '반복 사고 예방 대책' 문서를 확인해 주시겠습니까?", "연간 보안사고 발생 현황 및 개선 성과가 경영진(CISO, CEO 등)에게 정기적으로 보고되었는지 결재건을 보여주시겠습니까?"], "verifyEnd": "사고 이력 대장의 충실한 작성, 통계 분석 수행, 반복 사고 예방책 수립, 경영진 정기 보고 이력이 모두 확인되면 양호로 확정합니다.", "partial": ["사고 이력은 등록되고 있으나, 일부 소형 보안 이벤트/장애의 누락이 발견되는 이유는 무엇입니까?", "통계 분석 보고서는 작성되었으나 반복 유형에 대한 실질적인 예방책 연계가 미흡한 경위는 무엇입니까?", "이력 관리 대장의 누락분 보완 및 통계 기반 예방책 작성을 언제까지 완료하시겠습니까?"], "partialEnd": "이력 대장 전수 정비 및 통계 연계 예방 대책을 재작성하여 제출하도록 요구합니다.", "rootcause": ["보안사고 이력 대장 자체가 존재하지 않거나 사고 이력 관리를 전혀 하지 않은 사유는 무엇입니까?", "과거 발생 사고에 대한 통계나 기록이 없어 동일 사고가 계속 재발하는 상황을 인식하고 계십니까?", "사고 이력 관리를 누락해 온 내부 통제상의 원인은 무엇입니까?", "통합 사고 이력 대장 구축 및 경영진 보고 체계를 마련하기 위한 계획은 무엇입니까?"], "rootcauseEnd": "사고 관리 누계 체계 미비로 결함 처리하고, 사고 이력 대장 신설 및 정기 보고 의무화를 지시합니다.", "na": ["이 항목을 '해당없음'으로 분류한 사유는 무엇입니까?", "사고 발생 여부와 관계없이 사고 이력을 등록·관리하는 대장 체계는 필수인데, 적용 제외라고 판단한 이유가 있습니까?"], "naEnd": "이력 관리 체계는 사고 유무와 무관하게 필수적이므로 N/A를 취소하고 검사를 계속 진행합니다."}, "15-8": {"decisionQ": "최근 1년 이내 실시한 악성 이메일(피싱) 모의훈련 결과 보고서(연 2회 이상)와 취약자에 대한 사후 교육 이행 내역을 확인해 주시겠습니까?", "verify": ["최근 1년 동안 연 2회 이상 실시된 피싱 메일 모의훈련의 계획서 및 결과 보고서 결재건을 보여주시겠습니까?", "훈련 결과 보고서 내 열람율, 감염율(첨부파일 실행/링크 클릭율), 신고율에 대한 통계가 관리되고 있는지 확인해 주시겠습니까?", "훈련 시 악성 이메일을 클릭하거나 열람한 취약자(감염자) 명단과 이들에 대한 추가 보안교육 수강증을 조회해 주시겠습니까?", "임직원이 의심스러운 피싱 메일을 수신했을 때 즉시 신고할 수 있는 '피싱 신고 버튼(또는 신고 절차)' 안내 공문을 보여주시겠습니까?"], "verifyEnd": "연 2회 이상 훈련 이력, 클릭율/신고율 통계 관리, 취약자 대상 사후 교육 완료, 신고 절차 마련이 모두 증명되면 양호로 확정합니다. 연 1회만 실시했거나 취약자 조치가 없으면 미흡 처리합니다.", "partial": ["피싱 훈련은 연 2회 실시했으나, 감염자(클릭자)에 대한 추가 교육이 이행되지 않거나 지연된 사유는 무엇입니까?", "훈련 횟수가 연 1회에 그친 구체적 경위는 무엇입니까?", "누락된 추가 훈련 또는 취약자 보완 교육을 언제까지 완료하실 예정입니까?"], "partialEnd": "취약자 대상 즉시 보완 교육을 명령하고, 연 2회 훈련 주기 준수를 위한 향후 계획서를 요구합니다.", "rootcause": ["최근 1년간 피싱·소셜엔지니어링 모의훈련을 전혀 실시하지 않은 원인은 무엇입니까?", "임직원 대상 악성 메일 공격 위험이 높아지는 상황에서 피싱 훈련을 배제한 이유는 무엇입니까?", "훈련 미실시로 인한 임직원의 보안 의식 부재 및 랜섬웨어 감염 위험을 어떻게 통제할 계획이었습니까?", "연 2회 이상의 피싱 모의훈련 체계를 구축하기 위한 추진 계획은 무엇입니까?"], "rootcauseEnd": "피싱 대응 훈련 체계 부재로 결함 확정하고, 즉시 피싱 모의훈련 계획 수립 및 수행을 지시합니다.", "na": ["이 항목을 '해당없음'으로 평가한 사유는 무엇입니까?", "외부 이메일을 사용하는 모든 임직원이 피싱 공격 대상이 되는데, 훈련이 불필요하다고 판단한 근거가 있습니까?"], "naEnd": "이메일 시스템을 사용하는 저축은행 임직원 전체 대상 항목이므로 N/A 판정을 취소하고 평가를 진행합니다."}, "12-1": {"decisionQ": "시스템 및 설정 변경 시 요청, 영향분석, 승인, 적용, 결과확인의 단계별 절차와 긴급 변경 사후 정규화 절차가 지켜지고 있음을 ITSM 화면과 증적으로 바로 보여주실 수 있습니까?", "verify": ["ITSM 시스템에서 최근 3개월간 처리된 변경 요청(RFC) 목록 전체를 화면으로 조회해 주시겠습니까?", "감사역이 그중 임의로 지정하는 일반 변경건 2건과 긴급 변경건 1건의 상세 내역(영향분석서, 승인권자 결재, 사전/사후 영향 검증서)을 열어 보여주시겠습니까?", "긴급 변경건의 경우 사후 정규 승인 결재가 결함 발생 후 규정된 시간(예: 24시간 또는 익일) 내에 완결되었는지 결재 타임스탬프를 확인해 주시겠습니까?", "해당 변경 내용이 실제 서버의 작업 로그나 배포 로그와 정확히 일치하는지 배포 이력을 재조회해 보여주시겠습니까?"], "verifyEnd": "영향분석(IAM) 수행, 사전 승인, 작업 후 결과검증, 긴급 변경 사후 결재가 결재 타임스탬프 및 실제 배포 로그와 모두 일치하면 양호로 확정합니다.", "partial": ["변경 요청 및 승인은 ITSM에서 이뤄지나 영향분석(IAM) 작성이나 작업 후 결과확인서 첨부가 누락되는 비율이 있습니까?", "긴급 변경 후 사후 결재가 지연되거나 사후 정규화 절차가 서식 작성 수준에 그치고 있는 이유는 무엇입니까?", "이러한 미흡 사항이 특정 시스템이나 특정 외주개발팀에 국한되어 발생하는 것입니까?"], "partialEnd": "승인 절차는 존재하나 영향분석 또는 긴급 변경 사후 통제가 부분적으로 누락되었음을 확인하고, 미비한 단계의 표준화 및 정기 모니터링 강화를 개선사항으로 요구합니다.", "rootcause": ["승인 절차를 거치지 않고 서버나 DB 설정을 직접 변경한 작업이 발생한 경위는 무엇입니까?", "결재권자 승인 없이 배포가 진행될 수 있도록 CI/CD 및 작업 권한 통제가 통과된 이유는 무엇입니까?", "미승인 작업에 대해 모니터링이나 감사 로그 분석을 통해 사전 또는 사후에 자체적으로 인지한 적이 있습니까?"], "rootcauseEnd": "무단 변경 발생 또는 긴급 변경 사후 통제 부재는 심각한 통제 결함으로 판정하고, 통제 시스템 강제화(결재 연동 배포) 및 개선계획 제출을 요구합니다.", "na": ["해당 기간 동안 단 한 건의 시스템, 네트워크, DB 설정 변경도 발생하지 않았음을 입증할 수 있는 통제 내역이 있습니까?", "외주사 통제 환경 또는 SaaS 이용으로 직접 변경 작업이 원천적으로 불가능한 구조인지 관련 계약 및 서비스 수준 합의서(SLA)를 보여주시겠습니까?"], "naEnd": "변경 대상 시스템이 없거나 통제권이 외부에 분리되어 관리됨이 증명되면 N/A로 판정합니다."}, "12-2": {"decisionQ": "주요 운영 서버의 CPU, 메모리, 디스크 자원에 대한 임계값(80%) 경보 설정과 정기 용량 계획 및 초과 알림 처리 이력을 화면으로 보여주실 수 있습니까?", "verify": ["SMS/NMS 모니터링 시스템에 접속하여 계정계 및 뱅킹 주요 서버의 CPU/메모리/디스크 임계값 알림 설정 화면을 보여주시겠습니까?", "모든 주요 서버에 임계값이 80% 이하로 일괄 설정되어 있는지 화면상에서 확인해 주시겠습니까?", "최근 6개월 동안 임계값(80%) 초과 경보가 발생했던 이력과, 당시 담당자가 조치한 처리 내역(로그, 용량 증설, 프로세스 정리 등)을 조회해 보여주시겠습니까?", "올해 수립된 '정기 용량 계획 보고서'와 현재 실제 사용량 추이 그래프를 대조하여 보여주시겠습니까?"], "verifyEnd": "모든 주요 자원의 경보 임계값이 80% 이하로 설정되어 있고, 경보 발생 시 조치 이력이 존재하며, 정기 용량 계획에 따라 자원이 관리됨이 확인되면 양호로 확정합니다.", "partial": ["CPU 및 메모리는 80% 임계값 경보가 설정되어 있으나, 일부 디스크 파티션이나 DB 로그 영역의 임계값 설정이 누락되어 있습니까?", "임계값 초과 알림은 발생하나, 이에 대한 원인 분석 및 조치 내역 기록이 이메일/문자로만 남고 정식 이력으로 관리되지 않고 있습니까?", "용량 계획은 수립했으나 실제 사용량 급증 시 증설 예측 모델로 활용되지 못하고 있습니까?"], "partialEnd": "모니터링 체계는 구축되어 있으나 일부 서버 누락 또는 조치 이력 관리 미흡에 대해 부분 이행으로 보고 개선을 요구합니다.", "rootcause": ["주요 서버 자원의 임계값 알림 설정 자체가 꺼져 있거나 95% 이상으로 과도하게 높게 설정된 이유는 무엇입니까?", "디스크 가득 차임(Full) 등으로 장애가 발생할 때까지 모니터링 경보를 인지하지 못한 이유는 무엇입니까?", "정기적인 용량 산정 및 확장 계획 수립 절차가 아예 부재한 경위는 무엇입니까?"], "rootcauseEnd": "임계값 경보 미설정 및 용량 관리 부재는 장애 예방 통제 실패로 판정하여 심각 결함으로 지정하고 정밀 모니터링 재설정을 지시합니다.", "na": ["클라우드 Auto-scaling 또는 완전 관리형 SaaS를 사용하여 용량이 자동으로 가변 확장되므로 별도의 80% 임계값 관리가 불필요함을 검증할 수 있습니까?"], "naEnd": "자원 자동 확장 체계가 완비되어 물리적 용량 임계값 관리가 적용 대상이 아님이 입증되면 N/A로 인정합니다."}, "12-3": {"decisionQ": "운영 시스템의 일일 전체/증분 백업 수행 이력, 성공 알림, 오프사이트(원격지) 보관 현황 및 백업 매체 암호화 적용 여부를 백업 솔루션 화면에서 보여주실 수 있습니까?", "verify": ["백업 솔루션(예: Veritas, Commvault 등) 중앙 콘솔에 접속하여 최근 1개월간 일일 전체 및 증분 백업 성공/실패 로그 화면을 보여주시겠습니까?", "감사역이 지정하는 특정 날짜의 백업 실패건에 대한 자동 알림 수신 내역과 재작업(Retry) 성공 로그를 보여주시겠습니까?", "소호/원격지 백업 매체(테이프/소외 소장) 이송 일지와 오프사이트 백업 보관소 입출고 확인서를 대조해 주시겠습니까?", "백업 매체 저장 시 암호화(AES-256 등) 설정 정책이 활성화된 화면 또는 암호화 키 관리 상태를 확인해 주시겠습니까?"], "verifyEnd": "일일 전체/증분 백업 100% 성공(또는 재작업 성공), 오프사이트 물리적/논리적 분리 보관, 백업 매체 암호화가 모두 확인되면 양호로 확정합니다.", "partial": ["본점 및 데이터센터 백업은 정상이나 일부 외곽 시스템/DB의 백업 로그가 누락되어 있습니까?", "오프사이트 보관이 소외 데이터센터로 자동 소외 복제는 되나, 매체 물리 이송에 대한 관리 대장이 일부분 누락되어 있습니까?", "백업 소요 데이터의 암호화가 OS/DB 레벨에서는 적용되었으나 백업 전용 매체 저장 시에는 일부 평문 저장되고 있습니까?"], "partialEnd": "주요 데이터 백업은 이행 중이나 오프사이트 관리 대장 미비 또는 일부 매체 암호화 누락에 대해 부분 이행으로 평가하고 보완 조치를 권고합니다.", "rootcause": ["백업 실패 알림이 제대로 수신되지 않아 며칠간 백업이 누락된 상태로 방치된 경위는 무엇입니까?", "백업 매체를 소외 보관하지 않고 동일 전산실 내에 소장하거나, 소외 복제 설정이 중단된 이유는 무엇입니까?", "전자금융감독규정상 백업 매체 암호화 의무에도 불구하고 암호화를 적용하지 않은 이유는 무엇입니까?"], "rootcauseEnd": "백업 미수행, 오프사이트 보관 부재, 백업 매체 미암호화는 전자금융감독규정 제29조 위반 및 치명적 결함으로 판정하여 즉시 시정 조치합니다.", "na": ["실시간 완전 주-부 센터 간 주/야간 동기화 섀도잉 체계로 백업 매체 기반 관리가 물리적으로 존재하지 않는 구조입니까?"], "naEnd": "실시간 데이터 완전 무중단 복제 구조로 전통적 백업 매체 개념이 해당하지 않음이 확인되면 N/A로 판정합니다."}, "12-4": {"decisionQ": "분기 1회 이상 핵심 시스템에 대한 백업 데이터 복원 테스트를 실제 수행하고, 소요시간 및 성공 여부가 기록된 결과 보고서를 보여주실 수 있습니까?", "verify": ["금년도 분기별 백업 복원 테스트 계획서 및 결과 보고서 전체 문서를 제출해 주시겠습니까?", "감사역이 지정하는 가장 최근 분기 복원 테스트의 대상 시스템 목록(계정계, 정보계 등 핵심 시스템 포함 여부)을 보여주시겠습니까?", "테스트 시 실제 데이터 복원에 걸린 소요 시간(RTO 목표 대비) 및 복원된 데이터의 데이터베이스 정합성 검증 로그를 보여주시겠습니까?", "만약 복원 테스트 중 실패나 오차 발생 사례가 있었다면, 재테스트 수행 결과 및 원인 분석보고서를 재조회해 보여주시겠습니까?"], "verifyEnd": "분기 1회 이상 정기 수행, 핵심 시스템 포함, RTO 측정 및 정합성 검증 성공, 실패 시 재테스트 완결이 확인되면 양호로 확정합니다.", "partial": ["복원 테스트를 연 1~2회만 수행하거나, 일부 단위 시스템 위주로만 실시하고 계정계 핵심 DB는 제외하고 있습니까?", "복원 테스트 후 실패 원인 조치는 하였으나 재테스트 수행 증적이 누락되어 있습니까?", "복원 성공 여부만 간단히 기록하고 복원 소요시간(RTO) 측정 및 데이터 정합성 검증 절차가 부재합니까?"], "partialEnd": "복원 테스트는 수행하나 주기, 범위, RTO 측정 등 검증의 구체성이 일부 미흡하여 부분 이행으로 판정하고 개선을 권고합니다.", "rootcause": ["지난 1년간 백업 데이터 복원 테스트를 단 한 번도 수행하지 않은 경위는 무엇입니까?", "복원 테스트 실패 결과가 보고되었음에도 이를 방치하고 재테스트를 실시하지 않은 이유는 무엇입니까?", "복원 테스트 시나리오 자체가 없어 실제 장애 발생 시 백업 매체로 복원할 수 있는지 검증되지 않은 이유는 무엇입니까?"], "rootcauseEnd": "복원 테스트 미실시는 복구 불가 위험을 초래하는 심각한 결함으로 판정하며, 즉시 복원 시나리오 수립 및 테스트 수행을 요구합니다.", "na": ["해당 시스템이 신규 구축 후 운영 기간이 1분기 미만이어서 아직 정기 복원 테스트 주기(분기 1회)가 도래하지 않았음을 입증할 수 있습니까?"], "naEnd": "시스템 오픈 후 첫 분기 미도래 등 객관적 사유가 입증되면 N/A 처리합니다."}, "12-5": {"decisionQ": "OS, 미들웨어, DBMS의 보안패치를 월 1회 정기 적용하고 있으며, Critical(긴급) 취약점 발생 시 7일 이내 적용 및 예외 승인 절차가 준수됨을 패치 관리 시스템에서 보여주실 수 있습니까?", "verify": ["패치 관리 시스템(PMS) 또는 중앙 관리 콘솔에서 OS, 미들웨어, DBMS 대상 전체 패치 적용 현황 목록을 보여주시겠습니까?", "최근 3개월간 월 1회 정기 패치 수행 내역 및 대상 서버별 적용 성공률(%)을 조회해 주시겠습니까?", "최근 공지된 Critical(긴급) 보안 취약점 패치 1건을 지정할 테니, 취약점 공지일로부터 실제 패치 적용 완료일까지의 소요 일수를 타임스탬프와 함께 보여주시겠습니까?", "서비스 영향으로 패치를 즉시 적용하지 못한 예외 시스템이 있다면, 그에 대한 '패치 예외 승인서' 및 대체 보완통제 작성 이력을 열어 보여주시겠습니까?"], "verifyEnd": "정기 패치 월 1회 준수, Critical 패치 7일 이내 이행, 패치 예외 시스템의 정식 승인 및 보완통제가 모두 확인되면 양호로 확정합니다.", "partial": ["OS 정기 패치는 월 1회 적용되나, DBMS나 미들웨어 패치는 정기 일정 없이 수시/지연 적용되고 있습니까?", "Critical 패치가 7일을 초과하여 적용되었으나 이에 대한 사유서나 예외 승인 절차가 사후에 작성되었습니까?", "패치 예외 승인은 받았으나 대체 보완 통제(IPS 룰 적용, 접근 통제 강화 등) 조치가 명확히 기재되어 있지 않습니까?"], "partialEnd": "패치 관리는 수행 중이나 적용 지연 및 예외 관리 통제의 부분적 미비가 확인되어 부분 이행으로 판정합니다.", "rootcause": ["Critical 등급의 고위험 취약점이 발견되었음에도 한 달 이상 패치를 적용하지 않고 방치한 경위는 무엇입니까?", "운영 중인 서버/DB의 보안 패치 현황(Version 및 Patch Level) 자산 목록 자체가 업데이트되지 않고 있는 이유는 무엇입니까?", "패치 미적용 시스템에 대해 아무런 예외 승인 절차나 보완 통제 없이 운영하고 있는 경위는 무엇입니까?"], "rootcauseEnd": "긴급 패치 무단 방치 및 패치 관리 체계 부재는 보안 침해 사고 위험을 직결시키므로 결함으로 판정하고 개선계획 수립을 지시합니다.", "na": ["제조사 지원이 종료(EOS)되어 더 이상 패치가 제공되지 않는 구형 레거시 시스템으로, 이미 망분리 및 전용 샌드박스로 격리 통제 중인 경우입니까?"], "naEnd": "패치 제공이 불가능한 레거시로서 완벽한 격리 보완 통제가 승인된 경우에 한해 예외 판단합니다."}, "12-6": {"decisionQ": "전체 서버 및 단말에 백신이 100% 설치되어 실시간 탐지, 엔진 자동 업데이트, 정기 정밀 검사 및 악성코드 격리가 수행되고 있음을 백신 중앙 관리 콘솔에서 보여주실 수 있습니까?", "verify": ["백신 중앙 관리 서버(V3 OfficeSecurity, AhnLab EMS 등)에 접속하여 전체 대상 단말/서버 수 대비 백신 설치 단말 비율(100%) 화면을 보여주시겠습니까?", "최신 백신 바이러스 패턴 엔진 업데이트 정책이 '자동 업데이트(Real-time/Hourly)'로 설정된 화면을 확인해 주시겠습니까?", "전 단말 대상 주기적 정밀 검사(예: 주 1회 또는 월 1회) 예약 스케줄 설정과 최근 검사 완료 보고서를 보여주시겠습니까?", "최근 3개월 내 악성코드 탐지, 격리, 치료 처리 이력 보고서를 조회하여 치료 안 된 미조치 항목이 0건임을 확인해 주시겠습니까?"], "verifyEnd": "백신 설치율 100%, 엔진 최신화 유지, 정밀 검사 스케줄 가동, 악성코드 미조치건 0건이 입증되면 양호로 확정합니다.", "partial": ["PC 단말은 100% 설치되어 있으나, 일부 Linux/Unix 운영 서버의 백신 설치가 누락되어 있습니까?", "엔진 자동 업데이트는 설정되어 있으나 일부 폐쇄망 서버의 패턴 파일 수동 업데이트가 수개월간 지연되어 있습니까?", "악성코드가 탐지 및 격리는 되었으나, 해당 단말에 대한 추가 정밀 조사나 최종 조치 보고서 작성이 누락되어 있습니까?"], "partialEnd": "백신 관리가 전반적으로 이행 중이나 일부 서버 누락 또는 폐쇄망 패턴 업데이트 지연이 확인되어 부분 이행으로 판정합니다.", "rootcause": ["백신 모듈이 임의로 종료되거나 캡슐화되어 실시간 탐지 기능이 꺼진 단말이 방치된 경위는 무엇입니까?", "신규 추가된 서버에 백신 설치 절차가 누락되어 장기간 백신 없이 운영된 원인은 무엇입니까?", "악성코드 감염 경보가 발생했음에도 해당 단말 격리 및 네트워크 차단 조치를 취하지 않은 이유는 무엇입니까?"], "rootcauseEnd": "백신 미설치, 실시간 감시 비활성화, 감염 단말 미조치는 악성코드 확산 위험을 유발하는 결함으로 시정을 명합니다.", "na": ["해당 시스템이 OS가 없는 전용 하드웨어 장비(Appliance)이거나 백신 에이전트 설치가 불가능한 특수 목적 단말로 대체 통제책이 완비된 경우입니까?"], "naEnd": "백신 설치 불가능 특성 장비로서 대체 통제책이 확인된 경우 N/A로 판정합니다."}, "12-7": {"decisionQ": "모든 서버 및 네트워크 장비가 내부/외부 NTP 서버와 실시간 시간 동기화가 설정되어 있고 로그 타임스탬프의 일관성이 유지됨을 현장에서 바로 보여주실 수 있습니까?", "verify": ["감사역이 지정하는 주요 서버 2대(Windows/Linux)에 접속하여 NTP 동기화 설정 명령어(예: w32tm /query /status, ntpq -p 등) 실행 화면을 보여주시겠습니까?", "NTP 서버 구성도에서 주 NTP 서버 및 보조(이중화) NTP 서버 설정 내역을 확인해 주시겠습니까?", "감사역이 지목한 서버 2대의 현재 시스템 시간과 표출된 로그 타임스탬프의 오차가 1초 이내로 일치하는지 비교해 주시겠습니까?", "시간 동기화 오류(NTP 서비스 중단, 시간 갭 발생) 발생 시 담당자에게 알림이 발송되도록 설정된 몬스터/모니터링 경보 화면을 보여주시겠습니까?"], "verifyEnd": "전 장비 NTP 동기화 설정, NTP 이중화 구성, 서버 간 로그 타임스탬프 일관성(오차 범위 내), 동기화 오류 알림 완비가 확인되면 양호로 확정합니다.", "partial": ["서버 레벨은 NTP 동기화가 잘 되어 있으나 일부 네트워크 장비(스위치/방화벽)의 시간 동기화가 누락되어 있습니까?", "NTP 단일 서버로만 구성되어 있어 이중화 체계가 부재합니까?", "시간 동기화는 이루어지나 시간 오차 알림 설정이 없어 NTP 서비스 다운 시 사후 인지가 지연될 가능성이 있습니까?"], "partialEnd": "주요 서버 시간 동기화는 이행 중이나 장비 누락 또는 이중화/알림 설정 미비에 대해 부분 이행으로 평가합니다.", "rootcause": ["서버 간 시간 불일치로 인해 보안 로그 추적 및 사고 분석이 불가능한 상태로 운영된 원인은 무엇입니까?", "NTP 설정이 취소되어 서버 시계가 수분~수시간 이상 차이나는 현상을 방치한 이유는 무엇입니까?"], "rootcauseEnd": "시스템 시간 불일치는 로그의 법적 증거능력 무효화 및 사고 추적 불가 결함이므로 즉시 NTP 설정 재적용을 요구합니다.", "na": ["독립된 단일 망에서 단일 마스터 클럭에만 전적으로 의존하는 환경으로 별도 NTP 프로토콜 설정이 구조적으로 불필요한 경우입니까?"], "naEnd": "타임스탬프 일관성 유지를 위한 하드웨어 마스터 클럭 완비가 입증되면 N/A로 판정합니다."}, "12-8": {"decisionQ": "DBMS 내 불필요 계정·권한 정리, 샘플 DB 삭제, DB 감사 로그(Audit Log) 활성화 및 법정 보존 기간 준수 설정을 DB 관리 화면에서 보여주실 수 있습니까?", "verify": ["DB 관리 도구에서 운영 DBMS(Oracle, MSSQL 등) 전체 계정 목록을 조회하고, DBO/SA 이외 불필요 디폴트 계정(scott, test 등)이 락/삭제 처리된 화면을 보여주시겠습니까?", "DBMS 기본 설치 시 제공되는 샘플 데이터베이스 및 샘플 테이블 삭제 여부를 쿼리로 확인해 주시겠습니까?", "DB 감사 로그 설정 화면(Audit Trail 설정, DBSAFER/Fine-Grained Auditing 등)을 통해 계정 접속, DDL, 주요 DML에 대한 감사 로그가 활성화된 상태를 보여주시겠습니까?", "감사 로그 파일 저장소의 백업/보존 정책에서 전자금융감독규정에 명시된 보존 기간(최소 1년~3년 이상) 설정 화면을 확인해 주시겠습니까?"], "verifyEnd": "디폴트/샘플 계정 및 DB 삭제 완비, 주요 수행 작업 DB 감사 로그 활성화, 법정 보존기간 설정이 증명되면 양호로 확정합니다.", "partial": ["불필요 디폴트 계정은 락 처리되었으나 디폴트 비밀번호를 그대로 유지하고 있습니까?", "DB 감사 로그는 활성화되어 있으나 SELECT 등 조회 로그는 제외하고 변경(DDL/DML) 로그만 수집하고 있습니까?", "감사 로그 저장소 백업 정책은 있으나 용량 부족으로 실제 보존 기간이 1년 미만에 불과합니까?"], "partialEnd": "기본적인 DB 관리는 이행 중이나 보존 기간 미달 또는 일부 권한/로그 범위 미비에 대해 부분 이행으로 판정합니다.", "rootcause": ["운영 DB에 테스트용 샘플 DB 및 테스트 계정이 삭제되지 않고 그대로 방치된 경위는 무엇입니까?", "DB 감사 로그(Audit Log)를 성능 저하를 이유로 완전히 비활성화해 둔 경위는 무엇입니까?", "DB 감사 로그 보존 기간 미준수로 인해 과거 접속 및 변경 내역 추적이 불가능해진 원인은 무엇입니까?"], "rootcauseEnd": "DB 샘플 방치, 감사 로그 비활성화 및 보존 기간 미달은 데이터 보안의 중대한 결함으로 판정하여 즉시 개선을 지시합니다.", "na": ["해당 DB가 상용 DBMS가 아닌 설정값만 저장하는 전용 Key-Value Store 형태로 계정 및 감사 로그 개념이 적용 불가능한 구조입니까?"], "naEnd": "계정 및 SQL 구조가 없는 특수 메모리 DB 구조임이 객관적으로 증명되면 N/A 처리합니다."}, "13-1": {"decisionQ": "전자금융감독규정 제18조에 따라 업무망과 인터넷망이 물리적 또는 논리적으로 완벽히 분리되어 운영되고 있음을 네트워크 장비 및 관리 화면으로 바로 확인시켜 주실 수 있습니까?", "verify": ["현재 방화벽 및 스위치 관리 콘솔에서 업무망, DMZ, 인터넷망 간 Routing Table 및 VLAN 설정 상태를 보여주시겠습니까?", "개인신용정보를 처리하는 핵심 DB 서버가 속한 망이 별도 독립 네트워크 구역으로 격리되어 있는지 해당 스위치 ACL을 조회해 주시겠습니까?", "DMZ 구역 내 위치한 외부 접점 서버(예: 인터넷뱅킹 웹서버)에서 내부 업무망 DB로의 직접 접근이 차단되어 있음을 방화벽 정책으로 보여주시겠습니까?", "망 분리 예외 승인 시스템 목록을 출력하여, 승인된 예외 장비 외에 인가되지 않은 IP/MAC 접점이 없는지 매핑 테이블을 보여주시겠습니까?"], "verifyEnd": "제시된 네트워크 구성도와 실제 장비(방화벽/스위치) 콘솔의 Routing/ACL/VLAN 설정이 일치하고, DMZ 및 핵심DB망의 분리통제가 실시간 확인되며, 예외 승인 장비 현황에 결함이 없으면 양호로 확정합니다.", "partial": ["업무망과 인터넷망 분리는 되어 있으나, 일부 예외 단말이나 서버의 망혼용 연결에 대한 승인 절차가 누락되었거나 연장 기한이 초과된 상태입니까?", "핵심 DB 망이 독립 구역으로 존재하나, 개발망 등 타 내부망과의 접점 차단 룰이 일부 미흡한 이유는 무엇입니까?", "이러한 일부 통제 누락 상태가 발생한 시점과 경영진 보고 또는 내부 점검 시 지적된 적이 있습니까?", "완벽한 망 격리 조치를 위해 언제까지 네트워크 재설계 또는 정책 수정을 완료할 예정입니까?"], "partialEnd": "망 분리의 기본 틀은 갖추었으나 예외 관리나 내부 구획 통제가 일부 미흡하므로, 미흡 사항에 대한 개선계획 수립 및 예외 장비 즉시 정리를 조건으로 조치 이행을 요구합니다.", "rootcause": ["현재 업무망과 인터넷망 간에 물리적/논리적 분리가 제대로 적용되지 않고 혼용 사용되는 구역이 존재하는 원인은 무엇입니까?", "망 분리가 이행되지 않은 상태를 언제부터 인지하고 있었으며, 전자금융감독규정 위반 위험에 대해 상급자 보고가 이루어졌습니까?", "인터넷 접점(DMZ)과 내부 업무망 간 직접 통신이 허용되도록 설정된 경위는 무엇입니까?", "망 분리 미비에 따른 혼용 연결을 지금 즉시 차단하기 위해 취할 수 있는 긴급 네트워크 통제 조치는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제18조 위반 위험이 높은 중대 결함으로 확정하고, 즉시 시정 명령 및 네트워크 재구성 계획서를 서면으로 제출하도록 요구합니다.", "na": ["이 항목을 '해당없음'으로 응답하신 사유가 당 저축은행 내에 인터넷에 연결된 전산실/단말이 전혀 존재하지 않기 때문입니까?", "외부 연결망이 전혀 없는 단독 폐쇄망 환경임을 입증할 수 있는 통신 회선 계약서 및 네트워크 인프라 현황을 제시할 수 있습니까?"], "naEnd": "외부 인터넷 회선이 전혀 존재하지 않는 완전 격리 폐쇄망 환경임이 입증되면 해당없음을 확정합니다."}, "13-2": {"decisionQ": "전자금융감독규정 및 ISMS-P 기준에 따라 방화벽 룰셋에 대한 연 2회 이상 정기 점검과 불필요·Any 룰에 대한 정리가 이행되고 있음을 관련 보고서와 방화벽 콘솔로 입증할 수 있습니까?", "verify": ["최근 1년 동안 수행된 방화벽 룰셋 정기 검토 보고서(연 2회 이상) 및 결재 문서 2건을 제시해 주시겠습니까?", "방화벽 관리 화면에서 목적지 또는 출발지가 'Any'로 설정된 허용(Allow) 룰 검색을 실행하여 결과를 보여주시겠습니까?", "감사역이 지정하는 임의의 룰(최근 3개월간 트래픽 0인 룰)에 대해 삭제 또는 미사용 처리 조치 내역을 이력 관리 시스템에서 조회해 주시겠습니까?", "최근 변경된 방화벽 룰 3건을 무작위 지정할 테니, 해당 변경건의 신청서, 승인자, 작업 일시가 기록된 변경이력 시스템을 보여주시겠습니까?"], "verifyEnd": "연 2회 정기 검토 보고서가 존재하고, Any-to-Any 룰이 없으며, 트래픽 없는 불필요 룰의 정리가 확인되고, 무작위 지정 변경건의 승인 이력이 완벽히 매칭되면 양호로 확정합니다.", "partial": ["방화벽 룰 정기 검토가 연 1회만 수행되었거나 검토 주기(6개월)를 초과하여 진행된 이유는 무엇입니까?", "불필요 룰 정리는 진행 중이나 업무 영향도 평가 지연으로 미사용 룰이 상당수 삭제되지 않고 남아있는 상태입니까?", "일부 임시 허용 룰의 만료일 설정이 누락되어 정해진 기한 후 자동으로 차단되지 않는 사유는 무엇입니까?", "미비된 룰 검토 체계를 완비하고 미사용 룰을 전수 삭제하기 위한 조치 완료 예정일은 언제입니까?"], "partialEnd": "룰 검토 절차는 존재하나 수행 주기가 준수되지 않거나 미사용 룰 정리가 지연되고 있으므로, 룰 정비 완료 및 향후 주기 준수를 조건으로 개선 조치를 요구합니다.", "rootcause": ["방화벽에 과도한 권한을 부여하는 Any-to-Any 허용 룰이 현재 삭제되지 않고 운영 중인 경위와 원인은 무엇입니까?", "방화벽 룰 신규 등록 및 변경 시 사전 승인 절차 없이 임의로 설정이 적용된 이유가 무엇입니까?", "룰 정기 검토가 장기간(1년 이상) 전혀 이루어지지 않은 이유와 담당자/책임자의 인지 여부는 어떠합니까?", "위험도가 높은 Any 룰 및 미승인 룰을 즉시 삭제 또는 차단하기 위한 긴급 작업 가능 시점은 언제입니까?"], "rootcauseEnd": "보안 위험이 매우 높은 Any 룰 존재 또는 무단 룰 변경이 확인되어 결함으로 확정하며, 룰 전수 재조사 및 정비 계획 제출을 서면 요구합니다.", "na": ["방화벽 정책 관리 항목을 '해당없음'으로 표시한 사유가 네트워크 경계에 방화벽 장비 자체가 존재하지 않는 환경이기 때문입니까?", "방화벽 역할을 대행하는 타 보안장비가 있다면 해당 장비의 정책 관리 절차가 본 점검을 대체하고 있는지 입증할 수 있습니까?"], "naEnd": "방화벽 및 클라우드 Security Group 등 제어 장비가 전무하거나 타 검증 기준에 흡수됨이 타당할 때 해당없음을 확정합니다."}, "13-3": {"decisionQ": "침입탐지·차단시스템(IDS/IPS)의 시그니처가 주 1회 이상 최신으로 업데이트되고 있으며, 탐지 이벤트에 대한 분석 및 차단(Block) 모드가 적정하게 운영됨을 관리 화면으로 입증할 수 있습니까?", "verify": ["IPS 관리 콘솔에서 현재 적용된 시그니처 버전 및 최근 1개월간의 주차별 시그니처 업데이트 이력 로그를 보여주시겠습니까?", "IPS 핵심 네트워크 인터페이스의 운영 모드가 'Inline Block(차단 모드)'으로 설정되어 있음을 실시간 화면으로 확인해 주시겠습니까?", "최근 발생한 'High/Critical' 등급 탐지 이벤트 목록 중 감사역이 지정하는 2건에 대한 분석 및 조치 보고서(24시간 내 처리)를 조회해 주시겠습니까?", "정상 트래픽을 차단하는 오탐(False Positive) 방지를 위해 수행한 룰 튜닝 및 예외 처리 내역을 최근 3개월 기준으로 제시해 주시겠습니까?"], "verifyEnd": "시그니처 주 1회 이상 주기적 업데이트, IPS의 Inline 차단 모드 동작, 고위험 이벤트 처리 이력, 적정한 룰 튜닝 실적이 모두 확인되면 양호로 확정합니다.", "partial": ["시그니처 업데이트는 수행되나 주기가 불규칙하거나(예: 월 1회) 자동 업데이트 오류로 지연된 실적이 있습니까?", "IPS 장비 중 일부 구간(또는 특정 망)이 Inline 차단 모드가 아닌 Simple SPAN/Promiscuous(단순 탐지) 모드로 운영 중인 사유는 무엇입니까?", "탐지 이벤트 분석은 이루어지나, 오탐 관리 및 룰 튜닝 이력이 문서로 기록·관리되지 않는 상태입니까?", "차단 모드 전체 전환 및 시그니처 자동 업데이트 체계 보완을 언제까지 완료할 예정입니까?"], "partialEnd": "기본 탐지 기능은 수행 중이나 주 미준수, 일부 구간 탐지모드 운영, 튜닝 기록 미비 등 부분적 미흡이 확인되어 개선을 조건으로 의결합니다.", "rootcause": ["IPS 시그니처 업데이트가 장기간(1개월 이상) 중단되거나 방치된 원인은 무엇입니까?", "장비의 차단 성능 문제나 장애 우려로 인해 IPS를 차단 모드로 적용하지 못하고 방치한 경위는 무엇입니까?", "탐지된 고위험 공격 이벤트에 대해 담당자 확인 및 조치가 전혀 이루어지지 않은 이유는 무엇입니까?", "최신 위협 차단을 위해 시그니처 최신화 및 차단 모드 전환을 즉시 시행할 수 있습니까?"], "rootcauseEnd": "외부 침입 차단 체계의 중대한 공백(시그니처 방치, 차단 미적용)이 확인되어 결함으로 확정하며, IPS 정책 재정비 및 관리 대책 제출을 요구합니다.", "na": ["IDS/IPS 항목을 '해당없음'으로 판단한 사유가 전문 클라우드 보안관제 서비스(MSSP)로 이관되어 자체 장비 조회가 불가능하기 때문입니까?", "외부 관제업체를 사용하는 경우 해당 업체의 주 1회 시그니처 업데이트 및 24/7 차단 모드 운영 증빙을 대행 제출할 수 있습니까?"], "naEnd": "클라우드 또는 위탁 관제를 통해 본 기준 이상의 통제가 입증되면 해당없음 또는 대행 검증으로 처리합니다."}, "13-4": {"decisionQ": "네트워크 접근제어(NAC) 시스템을 통해 비인가 단말의 네트워크 접속이 즉시 차단되고, 백신·패치 미준수 단말의 자동 격리 및 예외 승인 통제가 이루어짐을 콘솔로 증명할 수 있습니까?", "verify": ["NAC 관리 콘솔에서 비인가 MAC/IP 단말이 내부망에 접속 시도 시 차단된 '비인가 단말 차단 이력 로그'(최근 1개월)를 보여주시겠습니까?", "백신 미설치 또는 필수 보안패치가 누락된 단말이 네트워크에서 차단되어 '격리(Quarantine) VLAN/페이지'로 이동한 현황을 실시간 조회해 주시겠습니까?", "NAC의 보안 정책(필수 백신 버전, 최신 OS 패치 여부 검사 룰)이 등록되어 운영되는 설정 화면을 보여주시겠습니까?", "현재 NAC 정책 적용 예외로 등록된 단말 목록을 조회하고, 각 단말별 '예외 승인 문서' 및 만료일 설정을 대조해 주시겠습니까?"], "verifyEnd": "비인가 차단 및 미준수 단말 격리 동작이 확인되고, 백신/패치 정책 검사 룰이 적용 중이며, 예외 단말 전체에 대해 적정한 승인서가 매칭되면 양호로 확정합니다.", "partial": ["비인가 단말 차단은 작동하나, 백신·패치 미준수 단말에 대한 격리 정책이 '차단'이 아닌 단순 '경고'로 설정되어 있는 사유는 무엇입니까?", "NAC 예외 단말 관리 목록은 존재하나, 일부 임시 예외 단말의 연장 승인서나 만료일 설정이 누락된 이유는 무엇입니까?", "NAC 정책 업데이트(신규 백신/패치 기준 반영) 주기가 정기적이지 않은 상태입니까?", "미준수 단말 자동 격리 강제화 및 예외 단말 정리를 위한 개선 조치 일정은 어떻게 됩니까?"], "partialEnd": "접속 통제 기본 기능은 작동하나 패치 미준수 격리 강도가 약하거나 예외 관리가 수동/지연되고 있어 개선 조치를 권고합니다.", "rootcause": ["내부망에 NAC 에이전트 미설치 단말이나 비인가 IP가 아무런 차단 없이 자유롭게 접속 가능한 원인은 무엇입니까?", "NAC 장비가 에이전트 미설치 또는 정책 미준수 단말을 격리하지 않고 차단 예외(Passive/Bypass) 모드로 방치된 이유는 무엇입니까?", "승인받지 않은 단말을 임의로 NAC 예외 리스트에 등록하여 사용해 온 경위는 어떠합니까?", "비인가 단말 접속 위험을 해소하기 위해 차단 모드 원복 및 예외 리스트 정리를 즉시 수행할 수 있습니까?"], "rootcauseEnd": "비인가 단말 접속 통제 무력화 또는 미승인 예외 등록이 확인되어 중대 결함으로 판정하고 차단 설정 원복 및 경위 제출을 요구합니다.", "na": ["NAC 항목을 '해당없음'으로 응답한 사유가 전 단말에 고정 IP 및 802.1X 포트 인증 기반 차단 체계가 구축되어 NAC을 완전히 대체하고 있기 때문입니까?", "포트 기반 물리 차단 등 대체 보안 통제 체계가 상시 작동 중임을 증빙할 수 있습니까?"], "naEnd": "802.1X 등 NAC 수준 이상의 네트워크 포트 보안 통제가 작동함이 검증되면 해당없음 처리합니다."}, "13-5": {"decisionQ": "무선침입차단시스템(WIPS)을 통해 저축은행 건물 내 비인가 AP 및 무선 단말의 접속 시도가 실시간 탐지·차단되고 있으며, 취약한 암호화 AP가 제거 운영됨을 화면으로 보여주실 수 있습니까?", "verify": ["WIPS 관리 콘솔에서 사옥 내 설치된 센서(Sensor)의 정상 동작 상태 및 커버리지 맵(Coverage Map)을 보여주시겠습니까?", "최근 1개월 내 사옥 주변에서 탐지된 'Rogue AP(비인가 AP)' 또는 '테더링/에그' 단말에 대한 자동 차단(Rogue Block) 실행 로그를 조회해 주시겠습니까?", "WIPS 탐지 정책에서 취약한 암호화 방식(WEP, WPA1 등)을 사용하는 AP 탐지 룰이 활성화되어 있는지 확인해 주시겠습니까?", "사옥 내부에서 인가되어 운영 중인 공식 업무용 AP 목록과 WIPS에 등록된 'White List AP' 리스트가 정확히 일치하는지 대조해 주시겠습니까?"], "verifyEnd": "전 사옥 범위 센서 정상 작동, 비인가 AP 차단 실적 확인, 취약 암호화 탐지 룰 적용, White List AP 일치가 모두 확인되면 양호 확정합니다.", "partial": ["WIPS 센서가 사옥 일부 구역(예: 고객 대기실, 별관)에 누락되어 무선 음영 지역이 존재하는 이유는 무엇입니까?", "비인가 AP 탐지는 정상 작동하나, 자동 차단(Block RF) 기능이 인근 타사 AP에 대한 간섭 우려로 '수동 탐지 모드'로만 운영 중입니까?", "취약 암호화 AP 제거 조치 이력이 일부 누락되어 정기적인 점검 내역으로 증명하기 어려운 상태입니까?", "무선 음영 지역 해소 및 자동 차단 정책의 안전적 적용을 위한 보완 계획은 무엇입니까?"], "partialEnd": "WIPS가 설치·운영 중이나 음영 지역이 존재하거나 차단 모드가 제한적이므로, 센서 추가 및 차단 정책 강화를 조건으로 조치를 권고합니다.", "rootcause": ["사옥 내 무선침입차단시스템(WIPS)이 설치되어 있지 않거나, 장비 전원이 꺼진 채 방치된 원인은 무엇입니까?", "내부망에 무단 연결된 개인용 비인가 무선 AP가 존재함에도 WIPS에서 아무런 탐지 및 차단이 이루어지지 않은 이유는 무엇입니까?", "전자금융감독규정상 금지된 취약한 암호화(WEP 등) AP를 내부 업무용으로 무단 설치해 사용해 온 경위는 무엇입니까?", "비인가 무선 연결을 통한 내부망 침투 위험을 막기 위해 즉시 취할 수 있는 차단 조치는 무엇입니까?"], "rootcauseEnd": "무선 보안 통제 체계의 심각한 부재(WIPS 미가동, 비인가 AP 방치)가 확인되어 결함으로 확정하고 경위서 제출 및 즉시 차단을 요구합니다.", "na": ["WIPS 점검 항목을 '해당없음'으로 표시한 사유가 저축은행이 위치한 건물 전체가 차폐 시설을 갖추고 있거나, 전 사옥에 무선 신호 방출이 불가능하도록 무선 완벽 통제 상태이기 때문입니까?", "무선 전파 차폐 검측 결과서 등 무선 위협이 원천 차단됨을 입증할 수 있는 객관적 증빙이 존재합니까?"], "naEnd": "물리적 무선 전파 완전 차폐 등 무선 위협 발생 가능성이 완전히 차단되었음이 객관적으로 입증되면 해당없음을 확정합니다."}, "13-6": {"decisionQ": "전사 엔드포인트 단말(임직원 PC 및 서버)에 EDR 에이전트가 100% 설치되어 운영 중이며, 탐지된 보안 위협 이벤트가 24시간 이내에 조사 및 처리됨을 관리 대시보드로 입증할 수 있습니까?", "verify": ["EDR 중앙 관리 콘솔에서 전체 자산(AD 계정/자산관리 DB) 대비 EDR 에이전트 설치율이 100%임을 보여주는 대시보드 화면을 확인해 주시겠습니까?", "최근 1개월간 EDR에서 탐지된 'High/Critical' 악성 행위(랜섬웨어, 미인가 스크립트 실행 등) 이벤트의 '24시간 이내 처리 이력 로그'를 제시해 주시겠습니까?", "현재 EDR 예외(에이전트 미설치 또는 탐지 예외)로 등록된 단말 목록을 조회하고, 각 단말별 승인 문서와 사유를 제시해 주시겠습니까?", "감사역이 지정하는 임의의 PC 2대에 대해 EDR 에이전트의 정상 동작 상태 및 중앙 관리 서버와의 최신 통신 일시를 재조회해 주시겠습니까?"], "verifyEnd": "EDR 설치율 100%(예외 승인건 제외), 고위험 이벤트의 24시간 내 분석·조치 완료, 지정 단말의 실시간 통신 상태가 검증되면 양호로 확정합니다.", "partial": ["전사 EDR 설치율이 100%에 미달(예: 95~99%)하여 신규 배포 PC나 특수 목적 PC에 설치가 누락된 사유는 무엇입니까?", "EDR 탐지 이벤트에 대한 분석 및 조치는 시행되나, 일부 복잡한 위협에 대해 24시간 기준을 초과하여 처리가 지연되는 이유는 무엇입니까?", "EDR 예외 단말 목록은 관리되고 있으나 예외 재검토 주기(예: 반기)에 따른 문서 업데이트가 지연된 상태입니까?", "에이전트 100% 설치 달성 및 24시간 내 이벤트 처리율 강화를 위한 조치 계획은 무엇입니까?"], "partialEnd": "EDR 시스템이 구축되어 작동 중이나 설치율 미달 및 처리 시한 초과 등 운영상 유예 사항이 존재하므로 개선 조치 이행을 요구합니다.", "rootcause": ["전사 단말 대비 EDR 에이전트 미설치 단말이 다수(설치율 90% 미만) 존재하도록 방치된 원인은 무엇입니까?", "EDR 대시보드상 악성코드 실행 및 위협 이벤트가 지속 발생함에도 담당자 확인 및 격리/대응 조치가 전혀 이루어지지 않은 경위는 무엇입니까?", "승인 절차 없이 임의로 EDR 에이전트를 삭제하거나 실시간 감시 기능을 비활성화한 단말이 존재하는 이유는 무엇입니까?", "미설치 단말에 대한 긴급 배포 및 위협 이벤트 전수 조사를 즉시 시작할 수 있습니까?"], "rootcauseEnd": "엔드포인트 위협 대응 통제 미비(설치율 저하, 위협 이벤트 방치)로 중대 결정을 내리며 즉시 전사 설치 및 미처리 이벤트 대응을 요구합니다.", "na": ["EDR 운영 점검 항목을 '해당없음'으로 응답한 사유가 저축은행 내 모든 단말이 물리적으로 외부와 완벽히 차폐된 VDI(가상데스크톱) 전용 환경이어서 타 백신/HIPS 솔루션으로 대체 운영되기 때문입니까?", "VDI 환경 등 대체 보안 체계가 EDR 수준의 행위 기반 탐지 능력을 포함하고 있음을 검증할 수 있습니까?"], "naEnd": "EDR을 대체하는 가상화 전용 보안 체계가 구축되어 동일 수준 이상의 기능이 입증되면 해당없음으로 확정합니다."}, "13-7": {"decisionQ": "DLP(정보유출방지) 솔루션을 통해 이메일, 웹, USB, 출력물 등 전 채널에서의 개인정보 및 중요 문서 유출이 차단되고 있으며, 예외 승인 및 이상 패턴 분석이 이행되고 있음을 콘솔로 확인시켜 주실 수 있습니까?", "verify": ["DLP 중앙 관리 콘솔에서 매체(USB/외장하드), 이메일, 웹 업로드, 프린터 출력 등 4대 채널에 대한 '유출 차단 정책 설정 화면'을 보여주시겠습니까?", "최근 1개월간 주민등록번호 등 개인정보가 포함된 문서의 유출 시도가 차단된 'DLP 차단 로그 및 상세 내역'을 조회해 주시겠습니까?", "USB 반출 또는 웹 업로드가 예외적으로 허용된 단말/사용자 리스트 및 해당건에 대한 사전 전자결재 승인 문서를 대조해 주시겠습니까?", "DLP 차단 이력 중 동일 사용자의 반복 차단 등 이상 유출 패턴을 분석하고 경영진 또는 정보보호최고책임자(CISO)에게 보고한 월간 분석 보고서를 제시해 주시겠습니까?"], "verifyEnd": "4대 채널 차단 정책 적용, 개인정보 차단 이력 존재, 예외 승인 문서와 설정의 100% 일치, 이상 패턴 보고서 실적이 확인되면 양호로 확정합니다.", "partial": ["DLP 채널 중 일부(예: 웹 업로드는 차단되나 모바일 핫스팟/특수 출력 채널)의 통제 정책 적용이 누락되거나 미흡한 사유는 무엇입니까?", "개인정보 유출 차단은 수행되나 차단 시 원본 파일 보관/임시 저장 조치가 연동되지 않아 사후 증거 확보가 어려운 상태입니까?", "USB 차단 예외 승인은 받았으나, 사용 기간 만료 후 예외 권한이 자동으로 회수되지 않고 남아있는 사유는 무엇입니까?", "전 채널 통제 완성 및 예외 자동 회수 프로세스 구축을 위한 조치 기한은 언제입니까?"], "partialEnd": "주요 채널 차단은 동작하나 일부 채널 누락 및 예외 만료 처리 지연이 확인되어 통제 완비 및 예외 정리를 조건으로 조치를 요구합니다.", "rootcause": ["개인정보가 수백 건 포함된 문서가 이메일/USB/웹을 통해 아무런 차단 없이 외부로 유출될 수 있도록 DLP 정책이 무력화된 원인은 무엇입니까?", "사전 승인 절차 없이 DLP 에이전트 작동을 멈추거나 차단 예외 정책을 임의로 등록하여 사용해 온 경위는 어떠합니까?", "DLP 차단 로그에 대량 유출 시도가 계속 기록됨에도 보안 담당자가 분석이나 소명 요구 없이 방치한 이유는 무엇입니까?", "유출 위험을 차단하기 위해 차단 정책 강제화 및 임의 예외 권한 전수 박탈 조치를 즉시 시행할 수 있습니까?"], "rootcauseEnd": "전자금융감독규정 제18조 위반 및 정보유출 통제 중대 결함으로 확정하며, DLP 전수 정책 재정비 및 책임자 경위서 제출을 요구합니다.", "na": ["DLP 운영 점검 항목을 '해당없음'으로 처리한 사유가 내부망 단말의 물리적 USB 포트가 전면 봉쇄되어 있고 외부 인터넷 연결망이 아예 존재하지 않는 특수 환경이기 때문입니까?", "물리적 매체 및 통신망을 통한 유출 가능성이 완전히 차단되었음을 증빙할 수 있는 시설/설비 현황을 제시할 수 있습니까?"], "naEnd": "물리적/논리적으로 유출 채널 자체가 원천 차단된 환경임이 입증되면 해당없음을 확정합니다."}, "13-8": {"decisionQ": "주요 서버 OS(Windows, Linux 등)에 대해 보안 설정 기준(CIS Benchmark 등)에 따른 Hardening이 적용되어 불필요 포트·서비스가 비활성화되고 기본 계정이 관리됨을 서버 현장에서 검증할 수 있습니까?", "verify": ["최근 수행한 서버 보안 설정(Hardening) 정기 점검 결과 보고서 및 서버별 보안 점검 체크리스트를 제시해 주시겠습니까?", "감사역이 지정하는 주요 서버 1대(Linux 또는 Windows)의 터미널/콘솔에 접속하여 불필요한 서비스(예: Telnet, FTP, rlogin)가 미가동(Inactive) 상태임을 보여주시겠습니까?", "해당 서버에서 기본 계정(root, administrator)의 직접 원격 접속 차단 설정 및 패스워드 복잡도/주기 설정 파일(/etc/pam.d 또는 OS 정책)을 열어 보여주시겠습니까?", "서버에서 외부로 열려있는 Listening 포트 목록(netstat/ss 명령어 결과)을 조회하여 허용되지 않은 미사용 포트가 없음을 확인해 주시겠습니까?"], "verifyEnd": "보안 점검 보고서 존재, 지정 서버의 불필요 서비스/포트 비활성화, 기본 계정 원격 접속 차단 및 패스워드 정책 설정이 현장 조회로 입증되면 양호로 확정합니다.", "partial": ["서버 보안 점검은 정기적으로 시행되나, 점검 결과 발굴된 취약 항목에 대한 조치(비활성화 등)가 업무 영향도를 이유로 수개월간 지연된 사유는 무엇입냐?", "신규 추가된 서버 중 일부에 대해 보안 설정 기준(Hardening 가이드)이 적용되지 않은 채 운영 환경에 투입된 경위는 어떠합니까?", "기본 계정 이름 변경은 완료되었으나 root/administrator 기본 계정의 직접 접속 차단이 일부 내부 망에서 허용되어 있는 상태입니까?", "미조치 서버 취약점 보완 및 신규 서버 보안 하드닝 자동화 완료 시점은 언제입니까?"], "partialEnd": "하드닝 가이드는 존재하나 신규 서버 누락 및 취약점 조치 지연 등 운영 통제가 부분적으로 미흡하므로 즉시 보완을 권고합니다.", "rootcause": ["서버 운영체제 설치 후 기본 설정(Default) 상태 그대로 보안 하드닝(서비스 차단, 계정 관리) 없이 운영망에 방치된 원인은 무엇입니까?", "서버의 root/administrator 계정 패스워드가 초기 비밀번호로 유지되거나 관리자 간 공유되어 사용된 경위는 무엇입니까?", "Telnet, FTP 등 암호화되지 않은 취약한 관리용 서비스가 외부/내부망에 오랫동안 오픈되어 있었던 이유는 무엇입니까?", "보안 위험이 높은 취약 서비스를 즉시 중지하고 root 원격 접속을 차단하는 긴급 하드닝 조치를 지금 실행할 수 있습니까?"], "rootcauseEnd": "서버 보안 설정 관리의 중대한 부재로 침해사고 위험이 높아 결함으로 확정하며 취약 서버 전수 하드닝 재실시를 요구합니다.", "na": ["서버 보안 설정 항목을 '해당없음'으로 표시한 사유가 당 저축은행이 서버 인프라를 전혀 직접 관리하지 않는 완전 관리형 Serverless/PaaS 환경만을 이용하기 때문입니까?", "클라우드 서비스 제공자(CSP)와의 책임 공유 모델상 OS 하드닝 책임을 CSP가 지고 있음을 입증하는 계약 문서를 제시할 수 있습니까?"], "naEnd": "Serverless 등 OS 제어권이 없는 서비스 구조임이 확인되면 해당없음 처리합니다."}, "13-9": {"decisionQ": "내부 네트워크 및 서버/네트워크 장비에 대해 반기 1회 이상 정기 취약점 점검을 수행하고, 발견된 취약점에 대해 기한 내 조치가 이행되고 있음을 증빙 문서로 입증할 수 있습니까?", "verify": ["최근 1년 동안 수행된 내부 네트워크 취약점 점검 결과 보고서(반기별 최소 2회) 및 취약점 도구/업체 계약서를 제출해 주시겠습니까?", "점검 보고서에 포함된 취약점 자산 목록과 실제 네트워크 자산 리스트를 대조하여 점검 대상 범위 누락이 없는지 보여주시겠습니까?", "가장 최근 점검에서 발견된 'High/Critical' 등급 취약점 항목들에 대한 '취약점 조치 이행 결과 보고서' 및 조치 완료 이력을 제시해 주시겠습니까?", "취약점 조치가 연기된 항목이 있다면, 정보보호최고책임자(CISO)가 승인한 '조치 연기 사유서 및 임시 보안 대책 문서'를 대조해 주시겠습니까?"], "verifyEnd": "반기 1회 이상 점검 수행 확인, 전 자산 대상 포함, 고위험 취약점의 조치 완료(또는 CISO 승인 연기)가 입증되면 양호로 확정합니다.", "partial": ["취약점 점검이 연 1회만 수행되어 반기 1회 이상 점검 기준을 미달한 사유는 무엇입니까?", "취약점 스캔은 완료되었으나, 발견된 중위험 이하 취약점에 대한 조치 일정이 수개월간 지연되고 있는 이유는 무엇입니까?", "신규 도입된 네트워크 장비나 일부 IP 대역이 취약점 스캔 대상범위에서 누락된 상태입니까?", "미조치 취약점의 전수 보완 및 점검 주기 준수를 위한 향후 조치 계획은 무엇입니까?"], "partialEnd": "점검은 실시되었으나 점검 주기가 미달되거나 일부 자산 누락 및 중위험 항목 조치가 지연되어 조속한 개선을 요구합니다.", "rootcause": ["내부 네트워크 취약점 점검을 최근 1년 이상 전혀 수행하지 않고 방치한 원인은 무엇입니까?", "점검 결과 패치 또는 설정 변경으로 즉시 조치 가능한 고위험 취약점이 다수 도출되었음에도 아무런 조치 없이 방치한 경위는 무엇입니까?", "취약점 점검 결과를 경영진이나 CISO에게 보고하지 않고 담당자 선에서 은폐하거나 무단 조치 완료 처리한 적이 있습니까?", "미조치 고위험 취약점을 해결하기 위해 긴급 패치 작업 및 재스캔을 언제 실시할 수 있습니까?"], "rootcauseEnd": "네트워크 취약점 점검 체계 부재 또는 고위험 취약점 방치로 결함 확정하며 긴급 취약점 점검 및 조치서 제출을 요구합니다.", "na": ["네트워크 취약점 점검 항목을 '해당없음'으로 표시한 사유가 당 저축은행의 모든 네트워크 인프라가 금융보안원 등 외부 공인기관의 주기적 보안점검에 전적으로 통합되어 실시되기 때문입니까?", "공인기관의 통합 점검 결과서로 본 점검을 완전히 대체할 수 있음을 입증하는 문서를 제시할 수 있습니까?"], "naEnd": "공인기관의 통합 점검 범위에 완벽히 포함됨이 입증되면 해당없음 또는 대행 검증으로 처리합니다."}, "11-1": {"decisionQ": "개발 프로젝트 추진 시 사업 초기 보안 요구사항 명세서 작성 및 설계 단계 보안 아키텍처 리뷰를 규정대로 이행하고 계십니까?", "verify": ["최근 1년 이내 완료된 대표 프로젝트의 '보안 요구사항 명세서' 및 '보안 아키텍처 리뷰 결과서'를 지금 화면에 띄워주시겠습니까?", "해당 프로젝트의 개발계획서 및 외주개발 계약서 내 보안 요구사항(비밀유지, 보안점검, 지체상금 등) 반영 조항을 바로 보여주실 수 있습니까?", "식별된 보안 요구사항 중 미충족 항목이 발생했을 때 예외 처리 승인을 받은 실제 결재 문서 이력이 있습니까?"], "verifyEnd": "프로젝트 초기 보안 요구사항 명세, 설계 단계 아키텍처 리뷰 결재, 외주 계약서 반영 및 예외 승인 절차가 모두 확인되면 양호로 확정합니다.", "partial": ["보안 요구사항 명세서는 작성되나 설계 단계 보안 아키텍처 리뷰가 누락되는 등 특정 절차만 부분적으로 이행되는 이유는 무엇입니까?", "외주 개발 계약 시 보안 조항은 표준계약서를 사용하지만 실제 프로젝트 수행 시 이행 여부 검증이 누락되는 상태입니까?", "완전한 보안 요구사항 정의 절차 이행을 위해 언제까지 프로세스를 정비할 계획입니까?"], "partialEnd": "일부 절차 누락에 따른 개선계획서를 제출받고, 차기 프로젝트부터 전 단계를 적용하도록 요청합니다.", "rootcause": ["개발 프로젝트 수행 시 보안 요구사항 정의나 아키텍처 리뷰 관련 internal 가이드라인 자체가 부재한 상태입니까?", "사업 부서나 개발팀의 독자적 추진으로 보안담당자 사전 협의 절차가 체계적으로 통제되지 못하는 원인은 무엇입니까?", "보안 미충족 항목을 인지하고도 별도 승인 없이 운영 환경 출시를 진행한 적이 있습니까?"], "rootcauseEnd": "결함으로 확정하고, 개발 관리 규정 개정 및 보안 아키텍처 리뷰 의무화 프로세스 신설을 요구합니다.", "na": ["최근 1년 동안 자체 개발 및 외주 개발 프로젝트가 단 한 건도 수행되지 않았음을 증빙할 수 있습니까?", "향후 시스템 신규 개발 또는 대규모 고도화 계획 발생 시 반영할 사전 보안성 검토 표준 절차가 마련되어 있습니까?"], "naEnd": "개발 실적이 없음을 확인하고 해당없음으로 처리하되, 향후 사업 추진 시 관련 규정 적용을 안내합니다."}, "11-2": {"decisionQ": "개발·테스트·운영 환경이 물리적/논리적으로 완전히 분리되어 있으며, 운영 데이터의 개발 환경 반입 및 직접 접속 통제가 정상 이행되고 있습니까?", "verify": ["개발, 테스트, 운영 네트워크 구간 분리 및 접근통제 설정을 네트워크 구성도와 방화벽 정책 화면으로 바로 시연해주시겠습니까?", "개발 서버 DB에서 운영 DB로의 직접 DB Link 또는 접속 경로가 차단되어 있음을 방화벽/접근제어 시스템 설정으로 보여주실 수 있습니까?", "개발 및 테스트 환경에 사용된 데이터 중 개인정보가 포함된 테이블을 재조회하여, 마스킹/가명처리 등 비식별화가 완료된 상태임을 보여주실 수 있습니까?"], "verifyEnd": "네트워크/서버 환경의 분리, DB 직접 접근 차단 설정, 테스트 데이터의 완벽한 비식별 처리가 확인되면 양호 확정합니다.", "partial": ["네트워크는 분리되어 있으나 개발 DB에서 운영 DB의 일부 참조 테이블로 직접 접근 경로가 열려있는 이유는 무엇입니까?", "운영 데이터를 개발 환경으로 반입 시 승인 절차는 거치고 있으나, 비식별화 처리가 일부 누락된 채 테스트에 사용된 적이 있습니까?", "운영 데이터 반입 통제 강화를 위해 비식별화 자동화 도구 도입 등 향후 조치 계획은 무엇입니까?"], "partialEnd": "개발 환경 내 운영 데이터 일부 노출 및 예외 접속에 대해 즉시 차단 조치명령 및 개선계획을 수립하도록 요구합니다.", "rootcause": ["개발 생산성 편의를 위해 개발자가 운영 DB에 직접 접근 권한을 상시 보유하고 있는 상태입니까?", "운영 데이터를 비식별화 없이 개발 서버로 복사하여 사용하도록 승인해 준 경위는 무엇입니까?", "전자금융감독규정 제23조(망분리 및 접근통제) 준수 여부에 대한 자체 점검이 이루어지지 않는 원인은 무엇입니까?"], "rootcauseEnd": "중대 결함으로 확정하고, 운영 데이터 즉시 파기, 개발-운영 통제 정책 재설립 및 감사 지적 보고서를 작성합니다.", "na": ["모든 시스템이 SaaS 형태이거나 온프레미스/클라우드 개발 환경을 전혀 두고 있지 않은 특수 구조입니까?"], "naEnd": "개발 환경 자체가 존재하지 않음을 확인하고 타당할 경우 N/A 처리합니다."}, "11-3": {"decisionQ": "소스코드 운영 배포 전 SAST(정적 취약점 분석) 도구 점검이 자동화되어 의무 적용되고 있으며, 고위험 취약점 0-Close 원칙을 준수하고 계십니까?", "verify": ["형상관리/CI-CD 파이프라인(GitLab, Jenkins 등)에 연동된 SAST 점검 자동화 설정 화면을 바로 보여주실 수 있습니까?", "최근 운영에 배포된 상위 2개 프로젝트의 SAST 결과 보고서를 조회하여 Critical/High 등급 취약점 조치(0-Close) 내역을 확인해 주시겠습니까?", "예외적으로 미조치된 취약점이 있다면 CISO 등 경영진의 정식 예외 승인을 받은 결재 문서가 존재합니까?"], "verifyEnd": "SAST 의무 점검 파이프라인 통제, 고위험 취약점 조치 완료(0-Close) 및 잔여 위험에 대한 경영진 결재가 입증되면 양호 처리합니다.", "partial": ["주요 신규 프로젝트는 SAST 점검을 수행하나, 수시 소규모 변경건에 대해서는 SAST 점검이 누락되는 이유는 무엇입니까?", "Critical 등급은 조치하나 High 등급 취약점에 대해 조치 기한을 지키지 못하고 미루어지는 상태입니까?", "전수 배포건 대상 SAST 의무 통제를 위해 CI/CD 파이프라인 강제 게이트웨이를 적용할 계획은 언제입니까?"], "partialEnd": "점검 대상 범위 누락 및 미조치 항목 발생에 대한 개선 조치 명령을 발송합니다.", "rootcause": ["SAST 라이선스 부족이나 담당자 부재로 인해 배포 전 정적 진단 절차 자체가 형식적으로 운영되거나 건너뛰고 있습니까?", "고위험 취약점이 다수 발견되었음에도 개발 일정 압박으로 조치나 예외 승인 없이 임의 배포를 강행한 경위는 무엇입니까?"], "rootcauseEnd": "취약한 소스코드 배포 위험을 결함으로 지정하고, CI/CD 배포 차단 룰 적용 및 전수 점검을 요구합니다.", "na": ["소프트웨어 자체 개발이 전혀 없고 100% 외산 COTS 솔루션 도입으로 소스 변경이 아예 발생하지 않는 시스템입니까?"], "naEnd": "자체/외주 개발 소스코드가 없는 솔루션 도입건임을 확인하여 해당없음 처리합니다."}, "11-4": {"decisionQ": "대고객 서비스 등 주요 웹/앱 시스템 신규 오픈 및 대규모 변경 전 DAST(동적 진단) 또는 모의해킹을 실시하고 조치 확인 후 오픈 결재를 받으셨습니까?", "verify": ["최근 1년 이내 신규 오픈한 웹/앱 서비스의 '모의해킹(DAST) 결과 보고서' 및 '취약점 조치 완료 확인서'를 결재 시스템에서 조회해 주시겠습니까?", "식별된 취약점이 전수 재검증(Re-testing)을 통해 조치 완료되었음을 증빙하는 재점검 리포트를 보여주실 수 있습니까?", "불가피하게 조치가 미완료된 상태에서 오픈을 강행한 사례가 있다면, 관련 예외 처리 보고 및 경영진 승인 문서를 확인해 주시겠습니까?"], "verifyEnd": "DAST/모의해킹 수행, 취약점 전수 조치 재검증 보고서 및 서비스 오픈 최종 승인 문서가 일치하면 양호 판정합니다.", "partial": ["모의해킹은 수행했으나, 지적된 취약점의 조치 여부를 재검증하지 않은 채 사전 오픈한 내역이 존재합니까?", "연간 모의해킹 수립 계획 대비 일부 시스템의 진단이 지연되어 조치 미완료 상태로 운영 중인 상태입니까?", "잔여 취약점 조치 완료 예정일 및 보완 대책 수립 현황을 설명해 주실 수 있습니까?"], "partialEnd": "취약점 조치 지연에 따른 긴급 보안 조치 및 재진단 수행을 요구합니다.", "rootcause": ["오픈 일정 차질을 이유로 DAST/모의해킹 진단 절차 자체를 완전히 생략하고 오픈을 진행한 것입니까?", "모의해킹 결과 취약점이 다수 발견되었음에도 보안담당자 확인 없이 오픈 승인 결재를 완료한 경위는 무엇입니까?"], "rootcauseEnd": "중대 보안 위험 배포로 결함 확정하고, 즉시 보안 진단 및 조치 후 재결재를 이행하도록 조치합니다.", "na": ["대고객 웹/앱 인터페이스가 없고 외부 접점이 전혀 없는 Pure Internal 백엔드 시스템 변경건입니까?"], "naEnd": "외부 노출 접점이 없는 내부 시스템임을 검증한 후 N/A 처리합니다."}, "11-5": {"decisionQ": "전사 소스코드에 대해 형상관리 시스템(Git 등)을 전면 적용하고, 무단 수정 방지를 위한 Branch 보호(Branch Protection) 설정이 통제되고 있습니까?", "verify": ["Git/형상관리 시스템 관리자 화면에서 Master/Main Branch에 대한 'Direct Push 제한 및 Pull Request(Code Review) 필수 승인' 통제 설정을 보여주실 수 있습니까?", "최근 소스 변경 이력(Commit Log)을 감사역이 지정하는 무작위 소스 파일로 재조회하여, Commit 메시지, 작업자, 승인자 이력이 추적되는지 보여주시겠습니까?", "형상관리 시스템 적용 대상 제외 시스템 목록 및 그에 대한 대체 관리 방안이 존재합니까?"], "verifyEnd": "형상관리 전사 적용, Branch protection 통제 설정 및 Commit 이력의 완벽한 추적성이 확인되면 양호 확정합니다.", "partial": ["주요 계정계 소스는 형상관리를 사용하나, 일부 단위 시스템이나 웹 소스가 형상관리 없이 서버 직접 수정 방식으로 관리되는 이유는 무엇입니까?", "Git을 사용 중이나 master branch에 개발자가 직접 push할 수 있도록 통제가 풀려있는 이유는 무엇입니까?", "미적용 시스템 및 Branch 보호 정책 강화를 위해 언제까지 개선을 완료할 예정입니까?"], "partialEnd": "형상관리 통제 미흡 구간에 대한 접근통제 강화 및 Branch protection 즉시 적용 명령을 하달합니다.", "rootcause": ["형상관리 시스템 구축 없이 소스코드를 운영 서버 내에서 개발자가 직접 VI 에디터 등으로 수정하여 운영하는 방식입니까?", "소스 수정 이력이 관리되지 않아 변경 원인 파악 및 이력 추적이 불가능한 경위는 무엇입니까?"], "rootcauseEnd": "중대 결함으로 확정하고, 전사 형상관리 시스템 의무화 및 운영 서버 직접 수정 권한 즉시 박탈을 요구합니다.", "na": ["자체 개발 소스가 전혀 없고 Package형 완성품을 운영하여 소스코드 형상 변경이 불가능한 경우입니까?"], "naEnd": "소스코드 변경이 불가능한 구조임을 확인하여 N/A 처리합니다."}, "11-6": {"decisionQ": "운영 배포 시 ITSM을 통한 요청->검토->승인->배포 통제 절차를 준수하며, 긴급 배포 시 별도 승인 및 사후 보고가 적정하게 운영되고 있습니까?", "verify": ["최근 1개월간 작성된 ITSM 배포 신청 및 승인 결재 이력 전체 목록을 시스템에서 조회해 주시겠습니까?", "감사역이 지정하는 무작위 2건의 일반 배포건에 대해 사전 검토자 승인 및 배포 실행자의 직무 분리가 되어있는지 보여주실 수 있습니까?", "최근 발생한 긴급 배포건에 대하여, 긴급 승인권자 승인 결재 및 배포 후 24시간 이내 사후 보고서 결재 문서를 확인해 주시겠습니까?"], "verifyEnd": "ITSM 표준 배포 프로세스 준수, 개발자-배포자 직무분리, 긴급 배포 사후 보고서 확인 시 양호 처리합니다.", "partial": ["일반 배포 프로세스는 준수되나, 긴급 배포 후 사후 보고서 결재가 규정된 기한을 초과하여 처리되는 이유는 무엇입니까?", "ITSM 결재는 득하였으나 개발자가 직접 운영 서버에 배포 권한을 갖고 스스로 배포를 수행하는 사례가 존재합니까?", "직무분리 강화 및 사후보고 기한 준수를 위한 대책은 무엇입니까?"], "partialEnd": "개발자 운영 직접 배포 통제 및 긴급 배포 사후 통제 강화를 권고합니다.", "rootcause": ["ITSM 변경 승인 절차 없이 구두 요청이나 메신저 요청만으로 운영 배포가 상시 이루어지고 있습니까?", "미승인 배포가 발생하는 원인이 무엇이며, 이를 상시 모니터링하는 통제 체계가 전혀 존재하지 않습니까?"], "rootcauseEnd": "무단 배포 위험 중대 결함 확정, ITSM 통제 강제화 및 미승인 배포 전수 조사를 지시합니다.", "na": ["운영 환경 배포가 전무한 시스템 유지보수 정지 기간 또는 해당 사항 없음 여부를 확인합니다."], "naEnd": "해당 기간 중 변경 배포가 없음을 검증하여 N/A 처리합니다."}, "11-7": {"decisionQ": "형상관리 소스코드와 운영 배포본 간의 불일치 여부를 정기적(분기 1회 이상)으로 자동 비교 검증하고 결과를 보고하고 계십니까?", "verify": ["최근 분기 수행된 '형상관리 소스 vs 운영 배포본 무단 변경 비교 점검 결과 보고서' 결재 문서를 보여주시겠습니까?", "운영 서버의 실제 실행 파일(바이너리/소스) 해시값(Hash/MD5)과 형상관리 최신 Release 해시값을 자동 비교하는 툴/스크립트의 실행 결과 화면을 보여주실 수 있습니까?", "점검 결과 불일치 항목이 발견되었을 때 조사하고 조치한 내역서가 존재합니까?"], "verifyEnd": "분기 1회 이상 무단 배포 점검 이력, 해시값 비교 검증 스크립트 시연 및 불일치 조치 내역이 확인되면 양호 확정합니다.", "partial": ["비교 점검을 실시하고 있으나, 주기(분기 1회)를 미준수하거나 일부 서버(예: 배치 서버)를 점검 대상에서 누락한 상태입니까?", "불일치 항목이 발견되었으나 원인 규명서 작성이 지연되고 있는 사례가 존재합니까?", "전수 서버 대상 자동 비교 솔루션 적용 및 분기 점검 정례화 계획은 무엇입니까?"], "partialEnd": "점검 대상 누락 및 주기 미준수에 대한 개선 계획 작성을 지시합니다.", "rootcause": ["형상관리 소스와 운영 배포본 비교 점검을 실시한 이력이 전혀 없고, 관련 절차가 정의되어 있지 않은 상태입니까?", "운영 서버에 소스가 직접 수정되었을 가능성을 방치하고 통제하지 못하는 원인은 무엇입니까?"], "rootcauseEnd": "중대 결함 확정, 즉시 전사 운영 소스-형상관리 소스 간 해시 비교 전수 조사 및 보고명령을 하달합니다.", "na": ["운영 배포본이 완전히 암호화된 H/W 펌웨어 형태이거나 검증이 불가능한 특수 환경입니까?"], "naEnd": "해당 타당성을 확인하여 N/A 결정합니다."}, "11-8": {"decisionQ": "테스트 데이터 생성 및 활용 시 실제 개인정보 사용을 금지하며, 가명처리/비식별화 조치 및 테스트 완료 후 파기를 이행하고 계십니까?", "verify": ["회사 '테스트 데이터 관리 지침/정책' 문서에서 실 개인정보 사용 금지 및 가명처리 의무화 조항을 확인해 주시겠습니까?", "테스트 DB에 데이터를 변환/생성하는 비식별화 솔루션 실행 이력 또는 가명처리 작업 수행 결과 확인서를 보여줄 수 있습니까?", "테스트 완료 후 테스트 DB 내 개인정보 파기 또는 초기화 수행 이력(파기 확인서, 스케줄러 로그)을 보여주실 수 있습니까?"], "verifyEnd": "테스트 데이터 비식별화 정책, 가명처리 도구 사용 이력 및 테스트 후 완벽한 파기 이력이 입증되면 양호 처리합니다.", "partial": ["테스트 데이터 비식별 처리를 시행하고 있으나 마스킹 규칙이 일부 개인정보 항목(예: 주소, 전화번호)에서 누락되는 상태입니까?", "테스트 완료 후 파기 절차가 수동으로 이루어져 일정 기간 테스트 DB에 가명정보가 장기 방치되는 사례가 있습니까?", "비식별 마스킹 패턴 보완 및 파기 자동화 처리 계획은 무엇입니까?"], "partialEnd": "마스킹 정책 보완 및 테스트 완료 데이터의 즉시 파기 조치를 요구합니다.", "rootcause": ["운영 DB의 실제 고객 데이터를 어떠한 비식별화/가명처리 조치도 없이 그대로 테스트 DB로 복사하여 개발/테스트에 사용하고 있습니까?", "개인정보보호법 제28조의2 및 ISMS-P 기준을 위반하여 실 개인정보를 테스트 환경에서 무단 사용한 경위는 무엇입니까?"], "rootcauseEnd": "중대 법률 위반 결함 확정, 테스트 DB 내 실 개인정보 즉시 파기 및 가명처리 시스템 도입 명령을 하달합니다.", "na": ["개인정보를 전혀 취급하지 않는 시스템(예: 단순 인프라 감시 시스템)의 개발/테스트건입니까?"], "naEnd": "개인정보 미취급 시스템임을 확인 후 N/A 처리합니다."}, "11-9": {"decisionQ": "운영 배포 시 배포 실패 또는 장애 발생에 대비한 롤백(Rollback) 계획을 수립하고, 정기적으로 롤백 테스트를 수행하고 계십니까?", "verify": ["최근 승인된 ITSM 배포 신청서에 첨부된 '롤백 계획서(소스/DB 복구 절차, RTO 목표 명시)'를 보여주시겠습니까?", "연 1회 이상 실시한 '롤백 모의훈련/테스트 결과 보고서' 및 훈련 시 소요된 RTO 달성 기록을 보여주실 수 있습니까?", "DB 스키마 변경(DDL/DML)이 포함된 배포 시 데이터 원복(Data Rollback) 스크립트 작성 및 검증 이력이 있습니까?"], "verifyEnd": "배포별 롤백 계획 수립, 데이터 롤백 절차 구비 및 연 1회 이상 롤백 테스트 성공 보고서 확인 시 양호 처리합니다.", "partial": ["소스코드 롤백 절차는 명시되어 있으나 DB 변경에 대한 Data Rollback 스크립트 작성이 누락된 상태입니까?", "롤백 계획서는 작성하나 연간 롤백 테스트/모의훈련을 수행하지 않은 기간이 1년을 초과하였습니까?", "DB 롤백 절차 보완 및 롤백 모의훈련 수행 추진 계획은 무엇입니까?"], "partialEnd": "DB 롤백 절차 보완 및 정기 롤백 모의훈련 수립을 권고합니다.", "rootcause": ["배포 시 롤백 계획 자체를 수립하지 않고 배포를 진행하여 배포 장애 발생 시 복구가 지연된 사례가 있습니까?", "롤백 수행 기준(RTO) 및 복구 절차에 대한 가이드라인이 전혀 부재한 원인은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 배포 필수 조건에 롤백 스크립트 첨부 의무화 및 모의훈련 실시를 요구합니다.", "na": ["단순 읽기 전용 서비스이거나 배포 실패 시 이전 버전 컨테이너로 100% 자동 즉시 복구(Blue/Green 무중단 배포)되는 구조입니까?"], "naEnd": "무중단 인프라 롤백 자동화 구조임을 시연 검증 후 N/A 처리합니다."}, "11-10": {"decisionQ": "시스템 개발 시 사용되는 오픈소스 라이선스 및 CVE 취약점을 모니터링(SCA 도구 활용 등)하고, 취약한 버전 사용을 통제하고 계십니까?", "verify": ["전사 오픈소스 사용 현황 인벤토리(목록) 및 라이선스 식별 내역서를 시스템에서 바로 조회해 주시겠습니까?", "SCA(소프트웨어 구성 분석) 도구 또는 CVE 모니터링 체계를 통해 식별된 오픈소스 보안 취약점 조치 이력 보고서를 보여주실 수 있습니까?", "신규 오픈소스 도입 시 사전 보안 및 라이선스 검토 승인을 거치는 절차가 운영되고 있습니까?"], "verifyEnd": "오픈소스 목록 관리, SCA 취약점 모니터링 및 조치 이력, 사전 도입 승인 절차가 확인되면 양호 확정합니다.", "partial": ["주요 오픈소스 라이선스 관리는 이루어지나, CVE 취약점 모니터링 및 업데이트 조치가 정기적으로 이루어지지 못하고 있습니까?", "SCA 도구 없이 개발자가 수동으로 작성한 오픈소스 목록에 의존하여 누락 가능성이 존재하는 상태입니까?", "자동화된 SCA 도구 도입 및 취약 오픈소스 패치 관리 강화 계획은 무엇입니까?"], "partialEnd": "오픈소스 취약점 점검 주기 정례화 및 자동화 점검 도구 적용을 권고합니다.", "rootcause": ["개발 프로젝트 수행 시 사용된 오픈소스 현황조차 파악되지 않고 있으며, 알려진 고위험 CVE 취약 버전이 운영 환경에 포함되어 방치된 것입니까?", "오픈소스 라이선스 위반 및 보안 취약점 관리를 위한 기본 지침이 부재한 원인은 무엇입습니까?"], "rootcauseEnd": "결함으로 확정하고, 전사 오픈소스 점검(SCA) 실시 및 취약한 오픈소스 패치를 즉시 지시합니다.", "na": ["오픈소스 라이브러리/프레임워크를 전혀 사용하지 않고 100% 자체 구현 또는 정식 지원 상용 라이브러리만 사용하는 경우입니까?"], "naEnd": "오픈소스 미사용 현황을 소스 구성 분석을 통해 확인한 후 N/A 처리합니다."}, "08-1": {"decisionQ": "신규 계정 생성 시 직속 상급자와 IT 부서의 이중 승인 절차를 거치며, 직무별 최소권한 원칙이 철저히 적용되고 있습니까? 지금 신청 결재건과 실제 계정 생성 로그를 대조해 주실 수 있습니까?", "verify": ["최근 3개월간 신규 발급된 계정 목록 중 감사역이 무작위로 지정하는 3개 계정의 전자결재 신청서(상급자 및 IT 승인)를 보여주시겠습니까?", "해당 3개 계정에 대해 '직무별 권한 매트릭스'상 정의된 표준 권한 외 추가 권한이 부여된 내역이 있는지 사용자 권한 관리 시스템에서 재조회해 보여주시겠습니까?", "신청서 결재 완료 시점과 실제 계정이 생성되어 권한이 부여된 시스템 로그 시점 간의 차이를 보여주실 수 있습니까?"], "verifyEnd": "결재문서상의 승인 이력(이중 승인), 권한 매트릭스 준수 여부, 신청 시점과 생성 로그의 시차 타당성이 모두 일치함이 실시간 화면 조회를 통해 확인되어 양호로 확정합니다.", "partial": ["상급자 승인만 거치고 IT 부서 승인이 누락되거나, 반대로 IT 담당자 임의로 먼저 계정을 만든 후 사후 결재를 받은 사례가 존재합니까?", "직무별 standard 권한 매트릭스가 정립되어 있으나, 예외 권한 신청 시 보완 통제나 기한 설정 없이 영구 권한으로 부여되는 비율이 어느 정도입니까?", "이러한 승인 절차 미비 및 권한 과다 부여 상태에 대해 개선 계획을 수립하고 이행 중이신지 설명해 주시겠습니까?"], "partialEnd": "일부 절차 누락 또는 과다 권한이 확인되므로 개선계획서를 요청하고 과다 부여된 권한의 즉시 회수 조치를 지시합니다.", "rootcause": ["IT 결재 절차가 시스템적으로 강제되어 있지 않고 구두 요청이나 메일 요청으로 계정을 생성해 준 경위가 무엇입니까?", "권한 매트릭스 자체가 최신화되지 않아 신청자가 기존 사용자의 권한을 그대로 복사(Clone)하여 신청하는 관행이 지속된 이유는 무엇입니까?", "이러한 미비점이 언제부터 발생했는지, 그리고 내부 통제 과정에서 걸러지지 않은 원인은 무엇입니까?"], "rootcauseEnd": "계정 신청·승인 절차 및 최소권한 통제 무력화로 '결함' 확정합니다. 조치기한을 명시한 개선계획서 및 전수 점검을 요구합니다.", "na": ["모든 계정 생성이 인사이동 시스템과 연동되어 100% 자동 생성/부여되어 수동 신청 절차가 완전히 존재하지 않는 형태입니까?", "자동 생성 로직에 대한 검증 및 권한 매트릭스 연동 설정 백엔드 감사 로그를 보여주실 수 있습니까?"], "naEnd": "자동화 시스템 연동 및 수동 개입 불가능함이 입증되어 해당없음(N/A)으로 판정합니다."}, "08-2": {"decisionQ": "퇴직자 및 계약 만료 외주인력의 계정이 퇴직일 당일(최대 1영업일 이내) 즉시 비활성화 또는 삭제되고 있습니까? 최근 퇴직자 명단과 계정 잠금 로그를 대조해 줄 수 있습니까?", "verify": ["최근 6개월간 HR 퇴직자 명단을 띄워주시고, 감사역이 무작위로 선택한 3명의 퇴직일자와 AD/인권관리시스템의 계정 비활성화 일시 로그를 대조해 주시겠습니까?", "계정 삭제/잠금 전 해당 퇴직자의 업무 데이터 및 소유 파일에 대한 백업 및 이관 승인 결재서를 보여주시겠습니까?", "계약이 종료된 외주 용역인력 명단과 해당 용역 계정(DBSAFER, VPN 등)의 실제 권한 회수 및 계정 차단 로그를 재조회해 보여주시겠습니까?"], "verifyEnd": "HR 인사발령 일자와 계정 차단/삭제 로그가 1영업일 이내로 정확히 일치하며 백업/이관 절차가 확인되어 양호로 확정합니다.", "partial": ["퇴직 처리 당일 계정이 차단되지 않고 인사팀의 통보 지연 등으로 2~3일 이상 계정이 유지된 사례가 존재합니까?", "내부 임직원 계정은 즉시 차단되나, 외주 용역인력 계정의 경우 계약 만료 후에도 회수되지 않고 유치된 경과가 있습니까?", "지연 회수된 계정으로 퇴직일 이후 실제 로그인 시도가 있었는지 접속 로그를 확인해 주시겠습니까?"], "partialEnd": "퇴직자 계정 회수 지연 사례가 일부 확인되었으나 퇴직 후 무단 접속 이력이 없는 경우, 즉시 계정 차단 조치 및 HR-IT 간 연동 프로세스 개선 조치를 요구합니다.", "rootcause": ["퇴직자 발생 시 HR 부서에서 IT 부서로 통보하는 정식 절차가 부재하거나 자동화되어 있지 않은 이유가 무엇입니까?", "퇴직일 이후에도 해당 계정이 사용된 로그가 발견되었는데, 누가 무슨 목적으로 접속했는지 경위를 설명해 주시겠습니까?", "퇴직자 계정 회수 누락에 대한 정기적인 점검(HR-IT 계정 재조회)이 이루어지지 않은 원인은 무엇입니까?"], "rootcauseEnd": "퇴직자 계정 미회수 및 퇴직 후 접속 이력 발생으로 심각한 보안 결함 확정. 관련자 경위서 작성 및 전수 조사를 지시합니다.", "na": ["최근 1년간 내부 임직원 퇴직 및 외부 용역 계약 종료 사례가 단 한 건도 없었습니까?"], "naEnd": "해당 기간 동안 퇴직자 및 용역 종료 건이 존재하지 않음이 HR 자료로 확인되어 N/A로 처리합니다."}, "08-3": {"decisionQ": "90일 이상 로그인 이력이 없는 장기 미사용 계정에 대해 자동 잠금/삭제 설정이 적용되어 있으며, 분기 1회 이상 정기 점검을 실시하고 있습니까?", "verify": ["운영중인 주요 시스템(AD, 서버, DB, 통합계정관리)의 계정 정책 설정 화면 중 '장기 미사용 계정 자동 잠금 기준(90일)' 설정값을 보여주실 수 있습니까?", "최근 분기에 실시한 '장기 미사용 계정 점검 및 정리 보고서' 결재 문서와 실제 계정 잠금/삭제 처리 이력 로그를 대조해 주시겠습니까?", "장기 출장, 육아휴직, 병가 등으로 인한 예외 계정 목록이 존재하는 경우, 예외 사유서 및 승인 문서가 구비되어 있는지 확인해 주시겠습니까?"], "verifyEnd": "90일 미사용 자동 잠금 설정이 확인되고, 분기별 정기 점검 보고서 및 예외 계정에 대한 통제 증빙이 타당하여 양호로 확정합니다.", "partial": ["90일 미사용 계정에 대한 자동 잠금 설정은 되어 있지 않으나, 수동으로 분기별 점검을 통해 정리하고 계십니까?", "일부 시스템(예: 계정관리 미연동 레거시 서버)에서 90일 이상 미사용된 계정이 발견되었으나 로그인 차단 조치가 안 된 비율이 어느 정도입니까?", "미사용 계정 발견 시 즉시 잠금 조치를 취하지 않고 방치한 사유가 무엇입니까?"], "partialEnd": "자동 잠금 설정 미비 또는 일부 레거시 시스템의 미사용 계정 방치가 확인되어 자동화 설정 및 미사용 계정 즉시 일괄 잠금을 요구합니다.", "rootcause": ["전자금융감독규정상 90일 미사용 계정 통제가 의무임에도 정책 설정이나 정기 점검을 수행하지 않은 원인은 무엇입니까?", "장기 미사용 계정으로 분류되었음에도 예외 승인 절차 없이 임의로 잠금을 해제하여 사용한 경위가 있습니까?", "계정 점검 보고서에는 잠금 처리했다고 작성되어 있으나, 실제 DB/서버상에는 계정이 'Active' 상태인 이유는 무엇입니까(허위 보고 여부)?"], "rootcauseEnd": "미사용 계정 관리 완전 미비 및 점검 보고 불일치로 '결함' 확정합니다. 정밀 감사 및 계정 일쇄 조치를 지시합니다.", "na": ["모든 계정이 매일 상시 사용하는 계정으로만 구성되어 있으며, 미사용 계정이 발생할 수 없는 구조적 증빙이 있습니까?", "단일 사용자 전용 시스템으로 사용자 변동이 전혀 없는 형태입니까?"], "naEnd": "해당 사유로 인한 N/A 처리가 불가능함을 안내하고 점검을 진행합니다(일반적으로 N/A 불가)."}, "08-4": {"decisionQ": "시스템 내 공용 계정(Shared Account) 및 패스워드 공유 사용이 엄격히 금지되어 있으며, 불가피한 공용 계정의 경우 책임 추적성을 위한 보완 통제(개인별 식별 로그)가 적용되어 있습니까?", "verify": ["전체 서버 및 DB 계정 목록 중 개인 식별이 불가능한 공용 계정(예: admin, osuser, batch 등)의 현황 명세를 보여주시겠습니까?", "불가피하게 사용 중인 공용 계정에 대해 '공용계정 사용 승인서' 및 주기적 재검토(최소 반기 1회) 결재 이력을 보여주시겠습니까?", "공용 계정 접속 시 PAM(특권계정관리) 또는 DBSAFER 등을 통해 접속 요청자의 '실제 사용자 ID(Real User ID)'가 로그에 기록·추적되는 시연을 보여주시겠습니까?"], "verifyEnd": "공용 계정이 최소화되어 승인 관리되고 있으며, 공용 계정 사용 시 2차 인증 및 개별 사용자 식별 로그가 명확히 기록됨을 확인하여 양호로 확정합니다.", "partial": ["공용 계정이 존재하고 사전 승인 절차도 거쳤으나, 접속 로그에서 실제 어떤 작업자가 로그인했는지 개인 식별(Real User 추적)이 불가능한 상태입니까?", "공용 계정의 패스워드가 문서나 메모장 등에 평문으로 보관되어 팀원 간에 공유되고 있습니까?", "패스워드 공유 방지를 위한 1회용 비밀번호(OTP)나 PAM 시스템 도입 조치가 진행 중입니까?"], "partialEnd": "공용 계정에 대한 실사용자 추적성 미비는 중대한 통제 결함이므로 즉시 PAM 연동 또는 개별 계정 전환 조치를 지시합니다.", "rootcause": ["개별 계정 생성이 기술적으로 가능함에도 불구하고 편의성을 위해 공용 계정을 지속적으로 사용해 온 사유는 무엇입니까?", "공용 계정 패스워드를 변경하지 않고 여러 담당자가 공유하여 사용할 경우 사고 발생 시 책임 추적이 불가능하다는 점을 인지하고 계셨습니까?", "시스템 개발/운영 외주업체에게 공용 계정 및 패스워드를 그대로 제공하여 작업하게 한 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §15 위반(공용 계정 금지 및 추적성 미비)으로 '결함' 확정합니다. 개별 계정 체계로의 일괄 전환을 요구합니다.", "na": ["시스템 내에 단 하나의 공용 계정도 존재하지 않으며, 모든 로그인 및 작업이 1인 1계정으로만 이루어지는 구조임을 입증할 수 있습니까?", "서버/DB 계정 생성 정책 및 전수 계정 리스트를 제시해 주시겠습니까?"], "naEnd": "전수 계정 점검 결과 공용 계정이 완전히 전무함이 입증되어 N/A(또는 100% 양호)로 확인합니다."}, "08-5": {"decisionQ": "Root, DBA 등 최상위 특권 계정 사용이 최소화되어 있으며, 일반 업무 시 사용이 금지되고 사전 승인 및 MFA, 작업 로그 정기 검토 통제가 적용되고 있습니까?", "verify": ["시스템별 Root, Administrator, DBA 권한을 보유한 특권 계정 명단 및 담당자 지정 현황을 보여주실 수 있습니까?", "일반 운영 업무 수행 시 Root 계정 직접 접속이 통제되고, 개인 계정으로 접속 후 sudo 등을 사용하거나 PAM을 통해 사전 승인받는 절차를 시연해 주시겠습니까?", "최근 1개월간 특권 계정 사용 승인 결재 내역과 실제 PAM/접근제어 솔루션에 기록된 작업 로그 및 세션 녹화 이력을 대조해 보여주시겠습니까?", "특권 계정 활동 로그에 대해 관리자/감사역이 정기적으로 검토하고 승인한 '특권 계정 로그 검토 보고서'를 제시해 주시겠습니까?"], "verifyEnd": "특권 계정 보유자 최소화, 직접 접속 차단 및 사전 승인 기반 작업, 세션 로그 보존 및 정기 검토 이력이 완비되어 양호로 확정합니다.", "partial": ["특권 계정 사용 시 사전 승인은 받도록 되어 있으나, 긴급 작업이라는 이유로 사후 승인이 상습화되어 있습니까?", "특권 계정 작업 로그는 기록되고 있으나, 이를 보안 관리자가 정기적으로 점검 및 검토(Sign-off)하는 통제가 누락되어 있습니까?", "Root 패스워드가 봉인되어 관리되고 있으나, 패스워드 재설정 및 봉인 봉투 점검 주기가 지켜지지 않고 있습니까?"], "partialEnd": "특권 계정 통제의 일부 절차(사후 보고 남발, 로그 미검토) 미비가 확인되므로 긴급 작업 승인 절차 강화 및 정기 로그 검토 실시를 지시합니다.", "rootcause": ["편의성을 이유로 엔지니어 및 DBA가 개인 계정이 아닌 Root/DBA 계정으로 직접 상시 접속하여 업무를 수행한 경위는 무엇입니까?", "특권 계정을 통한 무단 명령어 실행이나 원장 변경 위험에 대해 사전 통제(명령어 통제: rm, drop 등)를 설정하지 않은 이유는 무엇입니까?", "특권 계정 사용 로그인 시 MFA(다중인증)가 적용되지 않고 단일 패스워드로만 접속이 가능했던 사유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 §15 위반 및 특권 계정 통제 무력화로 '결함' 확정합니다. 즉시 특권 계정 직접 접속 차단 및 PAM 연동을 요구합니다.", "na": ["클라우드 SaaS 등 완전 관리형 서비스를 이용하여 고객사가 관리하는 Root/DBA 권한 자체가 전혀 존재하지 않는 구조입니까?", "해당 아키텍처 명세서 및 권한 분리 문서를 제시해 주시겠습니까?"], "naEnd": "특권 계정 관리 주체가 존재하지 않음이 확인되어 N/A로 처리합니다."}, "08-6": {"decisionQ": "비밀번호 정책이 규정(영문+숫자+특수문자 조합 8자 이상 또는 10자 이상, 90일 주기 변경, 최근 5개 재사용 금지, 최초 로그인 시 강제 변경)대로 시스템상에 통제 설정되어 있습니까?", "verify": ["AD(그룹 정책) 및 주요 임직원/고객 시스템의 '비밀번호 복잡도 설정 화면'을 라이브로 열어 길이, 조합, 히스토리 기억(5개) 설정값을 보여주시겠습니까?", "비밀번호 유효기간이 90일로 설정되어 있으며, 만료 사전 통지 및 만료 시 미변경 로그인 차단 설정 상태를 확인해 주시겠습니까?", "신규 계정 생성 후 임시 비밀번호로 최초 로그인할 때 비밀번호 변경 창이 강제로 팝업되는지 테스트 계정으로 시연해 주시겠습니까?"], "verifyEnd": "시스템 설정 화면 확인을 통해 비밀번호 복잡도, 변경 주기(90일), 재사용 금지(5개), 최초 변경 강제가 모두 적정히 설정되어 있음을 확인하여 양호 확정합니다.", "partial": ["AD는 규정대로 설정되어 있으나, 일부 레거시 서버나 DB의 자체 계정 비밀번호 정책이 8자 미만 또는 특수문자 미필수로 약하게 설정되어 있습니까?", "비밀번호 변경 주기가 90일이 아닌 180일 또는 연 1회로 길게 설정되어 있는 시스템이 존재합니까?", "최근 5개 재사용 금지 설정이 누락되어 기존에 사용하던 비밀번호를 그대로 재설정할 수 있는 상태입니까?"], "partialEnd": "일부 시스템의 비밀번호 정책 미비가 확인되므로 전 시스템 패스워드 정책 일괄 상향 및 재설정 조치를 지시합니다.", "rootcause": ["전자금융감독규정 §16의 비밀번호 안전성 기준을 알면서도 일부 시스템에 적용하지 않은 기술적/운영적 사유는 무엇입니까?", "개발자 편의나 애플리케이션 하드코딩 등을 이유로 DB 계정 비밀번호 변경을 수년간 수행하지 않고 방치한 경위는 무엇입니까?", "비밀번호 복잡도 정책을 우회할 수 있는 예외 계정이 존재하는지, 그 관리 상태는 어떠합니까?"], "rootcauseEnd": "전자금융감독규정 위반 및 비밀번호 보안 통제 미비로 '결함' 확정합니다. 전 시스템 설정 변경 및 이행 결과 제출을 지시합니다.", "na": ["비밀번호 기반 인증 방식을 전면 폐지하고, FIDO/Passkey 또는 100% PKI 인증서 기반으로만 로그인하는 시스템입니까?", "Passwordless 인증 관련 규정 및 기술 적용 문서 제출이 가능합니까?"], "naEnd": "Passwordless 인증 체계 도입으로 비밀번호 정책 항목은 N/A로 인정합니다."}, "08-7": {"decisionQ": "인터넷망 접속, VPN 원격근무, 내부 주요 시스템 및 금융거래 시 다중인증(MFA)이 의무적으로 적용되어 있으며 우회 경로가 차단되어 있습니까?", "verify": ["VPN 원격접속 및 내부 주요 서버/DB 접근제어 접속 시 ID/PW 외에 OTP, SMS, App Push 등 MFA가 호출되는 과정을 실시간 시연해 주시겠습니까?", "MFA 적용 대상 전체 시스템 목록과 제외 시스템(예예외) 목록 및 승인 문서를 보여주실 수 있습니까?", "MFA를 우회하여 접속할 수 있는 관리자 뒷문(Bypass IP, 예외 설정 등) 존재 여부에 대한 점검 결과서를 제출해 주시겠습니까?", "고객 및 내부자의 중요 금융거래(이체, 정보변경 등) 단계에 적용된 추가 인증(MFA) 설정 화면을 확인해 주시겠습니까?"], "verifyEnd": "원격접속, 주요 시스템 및 금융거래에 MFA가 전면 적용되어 있고 예외 승인 절차 및 우회 차단이 확실하여 양호 확정합니다.", "partial": ["VPN 접속 시에는 MFA가 적용되어 있으나, 내부망 접속 후 서버/DB 직접 접속 시에는 단일 인증(ID/PW)만 사용합니까?", "MFA 예외 대상자로 승인된 인원이 과다하거나, 예외 승인 기간이 명시되지 않고 영구 예외로 방치되어 있습니까?", "MFA 인증 단말기 분실 시 비상 인증 절차(비상 OTP 등)의 승인 통제가 미비합니까?"], "partialEnd": "일부 구간 MFA 미적용 및 예외 관리 부실이 확인되므로 MFA 적용 범위 확대 및 예외 재검토 조치를 지시합니다.", "rootcause": ["전자금융감독규정 §21에 따라 원격접속 및 중요 시스템 MFA 적용이 필수임에도 적용하지 않은 사유는 무엇입니까?", "MFA 솔루션 장애 시 Bypass 기능을 켜둔 후 정상화된 이후에도 이를 끄지 않고 방치한 이력이 있습니까?", "외주 개발자 원격 작업 시 MFA 없이 단순 ID/PW 또는 IP 허용만으로 접속을 허용한 경위는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 위반 및 원격접속 보안 중대 위협으로 '결함' 확정합니다. 즉시 MFA 전면 적용 및 Bypass 차단을 요구합니다.", "na": ["외부 원격접속을 전면 차단하고 내부망에서도 물리적으로 분리되어 MFA 적용 대상이 전혀 없는 환경입니까?"], "naEnd": "원격접속 및 금융거래가 존재하는 저축은행 환경 특성상 N/A 불인정, 점검을 진행합니다."}, "08-8": {"decisionQ": "전체 임직원 및 외주인력의 접근권한에 대해 반기 1회 이상 정기 검토를 실시하고, 불필요·과도 권한을 즉시 회수 및 결과 보고서로 승인받고 있습니까?", "verify": ["최근 반기(상/하반기)에 실시한 '전사 접근권한 정기 검토 결과 보고서' 전자결재 승인 문서를 보여주실 수 있습니까?", "권한 점검 결과 '권한 조정/회수 대상'으로 도출된 사용자 명단과 실제 권한 관리 시스템상에서 해당 권한이 회수 처리된 이력 로그를 대조해 주시겠습니까?", "각 부서장(소유자) 및 IT 보안관리자의 서명/승인이 검토 문서 내에 명확히 포함되어 있는지 확인해 주시겠습니까?"], "verifyEnd": "반기별 접근권한 정기 검토가 실시되었고, 도출된 과도 권한에 대한 즉시 회수 이력 및 결재 승인이 입증되어 양호 확정합니다.", "partial": ["접근권한 검토를 실시하긴 하였으나 반기 1회가 아닌 연 1회만 실시하였습니까?", "권한 검토 보고서는 작성되었으나, 회수 대상 권한이 실제 시스템상에서 즉시 회수되지 않고 수개월간 방치되었습니까?", "부서장의 실질적 검토 없이 IT 부서에서 일괄 승인 형태로 형식적인 점검만 진행되었습니까?"], "partialEnd": "점검 주기 미준수 또는 회수 조치 지연이 확인되므로 반기별 정기 점검 준수 및 권한 회수 자동화 조치를 지시합니다.", "rootcause": ["정기 접근권한 검토를 수행하지 않거나 일부 주요 시스템(DB, 통신장비 등)을 점검 대상에서 누락한 사유는 무엇입니까?", "인사이동(보직변경) 발생 시 기존 권한을 회수하지 않아 이전 부서 권한과 신규 부서 권한이 누적(Permission Creep)되는 현상을 방치한 이유는 무엇입니까?", "권한 검토 결과보고서의 내용과 실제 시스템 권한 상태가 불일치하는 사유(허위/형식적 점검)는 무엇입니까?"], "rootcauseEnd": "접근권한 정기 검토 미비 및 부실 관리로 '결함' 확정합니다. 전사 권한 재조사 및 과다 권한 일괄 회수를 요구합니다.", "na": ["조직 인원 및 시스템 권한의 변경이 전혀 발생할 수 없는 특수 환경입니까?"], "naEnd": "ISMS-P 및 ISO 27001 필수 항목으로 N/A 불인정, 점검을 진행합니다."}, "08-9": {"decisionQ": "사용자 PC 및 주요 단말, 업무 시스템의 세션 타임아웃이 10분(또는 규정 시간) 이내로 설정되어 있고, 동시 세션 제한 및 세션 재사용 방지 통제가 적용되어 있습니까?", "verify": ["AD 그룹 정책(GPO) 및 주요 웹/C/S 업무 시스템의 '화면보호기 및 세션 타임아웃(10분 이하) 설정 화면'을 보여주실 수 있습니까?", "감사역 PC 또는 테스트 단말에서 10분간 아무런 키보드/마우스 입력 없이 방치했을 때 세션이 자동으로 잠기거나 로그아웃되는지 직접 현장 시연해 주시겠습니까?", "동일 계정으로 2개 이상의 단말에서 중복 로그인 시도 시 기존 세션이 차단되거나 접속이 거부되는 '동시 세션 제한 설정'을 시연해 주시겠습니까?", "세션 타임아웃 예외가 적용된 시스템(예: 종합상황판, 모니터링 PC)이 있다면 예외 승인 문서와 보완 통제 현황을 제출해 주시겠습니까?"], "verifyEnd": "10분 이내 자동 세션 잠금 설정 및 시연 동작, 동시 세션 제한, 예외 시스템에 대한 타당한 승인이 확인되어 양호 확정합니다.", "partial": ["PC 화면보호기는 10분으로 설정되어 있으나, 주요 업무 시스템(웹 ERP, 계정계 등)의 세션 타임아웃은 30분 이상 또는 무제한으로 되어 있습니까?", "동시 세션 제한이 적용되어 있지 않아 한 계정으로 여러 명의 사용자가 동시에 접속하여 사용할 수 있습니까?", "세션 타임아웃 예외 등록된 단말에 대한 사전 승인 문서가 구비되어 있지 않습니까?"], "partialEnd": "업무 시스템 세션 타임아웃 미비 및 중복 로그인 허용이 확인되므로 전 시스템 타임아웃 10분 단축 및 동시 접속 차단 설정을 지시합니다.", "rootcause": ["업무 불편을 이유로 화면보호기 암호 잠금 및 업무 시스템 세션 타임아웃 정책을 해제하거나 길게 늘려서 운영한 사유는 무엇입니까?", "세션 토큰 재사용 방지(세션 만료 처리) 로직이 개발 단계에서 누락되어 웹 브라우저 재시작 시 로그인 상태가 유지되는 이유는 무엇입니까?", "동시 세션 통제가 통신 모듈 레벨에서 지원되지 않음에도 보완 대책을 강구하지 않은 경위는 무엇입니까?"], "rootcauseEnd": "세션 관리 통제 부실로 인한 자리를 비운 단말기 무단 사용 위험 노출로 '결함' 확정합니다. 시스템 설정 일괄 변경을 요구합니다.", "na": ["모든 업무가 비인가자 접근이 완전히 불가능한 가상화 디스플레이 환경이며 세션 자체가 존재하지 않는 형태입니까?"], "naEnd": "해당 사유 불인정, 일반적인 IT 환경이므로 점검을 진행합니다."}, "08-10": {"decisionQ": "외부에서의 원격접속은 VPN 등 암호화된 전용 통로로만 허용되며, MFA 적용, 접속 이력 90일 이상 보존, 외부 IP의 서버 직접 접속 차단 방화벽 정책이 완비되어 있습니까?", "verify": ["방화벽 및 접근통제 시스템의 룰셋(Rule-set)에서 '외부 인터넷 IP에서 내부 서버/DB로의 직접 접속(RDP, SSH, TELNET 등)을 차단(Drop/Deny)'하는 정책을 보여주실 수 있습니까?", "원격접속 시 반드시 VPN을 경유하도록 통제된 아키텍처 구성도와 VPN 접속 시 MFA가 연동되는 설정 화면을 보여주시겠습니까?", "VPN 및 원격접속 게이트웨이의 '접속 로그 저장 설정(최소 90일, 전자금융감독규정 준수 여부)' 및 최근 3개월간 접속 이력 로그를 재조회해 주시겠습니까?"], "verifyEnd": "외부 직접 접속 차단 방화벽 룰, VPN+MFA 강제 적용, 90일 이상 원격접속 로그 보존 및 정기 검토 이력이 확인되어 양호 확정합니다.", "partial": ["원격접속 시 VPN을 사용하고 있으나, 특정 외부 IP에 대해 방화벽에서 내부 서버 직접 접속(포트포워딩, 1:1 NAT)을 허용한 예외 정책이 존재합니까?", "원격접속 이력 로그는 기록되고 있으나 보존 기간이 90일 미만(예: 30일)으로 설정되어 있거나, 정기적인 로그 점검을 하지 않습니까?", "원격접속 허용 단말에 대한 보안 프로그램(백신, DLP 등) 필수 설치 검증 통제(NAC 연동 등)가 미흡합니까?"], "partialEnd": "방화벽 예외 허용 및 로그 보존기간 미흡이 확인되므로 즉시 직접 접속 정책 삭제 및 로그 보존기간 90일 이상 연장을 지시합니다.", "rootcause": ["전자금융감독규정 §18을 위반하여 외부에서 내부 서버로 직접 접속할 수 있는 방화벽 정책을 오픈해 준 경위 및 승인권자는 누구입니까?", "원격접속 이력 로그가 누락되거나 일부 접속자의 로그만 기록된 기술적 결함의 원인은 무엇입니까?", "외주업체 유지보수를 위해 상시 오픈된 원격접속 통로가 존재하고 사전 승인 절차 없이 사용하도록 방치한 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 위반 및 원격접속 보안 무력화로 '중대 결함' 확정합니다. 즉시 원격 통로 차단 및 보안성 검토를 지시합니다.", "na": ["임직원 및 외주인력을 포함하여 외부에서의 원격접속 자체를 기술적/제도적으로 100% 불허하고 통로가 전무합니까?"], "naEnd": "원격접속 네트워크 장비 및 방화벽 룰셋 재확인을 통해 원격접속 기능 자체가 완전히 거부되어 있음이 입증되면 N/A로 인정합니다."}, "09-1": {"decisionQ": "대상 시스템별 접근통제 정책이 문서화되어 있고, 역할 기반 접근통제(RBAC) 매트릭스가 최신 상태로 유지·공지되고 있습니까?", "verify": ["최근 개정된 접근통제 정책서와 시스템별 권한 매트릭스(RBAC) 문서를 현장에서 바로 출력 또는 화면으로 보여주실 수 있습니까?", "감사역이 지정하는 특정 부서(예: 여신심사부) 직원의 현 직무와 RBAC 매트릭스상 부여 가능한 권한 범위를 즉시 대조해 주시겠습니까?", "가장 최근 정책 개정 시 이해관계자 및 전사 임직원에게 공지한 게시물이나 이메일 발송 이력을 보여주실 수 있습니까?"], "verifyEnd": "접근통제 정책서 및 RBAC 매트릭스가 최신화되어 있고, 실제 직무 권한과 일치하며, 개정 공지 이력이 확인되면 양호로 확정합니다.", "partial": ["접근통제 정책서는 존재하나 RBAC 매트릭스가 일부 최신 시스템에 적용되지 않은 이유는 무엇입니까?", "정책 개정 후 전사 공지가 누락되었거나 개정 이력 관리가 지연된 사유는 무엇입니까?", "미반영된 시스템에 대한 RBAC 적용 완료 예정일은 언제입니까?"], "partialEnd": "일부 시스템 누락 및 공지 지연 건에 대해 개선이행 계획서를 제출하도록 요청하고 보완을 지시합니다.", "rootcause": ["시스템별 접근통제 정책 문서 자체가 없거나 실효성이 없는 상태로 방치된 원인은 무엇입니까?", "RBAC 개념이 적용되지 않고 개별 계정별로 무분별하게 권한이 부여되고 있는 이유는 무엇입니까?", "이러한 관리 부실 상태에 대해 경영진 보고나 내부감사 지적이 있었습니까?"], "rootcauseEnd": "결함으로 확정하며, 규정 재정비 및 전 시스템 RBAC 재설계 계획 작성을 요구합니다.", "na": ["해당 기관에서 접근통제 정책 수립 항목을 해당없음으로 판단한 근거는 무엇입니까?", "단독으로 운영되는 독립 시스템이 없어 중앙 규정만 적용받는 구조입니까?"], "naEnd": "타 상위 기관의 통제 정책을 그대로 적용받는 등 타당한 사유가 입증되면 N/A 처리합니다."}, "09-2": {"decisionQ": "업무 시스템별 접근 허용 화이트리스트가 적용되어 있고, 비인가 접근 시도 시 실시간 경보 및 차단 조치가 이루어지고 있습니까?", "verify": ["접근통제 솔루션 콘솔 화면에서 현재 설정된 시스템별 IP/MAC 화이트리스트 등록 목록을 즉시 조회해 보여주시겠습니까?", "감사역이 지정하는 미등록 IP로 주요 업무 시스템 접속을 시도할 때, 실시간 경보가 발생하고 접속이 차단되는 모습을 현장에서 시연해 주시겠습니까?", "최근 3개월간 발생한 비인가 접근 경보 이벤트 이력 및 그에 따른 담당자의 처리 소명 대장을 보여주실 수 있습니까?", "접근통제 예외 승인 대장을 열어 현재 활성화된 예외 IP/계정의 승인 문서 및 만료일 설정을 대조해 주시겠습니까?"], "verifyEnd": "화이트리스트 설정, 실시간 차단 시연, 경보 조치 이력, 예외 관리 현황이 모두 적정하면 양호로 확정합니다.", "partial": ["일부 외곽 시스템에 화이트리스트가 아닌 블랙리스트 방식이 혼용되고 있는 이유는 무엇입니까?", "비인가 접근 경보 발생 시 담당자가 즉시 확인하지 않고 사후 처리(1~2일 지연)하는 이유는 무엇입니까?", "예외 승인 기간이 만료되었음에도 화이트리스트에서 삭제되지 않고 남아있는 사유는 무엇입니까?"], "partialEnd": "경보 처리 지연 및 예외 목록 미정비 건에 대해 시정 조치를 요구합니다.", "rootcause": ["업무 시스템에 화이트리스트 통제 정책이 전혀 적용되어 있지 않은 경위는 무엇입니까?", "접근통제 솔루션이 우회 가능한 상태(네트워크 통제 미비 등)로 방치된 원인은 무엇입니까?", "비인가 접근 모니터링 체계 자체가 부재한 것에 대해 관리자 인지가 있었습니까?"], "rootcauseEnd": "중대 결함으로 확정하며, 전자금융감독규정 위반에 따른 즉시 개선명령을 발부합니다.", "na": ["시스템 접근통제 항목이 적용되지 않는 예외적인 시스템 환경입니까?"], "naEnd": "해당 사유가 객관적으로 입증되지 않으므로 N/A 처리가 불가능합니다."}, "09-3": {"decisionQ": "운영 DB 접속 시 DB 접근제어 솔루션을 필수로 거치도록 차단되어 있으며, DBA 외 일반 사용자의 SQL 직접 실행이 엄격히 통제되고 있습니까?", "verify": ["DB 접근제어 솔루션(예: DBSAFER, Chakra Max 등) 설정 콘솔에서 운영 DB 대상 접근제어 정책 적용 현황(100% 적용 여부)을 보여주시겠습니까?", "개발자 계정으로 DB Direct Tool(Toad, Orange, Orange 등)을 이용해 운영 DB IP로 직접 TCP 1521/3306 접속을 시도하는 모습을 현장에서 시연해 주시겠습니까? (방화벽/접근제어에 의해 접속 불가능해야 함)", "DBA 계정을 제외한 일반 운영자/개발자 계정으로 DB 접근제어 솔루션 로그인 후, CUD(INSERT, UPDATE, DELETE) 쿼리 직접 실행 시 차단 메시지가 발생하는지 시연해 주시겠습니까?", "최근 1개월간 저장된 DB 접근 이력 로그의 보존 현황과 감사자의 정기 검토 서명 이력을 조회해 주시겠습니까?"], "verifyEnd": "DB 접근제어 솔루션 전면 적용, 우회 접속 차단 시연, SQL 직접 실행 차단 시연, 로그 보존이 입증되면 양호로 확정합니다.", "partial": ["신규 생성된 특정 DB 서버가 DB 접근제어 솔루션 연동에서 누락된 사유는 무엇입니까?", "특정 업무용 계정에 예외적으로 SQL 직접 실행 권한이 상시 부여되어 있는 사유는 무엇입니까?", "DB 접근 이력 로그는 보존되고 있으나, 정기 검토 이력이 수개월간 누락된 이유는 무엇입니까?"], "partialEnd": "누락된 DB 연동, 과도한 예외 권한 회수, 정기 검토 재개 조치를 요구합니다.", "rootcause": ["운영 DB 접속 시 DB 접근제어 솔루션을 우회하여 Server Local 접속이나 IP 직접 접속이 허용되고 있는 경위는 무엇입이나?", "DBA가 아닌 개발자/운영자에게 운영 DB의 Drop/Delete/Update 직권 실행 권한이 부여된 원인은 무엇입니까?", "DB 접근 로그가 전혀 보존되지 않거나 임의 삭제가 가능한 상태인 사유는 무엇입니까?"], "rootcauseEnd": "고위험 결함으로 확정하며, DB 우회 경로 즉시 차단 및 권한 회수 조치서를 작성 요구합니다.", "na": ["운영 DB를 자체 구축하여 관리하지 않는 외부 위탁 형태입니까?"], "naEnd": "위탁 관리라 하더라도 저축은행 소유 데이터베이스인 경우 통제 의무가 있으므로 N/A 적용이 불가능합니다."}, "09-4": {"decisionQ": "개인정보처리시스템 접근 인가자가 필요 최소한으로 제한되어 있고, 접속 로그가 90일 이상(또는 법적 기준 이상) 안전하게 보존되며 정기 점검이 수행되고 있습니까?", "verify": ["개인정보처리시스템 접근 권한 보유자 목록을 조회하여, 현업 업무 담당자 수 대비 최소한으로 부여되어 있는지 대조해 주시겠습니까?", "개인정보처리시스템 서버의 로그 설정 화면을 열어 접속 로그 보존 기간이 90일 이상(고유식별정보 포함 시 1~2년 이상)으로 설정된 수치를 보여주시겠습니까?", "임의의 고객 개인정보 100건 이상 대량 조회 또는 다운로드 시도 시 탐지 경보가 발생하는 모니터링 설정 화면을 시연해 주시겠습니까?", "가장 최근 분기에 실시한 '개인정보 접근 권한 정기 재검토 및 불필요 권한 회수' 결재문서를 보여주실 수 있습니까?"], "verifyEnd": "최소인원 부여, 로그 보존기간 적정, 대량조회 모니터링 동작, 분기별 권한 재검토 이력이 확인되면 양호로 확정합니다.", "partial": ["퇴사자나 보직 이동자의 개인정보처리시스템 권한 삭제가 며칠간 지연된 사례가 존재하는 이유는 무엇입습니까?", "대량 조회 탐지 기준 산정 수치(예: 일일 1,000건)가 너무 높아 실효성이 떨어지는 사유는 무엇입니까?", "분기별 권한 검토는 수행되었으나, 불필요 권한 회수 결과에 대한 증빙이 일부 누락된 이유는 무엇입니까?"], "partialEnd": "권한 회수 절차 즉시 이행 및 대량조회 탐지 기준 하향 조정을 권고합니다.", "rootcause": ["전 임직원에게 업무상 필요 여부와 무관하게 개인정보처리시스템 조회 권한이 일률 부여된 원인은 무엇입니까?", "개인정보 접속 로그 보존 설정이 안 되어 있거나 90일 이전에 자동 삭제되도록 방치된 이유는 무엇입니까?", "권한 정기 검토 절차가 수년간 한 번도 수행되지 않은 관리 부실의 원인은 무엇입니까?"], "rootcauseEnd": "개인정보보호법 위반에 따른 엄중 결함으로 확정하고 정밀 감사 대상으로 전환합니다.", "na": ["해당 시스템이 개인정보(고유식별정보, 신용정보 등)를 전혀 처리하지 않는 시스템입니까?"], "naEnd": "개인정보 미취급 시스템임이 시스템 ERD 및 테이블 정의서로 입증되면 N/A로 판정합니다."}, "09-5": {"decisionQ": "업무용 PC에서 비업무용 인터넷 사이트 및 불필요 외부 서비스 접속이 철저히 차단되고 있으며, 예외 접속은 엄격한 승인 절차를 거쳐 운영됩니까?", "verify": ["웹 게이트웨이(URL Filtering 솔루션) 관리자 화면에서 비업무 사이트(비인가 클라우드, 웹하드, 증권, 게임 등) 차단 카테고리 설정 현황을 보여주시겠습니까?", "인터넷 예외 접속 승인 대장에서 최근 승인된 3건을 무작위 추출한 후, 실제 적용된 IP/Port 제한 정책과 승인 기안문상의 만료일을 대조해 주시겠습니까?", "감사역이 지정하는 외부 파일 공유 사이트(예: Dropbox, Google Drive 등)로 테스트 파일 업로드를 시도할 때 차단 팝업이 뜨는지 현장 시연해 주시겠습니까?", "최근 1개월간 인터넷 접속 로그 분석을 통한 이상 징후(대량 데이터 외붓 전송 등) 모니터링 보고서를 보여주실 수 있습니까?"], "verifyEnd": "사이트 차단 설정, 업로드 차단 시연, 예외 승인 관리 적정성, 이상 탐지 모니터링이 확인되면 양호로 확정합니다.", "partial": ["비업무 사이트 중 일부 웹하드/메일 사이트 차단 룰이 누락되어 접속 가능한 사유는 무엇입니까?", "인터넷 예외 승인 기간이 영구로 설정되어 있거나 사후 정비가 제대로 이루어지지 않은 이유는 무엇입니까?", "외부 파일 업로드 차단 솔루션(DLP 등)이 특정 브라우저에서 제대로 작동하지 않는 이유는 무엇입니까?"], "partialEnd": "차단 룰 업데이트 및 예외 접속 건 전수 재검토 조치를 지시합니다.", "rootcause": ["업무 PC에서 아무런 제한 없이 인터넷 전반 및 외부 파일 전송 서비스 접속이 허용된 경위는 무엇입니까?", "인터넷 접속 예외 처리 시 상급자 승인 절차 없이 담당자 임의로 차단을 해제해 온 사유는 무엇입니까?", "인터넷 접속 이력 로그를 전혀 수집 및 모니터링하지 않는 이유는 무엇입니까?"], "rootcauseEnd": "결함으로 확정하며, 인터넷 차단 정책 재설정 및 예외 승인 체계 수립을 요구합니다.", "na": ["내부망 PC가 인터넷과 완전 물리적/논리적으로 분리되어 인터넷 접속이 전혀 불가능한 환경입니까?"], "naEnd": "망분리가 완료되어 인터넷 접속이 원천 차단된 PC 환경임이 확인되면 해당없음(N/A)으로 판정합니다."}, "09-6": {"decisionQ": "PC 및 서버에 화이트리스트 방식의 프로그램 실행 통제 솔루션이 100% 설치되어 비인가 프로그램의 임의 실행이 차단되고 있습니까?", "verify": ["프로그램 실행 통제 솔루션(Application Control) 중앙 관리 콘솔에서 전체 PC 및 서버 대비 Agent 설치율(100% 여부) 화면을 보여주시겠습니까?", "감사역이 지정하는 비인가 실행 파일(예: 미승인 포터블 응용프로그램, 임의 작성된 .bat/.ps1 스크립트 등)을 PC에서 실행 시 차단 메시지가 발생하는지 현장에서 시연해 주시겠습니까?", "최근 1개월간 비인가 프로그램 실행 시도 차단 이력 로그 및 이상 행위 분석 내역을 관리 콘솔에서 조회해 주시겠습니까?", "허용된 프로그램 목록(화이트리스트)의 최신 갱신 이력과 신규 소프트웨어 도입 시 검증/등록 절차 문서를 보여주실 수 있습니까?"], "verifyEnd": "솔루션 설치율 100%, 비인가 프로그램 차단 시연, 차단 이력 관리, 화이트리스트 최신화가 입증되면 양호로 확정합니다.", "partial": ["일부 임시/테스트용 PC 또는 신규 서버에 에이전트 설치가 누락된 사유는 무엇입습니까?", "화이트리스트 최신화 주기가 정해져 있지 않아 신규 업무 프로그램 등록 시 임시로 전체 통제를 풀고 사용하는 이유는 무엇입니까?", "비인가 프로그램 실행 차단 로그는 발생하나, 담당자의 정기적인 모니터링 이력이 없는 사유는 무엇입니까?"], "partialEnd": "미설치 단말 에이전트 즉시 설치 및 화이트리스트 등록 예외 절차 정비를 지시합니다.", "rootcause": ["프로그램 실행 통제 솔루션 자체가 도입되어 있지 않거나 차단 모드가 아닌 단순 '모니터링(Auditing) 모드'로 열어둔 경위는 무엇입니까?", "사용자가 임의로 프로그램 실행 통제 에이전트를 종료하거나 삭제할 수 있도록 방치된 원인은 무엇입니까?", "해당 통제 정책 미비로 인한 악성코드 감염 및 비인가 툴 사용 위험에 대해 대책이 없는 사유는 무엇입니까?"], "rootcauseEnd": "중대 결함으로 확정하며, 차단 모드 전환 및 전사 에이전트 강제 적용을 명령합니다.", "na": ["폐쇄망 단말로 인가된 특수 목적인가 시스템으로서 별도의 엄격한 물리 통제가 적용된 환경입니까?"], "naEnd": "특수 환경이라 하더라도 프로그램 실행 통제 대체 방안이 입증되지 않으면 N/A 판정이 어렵습니다."}, "09-7": {"decisionQ": "개발 운영 환경이 완전히 분리되어 있고, 개발자의 운영 소스코드 및 운영 DB에 대한 직접 접근이 기술적으로 차단되어 있습니까?", "verify": ["개발 네트워크/개발 PC에서 운영 소스코드 배포 서버 및 운영 DB 서버로의 közvetlen 접근 차단(방화벽 ACL 설정 화면)을 보여주시겠습니까?", "개발자 계정으로 운영 서버에 SSH/RDP 또는 DB 클라이언트 접속을 시도하여 접속이 차단되는 현장 시연을 해주시겠습니까?", "비상시 또는 장애 조치를 위해 개발자에게 운영 접근 권한을 예외 부여했던 최근 '운영 접근 예외 승인 대장' 및 작업 완료 후 권한 회수 이력을 조회해 주시겠습니까?", "개발 환경과 운영 환경의 물리적/논리적 분리를 입증하는 네트워크 구성도 문서를 열어 설명해 주시겠습니까?"], "verifyEnd": "개발/운영 분리 통제, 직접 접속 차단 시연, 예외 승인 및 즉시 회수 이력이 입증되면 양호로 확정합니다.", "partial": ["개발자와 운영자의 계정이 구분되어 있으나 동일 PC에서 두 환경에 동시 접속 가능한 구조인 사유는 무엇입습니까?", "운영 장애 대응을 이유로 개발자에게 부여된 운영 DB 조회 권한이 소멸되지 않고 상시 유지되는 이유는 무엇입니까?", "개발/운영 배포 시 자동화 배포 툴(CI/CD)을 사용하지 않고 수동 배포를 진행하면서 개발자 접근이 일시 허용되는 사유는 무엇입니까?"], "partialEnd": "상시 부여된 운영 권한 즉시 회수 및 자동 배포 절차 적용을 지시합니다.", "rootcause": ["개발자가 운영 DB 및 운영 서버의 Root/Admin 계정 비밀번호를 공유하여 직접 수정하고 있는 경위는 무엇입니까?", "개발 환경과 운영 환경이 동일한 서버/네트워크 내에서 혼용되어 운영되는 원인은 무엇입니까?", "전자금융감독규정상 개발/운영 분리 의무를 준수하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 위반 중대 결함으로 확정하며, 계정 파기 및 네트워크 완전 분리를 명령합니다.", "na": ["자체 개발 업무가 전혀 없고 전량 외부 패키지 SW를 도입하여 운영만 수행하는 형태입니까?"], "naEnd": "개발 업무가 전혀 존재하지 않음이 조직도 및 업무 분장표로 입증되면 N/A 판정합니다."}, "10-1": {"decisionQ": "암호화 의무 대상 식별정보(주민번호·계좌번호·카드번호·비밀번호 등) 목록과, 예외적으로 암호화를 미적용한 항목에 대한 위험수용 승인 문서를 지금 보여주실 수 있습니까?", "verify": ["개인정보보호법 및 전자금융감독규정에 따른 암호화 대상 식별정보 목록 및 암호화 적용 현황표를 보여주시겠습니까?", "최신 신규 서비스(또는 시스템) 도입 시 진행한 암호화 영향평가 및 보안 검토 결재서를 확인할 수 있습니까?", "현재 DB, 파일, 전송 구간별로 정의된 암호화 정책 문서의 최신 개정판을 제시해 주시겠습니까?", "암호화 미적용 컬럼이 존재할 경우, 정보보호최고책임자(CISO) 또는 경영진이 승인한 위험수용 결재 문서가 마련되어 있습니까?"], "verifyEnd": "암호화 대상 목록이 법령 기준을 충족하여 현행화되어 있고, 미적용 항목에 대한 CISO/경영진의 정식 위험수용 승인 결재서가 확인되면 양호로 확정합니다.", "partial": ["암호화 대상 식별 목록은 존재하나 최근 신규 도입된 서비스의 데이터 컬럼이 누락되어 있는 이유는 무엇입니까?", "미적용 항목에 대한 내부 위험평가는 수행되었으나, 정식 결재(위험수용 승인) 절차가 완료되지 않은 상태로 운영 중인 사유가 무엇입니까?", "개정된 법령 기준이 반영되지 않은 채 과거 정책 문서가 유지되고 있는 원인은 무엇입니까?"], "partialEnd": "누락된 항목에 대한 즉시 현행화 및 미승인 위험수용 건에 대한 정식 결재 진행을 요청하고 개선계획을 수령합니다.", "rootcause": ["암호화 대상 식별 목록 자체가 없거나 법적 의무 항목(주민번호 등)이 암호화 대상에서 제외된 경위는 무엇입니까?", "미적용 항목에 대해 위험수용 절차 없이 임의로 암호화를 생략한 주된 이유가 무엇입니까? (예: 시스템 성능 이슈, 개발 편의성 등)", "신규 시스템 개발 과정에서 암호화 적용 여부를 검토하는 내부 통제 절차가 아예 부재한 상황입니까?"], "rootcauseEnd": "결함으로 확정하고, 전체 DB 대상 개인정보/신용정보 전수 조사 및 암호화 대상 정의서 재정립, 미적용 항목에 대한 위험수용/암호화 적용 계획 제출을 서면 요구합니다.", "na": ["해당 시스템 또는 법인이 개인신용정보, 주민등록번호, 계좌번호 등 암호화 대상 정보 자체를 전혀 수집·저장·처리하지 않는 근거가 있습니까?", "외부 위탁 또는 외부 솔루션을 사용하여 내부 DB에 암호화 대상 정보가 저장될 가능성이 완전히 차단되어 있음을 입증할 수 있습니까?"], "naEnd": "개인정보 및 금융신용정보 미처리 시스템임이 확인되면 해당없음(N/A)으로 처리합니다."}, "10-2": {"decisionQ": "DB 내 주민번호, 계좌번호, 비밀번호 등 민감정보 컬럼의 암호화 적용 상태와, 암호키가 애플리케이션과 분리된 별도 위치에 보관되어 있음을 솔루션 화면으로 직접 보여주시겠습니까?", "verify": ["DB 암호화 솔루션 관리자 화면에서 주민등록번호 및 비밀번호 컬럼의 암호화 설정 상태를 보여주시겠습니까?", "감사역이 지정하는 특정 운영 DB 테이블(예: 고객원장)의 스키마 및 암호화 암호문 저장 상태를 직접 쿼리하여 보여주실 수 있습니까?", "암호화 키가 저장된 서버 또는 HSM/KMS의 위치를 시스템 구성도 및 설정 파일에서 확인해 주시겠습니까? (애플리케이션 소스코드나 DB 내 평치 보관 여부 점검)", "DB 암호화 솔루션의 암호화 미적용 컬럼 탐지(스캐닝) 주기적 점검 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "DB 주요 컬럼이 암호화되어 있고, 실제 암호문 저장 상태가 확인되며, 암호키가 애플리케이션/DB와 완전히 분리되어 관리됨이 검증되면 양호로 확정합니다.", "partial": ["주민등록번호는 암호화되었으나, 계좌번호나 카드번호 등 일부 민감정보 컬럼이 평문으로 저장되어 있는 사유는 무엇입니까?", "DB 암호화는 적용되어 있으나 암호화 키가 애플리케이션 서버 내 로컬 파일 형태로 보관되어 있는 이유는 무엇입니까?", "운영 DB는 암호화되어 있으나 개발/검증 DB로 복제된 데이터에 민감정보가 평문으로 남아있는 이유는 무엇입니까?"], "partialEnd": "미암호화 컬럼 및 키 보관 분리 미흡 사항에 대해 조치 계획 수립을 요구하고 보완을 명령합니다.", "rootcause": ["DB 내 주민등록번호 또는 비밀번호가 평문으로 저장되어 있는 이유는 무엇입니까?", "암호화 키가 소스코드 내에 하드코딩되어 있거나 DB 테이블 내에 함께 저장되어 있는 경위는 무엇입니까?", "DB 암호화 솔루션이 정상 작동하지 않거나 복호화 권한 통제가 전혀 이루어지지 않고 있는 원인은 무엇입니까?"], "rootcauseEnd": "중대 결함으로 확정하고 즉시 DB 컬럼 암호화 적용, 소스코드 내 키 제거, 키 분리 보관 조치 및 이행 결과 제출을 서면 요구합니다.", "na": ["해당 DB가 개인신용정보, 계좌번호, 비밀번호 등을 전혀 저장하지 않는 연계/임시 DB임을 증빙할 수 있습니까?"], "naEnd": "민감정보가 전혀 저장되지 않는 DB임을 스키마 확인 후 해당없음(N/A)으로 판정합니다."}, "10-3": {"decisionQ": "외부 대고객 웹/앱 서비스의 TLS 1.2 이상 강제 설정 여부 및 TLS 1.0/1.1 비활성화 상태, 내부 민감정보 전송 구간 암호화 설정을 스캔 도구나 설정 파일로 보여주시겠습니까?", "verify": ["웹 서버(Nginx, Apache 등) 또는 L7 스위치의 SSL/TLS 설정 파일에서 TLS 1.0, TLS 1.1이 Explicitly Disable 처리되어 있음을 보여주시겠습니까?", "외부 SSL 점검 도구(예: OpenSSL 명령어 또는 SSL Labs 스캔)로 대고객 도메인을 즉시 조회하여 TLS 1.2 이상만 통과되는지 시연해 주시겠습니까?", "금융결제원, 타 기관 등과 연계되는 금융전문(FEP/전문통신) 전송 구간에 암호화(VPN, dedicated TLS 등)가 적용되어 있음을 구성도로 증빙해 주시겠습니까?", "내부망에서 서버 간 민감정보(주민번호 등)를 전송할 때 적용된 통신 암호화(HTTPS, gRPC TLS 등) 설정 화면을 보여주시겠습니까?"], "verifyEnd": "TLS 1.0/1.1이 차단되고 TLS 1.2 이상만 허용되며, 금융전문 및 내부 민감정보 전송 구간 암호화가 확인되면 양호로 확정합니다.", "partial": ["외부 대고객 구간은 TLS 1.2 이상이 적용되었으나, 구형 단말 지원 등을 이유로 일부 레거시 API 구간에 TLS 1.0/1.1이 열려있는 사유는 무엇입니까?", "외부 구간은 암호화되어 있으나, 내부망 서버 간 민감정보 전송 구간이 HTTP(평문)로 통신 중인 사유는 무엇입니까?"], "partialEnd": "취약한 TLS 버전 비활성화 및 내부 구간 암호화 적용을 포함한 차단 이행 계획 수립을 요구합니다.", "rootcause": ["인터넷 전송 구간에 TLS 통신이 전혀 적용되지 않고 HTTP(평문)가 허용되고 있는 경위는 무엇입니까?", "TLS 1.0/1.1 취약 프로토콜 비활성화 조치가 지금까지 이루어지지 않은 원인은 무엇입니까?", "금융전문 전송 구간에 암호화 통신이 적용되지 않고 평문 전문을 전송하고 있는 이유는 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 취약 프로토콜 차단, 웹서버 설정 변경, 금융전문 구간 암호화 솔루션 즉시 적용을 서면 요구합니다.", "na": ["해당 시스템이 외부 인터넷과 연결되지 않고, 데이터 전송 기능이 전혀 없는 단독(Stand-alone) 시스템임을 입증할 수 있습니까?"], "naEnd": "네트워크 전송 기능이 없는 시스템임이 확인되면 해당없음(N/A)으로 처리합니다."}, "10-4": {"decisionQ": "전사 시스템 및 암호화 솔루션에서 MD5, SHA-1, DES, 3DES, RC4 등 취약 암호 알고리즘 사용을 금지하고 AES-128 이상, SHA-256 이상을 사용하고 있음을 점검 결과서 및 설정 화면으로 증빙해 주시겠습니까?", "verify": ["전사 암호 알고리즘 사용 현황 점검 결과 보고서(최근 1년 이내)를 보여주시겠습니까?", "DB 암호화, 파일 암호화, 비밀번호 암호화(Hash)에 적용된 알고리즘 설정(예: AES-256, SHA-256/512, PBKDF2 등)을 화면으로 보여주시겠습니까?", "과거 사용되던 취약 알고리즘(MD5, DES 등)에 대한 제거/고도화 이행 확인서나 변경 완료 내역을 확인할 수 있습니까?", "자체 암호 알고리즘 연구/사용을 금지하고 표준 검증 암호모듈(KCMVP 등) 사용을 명시한 내부 정보보호 지침을 보여주시겠습니까?"], "verifyEnd": "취약 알고리즘 사용이 없으며, 표준 안전 알고리즘(AES-128↑, SHA-256↑) 적용 및 KCMVP 검증 모듈 사용이 확인되면 양호로 확정합니다.", "partial": ["신규 시스템은 안전한 알고리즘을 사용하나, 일부 레거시 시스템 또는 내부 대사 파일 처리에 아직 MD5나 SHA-1이 남아있는 사유는 무엇입니까?", "취약 알고리즘 제거 계획은 수립되어 있으나, 목표 기한이 도래했음에도 이행이 지연되고 있는 원인은 무엇입니까?"], "partialEnd": "잔존 취약 알고리즘 현황을 파악하고 즉시 대체 알고리즘 전환 조치 계획을 제출하도록 요구합니다.", "rootcause": ["비밀번호 저장 시 단순 MD5 또는 SHA-1 단방향 암호화를 여전히 사용하고 있는 경위는 무엇입니까?", "DB 및 파일 암호화에 DES, 3DES, RC4 등 폐기 권고된 대칭키 알고리즘을 그대로 방치한 이유는 무엇입니까?", "암호 알고리즘 정책 표준 기준 자체가 부재하거나 취약 알고리즘 점검을 한 번도 실시하지 않은 원인은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 취약 알고리즘 전수 조사, 안전한 알고리즘(AES-256, SHA-256 등)으로의 재암호화 및 알고리즘 교체 계획 제출을 요구합니다.", "na": ["암호화 기능을 자체 구현하지 않고, 상용 표준 검증 암호화 모듈만을 사용하는 단일 패키지 시스템으로서 별도 알고리즘 설정 변경이 불가능한 구조임을 입증할 수 있습니까?"], "naEnd": "자체 구현이 없는 완제품 형태이며 표준 알고리즘 탑재가 확인되는 경우 해당없음(N/A) 처리합니다."}, "10-5": {"decisionQ": "암호키의 생성·보관을 위해 HSM 또는 KMS를 운용 중인지, 그리고 키 보관 서버와 암호화 적용 서버가 분리되어 있으며 복수 관리자 승인 체계로 운영되는지 설정을 보여주시겠습니까?", "verify": ["HSM(하드웨어 보안 모듈) 또는 KMS(키 관리 시스템) 장비/솔루션 운영 현황 및 물리적/논리적 구성도를 보여주시겠습니까?", "키 보관 서버(KMS/HSM)와 암호화 수행 서버(DB/App)의 IP 및 물리적 분리 상태를 구성도와 네트워크 설정에서 확인해 주시겠습니까?", "암호키 생성, 접근, 주입 시 2명 이상의 승인자(복수 관리자 / Dual Control / Split Knowledge)가 필요한 설정 화면 또는 작업 이력을 보여주시겠습니까?", "암호키의 백업 데이터 및 복구 절차서가 문서화되어 있고 백업본 역시 안전하게 암호화 보관되고 있음을 보여주시겠습니까?"], "verifyEnd": "HSM/KMS 활용, 키 보관/암호화 서버 분리, 복수 관리자 통제, 백업/복구 절차가 모두 확인되면 양호로 확정합니다.", "partial": ["KMS를 운용하고 있으나 일부 시스템의 키가 KMS에 등록되지 않고 일반 파일 서버에 보관 중인 사유는 무엇입니까?", "복수 관리자 체계가 지침에 명시되어 있으나 실제 키 생성 작업 시 단독 계정으로 처리된 이력이 존재하는 이유는 무엇입니까?"], "partialEnd": "단독 접근 권한 이력을 지적하고 즉시 HSM/KMS 통합 및 복수 관리자 승인 통제를 강제하도록 개선을 요청합니다.", "rootcause": ["KMS/HSM을 도입하지 않고 암호키를 평문 파일 형태로 OS/DB 서버 내에 임의 보관하는 경위는 무엇입티까?", "특정 담당자 1인이 암호키 생성, 발급, 폐기 등 모든 권한을 독점하고 있는 원인은 무엇입니까?", "암호키 백업본이 존재하지 않거나, 백업 키가 아무런 보호 조치 없이 보관되고 있는 이유는 무엇입니까?"], "rootcauseEnd": "중대 결함으로 확정하고 HSM/KMS 도입 검토, 키 관리 권한의 분리(Dual Control) 및 키 백업 통제 재정비를 서면 요구합니다.", "na": ["암호화 키 관리를 자체 수행하지 않고, 금융당국이 승인한 공인/외부 전문 키 관리 전용 서비스만을 이용하며 자체 키 생성이 필요 없는 구조임을 증빙할 수 있습니까?"], "naEnd": "키 관리가 외부 공인 규격에 전적으로 위탁된 구조임이 확인되면 해당없음(N/A) 처리합니다."}, "10-6": {"decisionQ": "대칭키에 대한 연 1회 이상 주기적 교체 이력 대장, 구키 폐기 확인서, 그리고 키 교체 후 암호화 데이터의 재암호화 이행 작업 결과를 보여주시겠습니까?", "verify": ["최근 2년간의 암호키 교체 이력 대장(교체 일시, 작업자, 대상 시스템, 승인자 등)을 보여주시겠습니까?", "키 교체 수행 시 작성된 내부 기안서(승인 문서) 및 작업 완료 보고서를 확인할 수 있습니까?", "구키(Past Key) 폐기 시 작성된 '구키 폐기 확인서' 및 폐기 처리 로그를 보여주시겠습니까?", "암호키 교체 후 기존 암호화 데이터에 대한 '재암호화(Re-encryption)' 작업 로그 및 정상 서비스 동작 확인서를 제시해 주시겠습니까?"], "verifyEnd": "연 1회 이상 키 교체 이력이 확인되고, 구키 폐기 증적 및 재암호화 이행 결과가 명확하면 양호로 확정합니다.", "partial": ["키 교체 주기가 내부 지침(연 1회)을 초과하여 1년 6개월 이상 연체된 사유는 무엇입니까?", "신규 키로 교체는 완료했으나 기존 데이터 재암호화가 일부 누락되어 구키를 폐기하지 못하고 복호화용으로 보유 중인 사유는 무엇입니까?"], "partialEnd": "미완료된 재암호화 조치 및 구키 폐기 이행 계획 제출을 서면 요청합니다.", "rootcause": ["시스템 구축 이후 단 한 번도 암호키를 교체하지 않고 수년간 동일 키를 사용 중인 경위는 무엇입니까?", "키 교체 절차가 문서화되어 있지 않거나 키 교체 작업을 수행할 수 있는 기능/툴 자체가 없는 이유는 무엇입니까?", "구키가 폐기되지 않고 서버 내에 평문으로 지속 방치되고 있는 원인은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 즉시 키 교체 수립 및 데이터 재암호화, 구키 안전 폐기 절차 이행을 촉구합니다.", "na": ["해당 시스템이 비대칭키(공개키 PKI)만을 활용하여 대칭키 교체 주기의 적용을 받지 않거나, 자동 키 교체 알고리즘(예: Ephemeral Key)이 적용되어 별도 수동 교체가 불필요한 구조임을 입증할 수 있습니까?"], "naEnd": "자동 키 교체 구조 또는 비대칭키 전용 구조임이 증빙되면 해당없음(N/A)으로 처리합니다."}, "10-7": {"decisionQ": "소외(Off-site) 소산 백업 매체(테이프, 원격지 디스크 등) 및 백업 데이터 네트워크 전송 시 암호화가 적용되어 있음을 백업 솔루션 설정 화면으로 증빙해 주시겠습니까?", "verify": ["백업 솔루션(예: Veritas, Commvault 등)의 정책 설정 화면에서 '백업 데이터 암호화(Encryption)' 옵션이 활성화되어 있는지 보여주시겠습니까?", "백업 데이터를 원격지로 전송하는 구간(네트워크)에 암호화 프로토콜(IPsec, TLS 등)이 적용되어 있음을 네트워크 설정으로 증빙할 수 있습니까?", "오프사이트로 반출되는 소산 백업 매체(테이프/외장매체)에 대한 암호화 적용 확인서를 보여주시겠습니까?", "백업 매체 암호화 키 관리 방안 및 백업 복원 테스트 시 정상 복호화되는 결과 보고서를 제시해 주시겠습니까?"], "verifyEnd": "백업 저장 매체 암호화, 전송 구간 암호화 및 복원 시 정상 복호화 작동이 확인되면 양호로 확정합니다.", "partial": ["소산 백업 매체는 암호화되었으나, 백업 데이터를 소산지로 전송하는 네트워크 구간 암호화가 누락된 사유는 무엇입니까?", "백업 암호화는 적용되어 있으나 백업 복호화 키 관리가 평문으로 작성되어 백업 서버에 저장된 사유는 무엇입니까?"], "partialEnd": "백업 전송 구간 암호화 조치 및 백업 키 관리 안전성 강화를 요구합니다.", "rootcause": ["오프사이트로 반출되는 백업 테이프/매체가 암호화되지 않은 평문 상태로 반출·보관되고 있는 경위는 무엇입니까?", "백업 솔루션의 암호화 라이선스 미도입 또는 성능 저하를 이유로 백업 암호화를 전면 생략한 사유는 무엇입니까?", "백업 데이터 복원 테스트를 한 번도 실시하지 않아 복호화 가능 여부조차 파악하지 못하고 있는 원인은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 백업 매체/전송 구간 즉시 암호화 적용 및 복원/복호화 테스트 수행 보고 제출을 요구합니다.", "na": ["백업 데이터를 소산 반출하지 않고, 내부적으로 통제된 분산 가상화 저장소에만 실시간 동기화하여 별도 물리 매체 백업 및 반출이 전혀 없는 구조임을 입증할 수 있습니까?"], "naEnd": "물리적 매체 소산 및 외부에 데이터 전송이 없는 구조임이 확인되면 해당없음(N/A) 처리합니다."}, "10-8": {"decisionQ": "전사 운영 중인 SSL/TLS 인증서의 관리 대장(만료일 현행화)과 만료 30일 전 자동 알림 체계, 및 자체 서명(Self-signed) 인증서 오용 여부를 보여주시겠습니까?", "verify": ["전사 SSL 인증서 목록(발급기관, 적용 도메인, 만료예정일, 담당자 포함) 관리 대장을 보여주시겠습니까?", "인증서 만료 30일 전 담당자에게 SMS/메일/슬랙 등으로 자동 발송되는 '만료 사전 알림 모니터링 시스템' 설정 화면을 보여주시겠습니까?", "운영 환경 대고객 서비스에 사설/자체 서명(Self-signed) 인증서가 아닌 공인 인증기관(CA) 발급 인증서가 적용되어 있음을 브라우저/도구를 통해 증빙해 주시겠습니까?", "최근 1년간 SSL 인증서 만료로 인한 서비스 장애 또는 경고창 발생 이력이 없음을 모니터링 로그로 확인할 수 있습니까?"], "verifyEnd": "인증서 관리 대장 현행화, 만료 30일 전 알림 체계 동작, 공인 인증서 사용 및 만료 장애 없음이 확인되면 양호로 확정합니다.", "partial": ["인증서 관리 대장은 있으나 최근 신규 추가된 시스템의 인증서 만료일이 누락되어 현행화가 불비한 사유는 무엇입니까?", "자동 알림 시스템이 구축되어 있으나 알림 수신 담당자 퇴사 후 현행화가 안 되어 실제 알림이 전달되지 않은 이유는 무엇입니까?"], "partialEnd": "인증서 목록 즉시 현행화 및 알림 수신자 정보 변경 조치를 요청합니다.", "rootcause": ["운영 대고객 웹/앱 서비스에 공인 인증서가 아닌 자체 서명(Self-signed) 인증서를 적용하여 사용자에게 보안 경고를 노출하고 있는 경위는 무엇입니까?", "인증서 만료일 관리 통제가 전혀 이루어지지 않아 실제로 인증서가 만료되어 서비스 장애가 발생한 이유는 무엇입니까?", "와일드카드(*) 인증서의 개인키 관리 소홀로 여러 외부 서버에 임의 복제되어 방치되고 있는 원인은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 공인 인증서 즉시 교체, 인증서 통합 관리 프로세스 수립 및 개인키 안전 관리 대책 제출을 서면 요구합니다.", "na": ["외부 대고객 서비스 및 SSL/TLS 암호화 통신을 사용하는 웹/앱 시스템을 일체 운용하지 않는 환경임을 증빙할 수 있습니까?"], "naEnd": "SSL 통신을 사용하는 웹/API 시스템이 없음이 확인되면 해당없음(N/A) 처리합니다."}, "06-1": {"decisionQ": "현재 관리 중인 IT 외부업체 계약 목록과 해당 업체들이 처리하는 정보자산 범위를 현장에서 시스템 및 대장으로 즉시 확인해 주실 수 있습니까?", "verify": ["IT 계약 관리 시스템 또는 대장에서 현재 활성화된 외부업체 목록(ITO, 유지보수, 컨설팅 등) 전체를 조회해 주시겠습니까?", "감사역이 지정한 임의의 2개 업체에 대해 처리하는 정보자산 범위(고객정보, 원장, 소스코드 등)가 매핑된 대장을 보여주시겠습니까?", "최근 1년 내 해당 업체들의 보안사고 이력 조회 내역 및 계약 만료/갱신 관리 현황을 보여주시겠습니까?", "계약 만료 시 즉시 권한이 회수되고 대상 목록에서 업데이트되는 자동/수동 절차를 설명해 주시겠습니까?"], "verifyEnd": "외부업체 목록, 처리 정보자산 범위, 사고 이력, 만료 관리 현황이 모두 일치하고 감사역 지정 항목 재조회 시에도 누락이 없으면 양호로 판정합니다.", "partial": ["외부업체 계약 목록은 관리되고 있으나, 업체별 처리 정보자산 범위가 일부 누락된 이유는 무엇입니까?", "계약 만료 내역은 관리되나 보안사고 이력 관리가 미흡한 상태가 언제부터 지속되었습니까?", "전년도 감사나 자체 점검에서도 동일한 목록 누락이 지적된 적이 있습니까?", "정보자산 범위 및 사고 이력을 포함한 완전한 대장 갱신을 언제까지 완료할 계획입니까?"], "partialEnd": "누락된 정보자산 범위 및 사고 이력 현황을 보완하도록 개선계획 수립을 요청하고 보완 제출을 확인합니다.", "rootcause": ["IT 외부업체 계약 목록이나 처리 정보자산 범위 자체가 식별·관리되지 않고 있는 원인은 무엇입니까?", "현업 부서에서 독자적으로 계약을 진행하여 IT/보안부서로 통보되지 않는 구조적 문제가 있습니까?", "이러한 현황 미관리 상태를 인지하고도 상급자나 경영진에게 보고하지 않은 이유가 있습니까?", "즉시 전수 조사를 통해 외부업체 및 정보자산 파악 대장을 작성할 수 있는 일정은 어떻게 됩니까?"], "rootcauseEnd": "외부자 현황 관리 미흡으로 결함 확정하며, 외부업체 및 처리 정보자산 전수조사 및 관리 프로세스 수립을 권고합니다.", "na": ["IT 관련 외부업체 계약(ITO, 유지보수, 컨설팅, 외주개발 등)을 단 한 건도 체결하지 않고 100% 자체 인력으로만 운영 중이십니까?", "향후 외부업체 계약 도입 시 현황 관리를 위한 표준 절차가 마련되어 있습니까?", "외부자 관리가 전혀 필요 없음을 입증할 수 있는 조직 구성 및 IT 운영 현황 자료를 제시할 수 있습니까?"], "naEnd": "외주 및 외부 협력업체가 전혀 없는 완전 자체 운영임이 확인되면 해당없음(N/A)으로 종결합니다."}, "06-2": {"decisionQ": "외부업체 계약 체결 시 표준계약서 내 보안 필수 조항(비밀유지, 책임, 감사권, 파기)이 명시되어 있고 사전 협의 이력이 존재합니까?", "verify": ["현재 사용 중인 IT 외부업체 표준 계약서 양식을 보여주시겠습니까?", "감사역이 지정한 최근 계약 체결 업체 2곳의 실제 날인된 계약서를 보여주시겠습니까?", "해당 계약서 내 비밀유지, 보안사고 발생 시 손해배상 책임, 당행의 감사권, 데이터 반환 및 파기 조항이 포함되어 있는지 구체적 조항을 찍어주시겠습니까?", "계약 체결 전 보안부서와 작성한 보안요건 협의 이메일이나 검토 메모를 보여주시겠습니까?"], "verifyEnd": "필수 보안 조항 5가지(비밀유지, 책임, 감사권, 데이터 반환, 파기)가 모두 포함되어 있고 사전 협의 증적이 확인되면 양호로 판정합니다.", "partial": ["비밀유지와 보안사고 책임 조항은 있으나, 당행의 '감사권'이나 '데이터 파기확인' 조항이 누락된 이유는 무엇입니까?", "사전 보안 협의 절차 없이 사업부서에서 계약을 진행한 건이 일부 발생한 경위는 무엇입니까?", "누락된 보안 조항에 대해 특약 형태로 추가 체결할 계획이 있습니까?"], "partialEnd": "누락된 필수 보안 조항을 확인하여 기존 계약에 대한 변경계약 체결 및 표준양식 개정을 요구합니다.", "rootcause": ["계약서 내 필수 보안 조항이 통째로 누락된 채 계약이 체결된 원인은 무엇입니까?", "보안 부서의 계약서 사전 검토 프로세스가 법적/제도적으로 강제되어 있지 않습니까?", "데이터 반환 및 파기 확인서를 수령하지 않고 계약을 종료한 이유와 책임자는 누구입니까?"], "rootcauseEnd": "계약서 보안 요건 통제 미흡으로 중대 결함 확정하며, 사전 보안검토 의무화 및 변경계약 체결을 지시합니다.", "na": ["모든 IT 업무를 외부 위탁 없이 자체 인력 및 내부 자산으로만 수행하여 외부 계약이 전혀 없습니까?", "외부 소프트웨어 구매 외에 데이터 접촉이 발생하는 유지보수/운영 계약이 단 한 건도 없는 것이 맞습니까?"], "naEnd": "외부 계약이 전혀 존재하지 않음이 증빙되면 해당없음(N/A) 처리합니다."}, "06-3": {"decisionQ": "IT 수탁사 선정 전 보안역량 평가(보안설문/ISMS)를 실시하고, 연 1회 이상 정기 재평가를 수행하고 있습니까?", "verify": ["IT 수탁사 선정 시 적용하는 보안역량 평가 기준 및 설문지 양식을 보여주시겠습니까?", "최근 1년 내 신규 선정한 수탁사의 평가 점수표 및 수탁사가 제출한 ISMS 인증서(또는 보안 점검표)를 보여주시겠습니까?", "기존 수탁사에 대해 연 1회 실시한 정기 재평가 결과 보고서를 보여주시겠습니까?", "평가 점수가 미달된 업체가 발생했을 때 처리(계약 해지 또는 보완 요구)한 실제 사례가 있습니까?"], "verifyEnd": "신규 선정 전 보안 평가 증적과 연 1회 정기 재평가 결과가 모두 확인되고, 미달 업체 조치 방안이 수립되어 있으면 양호로 판정합니다.", "partial": ["신규 선정 시에는 평가를 하나, 연 1회 정기 재평가가 일부 누락된 이유는 무엇입니까?", "ISMS 인증서만 확인하고 자체 보안 설문 평가를 생략한 기준이 내부 규정에 명시되어 있습니까?", "미비점이 발견된 수탁사에 대한 재평가 이행 기한은 어떻게 설정하고 계집합니까?"], "partialEnd": "누락된 수탁사 정기 재평가를 즉시 실시하도록 하고, 재평가 결과 제출을 조건으로 보완 관리합니다.", "rootcause": ["수탁사 선정 시 보안 역량 평가를 전혀 거치지 않고 IT 사업을 추진한 경위는 무엇입니까?", "전자금융감독규정 제26조에 따른 수탁사 평가 의무를 내부 지침에 반영하지 않은 이유는 무엇입니까?", "정기 재평가를 수년간 수행하지 않은 담당 부서의 관리 소홀 원인은 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 위반 및 수탁사 보안심사 미흡으로 중대 결함 처리하며, 정기 재평가 체계 재정비를 권고합니다.", "na": ["개인신용정보나 중요 금융 IT 시스템을 외부에 위탁(수탁) 처리하는 업무가 전혀 없습니까?", "단순 단순 물품 구매 외에 IT 개발, 유지보수, 운영 위탁이 전혀 없음을 증빙할 수 있습니까?"], "naEnd": "IT 및 개인정보 수탁 업무가 존재하지 않음이 확인되면 해당없음(N/A)으로 처리합니다."}, "06-4": {"decisionQ": "수탁사 및 개인정보 처리 위탁사를 대상으로 연 1회 이상 현장 보안점검을 실시하고 지적사항을 관리하고 있습니까?", "verify": ["금년도 수탁사 현장 보안점검 계획서 및 점검 체크리스트 양식을 보여주시겠습니까?", "최근 실시한 수탁사 현장 점검 결과 보고서 2건과 방문 시 작성한 사진/서명 등 실제 현장 방문 증적을 제시해 주시겠습니까?", "점검 결과 도출된 지적사항에 대해 수탁사가 제출한 개선조치 확인서 및 완료 이력을 보여주시겠습니까?", "개인정보 처리 위탁사에 대해서도 동일한 현장 점검 기준이 적용되어 수행되었습니까?"], "verifyEnd": "연간 계획에 따른 현장 점검 수행 증적, 체크리스트, 지적사항 조치 내역이 모두 확인되면 양호로 판정합니다.", "partial": ["현장 점검을 실시했으나 서면 점검으로 대체된 비율이 높은 사유는 무엇입니까?", "현장 점검 지적사항에 대한 조치 완료 확인이 지연되고 있는 이유는 무엇입니까?", "개인정보 위탁사 일부가 점검 대상에서 누락된 경위는 어떻게 됩니까?"], "partialEnd": "서면 대체 사유의 타당성을 검토하고, 누락된 위탁사에 대한 추가 현장 점검 및 조치 완료 이행을 요구합니다.", "rootcause": ["수탁사 현장 보안 점검을 최근 1년 이상 전혀 실시하지 않은 이유는 무엇입니까?", "개인정보보호법 제26조 및 전자금융감독규정 제27조에 따른 현장 점검 의무를 알고도 이행하지 않은 것입니까?", "점검 인력 부족이나 예산 문제는 어떻게 해결할 계획입니까?"], "rootcauseEnd": "법적 의무 사항인 수탁사 현장 점검 미이행으로 결함 확정하며, 현장 점검 계획 수립 및 즉시 시행을 지시합니다.", "na": ["IT 및 개인정보 처리를 위탁받아 수행하는 외부 수탁업체가 단 1곳도 없습니까?", "외부 업체 현장 방문 점검 대상이 없음을 입증할 수 있습니까?"], "naEnd": "위탁업체가 전혀 없는 것으로 확증되면 해당없음(N/A) 처리합니다."}, "06-5": {"decisionQ": "상주 외주개발자의 보안서약서 징구, 개발 환경 외 접근 차단, 테스트 데이터 비식별화 통제가 철저히 적용되고 있습니까?", "verify": ["현재 상주 중인 외주개발자 명단과 이들의 보안서약서/NDA 제출 완료 대장을 보여주시겠습니까?", "외주개발자 IP/계정 기준으로 운영 DB 및 운영 시스템 접근이 방화벽/접근통제 시스템에서 차단되어 있는지 실제 설정을 보여주시겠습니까?", "개발 및 테스트 DB에 운영 개인정보가 비식별화(마스킹/변환)되어 적용된 현황을 조회해 주시겠습니까?", "외주개발자의 PC에서 소스코드 및 자료 반출 시 승인 절차와 반출 승인 대장을 보여주시겠습니까?"], "verifyEnd": "보안서약서 100% 징구, 운영 환경 격리 차단 설정, 테스트 데이터 비식별화, 반출 통제 증적이 모두 확인되면 양호로 판정합니다.", "partial": ["일부 외주개발자의 보안서약서 제출이 지연된 사유는 무엇입니까?", "개발 DB에 운영 데이터가 일부 비식별화되지 않고 직접 이관되어 사용된 사례가 있습니까?", "반출 승인 대장은 있으나 실제 반출 파일과의 대조 검증 조치가 누락된 이유는 무엇입니까?"], "partialEnd": "누락된 보안서약서를 즉시 징구하고, 개발 DB 내 미변환 데이터의 즉시 파기 및 비식별화를 요구합니다.", "rootcause": ["상주 외주개발자에게 운영 DB 직접 접근 권한이 부여되어 있었던 원인은 무엇입니까?", "테스트용 데이터로 실제 고객 개인정보를 그대로 복제하여 사용한 경위는 무엇입니까?", "외주인력 출입 및 PC 보안 통제가 전반적으로 방치된 관리상 책임자는 누구입니까?"], "rootcauseEnd": "개인정보보호법 위반 및 외주인력 통제 미흡으로 중대 결함 처리하며, 접근권한 즉시 회수 및 데이터 비식별화를 지시합니다.", "na": ["당행 내에 상주하거나 리모트로 개발 업무를 수행하는 외주 개발 인력이 전혀 없습니까?", "100% 내부 임직원으로만 시스템 개발 및 유지보수를 수행함을 증빙할 수 있습니까?"], "naEnd": "상주 외주개발자가 존재하지 않음이 확인되면 해당없음(N/A) 처리합니다."}, "06-6": {"decisionQ": "외주 개발 소스코드의 납품 의무화, 납품 시 정적분석(SAST) 취약점 점검, 지식재산권 귀속 조항이 준수되고 있습니까?", "verify": ["외주 개발 계약서 상 소스코드 제출 의무 및 지식재산권(저작권) 당행 귀속 명시 조항을 보여주시겠습니까?", "최근 완료된 외주 개발 프로젝트의 소스코드 수령 확인서 및 형상관리 시스템(Git/SVN 등) 등록 이력을 보여주시겠습니까?", "검수 전 실시한 SAST(정적 소스코드 취약점 분석) 결과 보고서와 발견된 보안 취약점 조치 내역을 보여주시겠습니까?", "SAST 점검에서 도출된 고위험 취약점이 조치 완료된 후 재점검한 결과를 확인해 주시겠습니까?"], "verifyEnd": "계약서 상 IP 귀속 명시, 형상관리 등록, SAST 점검 수행 및 취약점 제거 보고서가 모두 확인되면 양호로 판정합니다.", "partial": ["소스코드는 수령하였으나 SAST 정적 분석이 일부 모듈에 대해서만 수행된 이유는 무엇입니까?", "지식재산권 공동 소유로 계약된 사유와 당행 지분권 보호 조치는 마련되어 있습니까?", "발견된 중/약위험 취약점에 대한 조치 이행 기한이 지연된 경위는 어떻게 됩니까?"], "partialEnd": "누락된 소스코드 전체에 대한 SAST 추가 점검을 실시하고 남아있는 취약점 조치를 이행하도록 요구합니다.", "rootcause": ["외주 개발 결과물의 소스코드를 인수받지 못했거나 형상관리에 등록하지 않은 원인은 무엇입니까?", "SAST 보안 취약점 점검을 전혀 거치지 않고 운영 환경에 소스코드를 배포한 경위는 무엇입니까?", "계약서에 지식재산권 귀속 조항이 누락되어 향후 분쟁 위험이 존재하는 이유는 무엇입니까?"], "rootcauseEnd": "소스코드 보안 검수 부재 및 지식재산권 위험으로 결함 확정하며, 소스코드 전수 확보 및 SAST 점검 배포 통제를 지시합니다.", "na": ["외주 개발 프로젝트를 전혀 진행하지 않으며 완전한 완제품(COTS) 패키지만 구매하여 사용합니까?", "소스코드 수정이 수반되는 자체/외주 커스터마이징 개발이 전혀 없는 시스템임을 증빙할 수 있습니까?"], "naEnd": "소프트웨어 개발/수정 업무가 없는 패키지 도입에 해당하면 해당없음(N/A) 처리합니다."}, "06-7": {"decisionQ": "외부자의 원격/internal 접근 시 전용 VPN 사용, 계정 분리, 접속 로그 모니터링 및 업무 종료 후 즉시 차단이 이행되고 있습니까?", "verify": ["외부자 원격접속용 전용 VPN 설정 화면 및 MFA(다중인증) 적용 현황을 보여주시겠습니까?", "외부자 전용 계정 생성/관리 대장을 열어 내부 임직원 계정과 물리적/논리적으로 분리되어 관리되는지 보여주시겠습니까?", "최근 1개월간 외부자 원격접속 이력 로그를 조회하고, 감사역이 지정한 2개 계정의 접속/해제 시각을 재조회해 보여주시겠습니까?", "계약 종료 또는 당일 업무 종료 후 외부자 계정 및 VPN 접속 권한이 즉시 비활성화(차단)된 이력을 보여주시겠습니까?"], "verifyEnd": "전용 VPN 및 MFA, 계정 분리, 접속 로그 보존, 업무 종료 후 권한 즉시 차단 증적이 모두 확인되면 양호로 판정합니다.", "partial": ["외부자 원격접속 시 MFA가 일부 예외 처리되어 적용된 사유는 무엇입니까?", "업무 종료 후 자동 차단되지 않고 담당자 수동 차단 지연으로 밤늦게까지 권한이 남은 사례가 발생한 이유는 무엇입니까?", "접속 로그 모니터링 주기가 월 1회로 길어 즉각적인 이상징후 탐지가 어려운 점에 대한 보완책은 무엇입니까?"], "partialEnd": "모든 외부자 원격접속에 MFA를 강제 적용하고, 업무 종료 후 자동 차단(Time-out) 모듈 조치 및 모니터링 주기를 단축하도록 요구합니다.", "rootcause": ["외부자가 전용 VPN 없이 내부 임직원용 VPN이나 일반 경로로 내부망에 직접 접속한 경위는 무엇입니까?", "외부자 계정을 임직원 공용 계정으로 공유하여 사용하여 개별 이력 추적이 불가능한 이유는 무엇입니까?", "퇴사 또는 계약 종료된 외부자의 계정이 수개월간 차단되지 않고 방치된 관리상 원인은 무엇입니까?"], "rootcauseEnd": "외부자 원격접속 및 계정 관리 중대 결함으로 확정하며, 계정 전수 조사, 무단 권한 즉시 삭제 및 MFA 강제를 명령합니다.", "na": ["외부 업체의 원격 접속이나 당행 내부망/시스템에 대한 외부자 접근을 철저히 불허하고 100% 차단하고 있습니까?", "외부자에 의한 원격 유지보수 및 접속이 시스템적으로 불가능함을 증빙할 수 있습니까?"], "naEnd": "외부자의 내부망 접근 및 원격 접속 채널이 존재하지 않음이 증빙되면 해당없음(N/A) 처리합니다."}, "06-8": {"decisionQ": "수탁사가 IT/개인정보 업무를 재위탁할 때 당행의 사전 승인을 거치고, 재수탁사에도 동일한 보안요건이 적용 및 점검되고 있습니까?", "verify": ["수탁사의 재위탁 현황을 관리하는 재위탁 관리 대장을 보여주시겠습니까?", "재위탁이 발생한 경우 당행이 사전에 검토하고 승인한 재위탁 사전 승인 신청서 및 결재 문서를 보여주시겠습니까?", "수탁사와 재수탁사 간 체결된 계약서에서 당행 계약과 동일한 보안요건 및 비밀유지 조항이 부과되어 있는지 확인해 주시겠습니까?", "당행 또는 원수탁사가 재수탁사를 대상으로 실시한 보안 점검 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "사전 승인 이력, 동일 보안요건 부과 계약, 재수탁사 보안 점검 수행 증적이 확인되면 양호로 판정합니다.", "partial": ["재위탁 사실은 파악하고 있으나, 사전 승인 절차가 사후 보고 형태로 진행된 경위는 무엇입니까?", "재수탁사에 대한 보안 점검이 원수탁사의 자체 점검 결과 제출로 대체되고 당행의 실질적 검증이 부족한 사유는 무엇입니까?", "재위탁 승인 절차가 지연될 때 적용하는 임시 통제 방안이 있습니까?"], "partialEnd": "재위탁 사전 승인 프로세스를 엄격히 재정립하고, 재수탁사에 대한 보안 점검 결과 증적 제출을 강화하도록 요구합니다.", "rootcause": ["당행의 사전 승인 없이 수탁사가 임의로 제3자에게 재위탁을 진행한 사실을 파악하지 못한 원인은 무엇입니까?", "개인정보보호법 제26조에 따른 재위탁 사전 승인 의무가 계약서 및 프로세스에서 누락된 이유는 무엇입니까?", "재수탁사에 의한 보안 사고 발생 시 당행의 대응 및 법적 통제 수단이 부재한 경위는 무엇입니까?"], "rootcauseEnd": "개인정보보호법 위반 및 재위탁 통제 미흡으로 결함 처리하며, 임의 재위탁 시정 조치 및 계약 해지 조건 검토를 지시합니다.", "na": ["당행의 모든 IT 및 개인정보 수탁업체가 재위탁을 절대 수행하지 않으며, 전량 직접 처리함을 확인하였습니까?", "계약서상 '재위탁 완전 금지' 조항이 명시되어 있고 실제로도 재위탁 건이 0건임을 입증할 수 있습니까?"], "naEnd": "재위탁 금지 조항이 존재하고 실제 재위탁이 전혀 존재하지 않음이 증빙되면 해당없음(N/A) 처리합니다."}, "06-9": {"decisionQ": "SaaS 및 패키지 소프트웨어 도입 시 사전 보안검토, 오픈소스 라이선스/취약점(CVE) 관리 및 공급망 위험평가를 수행하고 있습니까?", "verify": ["SaaS 및 상용 패키지 소프트웨어 도입 시 작성한 사전 보안성 검토 결과 보고서를 보여주시겠습니까?", "시스템에 적용된 오픈소스 라이선스 및 소프트웨어 구성요소(SBOM) 관리 대장을 보여주시겠습니까?", "CVE 등 오픈소스 보안 취약점에 대한 모니터링 체계 및 최근 취약점 패치/조치 이력을 보여주시겠습니까?", "외부 소프트웨어 공급망 전체에 대한 위험 평가 수행 결과서를 제시해 주시겠습니까?"], "verifyEnd": "SW 사전 보안검토, 오픈소스 SBOM 관리, CVE 모니터링/패치 및 공급망 위험평가 증적이 완비되어 있으면 양호로 판정합니다.", "partial": ["상용 SW 사전 보안검토는 수행하나, 오픈소스 라이선스 및 취약점 관리가 일부 누락된 사유는 무엇입니까?", "CVE 고위험 취약점 인지 후 패치 적용까지의 시일이 지연된 경위는 어떻게 됩니까?", "SaaS 도입 시 보안성 검토 항목 중 금융자산 데이터 저장 통제 검토가 미흡한 사유는 무엇입니까?"], "partialEnd": "오픈소스 SBOM 대장 수립 및 CVE 취약점 자동점검 도구 도입을 권고하고, 누락된 SW의 패치를 조속히 완료하도록 요구합니다.", "rootcause": ["SaaS나 외부 패키지 소프트웨어를 보안 부서 협의 없이 사업부서가 무단 도입하여 사용한 경위는 무엇입니까?", "오픈소스 라이선스 위반 위험 및 보안 취약점(CVE) 관리를 전혀 수행하지 않는 원인은 무엇입니까?", "공급망 SW를 통한 웜/악성코드 유입 위험에 대해 위험 평가 체계가 전무한 이유는 무엇입니까?"], "rootcauseEnd": "공급망 SW 보안 관리 부재로 결함 처리하며, SaaS/패키지 도입 사전통제 강화 및 오픈소스 점검 프로세스 수립을 명합니다.", "na": ["외부 SaaS, 상용 패키지 SW, 오픈소스를 일절 사용하지 않고 100% 자체 코딩으로만 모든 시스템을 구축하여 운영합니까?", "외부 SW 도입이 전혀 없는 환경임을 입증할 수 있습니까?"], "naEnd": "외부 SW, SaaS, 오픈소스 이용이 전혀 없는 완전 자체 개발 환경임이 입증되면 해당없음(N/A) 처리합니다."}, "07-1": {"decisionQ": "전산실 출입이 카드 및 생체인증으로 통제되고 인가자 목록이 인사이동 즉시 반영되며 출입 이력이 90일 이상 보존되고 있습니까? 이를 출입통제 시스템 설정 화면과 실제 로그로 보여주실 수 있습니까?", "verify": ["전산실 출입통제 시스템에 등록된 전체 인가자 명단을 화면에 띄워 주시겠습니까?", "최근 1개월 내 퇴사자 또는 부서 이동자 중 2명을 감사역이 지정할 테니, 이들의 출입 권한이 즉시 해제된 이력(권한 변경 로그)을 보여주시겠습니까?", "오늘 기준 90일 전 날짜의 출입 로그가 정상적으로 조회되는지 시스템 화면으로 재조회해 주시겠습니까?", "최근 3개월 간 발생한 미인가자의 출입 시도(태깅 오류, 권한 없음) 알림 이력과 이에 대한 보안요원/관리자 조치 기록을 보여주시겠습니까?"], "verifyEnd": "전산실 출입 권한의 즉시 삭제 내역, 90일 이상의 출입 이력 보존, 미인가 출입 시도에 대한 정상 조치 기록이 확인되면 양호로 판정합니다.", "partial": ["카드/생체인증 통제 및 90일 로그 보존은 되고 있으나, 인사이동 시 권한 삭제가 지연(예: 퇴사 후 수일 뒤 삭제)된 사례가 있습니까?", "퇴직자 권한 삭제 지연이 발생한 구체적인 원인과 지연 기간은 어떻게 됩니까?", "권한 삭제가 지연된 기간 동안 해당 인원의 실제 전산실 출입 이력이 존재하는지 대조해 보셨습니까?"], "partialEnd": "권한 관리 적시성 미흡으로 부분이행 판정하고, 인사시스템과 출입통제 시스템 간 자동 연동 또는 상시 검증 절차 마련을 권고합니다.", "rootcause": ["출입통제 시스템이 설치되지 않았거나 지문/카드 대여 등 우회 출입이 방치되고 있는 원인은 무엇입니까?", "출입 이력 보존 기간이 90일 미만으로 설정되어 있거나 로그 저장소가 부족한 상황을 언제부터 알고 계셨습니까?", "미인가 출입 시도 발생 시 경보 알림이나 후속 확인 절차가 전혀 이루어지지 않은 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제20조 위반 결함으로 확정하고, 물리적 출입통제 시스템 재정비 및 권한/로그 관리 개선계획 제출을 요구합니다.", "na": ["자체 전산실을 운영하지 않고 외부 전문 데이터센터(IDC)를 100% 임차하여 사용하고 계십니까?", "IDC 수탁기관의 출입통제 및 로그 보존에 대한 정기 점검 또는 감사 결과를 보유하고 계십니까?"], "naEnd": "전산실 미보유에 따른 타당성이 입증되면 해당없음으로 처리하되, 위탁관리 점검 기록을 재확인합니다."}, "07-2": {"decisionQ": "전산실 내·외부에 CCTV가 빠짐없이 설치되어 있고 영상 보존기간이 60일 이상으로 설정되어 운영 중입니까? 관리 화면에서 설정값과 녹화 이력을 직접 확인해 주시겠습니까?", "verify": ["CCTV 통합 관리 소프트웨어의 카메라 목록 및 전산실 내부/출입구 모니터링 화면을 보여주시겠습니까?", "시스템 환경설정 화면에서 영상 저장 기간이 '60일' 이상으로 지정되어 있는지 감사역에게 보여주시겠습니까?", "감사역이 임의로 지정하는 특정 날짜(예: 50일 전 특정 시간)의 전산실 녹화 영상을 재생해 보여주시겠습니까?", "개인정보처리방침 또는 영상정보처리기기 운영·관리 방침에 전산실 CCTV 설치 목적 및 위치가 고지되어 있는지 웹사이트/문서로 확인해 주시겠습니까?"], "verifyEnd": "CCTV 사각지대 부재, 60일 이상 영상 보존 설정 및 실제 재생 확인, 개인정보처리방침 고지가 완비되어 있으면 양호로 확정합니다.", "partial": ["CCTV는 설치되어 있으나 일부 사각지대가 존재하거나, 저장 공간 부족으로 실제 보존기간이 45~50일 수준에 머무는 상황입니까?", "영상 저장 용량 증설 계획이나 카메라 추가 설치 계획이 수립되어 있습니까?"], "partialEnd": "보존기간 미달 및 사각지대 존재로 부분이행 판정하며, 스토리지 확장 및 카메라 위치 조정을 요구합니다.", "rootcause": ["CCTV가 녹화되지 않고 방치되어 있거나 녹화장치(NVR/DVR) 고장을 방치한 원인은 무엇입니까?", "영상 보존기간 규정(60일 이상)을 숙지하지 못했거나 관리 주체가 불분명한 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제20조 위반 결함으로 확정하고, CCTV 정비 및 보존기간 준수를 위한 수시 점검 체계를 마련하도록 조치합니다.", "na": ["전산실이 위탁 데이터센터(IDC)에 위치하여 센터 차원의 CCTV 관리를 제공받고 계십니까?", "IDC 제공업체로부터 CCTV 60일 이상 녹화 보증 및 점검 확인서를 제출받아 관리하고 계십니까?"], "naEnd": "IDC 위탁 운영 타당성이 입증되면 해당없음 처리하되, 위탁업체의 보존기간 이행 확인서를 수집합니다."}, "07-3": {"decisionQ": "전산실 내 온도(18~22°C) 및 습도(40~60%)가 적정 수준으로 유지되고 있으며, 화재감지 및 청정소화약제 소화설비의 정기 점검이 수행되고 있습니까? 모니터링 로그와 점검 기록을 보여주시겠습니까?", "verify": ["항온항습기 중앙 모니터링 시스템에서 현재 온·습도 수치 및 최근 1개월 간 온·습도 트렌드 로그를 보여주시겠습니까?", "최근 온·습도 임계치 초과(예: 25°C 이상) 발생 시 관리자에게 발송된 알림 이력과 대응 조치 보고서를 보여주시겠습니까?", "소방시설 전문업체에서 수행한 최근 '화재감지 및 청정소화약제 설비 정기점검 결과 보고서'를 제시해 주시겠습니까?", "전산실 내부 소화약제 용기실의 약제 누설 여부 및 압력계 점검 기록부(월간 점검표)를 보여주시겠습니까?"], "verifyEnd": "항온항습 모니터링 및 임계치 알림 작동, 화재감지/소화설비의 정기점검 이력이 모두 입증되면 양호로 확정합니다.", "partial": ["항온항습기는 작동하나 온·습도 기록이 자동 저장되지 않고 수기 작성에 의존하거나, 소화설비 점검 주기가 일부 지연된 적이 있습니까?", "온·습도 이탈 시 자동 알림(SMS/카톡 등) 체계가 구축되어 있습니까?"], "partialEnd": "환경 모니터링 및 소방점검 관리 체계 일부 미흡으로 부분이행 판정하고, 자동 기록/알림 모니터링 구축을 권고합니다.", "rootcause": ["전산실 적정 온·습도 기준을 벗어난 상태로 장시간 방치되거나 항온항습기 고장을 수개월 간 조치하지 않은 이유는 무엇입니까?", "법정 화재감지 및 소화설비 정기점검을 실시하지 않은 사유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제20조 위반 결함으로 확정하고, 전산실 환경 관리 및 소방안전 점검 즉시 이행을 요구합니다.", "na": ["전산실을 직접 보유하지 않고, 전문 IDC에 클라우드 또는 Co-location 형태로 입주하여 IDC에서 환경 관리를 일괄 수행합니까?", "IDC 업체의 온·습도 유지 및 소방점검 연차 보고서를 제출받아 검토하고 계십니까?"], "naEnd": "IDC 위탁 운영 타당성 확인 시 해당없음 처리하되, IDC 환경 관리보고서를 증빙으로 확보합니다."}, "07-4": {"decisionQ": "UPS 용량 적정성이 정기적으로 점검되고, 배터리 정기 교체 및 비상발전기 월 1회 이상 정기 점검이 이행되고 있습니까? 관련 점검 보고서와 모니터링 화면을 보여주시겠습니까?", "verify": ["전산실 전체 전력 부하 대비 UPS 용량 적정성을 검토한 'UPS 용량 점검 보고서(또는 연간 점검표)'를 제시해 주시겠습니까?", "UPS 배터리의 내구연한 및 최근 정기 교체 실적(세금계산서, 작업완료보고서 등)을 보여주시겠습니까?", "비상발전기 가동 점검(월 1회 이상 무부하/부하 운전) 점검 대장 및 최근 6개월 점검 기록을 제시해 주시겠습니까?", "UPS 관리 화면에서 현재 배터리 충전 상태 및 입력/출력 전압 정상 여부를 감사역에게 보여주시겠습니까?"], "verifyEnd": "UPS 용량 적정성, 배터리 정기 교체 이력, 월 1회 이상 발전기 점검 기록이 모두 확인되면 양호로 확정합니다.", "partial": ["UPS와 배터리는 정상 작동하나, 비상발전기 점검이 월 1회 미만으로 불정기적으로 수행되거나 점검 대장에 일부 누락이 있습니까?", "발전기 정기 점검 주기를 준수하지 못한 사유와 개선 계획은 무엇입니까?"], "partialEnd": "발전기 점검 주기 미준수로 부분이행 판정하며, 정기점검 스케줄 엄수를 권고합니다.", "rootcause": ["UPS 배터리 교체 주기가 수년 간 지나 방치되었거나 노후화되어 정전 시 전산실 다운 위험이 방치된 원인은 무엇입니까?", "비상발전기가 없거나 장기간 점검을 전혀 하지 않아 비상시 동작 여부를 알 수 없는 이유는 무엇입니까?"], "rootcauseEnd": "전자금융감독규정 제29조 위반 결함으로 확정하고, UPS 배터리 즉시 교체 및 비상발전기 정비계획 수립을 요구합니다.", "na": ["센터 자체 전원이 아닌 IDC 빌딩 전력망(이중화된 UPS 및 빌딩 비상발전기)을 완전히 제공받는 형태입니까?", "IDC 사업자가 제공하는 UPS 및 발전기 정기점검 및 절체훈련 결과서를 받아 관리하고 계습니까?"], "naEnd": "IDC 전력 인프라 이용 타당성이 확인되면 해당없음 처리하되, IDC의 점검 결과를 증빙으로 확보합니다."}, "07-5": {"decisionQ": "전산실 내 서버 및 네트워크 장비 반출입 시 사전 결재 승인 절차를 거치고 반출입 대장을 관리하며 반출입 시 보안 검사를 실시하고 있습니까? 결재 문서와 대장을 제시해 주시겠습니까?", "verify": ["전산장비 반출입 보안 관리 지침(승인 절차서) 문서를 보여주시겠습니까?", "최근 6개월 간 발생한 장비 반출입(신규 장비 입고, 노후 장비 반출, 수리 등) 결재 문서 2건을 보여주시겠습니까?", "전자결재 문서의 장비 시리얼 번호와 물리적 반출입 대장(또는 시스템 대장)의 기록이 일치하는지 대조해 보여주시겠습니까?", "반출 장비에 대한 저장매체 파기/데이터 삭제 검사서 및 반입 장비의 악성코드 점검 기록을 보여주시겠습니까?"], "verifyEnd": "반출입 사전 결재, 대장 관리의 정확성, 반출입 시 보안 검사(데이터 삭제/악성코드 점검) 실적이 확인되면 양호로 확정합니다.", "partial": ["반출입 사전 승인은 이루어지나 반출입 대장에 입출고 시점, 작업자 서명 등 일부 항목이 누락된 채 관리되고 있습니까?", "대장 작성 누락을 방지하기 위한 관리 개선 방안은 무엇입니까?"], "partialEnd": "반출입 대장 관리 미흡으로 부분이행 판정하고, 반출입 등록 절차 강화를 권고합니다.", "rootcause": ["사전 결재 없이 장비를 무단 반출입하거나 실물 대장을 전혀 작성하지 않는 이유는 무엇입니까?", "반출 장비 내 고객정보/중요 데이터 존재 여부나 파기 검사 없이 외부로 반출되는 사유는 무엇입니까?"], "rootcauseEnd": "ISMS-P 2.4.1 위반 결함으로 확정하며, 장비 반출입 즉시 통제 및 미승인 반출입 전수조사를 요구합니다.", "na": ["최근 1년 간 전산실 내 장비의 신규 입고, 반출, 교체 실적이 단 한 건도 없었습니까?", "장비 이동이 전혀 없었음을 입증할 자산 관리 대장 현황을 보여주시겠습니까?"], "naEnd": "장비 이동 실적 없음이 확인되면 해당없음 처리하되, 반출입 지침 및 승인 체계의 유효성은 점검합니다."}, "07-6": {"decisionQ": "PC 자리 이탈 시 화면보호기(10분 이내 비밀번호 잠금)가 자동 실행되도록 중앙 그룹정책(GPO)으로 강제 적용되어 있으며, 클린 데스크 정책이 현장에서 이행되고 있습니까?", "verify": ["AD 그룹정책 관리자(GPO) 화면에서 직원 PC 대상 화면보호기 대기시간(10분 이내) 및 비밀번호 해제 설정 정책을 보여주시겠습니까?", "감사역이 지정하는 임의의 직원 PC 1대에서 화면보호기 설정 창을 열어 사용자가 임의로 변경할 수 없게 비활성화되어 있는지 보여주시겠습니까?", "최근 실시한 '클린 데스크 정기 점검 결과 보고서' 및 위발자 적발/경고 내역을 제시해 주시겠습니까?", "현재 사무실 내 주요 책상에 민감 서류(고객정보, 비밀번호 적힌 메모 등)가 방치되어 있는지 감사역과 현장 점검을 진행하시겠습니까?"], "verifyEnd": "GPO를 통한 화면 잠금 강제화, 클린 데스크 정기 점검 및 현장 점검에서 민감 서류 방치가 없음이 확인되면 양호로 확정합니다.", "partial": ["화면보호기 설정은 되어 있으나 일부 예외 PC(개발용, 모니터링용)에 대한 잠금 예외 승인 절차가 미흡하거나 통제가 누락되어 있습니까?", "예외 PC 목록과 보안 대책(물리적 접근 통제 등)을 보유하고 계십니까?"], "partialEnd": "화면 잠금 예외 PC 관리 미흡으로 부분이행 판정하며, 예외 신청 및 대체 통제 수립을 요구합니다.", "rootcause": ["화면보호기 대기시간이 10분을 초과 설정되어 있거나 비밀번호 잠금이 설정되지 않은 원인은 무엇입니까?", "직원 책상 위에 고객 개인정보 서류나 비밀번호 메모가 상시 방치되고 점검이 전혀 이루어지지 않는 사유는 무엇입니까?"], "rootcauseEnd": "ISMS-P 2.4.4 위반 결함으로 확정하고, GPO 일괄 적용 및 클린 데스크 점검 강화 조치를 요구합니다.", "na": ["해당사항 없음 대상이 아닙니다. (모든 임직원 및 PC에 필수 적용되는 항목입니다.)"], "naEnd": "이 항목은 해당없음으로 처리될 수 없습니다."}, "07-7": {"decisionQ": "신규 전산 장비 도입 시 사전 보안 취약점 점검을 거치고, 기본 패스워드 변경 및 중고/재사용 장비의 데이터 완전 초기화 절차를 준수하고 있습니까? 결재서류와 검사표를 보여주시겠습니까?", "verify": ["최근 도입된 서버/네트워크 장비의 '도입 보안 검토 결재 문서' 및 사전 취약점 점검 결과표를 보여주시겠습니까?", "장비 초기 설정 시 제조사 기본 패스워드(default password)를 변경했음을 입증하는 초기 설정 점검 체크리스트를 제시해 주시겠습니까?", "최근 재사용되거나 매각/폐기된 중고 장비의 '데이터 완전 초기화(디스크 와이핑/디가우징) 확인서'를 보여주시겠습니까?", "장비 도입 및 초기화 과정에 사용된 데이터 삭제 전문 솔루션의 작업 로그를 감사역에게 제시해 주시겠습니까?"], "verifyEnd": "신규 장비 사전 보안 검토, 기본 패스워드 변경, 재사용/반출 장비의 데이터 초기화 증빙이 확인되면 양호로 확정합니다.", "partial": ["신규 장비 도입 검토는 수행되나 제조사 기본 패스워드 변경 여부를 확인하는 공식 체크리스트가 누락되어 있습니까?", "중고 장비 데이터 초기화 시 전문 솔루션 로그 대신 담당자 수기 확인서만 존재하는 사례가 있습니까?"], "partialEnd": "장비 도입/재사용 보안검증 절차 일부 누락으로 부분이행 판정하고, 초기화 증빙 강화를 권고합니다.", "rootcause": ["신규 장비 도입 시 보안 검토 없이 즉시 운영망에 투입되거나 기본 패스워드(admin/admin 등)를 그대로 방치한 원인은 무엇입니까?", "재기업/재사용 장비의 저장매체를 초기화하지 않고 재배치하여 이전 데이터 노출 위험을 방치한 사유는 무엇입니까?"], "rootcauseEnd": "ISMS-P 2.4.5 위반 결함으로 확정하고, 운영 중인 장비의 기본 패스워드 전수 점검 및 데이터 초기화 절차 정비를 요구합니다.", "na": ["최근 1년 간 신규 장비 도입 및 중고 장비 재사용/폐기 실적이 전혀 없었습니까?", "장비 도입 및 자산 변동이 없었음을 증명할 자산 관리 대장을 제시해 주시겠습니까?"], "naEnd": "장비 도입/교체 실적이 없음이 입증되면 해당없음 처리하되, 향후 도입 시 적용할 보안 절차 보유 여부를 확인합니다."}, "02-1": {"decisionQ": "위험평가 방법론을 문서화하고 매년 위험평가 계획을 수립·이행하고 있다고 응답하셨습니다. 그 방법론 문서와 최근 연간 계획서를 함께 보여주실 수 있습니까?", "verify": ["위험평가 방법론 문서를 화면에 띄워 주시겠습니까? 자산기반 방식인지 시나리오 기반 방식인지, 혹은 혼합 방식인지 구체적으로 설명해 주시겠습니까?", "최근 3개년 연간 위험평가 계획서를 함께 조회해 주시겠습니까? 계획 수립 시기가 매년 일정한 시점(예: 연초)에 이루어졌는지 확인 가능합니까?", "가장 최근 위험평가 결과에 대한 경영진(또는 정보보호위원회) 승인 서명본을 보여주시겠습니까?", "현재 방법론이 최신 ISMS-P 인증기준이나 전자금융감독규정 개정사항을 반영하여 언제 마지막으로 개정되었는지 개정이력을 함께 보여주시겠습니까?"], "verifyEnd": "방법론 문서, 연간 계획서, 경영진 승인본, 개정이력이 모두 실물로 확인되고 시기·형식상 결함이 없으면 양호로 확정합니다. 방법론은 있으나 실제 계획 수립 시기가 매년 들쭉날쭉하거나 개정이력이 방치되어 있다면 부분이행으로 전환하십시오.", "partial": ["방법론 문서화, 연간 계획 시기, 경영진 승인, 법령 반영 네 가지 체크포인트 중 구체적으로 어느 부분이 미흡합니까?", "그 부분이 미흡한 이유는 무엇입니까? (예: 담당자 공백, 우선순위 밀림 등)", "작년 감사(또는 전년도 점검)에서도 동일한 부분이 지적된 적이 있습니까?", "언제까지 어떤 방식으로 보완하실 계획입니까?"], "partialEnd": "미흡 부분을 특정하여 개선계획과 기한을 서면으로 요청하고, 다음 점검 시 완전 이행 여부를 재확인합니다.", "rootcause": ["그렇다면 현재 위험평가는 어떤 기준이나 절차로 이루어지고 있습니까? 문서화된 방법론 없이 진행되고 있는 겁니까?", "방법론이나 연간 계획이 부재한 상태가 언제부터 지속되어 왔습니까?", "이 사실을 스스로 인지하고 계셨습니까, 아니면 이번 감사에서 처음 지적받으신 겁니까? 인지하셨다면 상급자나 경영진에게 보고한 적이 있습니까?", "지금 당장 임시로 취할 수 있는 조치와, 방법론 수립을 포함한 근본적 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 위험평가 방법론 수립 및 연간 계획 이행 계획서를 서면으로 요청합니다. 이후 02-2(정보자산 목록 및 위험평가) 항목의 실제 수행 여부도 함께 재확인하는 것이 필요합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "위험평가 자체를 외부 위탁(예: ISMS-P 인증기관)에 전적으로 의존하고 있는 경우라면, 그 위탁 범위와 자체 검토 절차는 어떻게 구성되어 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제이며, 조직·시스템 변화 시 재검토하는 절차가 있습니까?"], "naEnd": "해당없음 판단의 근거가 타당하면 확인을 종료하고, 향후 조직·시스템 변화 시 재점검이 필요함을 안내합니다."}, "02-2": {"decisionQ": "정보자산 목록을 기반으로 CIA(기밀성·무결성·가용성) 관점의 위험평가를 수행하고 있다고 응답하셨습니다. 최신 정보자산 목록과 위험등록부를 함께 보여주실 수 있습니까?", "verify": ["최신 정보자산 목록(하드웨어·소프트웨어·데이터 포함)을 화면에 띄워 주시겠습니까?", "감사역이 이 자리에서 임의로 지정하는 자산 2~3개에 대해, 위험등록부에서 해당 자산의 CIA 등급 산정 근거를 바로 조회해 주시겠습니까?", "최근 수행된 위협·취약성 분석 보고서를 보여주시겠습니까? 분석 시점과 대상 범위를 확인할 수 있습니까?", "최근 자산 변경(신규 도입, 폐기, 구성 변경 등) 사례를 하나 짚어, 그 시점에 위험평가가 재수행되었는지 이력으로 확인해 주시겠습니까?"], "verifyEnd": "정보자산 목록, 감사역 임의 지정 자산의 위험등급 근거, 위협·취약성 분석 보고서, 자산 변경 시 재평가 이력이 모두 일치하게 확인되면 양호로 확정합니다. 목록에는 있으나 감사역이 지정한 자산의 위험등급 근거를 즉시 제시하지 못하면 그 자체를 미흡 사유로 봅니다.", "partial": ["정보자산 목록, CIA 등급 산정, 위협·취약성 평가, 변경 시 재평가 중 구체적으로 어느 부분이 부분적으로만 이행되고 있습니까?", "그 부분이 미흡한 이유는 무엇입니까?", "이 부분이행 상태가 지난 점검(또는 전년도 감사)에서도 동일하게 지적된 적이 있습니까?", "완전한 이행을 위해 언제까지 어떤 조치를 취하실 계획입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 완전 이행 여부를 재확인합니다.", "rootcause": ["그렇다면 현재 정보자산 목록은 어느 수준까지 관리되고 있습니까? 누락되거나 최신화되지 않은 자산 유형이 있습니까?", "CIA 등급 산정이 이루어지지 않고 있다면, 위험 우선순위는 어떤 기준으로 판단하고 계십니까?", "이 문제를 스스로 인지하셨습니까, 아니면 외부 지적이나 사고를 계기로 알게 되셨습니까? 인지하셨다면 경영진에게 보고하셨습니까?", "지금 즉시 취할 수 있는 임시 조치와, 정보자산 목록 정비 및 위험평가 재수행을 포함한 근본적 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 정보자산 목록 정비 및 위험평가 재수행 계획서를 서면으로 요청합니다. 02-1(위험관리 방법론)의 실제 적용 여부와 02-6(적용범위 적정성)도 함께 재확인하는 것이 필요합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "정보자산 목록 관리 자체를 외부(그룹사, 위탁업체 등)에 전적으로 의존하고 있다면, 그 위탁 범위와 자체 검증 절차는 무엇입니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 향후 자산 규모·범위 변화 시 재점검이 필요함을 안내합니다."}, "02-3": {"decisionQ": "허용 가능 수준을 초과하는 위험에 대해 4T(수용·경감·회피·전가) 처리계획을 수립하고 경영진 승인을 받고 있다고 응답하셨습니다. 최신 위험처리 계획서와 승인 서류를 함께 보여주실 수 있습니까?", "verify": ["허용 수준 초과 위험 목록과 그에 대한 4T 처리방안이 문서화된 위험처리 계획서를 보여주시겠습니까?", "해당 계획서에 대한 경영진 승인 서류(결재문서)를 함께 조회해 주시겠습니까?", "위험처리 과제 현황표에서 감사역이 지정하는 과제 1~2건의 담당자·일정을 바로 확인해 주시겠습니까?", "그 과제들의 실제 이행 완료 확인서 또는 진행 상황을 계획서상 일정과 대조해 보여주시겠습니까?"], "verifyEnd": "위험처리 계획서, 경영진 승인 서류, 감사역이 지정한 과제의 담당자·일정, 실제 이행 현황이 모두 일치하면 양호로 확정합니다. 계획서상 일정과 실제 이행 현황이 어긋나면 부분이행 또는 미흡으로 전환하십시오.", "partial": ["계획 수립, 경영진 승인, 담당자·일정 명확화, 계획-이행 일치 중 어느 부분이 부분적으로만 이행되고 있습니까?", "그 부분이 미흡한 이유는 무엇입니까?", "이 부분이행 상태가 전년도 감사에서도 동일하게 지적된 적이 있습니까?", "완전한 이행을 위해 언제까지 어떤 조치를 취하실 계획입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 완전 이행 여부를 재확인합니다.", "rootcause": ["그렇다면 허용 수준을 초과하는 위험은 현재 어떻게 관리되고 있습니까? 처리계획 없이 방치되고 있는 겁니까?", "경영진 승인 없이 처리 방안이 임의로 결정되고 있다면, 그 의사결정 주체는 누구입니까?", "이 상태가 언제부터 지속되어 왔으며, 스스로 인지하고 계셨습니까?", "지금 즉시 취할 수 있는 임시 조치와, 위험처리 계획 수립·승인체계 정비를 포함한 근본적 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 위험처리 계획 수립 및 경영진 승인 체계 정비 계획서를 서면으로 요청합니다. 02-4(위험처리 이행 점검), 02-5(잔여위험 수용 관리)와 직결되는 사안이므로 함께 재확인이 필요합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: 허용 수준 초과 위험이 현재 존재하지 않음)", "허용 수준 초과 위험이 향후 발생할 가능성에 대비한 절차가 마련되어 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 향후 초과 위험 발생 시 즉시 처리계획을 수립하도록 안내합니다."}, "02-4": {"decisionQ": "위험처리 과제의 추진 현황을 정기적으로 점검하고, 미이행 항목은 원인을 분석하며, 기한 연장 시 재승인을 받고 있다고 응답하셨습니다. 최근 점검 이력과 미이행 원인 분석 보고서를 함께 보여주실 수 있습니까?", "verify": ["최근 분기(또는 반기) 위험처리 이행 현황표를 조회해 주시겠습니까?", "감사역이 지정하는 미이행 과제 1건에 대해, 원인 분석 보고서를 바로 조회해 주시겠습니까?", "이행 기한이 연장된 과제가 있다면, 그 재승인 결재문서를 보여주시겠습니까?", "점검 주기가 규정(분기 또는 반기)대로 지켜지고 있는지 최근 3~4회 점검 이력의 날짜를 확인해 주시겠습니까?"], "verifyEnd": "이행 현황표, 미이행 원인 분석 보고서, 기한 연장 재승인 문서, 점검 주기 준수 이력이 모두 확인되면 양호로 확정합니다. 점검은 하고 있으나 미이행 항목에 대한 원인 분석이 형식적이거나 부재하면 미흡으로 봅니다.", "partial": ["정기 점검, 원인 분석, 재승인 절차, 점검 주기 중 어느 부분이 부분적으로만 이행되고 있습니까?", "그 부분이 미흡한 이유는 무엇입니까?", "이 부분이행 상태가 전년도 감사에서도 지적된 적이 있습니까?", "완전한 이행을 위해 언제까지 어떤 조치를 취하실 계획입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 완전 이행 여부를 재확인합니다.", "rootcause": ["그렇다면 위험처리 과제의 추진 현황은 현재 어떤 방식으로 관리되고 있습니까? 정기 점검 없이 방치되고 있는 겁니까?", "미이행 과제가 다수 누적되어 있다면, 그 규모와 기간은 어느 정도입니까?", "이 상태를 스스로 인지하고 계셨습니까? 경영진에게 보고된 적이 있습니까?", "지금 즉시 취할 수 있는 임시 조치와, 점검체계 정비를 포함한 근본적 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 위험처리 이행 점검체계 정비 계획서를 서면으로 요청합니다. 02-3(위험처리 계획 수립)의 실효성과 함께 재확인이 필요합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: 현재 진행 중인 위험처리 과제가 없음)", "향후 위험처리 과제가 발생할 경우의 점검 절차는 준비되어 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 향후 과제 발생 시 정기 점검 체계를 즉시 적용하도록 안내합니다."}, "02-5": {"decisionQ": "잔여위험에 대해 경영진이 인식·수용하는 의사결정을 문서화하고, 주기적으로 재평가하고 있다고 응답하셨습니다. 잔여위험 목록과 경영진 수용 결재서를 함께 보여주실 수 있습니까?", "verify": ["최신 잔여위험 목록과 각 항목의 수용 사유를 조회해 주시겠습니까?", "감사역이 지정하는 잔여위험 항목 1건에 대해, 경영진의 인식·수용 서명(또는 전자결재)을 바로 확인해 주시겠습니까?", "잔여위험 재평가 이력을 조회하여, 연 1회 이상의 주기가 지켜지고 있는지 확인해 주시겠습니까?", "잔여위험이 실제로 현실화된 사례가 있었다면, 그에 대한 대응 체계와 결과를 설명해 주시겠습니까?"], "verifyEnd": "잔여위험 목록, 경영진 수용 서명, 재평가 이력, 실제 발생 시 대응 체계가 모두 확인되면 양호로 확정합니다. 목록은 있으나 경영진 서명 없이 형식적으로 관리되고 있다면 미흡으로 전환하십시오.", "partial": ["목록화, 경영진 수용 서명, 재평가 주기, 대응 체계 중 어느 부분이 부분적으로만 이행되고 있습니까?", "그 부분이 미흡한 이유는 무엇입니까?", "이 부분이행 상태가 전년도 감사에서도 지적된 적이 있습니까?", "완전한 이행을 위해 언제까지 어떤 조치를 취하실 계획입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 완전 이행 여부를 재확인합니다.", "rootcause": ["그렇다면 잔여위험은 현재 어떻게 관리되고 있습니까? 경영진 인식 없이 실무선에서만 처리되고 있는 겁니까?", "재평가가 이루어지지 않고 있다면, 그 기간은 얼마나 됩니까?", "이 상태를 스스로 인지하고 계셨습니까? 경영진에게 보고된 적이 있습니까?", "지금 즉시 취할 수 있는 임시 조치와, 잔여위험 관리체계 정비를 포함한 근본적 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 잔여위험 목록화 및 경영진 수용 절차 정비 계획서를 서면으로 요청합니다. 02-3(위험처리 계획 수립)과 연계하여 재확인이 필요합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: 현재 잔여위험이 존재하지 않음)", "향후 잔여위험이 발생할 경우의 수용 절차는 준비되어 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 향후 잔여위험 발생 시 수용 절차를 즉시 적용하도록 안내합니다."}, "02-6": {"decisionQ": "ISMS-P 인증 범위와 실제 정보자산 처리 범위가 일치하고, 범위 변경 시 재평가를 수행하고 있다고 응답하셨습니다. 인증 범위 정의서와 실제 자산 처리 현황도를 함께 보여주실 수 있습니까?", "verify": ["ISMS-P 인증 범위 정의서를 조회해 주시겠습니까?", "감사역이 지정하는 정보 처리 시스템 1~2개에 대해, 해당 시스템이 인증 범위 내에 포함되어 있는지 정보자산 처리 현황도로 바로 확인해 주시겠습니까?", "최근 조직 개편이나 시스템 도입·변경 사례가 있었다면, 그에 따라 인증 범위 재검토가 이루어졌는지 이력으로 보여주시겠습니까?", "최근 ISMS-P 인증심사에서 범위 적정성에 대한 지적 사항이 있었습니까? 있었다면 그 조치 결과를 보여주시겠습니까?"], "verifyEnd": "인증 범위 정의서, 감사역이 지정한 시스템의 범위 포함 여부, 조직·시스템 변경 시 재검토 이력, 인증심사 지적사항 조치 결과가 모두 확인되면 양호로 확정합니다. 감사역이 지정한 시스템이 실제로는 범위 밖에서 정보자산을 처리하고 있다면 그 자체를 미흡 사유로 봅니다.", "partial": ["범위 정의서와 실제 처리 범위 일치, 변경 시 재검토, 인증심사 지적사항 조치 중 어느 부분이 부분적으로만 이행되고 있습니까?", "그 부분이 미흡한 이유는 무엇입니까?", "이 부분이행 상태가 전년도 감사(또는 인증심사)에서도 지적된 적이 있습니까?", "완전한 이행을 위해 언제까지 어떤 조치를 취하실 계획입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 완전 이행 여부를 재확인합니다.", "rootcause": ["그렇다면 현재 인증 범위 밖에서 정보자산을 처리하고 있는 시스템은 어느 정도 규모입니까?", "이 범위 불일치 상태가 언제부터 발생했는지 파악하고 계십니까?", "이 문제를 스스로 인지하셨습니까, 아니면 외부 지적(인증심사, 감독당국 등)으로 알게 되셨습니까? 인지하셨다면 경영진에게 보고하셨습니까?", "지금 즉시 취할 수 있는 임시 조치와, 범위 재검토 및 인증 갱신을 포함한 근본적 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 인증 범위 재정의 및 조치 계획서를 서면으로 요청합니다. 02-2(정보자산 목록 및 위험평가)의 자산 목록과 실제 범위가 일치하는지 함께 재확인하는 것이 필요합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: ISMS-P 인증 대상 자체가 아님)", "향후 인증 의무 대상이 될 가능성이 있습니까? 있다면 사전 준비 절차가 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 향후 서비스·조직 범위 변화 시 재검토가 필요함을 안내합니다."}, "03-1": {"decisionQ": "최상위 정보보호 정책서의 연 1회 이상 검토·개정, 대표이사 승인, 전 직원에 대한 고지가 정상적으로 이루어지고 있는지 현장 화면과 문서로 바로 확인해 주시겠습니까?", "verify": ["가장 최근 대표이사 결재(전자결재 또는 실물 서명)가 완료된 최상위 정보보호 정책서 승인 문서 원본을 보여주시겠습니까?", "해당 정책서의 제·개정 이력표에서 최근 1년 이내 정기 검토 또는 개정 기록을 확인해 주시겠습니까?", "전 직원 고지가 이루어진 사내 게시물, 공문, 또는 그룹웨어 메일 수신 확인 이력을 이 자리에서 조회해 보여주실 수 있습니까?", "감사역이 지정하는 임의 임직원 2명의 계정으로 그룹웨어에 접속하여, 최신 정책서를 누구나 쉽게 열람할 수 있는 상태인지 재조회해 주시겠습니까?"], "verifyEnd": "대표이사 결재 승인본, 1년 이내 개정 이력, 전 직원 배포 증적 및 임의 계정 접속 시 열람 가능 여부가 모두 확인되면 양호로 확정합니다. 사전 준비 자료와 실시간 재조회 결과가 다를 경우 미흡으로 판정합니다.", "partial": ["경영진 승인 및 개정은 완료되었으나 전 직원 고지/배포가 일부 누락되었거나(예: 신규 입사자 제외 등), 배포는 되었으나 승인 절차가 완비되지 않은 상태입니까?", "부분적으로만 관리되고 있는 사유는 무엇입니까?", "과거 전년도 감사나 자체 점검에서도 동일한 정책 관리 지적사항이 반복되었습니까?", "전사 고지 체계 완비 및 정책서 전체 보완을 위해 설정한 완료 목표일은 언제입니까?"], "partialEnd": "미흡 항목을 특정하여 조치 계획서를 접수하고, 차기 점검 시 재배포 이력 및 결재 증적을 재확인합니다.", "rootcause": ["최상위 정책서의 대표이사 최종 승인 절차가 누락되거나 연간 정기 검토가 이루어지지 않은 주된 원인은 무엇입니까?", "정보보호위원회 또는 경영진 보고 절차가 적시에 수행되지 못한 계기나 장애요인이 있었습니까?", "이러한 미개정·미승인 상태를 정보보호최고책임자(CISO)나 경영진에게 보고하고 개선을 시도한 적이 있습니까?", "지적된 미흡 사항에 대해 즉시 이행할 수 있는 정기 검토 프로세스 신설 및 승인 추진 계획은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 CISO 및 경영진 보고를 포함한 정책서 제·개정 조치 계획서를 공식 접수합니다.", "na": ["해당 저축은행이 타 금융지주/본사의 정보보호 정책을 전적으로 적용받아 자체 최상위 정책서 작성이 면제되는 구조입니까?", "지주/본사 정책을 적용받는 경우, 내부 위임전결 규정 및 그룹 공통 정책 적용에 대한 승인 근거가 명확히 존재합니까?", "지주/본사 정책 개정 시 당행으로의 전달 및 반영 프로세스가 주기적으로 점검되고 있습니까?"], "naEnd": "지주/본사 공통 정책 적용에 대한 규정상 근거 및 전달 프로세스가 확인되면 N/A로 인정합니다."}, "03-2": {"decisionQ": "정보보호 정책-지침-절차 체계가 계층별로 연계 구축되어 있으며, 최신 버전 관리 및 상충 여부 검토가 지속적으로 이루어지고 있는지 문서를 통해 확인해 주시겠습니까?", "verify": ["당행의 정보보호 체계도(정책-지침-절차 연계표)와 현행 지침·절차서 전체 마스터 목록을 출력/화면 조회해 주시겠습니까?", "감사역이 무작위로 선택한 지침 2건(예: 개인정보보호 지침, 네트워크 보안 지침)의 최신 개정 이력과 개정 이유를 보여주시겠습니까?", "버전 관리 대장(또는 문서관리시스템 버전 등록 화면) 상에서 구버전과 신버전의 차이점 및 승인 이력이 관리되고 있음을 확인해 주시겠습니까?", "상위 정책 개정 시 하위 지침 및 절차서가 연동되어 개정된 내역을 비교 표로 보여주실 수 있습니까?"], "verifyEnd": "정책-지침-절차 체계가 정립되어 있고, 임의 추출한 지침의 버전 관리 및 상하위 규정 간 정합성이 확인되면 양호로 확정합니다.", "partial": ["상위 정책과 하위 지침은 정립되어 있으나 최신 절차서(SOP)의 개정이 지연되어 상충되는 내용이 존재합니까?", "버전 관리가 전산 시스템이 아닌 수기 대장으로 운영되어 일부 누락이 발생하고 있습니까?", "이러한 버전 관리 미흡 사항이 발생하게 된 사유와 향후 개선 방안은 무엇입니까?", "전수 점검을 통해 상충·중복 항목을 정비하는 데 필요한 예상 소요 기간은 얼마입니까?"], "partialEnd": "하위 지침 및 절차서 정비 계획서를 제출받고 정비 기한 내 반영 여부를 차기 점검에서 확인합니다.", "rootcause": ["하위 지침/절차서의 표준 양식이 없거나 버전 관리가 전혀 이루어지지 않고 있는 근본적인 이유는 무엇입니까?", "정책 개정 후 하위 지침으로의 반영을 전담하는 관리 프로세스나 담당자 지정이 부재합니까?", "지침 간 내용 상충으로 인해 실제 업무 현장에서 혼선이 발생한 사례가 있었습니까?", "통합 지침 관리 체계 수립을 위한 즉각적인 조치 방안은 무엇입니까?"], "rootcauseEnd": "결함으로 판정하며, 정보보호 지침 체계 재정비 및 전수 조사 계획 수립을 서면 요청합니다.", "na": ["조직 규모 또는 규정 관리 체계상 '정책-지침-절차'를 단일 통합 문서 규정으로 운영하도록 승인받았습니까?", "통합 규정 내에서 정책적 선언과 세부 실행 절차가 명확히 구분되어 관리되고 있습니까?"], "naEnd": "단일 통합 규정 운용에 대한 합리적 사유 및 내부 규정 승인 근거가 확인되면 해당 조항 적용을 유연하게 판정합니다."}, "03-3": {"decisionQ": "전자금융감독규정, 개인정보보호법 등 관련 법령 및 인증기준 개정 사항에 대한 모니터링 체계와 내부 반영(3개월 이내) 절차가 적정하게 운영되는지 확인해 주시겠습니까?", "verify": ["최근 2년 이내 법령/감독규정 개정 사항에 대한 내부 '모니터링 보고서' 또는 '법령 개정 영향분석서'를 제출해 주시겠습니까?", "법령 개정 후 3개월 이내에 당행 내부 정보보호 지침/절차에 반영되어 개정 완료된 이력 비교표를 보여주시겠습니까?", "법령 반영이 지연되어 '미반영 예외 승인'을 받은 건이 있다면, 이에 대한 위험평가 및 CISO 승인 문서를 확인해 주시겠습니까?", "감사역이 지정하는 최근 감독규정 개정 조항(예: 망분리 완화 또는 계정관리 강화 등)이 내부 지침 몇 조 몇 항에 반영되었는지 이 자리에서 규정집을 열어 보여주시겠습니까?"], "verifyEnd": "법령 개정 모니터링 실적, 3개월 이내 규정 반영 이력, 감사역 지정 조항의 실제 반영 여부가 확인되면 양호로 확정합니다.", "partial": ["법령 개정 모니터링은 수행되었으나 내부 지침 반영 기한(3개월)을 초과하여 반영되었습니까?", "지연 사유에 대한 공식적인 예외 승인 절차(위험평가 및 CISO 결재)가 일부분 누락되었습니까?", "지연 발생의 원인은 무엇이며, 현재 미반영된 다른 법령 개정 항목이 존재하는지 전수 내역을 작성해 주시겠습니까?"], "partialEnd": "미반영/지연 반영 항목에 대한 조치 계획을 제출받고 반영 완료시까지 모니터링을 강화합니다.", "rootcause": ["법령 및 인증기준 개정 모니터링 절차 자체가 부재하거나 담당자 미지정 상태인 이유는 무엇입니까?", "법률 개정에도 불구하고 내부 규정이 개정되지 않아 법적 준거성(Compliance) 위반 위험에 노출된 상태를 인지하고 있었습니까?", "관련 법령 미반영 건에 대해 경영진에 위험 보고를 실시한 적이 있습니까?", "법령 개정 대응 프로세스 정비 및 미반영 지침에 대한 즉각적인 개정 계획은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 법령 미반영 항목 전수 조사 및 즉시 규정 개정을 공식 서면 요구합니다.", "na": ["최근 2년간 당행 정보보호 업무와 직·간접적으로 연관된 신규 법령, 감독규정, 인증기준의 제·개정이 전혀 없었습니까?", "외부 법률 자문 또는 지주사 법무팀을 통해 개정 사항 없음이 검증된 결과 보고서가 있습니까?"], "naEnd": "관련 법령 개정 사실이 없었음이 객관적 법률 검토 문서로 확인되면 해당없음(N/A) 처리합니다."}, "03-4": {"decisionQ": "연 1회 이상 내부 정보보호 감사를 독립적인 인력이 계획, 체크리스트, 결과 보고 절차에 따라 적정하게 수행하고 있는지 증적을 확인해 주시겠습니까?", "verify": ["당해 연도(또는 전년도) 내부 정보보호 감사 계획서 및 대표이사(또는 감사위원회) 승인 문서를 제출해 주시겠습니까?", "감사 수행 시 사용된 최신 정보보호 감사 체크리스트 원본과 피감사 부서별 작성 내역을 보여주시겠습니까?", "감사 결과 보고서와 함께 대표이사/경영진에게 보고된 결재 문서 및 회의록 이력을 확인해 주시겠습니까?", "감사 수행 인원의 소속, 담당 업무 및 독립성 확약서(또는 피감사 업무 직무 겸직 없음 확인서)를 보여주실 수 있습니까?"], "verifyEnd": "승인된 감사계획, 최신 체크리스트, 경영진 보고서 및 감사인의 업무 독립성이 모두 입증되면 양호로 확정합니다.", "partial": ["내부 감사는 실시되었으나 체크리스트가 최신 인증기준/법령을 반영하지 못한 구버전이거나, 독립성이 일부 미흡(자체 부서 상호 감사 등)합니까?", "경영진 보고가 서면 결재가 아닌 구두 보고 형태로 단순 처리되었습니까?", "감사의 독립성 확보 및 체크리스트 고도화를 위해 수립한 개선안은 무엇입니까?"], "partialEnd": "독립성 확보 방안 및 체크리스트 재정비 계획을 수립하도록 조치요구합니다.", "rootcause": ["연간 내부 정보보호 감사를 실시하지 않았거나 감사 결과 보고서를 작성하지 않은 사유는 무엇입니까?", "정보보호 담당자가 본인의 업무를 직접 감사하는 등 직무 분리 및 독립성이 완전히 상실된 경위는 무엇입니까?", "내부감사 미실시에 따른 위험에 대해 경영진에 보고된 바가 있습니까?", "차기 내부감사의 객관성 확보를 위한 외부 전문기관 활용 또는 독립 감사인 지정 계획은 무엇입니까?"], "rootcauseEnd": "중대 결함으로 확정하고 CISO 및 감사위원회에 해당 사실을 즉시 통보 조치합니다.", "na": ["당행 규정상 정보보호 감사가 전사 중앙 감사부서의 연간 종합감사 항목으로 완전 통합되어 별도로 실시되는 구조입니까?", "중앙 감사부서의 감사 항목 내 정보보호 영역이 ISMS-P/감독규정 수준으로 포함되어 수행된 결과 문서가 있습니까?"], "naEnd": "전사 종합감사 내 정보보호 분야가 완전 포함되어 독립 수행된 증적 확인 시 별도 감사건은 N/A 인정합니다."}, "03-5": {"decisionQ": "내부감사, 외부검사, ISMS-P 심사 등의 지적사항에 대해 조치 계획 수립, 이행 관리, 미이행 시 재감사 및 반복 지적 원인 분석이 체계적으로 관리되고 있습니까?", "verify": ["최근 2년간 발생한 감사/심사 지적사항 이력 관리 대장 전체를 화면으로 보여주시겠습니까?", "지적사항별 조치 담당자 지정, 조치 기한, 그리고 이행 완료 확인서(증빙 문서 포함) 결재건을 확인해 주시겠습니까?", "기한 내 미이행된 항목에 대한 재감사 실시 결과 보고서 또는 독촉/경고 발송 이력을 보여주시겠습니까?", "동일한 지적사항이 연속 2회 이상 발생한 건에 대한 '반복 지적 원인 분석 및 근본 대책 보고서'를 확인해 주시겠습니까?"], "verifyEnd": "조치 대장 관리, 조치완료 증빙, 미이행 시 재감사 이행, 반복 지적 원인분석 보고서가 확인되면 양호로 확정합니다.", "partial": ["지적사항 조치는 대부분 진행되었으나 조치 완료 증빙 확인 절차가 누락되어 대장상에만 완료로 표기되어 있습니까?", "지적사항 관리 대장이 수기로 관리되어 일부 지적건의 이행 기한 추적이 지연되었습니까?", "미비된 증적 보완 및 이력 관리 시스템화 계획은 무엇입니까?"], "partialEnd": "미완료 및 증적 미흡 항목에 대한 즉시 보완을 요구하고 관리 대장 재정비를 지시합니다.", "rootcause": ["지적사항에 대한 조치 계획 자체가 수립되지 않거나 담당자 지정 없이 방치된 사유는 무엇입니까?", "미이행 지적사항에 대하여 재감사나 경영진 보고 조치가 전혀 이루어지지 않은 이유는 무엇입니까?", "반복적으로 동일 결함이 지적됨에도 근본 원인 제거를 위한 예산/인력 투입이 거부되었습니까?", "미이행 지적사항을 즉시 해소하기 위한 경영진 보고 및 조치 이행 로드맵은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 미이행 지적사항에 대한 즉시 개선 명령 및 감사위원회 보고 조치를 취합니다.", "na": ["최근 3년간 내부감사, 외부기관 검사, ISMS-P 심사 등에서 단 1건의 지적사항도 발생하지 않았습니까?", "지적사항 무(Zero)에 대한 공식 검사/심사 결과 통보서가 존재합니까?"], "naEnd": "지적사항 없음이 공식 문서로 검증된 경우에 한하여 본 조항을 N/A 처리합니다."}, "03-6": {"decisionQ": "연 1회 이상 경영진이 참석하는 정보보호 경영검토(Management Review)가 필수 입·출력 항목을 갖추어 수행되고 결과가 보고되고 있는지 확인해 주시겠습니까?", "verify": ["당해 연도(또는 전년도) 정보보호 경영검토 개최 계획서 및 경영진 참석 회의록 원본을 보여주시겠습니까?", "회의록 상에 CEO/CISO 등 경영진의 서명(또는 전자결재 서명)이 완료되어 있는지 확인해 주시겠습니까?", "경영검토 보고서 내 입력 항목(감사 결과, 위험평가 결과, 성과지표 등)과 출력 항목(자원 할당, 개선 결정 등)이 규정대로 정의·보고되었습니까?", "경영검토 결과 도출된 경영진 지시사항/개선결정 조치 현황 보고서를 이 자리에서 조회해 주시겠습니까?"], "verifyEnd": "경영진 서명 회의록, 필수 입·출력 항목 포함 여부, 경영검토 후속 개선사항 이행이 입증되면 양호로 확정합니다.", "partial": ["경영검토 보고는 진행되었으나 CISO 보고로만 대체되고 CEO 등 최고경영진 참석/서명이 누락되었습니까?", "입력 항목 중 일부(예: 위험평가 결과 누락 등)가 누락된 채 형식적으로 회의가 진행되었습니까?", "경영진 참석 범위 확대 및 경영검토 보고서 표준화를 위한 개선 계획은 무엇입니까?"], "partialEnd": "경영진 참석 요건 준수 및 보고서 항목 보완을 지시하고 차기 경영검토 시 재점검합니다.", "rootcause": ["연간 정보보호 경영검토 자체를 실시하지 않은 근본적인 이유는 무엇입니까?", "경영검토 결과를 경영진에 보고하지 않거나 개선 결정사항에 대한 후속 조치가 전무한 사유는 무엇입니까?", "경영검토 수행 의무화 및 프로세스 정립을 위해 즉시 취할 수 있는 조치는 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 경영진이 참석하는 정기 경영검토 수립 및 개최를 서면 촉구합니다.", "na": ["당행이 다른 경영 보고 체계(예: 정보보호위원회) 내에 경영검토 필수 입·출력 항목을 완전히 포함하여 운영하고 있습니까?", "해당 위원회 회의록에 CEO 참석 및 경영검토 항목 심의·의결 내역이 명시되어 있습니까?"], "naEnd": "이사회/정보보호위원회 등 타 고위급 회의체에서 경영검토 요건을 100% 충족하여 수행한 경우 예외를 인정합니다."}, "03-7": {"decisionQ": "ISMS-P 등 보유 정보보호 인증의 갱신/사후심사 일정 관리, 사후심사 지적사항의 기한 내 이행, 인증 범위 변경 시 재심사 절차가 적정하게 관리되고 있습니까?", "verify": ["현재 유효한 ISMS-P 인증서 원본(유효기간 명시) 및 인증기관과의 당해 연도 사후/갱신 심사 계약서를 제출해 주시겠습니까?", "가장 최근 수행된 ISMS-P 사후/갱신 심사 결과 통보서 및 심사 지적사항 이행 완료 확인서(인증기관 제출 결재본)를 보여주시겠습니까?", "최근 신규 서비스 오픈이나 IT 인프라 변경으로 인증 범위 변경 요인이 발생했을 때, 이에 대한 재심사/범위 변경 신청 절차를 이행한 증적을 보여주실 수 있습니까?", "연간 인증 유지 예산 집행 내역 및 심사 일정 관리 로드맵 문서를 이 자리에서 확인해 주시겠습니까?"], "verifyEnd": "유효한 인증서, 사후심사 지적사항 기한 내 완료 증적, 범위 변경 절차 이행 및 일정 관리가 확인되면 양호로 확정합니다.", "partial": ["인증 유지 및 사후심사는 완료되었으나 심사 지적사항 조치 기한이 일부 지연되어 인증기관에 연장 요청을 했습니까?", "인증 범위 변경 소지가 있었으나 심사기관 사전 보고가 다소 지연되었습니까?", "지연 항목에 대한 조치 완료 예정일 및 인증기관 협의 결과 문서를 확인해 주시겠습니까?"], "partialEnd": "인증기관 제출 조치계획서에 따른 최종 이행 완료 여부를 지속 추적 관리합니다.", "rootcause": ["사후심사 미신청 또는 지적사항 미조치로 인해 인증 실효/유휴 위기에 처한 경위는 무엇입니까?", "인증 유지 예산 미반영이나 담당자 방치로 인해 인증 관리 일정이 일탈된 이유는 무엇입니까?", "인증 취소 위험 발생 시 경영진 보고 및 즉각적인 인증기관 대응 계획은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 인증 자격 유지를 위한 비상 조치 계획서 작성을 공식 요구합니다.", "na": ["당행이 법적 ISMS-P 의무 지정 대상이 아니며, 자율 인증도 신청/보유하고 있지 않은 상태입니까?", "의무 지정 대상 제외 기준(매출액, 이용자 수 등)에 대한 법적 검토 보고서가 작성되어 있습니까?"], "naEnd": "ISMS-P 의무 대상이 아니며 자율 인증도 보유하지 않음이 확인되면 N/A로 처리합니다."}, "04-1": {"decisionQ": "정보자산(HW, SW, 데이터, 인력) 목록이 최신화되어 관리되고 있으며, 연 1회 이상 전수조사 및 실물 일치 여부를 점검하고 계십니까? 관리 시스템이나 대장에서 실시간으로 조회 가능합니까?", "verify": ["자산관리 시스템(또는 대장)에서 HW, SW, 데이터, 인적 자산 목록의 최신 현황을 바로 화면으로 출력해 주시겠습니까?", "최근 3개월 내 신규 도입되거나 폐기된 HW/SW 자산 2건을 지정할 테니, 변경 신청 결재 문서와 자산 대장 반영 이력을 대조해 보여주실 수 있습니까?", "가장 최근에 실시한 연간 자산 전수조사 결과 보고서 및 실사 확인서 원본을 보여주시겠습니까?", "감사역이 지금 지정하는 서버/매체 2대의 시리얼 번호 및 설치 위치를 자산 대장 및 실물 위치와 즉시 대조해 보여주실 수 있습니까?"], "verifyEnd": "자산 대장의 4대 유형(HW, SW, 데이터, 인력) 관리가 완비되어 있고, 감사역이 임의 지정한 자산의 실물·시리얼 번호·위치 및 변경 결재 이력이 대장과 100% 일치하며, 연 1회 전수조사 수행 실적이 입증되면 양호로 확정합니다.", "partial": ["HW/SW는 대장에 반영되어 있으나 데이터 및 인적 자산 목록이 누락되었거나 update가 지연되고 있는 항목이 있습니까?", "신규 도입 또는 폐기 시 대장 반영이 즉시 이루어지지 않고 분기별/연간 단위로 후행 입력되는 이유는 무엇입니까?", "전수조사는 실시했으나 일부 실물 누락 및 위치 불일치 건에 대해 재조정 조치 보고서가 누락된 상태입니까?"], "partialEnd": "누락된 자산 유형(데이터·인적자산)의 즉시 반영 및 변경 반영 주기 단축(즉시 처리)을 지시하고, 불일치 자산에 대한 재정비 계획 수립을 조건으로 부분 이행 처리합니다.", "rootcause": ["자산 관리 담당자가 명확히 지정되어 있지 않거나, 자산 변경 통보 절차(도입/폐기 프로세스와 자산대장 연동)가 부재한 상태입니까?", "전수조사를 실시하지 않거나 자산 대장 내용과 실제 보유 현황 간 심각한 불일치(미상 자산 발견 등)가 발생하는 원인은 무엇입니까?", "경영진 또는 정보보호최고책임자(CISO)에게 자산 실사 결과 미흡 사항을 보고하지 않은 이유는 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고 자산관리 프로세스 전면 재수립, 자산대장 전수 재작성 및 CISO 보고를 이행하도록 조치요구서를 발급합니다.", "na": ["해당 기관이 모든 IT 자산을 외부 클라우드 MSP에 전적으로 위탁하여 직접 관리하는 물리적/논리적 자산이 전혀 없는 형태입니까?", "위탁 관리 중이라 하더라도 클라우드 내 인프라(가상자산, DB, 계정 등) 자산 목록을 수시로 교부받아 자체 검증하는 절차가 있습니까?"], "naEnd": "클라우드 서비스 이용 등으로 직접 물리 자산을 보유하지 않더라도 논리적 자산 관리 책임이 확인되므로, 순수 N/A 적용은 불가하며 관리 범위 조정을 안내합니다."}, "04-2": {"decisionQ": "모든 정보자산별로 명확한 소유자(담당부서 및 정/부 담당자)가 지정되어 있으며, 인사이동이나 부재 시 이관 및 대행 절차가 정상적으로 작동하고 있습니까?", "verify": ["자산대장 상에 관리부서, 소유자(정), 대행자(부) 항목이 명시되어 있는지 화면으로 확인해 주시겠습니까?", "최근 6개월 내 인사이동이 발생한 담당자 2명의 자산 이관 확인서 및 자산대장 변경 승인 내역을 조회해 주시겠습니까?", "감사역이 지정한 핵심 자산(메인 DB, 핵심 백업서버 등)의 소유자에게 해당 자산의 보안 관리 책임 범위 및 보호 요구사항을 숙지하고 있는지 즉시 인터뷰/서약서로 증명할 수 있습니까?", "장기 부재(휴가, 출장 등) 발생 시 소유권 권한 대행 설정이 시스템적으로 처리되는지 설정 화면을 보여주시겠습니까?"], "verifyEnd": "자산별 정/부 소유자 지정이 완비되어 있고, 최근 인사이동에 따른 이관 내역이 확인되며, 소유자가 책임 권한을 정확히 인지하고 있음이 검증되면 양호로 확정합니다.", "partial": ["자산 소유 부서는 지정되어 있으나 개인 단위(정/부 담당자) 지정이 누락되어 있습니까?", "인사 이동 후 자산 이관 처리가 규정된 기한(예: 7일)을 초과하여 뒤늦게 업데이트되는 경향이 있습니까?", "소유자 부재 시 대행자 지정 프로세스가 서면으로만 존재하고 시스템 권한 대행으로 이어지지 않고 있습니까?"], "partialEnd": "부서 단위 관리에서 개인(정/부) 관리로 상세화하도록 개선을 요구하고, 인사발령 시스템과 자산 이관 프로세스의 자동 연동 강화를 권고합니다.", "rootcause": ["자산 소유자 지정 기준 자체가 부재하거나, 퇴사자/전보자의 계정 및 관리 자산이 방치되어 소유자 불명 자산(Orphan Asset)이 존재합니까?", "자산 소유자가 자신이 관리 책임자임을 인지하지 못하고 IT 운영팀에만 책임을 전가하는 구조적 문제가 있습니까?"], "rootcauseEnd": "결함으로 확정하며, 소유자 없는 자산에 대한 전수 조사 및 소유자 재지정, 자산 관리책임 동의서 재작성을 이행하도록 요구합니다.", "na": ["단일 전산 담당자 1인이 전적으로 모든 IT 인프라를 운영/관리하여 소유자 분율의 실익이 없는 극소형 조직입니까?"], "naEnd": "저축은행업권 특성상 최소한의 업무 분장 및 정/부 지정이 필수적이므로 N/A는 인정되지 않습니다."}, "04-3": {"decisionQ": "정보자산에 대한 분류 기준(공개/내부용/대외비/기밀)이 수립되어 있으며, 이에 따른 라벨링 및 취급 통제(인쇄·배포·폐기 등)가 적용되고 있습니까?", "verify": ["정보 분류 기준 정의서 및 지침 개정 이력을 최신 버전으로 화면에 조회해 주시겠습니까?", "자산대장 상 모든 정보자산(문서, DB, 소스코드 등)에 정보 등급(기밀/대외비 등)이 지정되어 있는지 필터링해 보여주실 수 있습니까?", "보안문서(대외비 이상) 2건을 지정할 테니 문서 상단/하단의 보안 라벨 표시와 DRM(또는 문서보안) 등급 설정 현황을 직접 시연해 주시겠습니까?", "정보등급 변경(예: 기밀->내부용)이 발생한 자산의 등급 변경 승인 신청서 및 재라벨링 이력을 보여주실 수 있습니까?"], "verifyEnd": "정보 분류 정의서가 존재하고, 자산대장에 등급이 100% 매핑되어 있으며, 실제 문서/문서보안 솔루션 상 라벨링 및 취급 통제가 일치하게 적용됨이 확인되면 양호로 확정합니다.", "partial": ["전자문서(DRM)에는 정보등급 라벨링이 자동 적용되나, 출력물이나 HW/SW 자산에는 분류 표시가 누락되어 있습니까?", "정보 분류 기준은 수립되어 있으나, 자산 대장 상 일부 자산의 등급 지정이 누락('미분류')되어 있습니까?", "분류 변경 절차가 존재하나 승인 절차 없이 담당자 임의로 등급을 하향 변경하는 사례가 있습니까?"], "partialEnd": "비전자 자산 및 물리적 출력물에 대한 라벨링 방안 보완을 지시하고, 자산대장 내 미분류 항목에 대한 즉시 등급 부여를 요구합니다.", "rootcause": ["정보 분류 기준 자체가 유효하지 않거나, 직원들이 등급 분류 기준을 숙지하지 못해 모든 문서를 임의(기본값)로 방치하고 있습니까?", "DLP나 DRM 등 기술적 통제 수단과 정보 분류 체계가 연동되어 있지 않아 등급에 따른 차등 통제가 불가능한 상태입니까?"], "rootcauseEnd": "결함으로 확정하고, 정보분류 체계 재정비, DRM/DLP 통제 정책 연동 및 전 직원 대상 분류 표식 교육 수립을 명합니다.", "na": ["취급하는 모든 정보가 일반에 완전 공개된 공공 데이터뿐이어서 비밀성 통제가 불필요한 경우입니까?"], "naEnd": "저축은행은 개인금융정보 및 신용정보를 다루므로 N/A 타당성이 성립하지 않습니다."}, "04-4": {"decisionQ": "USB, 외장HDD 등 이동식 매체의 사용 승인·등록·반납 절차가 준수되고 있으며, 미인가 매체의 차단 및 분실 보고 체계가 기술적·관리적으로 작동하고 있습니까?", "verify": ["이동식 매체 관리 대장(등록 매체 시리얼, 사용자, 승인 기간)을 시스템 상에서 즉시 조회해 보여주시겠습니까?", "감사역이 지정하는 미등록 USB를 현장 관리 PC에 삽입했을 때, 매체 제어 솔루션(DLP 등)에서 즉시 차단 팝업이 뜨고 차단 로그가 남는지 시연해 주시겠습니까?", "최근 3개월 내 승인된 이동식 매체 신청 결재 문서 2건과 실제 매체 관리대장의 등록 정보를 대조해 주시겠습니까?", "최근 발생한 이동식 매체 분실/도난 보고 이력 또는 정기 매체 실사 점검 결과 보고서를 보여주실 수 있습니까?"], "verifyEnd": "관리 대장에 수록된 매체만 승인 사용되고, 미인가 USB 접속 시 기술적으로 즉시 차단되며, 승인 문서와 대장이 일치하고 정기 실사 이력이 확인되면 양호로 확정합니다.", "partial": ["이동식 매체 차단 솔루션은 적용되어 있으나, 보조기억매체 관리 대장의 입출고 및 반납 현황이 서면으로만 어설프게 관리되고 있습니까?", "일반 PC는 USB가 차단되나 서버, 단말 등 특정 예외 직군에 대해 통제 예외가 과도하게 승인되고 있습니까?", "승인된 매체 내 암호화 기능(보안 USB) 적용이 일부 일반 USB 사용 승인으로 대체되고 있습니까?"], "partialEnd": "예외 승인 절차를 엄격화하고 일반 USB 사용 금지 및 보안 USB 사용 의무화를 지시하며 매체 대장 업데이트 단축을 권고합니다.", "rootcause": ["DLP/매체제어 솔루션이 에이전트 미설치 또는 정책 오설정으로 인해 미인가 이동식 매체 접속을 차단하지 못하고 있습니까?", "매체 등록 절차 없이 임의의 개인 USB를 업무에 자유롭게 사용하는 문화가 방치되어 있습니까?"], "rootcauseEnd": "중대 결함으로 확정하고 미인가 매체 전면 차단 정책 즉시 적용, 보안 USB 전수 조사 및 위반자 경위서 제출을 조치 요구합니다.", "na": ["전사 모든 PC/서버의 USB 포트가 물리적으로 봉인(Port Lock)되어 있고 솔루션으로 완벽 차단되어 이동식 매체 제도가 존재하지 않는 경우입니까?"], "naEnd": "물리적/기술적 전면 차단으로 이동식 매체 자체를 아예 사용하지 않음을 보드/기술 설정으로 입증하는 경우 N/A 판정을 검토합니다."}, "04-5": {"decisionQ": "불용 HW, 저장매체 폐기 시 데이터 완전 삭제(디가우징, 덮어쓰기, 천공/물리파괴)가 수행되고 있으며, 삭제/폐기 확인서 발급 및 외부 업체 통제가 엄격히 이루어지고 있습니까?", "verify": ["최근 1년 이내 진행된 HW/저장매체 폐기 관련 '자산 폐기 신청 결재 문서'를 화면에 조회해 주시겠습니까?", "해당 폐기건에 대한 데이터 삭제 확인서(소프트웨어 완전삭제 전용도구 리포트, 디가우징/천공 작업 사진 및 로그) 원본을 보여주시겠습니까?", "외부 전문 폐기 업체를 이용한 경우, 보안 준수 기획서, 비밀유지계약서(NDA), 폐기 작업 시 담당자 현장 참관 확인서를 보여주실 수 있습니까?", "자산 관리 대장에 폐기된 자산의 상태가 '폐기'로 변경되고 폐기 일자/증빙 번호가 매핑되어 있는지 보여주실 수 있습니까?"], "verifyEnd": "폐기 결재, 완전 삭제 증빙(디가우징/천공 로그 및 사진), 외부 업체 NDA 및 담당자 참관 확인서, 자산대장 처리 상태가 완벽히 일치하면 양호로 확정합니다.", "partial": ["데이터 완전삭제(디가우징/천공)는 수행되었으나 관련 작업 사진이나 상세 삭제 로그 수록이 누락된 확인서만 존재하는 경우입니까?", "외부 업체 폐기 시 담당자가 현장에 참관하지 않고 업체가 제출한 파쇄 완료 확인서만 수령하고 있습니까?", "자산대장 상 폐기 처리가 실시간이 아닌 수개월 후 일괄 반영되는 등 반영 시차가 발생합니까?"], "partialEnd": "외부 업체 폐기 시 입회 참관을 의무화하도록 절차 개선을 지시하고, 폐기 증빙 보고서에 삭제 구체 로그/사진 첨부를 표준화하도록 요구합니다.", "rootcause": ["저장매체 폐기 시 단순 포맷만 수행하거나 데이터 완전 삭제 절차 없이 고물상/외부 업체에 무단 매각/폐기한 사실이 있습니까?", "데이터 완전삭제 장비(디가우저/천공기) 관리 미흡 또는 검증 불가능한 소프트웨어 로직을 사용하여 완전 파괴를 입증하지 못합니까?"], "rootcauseEnd": "상(High) 위험 결함으로 확정하고, 정보유출 위험에 대한 긴급 조사, 저장매체 폐기 통제지침 수립 및 입회·삭제 검증 체계 전면 재수립을 이행 요구합니다.", "na": ["설립 이후 지금까지 단 한 건의 HW 및 저장매체 폐기/교체 실적이 전혀 없는 신설 기관이거나 완전히 모든 인프라를 대여/임차 서비스 형태로만 이용하여 자체 폐기 매체가 없는 경우입니까?"], "naEnd": "실제로 폐기 대상 자산이 발생하지 않았음이 자산 도입 연식 및 현황으로 입증되는 경우에 한해 N/A를 검토하며, 폐기 절차 정의서 유무는 별도 점검합니다."}, "04-6": {"decisionQ": "SW 라이선스 보유 현황과 실제 PC/서버 상의 설치 수량이 정확히 관리되고 있으며, 자동화 도구를 통한 불법 SW 점검 및 오픈소스 라이선스 관리가 이루어지고 있습니까?", "verify": ["소프트웨어 구매 계약서/라이선스 증서 기준 보유 수량 대장을 조회해 주시겠습니까?", "SW 자동 관리 솔루션(또는 중앙 점검 도구) 콘솔에서 실제 설치된 SW 수량과 보유 라이선스 수량 간의 비교 분석 리포트를 즉시 출력해 보여주시겠습니까?", "감사역이 임의로 지정한 특정 상용 SW 2종(예: MS Office, 한글, Adobe 등)의 라이선스 보유 수량과 현재 인스톨 수량을 현장에서 직접 대조해 주시겠습니까?", "가장 최근에 실시한 전사 불법 상용 SW 점검 결과 보고서 및 미인가 SW 삭제 조치 내역을 조회해 보여줄 수 있습니까?", "기관 내에서 사용 중인 주요 오픈소스 SW 목록과 해당 라이선스 유형(GPL, Apache, MIT 등) 관리 대장을 보여주실 수 있습니까?"], "verifyEnd": "보유 라이선스 수량 대비 설치 수량이 100% 이내이고, 자동화 도구를 통한 정기 불법 SW 점검 및 조치 이력이 있으며, 오픈소스 라이선스 유형 관리가 입증되면 양호로 확정합니다.", "partial": ["전체 라이선스 수량은 준수되나, 부서 간 라이선스 수량 할당 및 수동 대장 관리가 부실하여 일부 단말에서 초과 설치로 오인될 여지가 있습니까?", "상용 SW 점검은 정기적으로 시행하나, 개발 부서의 오픈소스 라이선스 유형 및 보안 취약점 관리가 대장에 누락되어 있습니까?", "자동화 중앙 관리 도구 없이 사용자 자율 점검 방식에 주로 의존하고 있습니까?"], "partialEnd": "오픈소스 라이선스 관리 절차 신설 및 중앙 수량 통제 솔루션 보완을 지시하며 수동 관리 대장의 정밀 업데이트를 요구합니다.", "rootcause": ["보유 라이선스 수량을 초과하여 불법 상용 소프트웨어를 전사적으로 무단 설치·사용하고 있습니까?", "SW 구매 모니터링이 전혀 이루어지지 않고 직원이 임의로 인터넷에서 불법 프로그램/오픈소스를 다운로드하여 운영 업무에 사용하는 것을 방치하고 있습니까?"], "rootcauseEnd": "결함으로 확정하고 불법 SW 즉시 삭제 및 모니터링 강제 조치, 정품 라이선스 추가 확보 및 오픈소스 관리 지침 수립을 요구합니다.", "na": ["모든 단말이 중앙 VDI(가상 데스크톱)로 통제되고 인터넷이 완전 차단되어 중앙에서 배포된 정품 SW 외에는 설치가 구조적으로 전면 불가능한 환경입니까?"], "naEnd": "VDI 통제 환경이라 할지라도 서버용 라이선스 및 DB, 미들웨어, 오픈소스 라이선스 관리 책임이 존재하므로 N/A 적용은 불가능합니다."}, "05-1": {"decisionQ": "핵심 IT·보안 인력 채용 시 신원조회 및 보안서약서 징구가 규정대로 이행되고 있음을 관련 시스템 및 증적을 통해 바로 확인해 주시겠습니까?", "verify": ["채용 절차서 상 핵심 IT·보안 인력에 대한 신원조회 필수 실시 조항을 보여주시겠습니까?", "최근 1년 이내 입사한 IT·보안 인력 명단 중 감사역이 무작위 지정한 2명에 대한 '신원조회 결과 보고서' 결재 문서와 '입사 시 보안서약서' 원본(또는 전자결재본)을 화면으로 조회해 주시겠습니까?", "만약 신원조회를 거부하거나 결과에 결격 사유가 발생한 경우, 채용을 제한하는 세부 절차와 실제 적용 사례가 있습니까?"], "verifyEnd": "채용 규정 내 신원조회 명시, 무작위 추출 입사자의 신원조회 보고서 및 보안서약서 결재 증적이 모두 확인되고 거부 시 채용제한 절차가 타당하면 양호로 확정합니다.", "partial": ["입사 시 보안서약서는 전원 징구하나, 신원조회가 일부 인원에게 누락되거나 입사 후 뒤늦게 진행된 이유는 무엇입니까?", "신원조회 거부 시 채용을 통제할 수 있는 구체적인 가이드라인이나 결재 통제 절차가 미비한 상태입니까?", "미비한 부분에 대한 개선 조치가 진행 중이며 언제까지 보완이 완료될 예정입니까?"], "partialEnd": "신원조회 누락 또는 입사 후 지연 징구 등 부분 미흡 사항을 특정하여 채용 절차서 개정 및 소급 점검 개선계획을 요청합니다.", "rootcause": ["핵심 IT·보안 인력 채용 시 신원조회가 전혀 실시되지 않거나 규정상 근거가 없는 이유는 무엇입니까?", "인사 부서와 IT/정보보호 부서 간 채용 시 보안 검증 협조 체계가 구축되어 있지 않습니까?", "이러한 보안 검증 부재 상태를 경영진에게 보고하거나 문제제기한 적이 있습니까?"], "rootcauseEnd": "채용 전 보안 검증 체계 미비로 결함 확정하며, 신원조회 및 서약서 징구 의무화 절차 수립을 위한 서면 개선계획을 요구합니다.", "na": ["최근 1~2년간 신규 채용된 IT 및 정보보호 인력이 단 한 명도 없는 상태입니까?", "향후 IT 인력 채용 발생 시 적용할 채용 전 보안 검증 절차 표준안은 마련되어 있습니까?"], "naEnd": "해당 기간 내 IT/보안 인력 채용 이력이 없음이 인사발령 대장 등으로 입증되면 해당없음 처리합니다."}, "05-2": {"decisionQ": "전 임직원 대상 연간 정보보호 교육 계획에 따른 이수율 관리 및 신규 입사자 교육이 제대로 이행되고 있습니까?", "verify": ["올해 승인받은 '연간 정보보호 교육 계획서' 결재문서와 현재 기준 임직원 교육 이수 현황표를 조회해 주시겠습니까?", "교육 미이수자에 대한 재교육 독려 공문이나 인사상 불이익 조치 내역이 시스템에 남아 있습니까?", "최근 3개월 내 입사한 신규 입사자 2명을 무작위 지정할 테니, 입사 직후 진행된 정보보호 교육 이수증 또는 LMS 기록을 보여주시겠습니까?", "올해 진행된 교육 교재에 최신 신종 피싱, 딥페이크 등 최신 보안 위협 사례가 반영되어 있습니까?"], "verifyEnd": "연간 계획 수립, 전 임직원 high-level 이수율(또는 미이수자 조치), 신규 입사자 입사 직후 교육 기록 및 최신 교재 내용이 모두 증빙되면 양호로 확정합니다.", "partial": ["정기 교육은 실시했으나 신규 입사자에 대한 입사 직후 교육이 수개월 누락된 후 분기별로 모아서 실시되는 이유는 무엇입니까?", "교육 이수율이 목표치에 미달함에도 미이수자에 대한 후속 조치(재교육, 경고 등)가 이루어지지 않은 이유는 무엇입니까?"], "partialEnd": "신규 입사자 즉시 교육 체계 누락 및 미이수자 관리 미흡에 대한 개선계획 수립을 요구합니다.", "rootcause": ["연간 정보보호 교육 계획 자체가 수립되지 않거나 전 임직원 대상 교육이 실시되지 않은 원인은 무엇입니까?", "교육 실시 후 이수 명단이나 결과 보고서를 관리하지 않는 이유는 무엇입니까?"], "rootcauseEnd": "보안 교육 의무 불이행으로 결함 확정하고, 전 임직원 보수 교육 실시 및 이수 관리 절차 마련을 촉구합니다.", "na": ["전체 임직원이 존재함에도 보안 교육 적용 대상에서 제외되는 특수 예외 부서나 인력이 있습니까?"], "naEnd": "법령 및 ISMS-P 상 전 임직원 필수 항목이므로 원칙적으로 N/A는 불가하며 예외 인정되지 않습니다."}, "05-3": {"decisionQ": "개인정보보호법에 따른 개인정보 취급자 지정 현황 및 이들에 대한 연 1회 이상 보호 교육, 수탁사 교육 점검이 이루어지고 있습니까?", "verify": ["개인정보 처리시스템(고객정보 DB 등) 권한 보유자 기반으로 작성된 '개인정보 취급자 지정 목록'을 시스템에서 조회해 주시겠습니까?", "해당 취급자 명단과 '개인정보 보호 교육 이수 명단'을 대조하여 100% 이수 여부를 확인해 주시겠습니까?", "개인정보 처리 위탁 계약을 체결한 주요 수탁사(콜센터, IT 외주사 등) 직원 대상 교육 이수 확인서 또는 점검 결과 보고서를 제출해 주시겠습니까?"], "verifyEnd": "개인정보 취급자 지정 목록의 정확성, 취급자 전원 교육 이수 증적, 수탁사 교육 점검 증빙이 모두 확인되면 양호로 확정합니다.", "partial": ["자사 개인정보 취급자 교육은 완료되었으나 외주 수탁사 취급자에 대한 교육 실시 여부 확인 및 증적 수집이 누락된 이유는 무엇입니까?", "개인정보 취급자 목록 업데이트가 주기적으로 이루어지지 않아 퇴직자나 부서 이동자가 취급자 교육 대상에 섞여 있는 이유는 무엇입니까?"], "partialEnd": "수탁사 교육 관리 절차 수립 및 취급자 명단 실시간 연동/정리 조치를 요청합니다.", "rootcause": ["개인정보 취급자 지정을 별도로 관리하지 않거나 일반 정보보호 교육으로 퉁치고 법정 개인정보 보호 교육을 별도 이수하지 않은 원인은 무엇입니까?", "개인정보보호법 제28조 관련 관리적 보호조치 의무 이행에 대한 담당자 인식 부족이 원인입니까?"], "rootcauseEnd": "개인정보보호법 위반 위험(과태료 대상)이 존재하므로 결함 확정 및 즉시 개인정보 취급자 전수 교육 실시를 요구합니다.", "na": ["당 저축은행 내에 개인정보를 취급하는 업무나 개인정보 처리시스템 자체가 전혀 존재하지 않습니까?"], "naEnd": "저축은행 특성상 고객 개인정보 처리가 필수적이므로 N/A는 타당하지 않으며 수용 불가합니다."}, "05-4": {"decisionQ": "보안 규정 위반자에 대한 징계 절차서가 수립되어 있으며, 실제 위반 발생 시 처분 및 재발방지 교육 활용이 이루어지고 있습니까?", "verify": ["정보보호 위반 행위 유형별 징계 양정 기준이 포함된 '보안 징계 절차서(또는 인사 징계 규정)'를 보여주시겠습니까?", "최근 1~2년간 발생한 '보안 위반 사례 이력 대장'과 해당 건에 대한 인사위원회 결재문서(또는 처분서)를 조회해 주시겠습니까?", "보안 위반 행위 분석을 통해 작성된 '재발방지 예방 공문'이나 전사 공유된 '위반 사례 보안 교육 자료'를 시스템에서 보여주시겠습니까?"], "verifyEnd": "징계 절차서의 단계별 명시, 실제 위반 건에 대한 규정대로의 처분 증적, 위반 사례의 교육 및 예방 조치 활용이 확인되면 양호 확정합니다.", "partial": ["보안 위반자에 대해 구두 경고 등 비공식 처분만 내리고 '보안 위반 사례 이력 대장'에 공식 등록하여 관리하지 않은 이유는 무엇입니까?", "위반 건에 대한 징계는 이루어졌으나, 해당 사례를 무명화하여 전사 교육 자료나 예방 공문으로 재활용하는 절차가 누락된 이유는 무엇입니까?"], "partialEnd": "위반 이력의 공식 대장 관리 및 재발방지 교육 연계 절차 보완을 요청합니다.", "rootcause": ["보안 규정을 명백히 위반한 사례가 있었음에도 징계 절차를 전혀 가동하지 않고 묵인한 경위는 무엇입니까?", "보안 위반 처분 기준 자체가 규정에 모호하게 되어 있어 실효성 있는 제재가 불가능한 상황입니까?"], "rootcauseEnd": "보안 의무 위반 처리 통제 무력화로 결함 확정하며, 보안 징계 양정 기준 신설 및 엄정한 위반 처리 체계 재정비를 요구합니다.", "na": ["최근 3년간 당 저축은행에서 보안 규정 위반 행위가 단 한 건도 발생하지 않은 상태입니까?", "위반 발생 건이 없더라도, 위반 발생 시 적용할 징계 절차와 예방 교육 체계는 준비되어 있습니까?"], "naEnd": "위반 사례 발생 건수가 0건인 경우 '위반 사례 처리' 증적은 N/A 가능하나, '징계 절차서' 및 '예방 교육 체계'는 반드시 평가하여 양호/미흡을 판정합니다."}, "05-5": {"decisionQ": "퇴직 발생 시 당일 계정/권한 즉시 회수, 자산 반납 및 퇴직 후 비밀유지 서약서 징구가 철저히 통제되고 있습니까?", "verify": ["최근 3개월 내 퇴직자 2명을 무작위 지정할 테니, 인사 시스템의 퇴직 처리 일시와 AD/코어뱅킹/DB 등 주요 시스템의 계정 잠금·삭제 로그 일시를 대조해 보여주시겠습니까?", "해당 퇴직자의 '퇴직 처리 체크리스트' 및 노트북, 보안카드 등 IT 자산 반납 확인서를 보여주시겠습니까?", "퇴직 당일 징구된 '퇴직 후 비밀유지 서약서' 결재 스캔본을 시스템에서 조회해 주시겠습니까?"], "verifyEnd": "퇴직 당일 계정 및 권한 즉시 삭제/잠금 확인, 자산 반납 확인서 완비, 퇴직 후 비밀유지 서약서 징구가 검증되면 양호 확정합니다.", "partial": ["자산 반납과 서약서 징구는 당일 완료되었으나, IT 계정 및 권한 회수가 퇴직 후 수일(예: 주말 포함 3~4일) 지연되어 처리된 이유는 무엇입니까?", "인사 부서의 퇴직 통보가 IT 보안 부서로 즉시 전달되지 않는 시스템적 한계가 있습니까?"], "partialEnd": "계정 회수 지연 위험에 대해 인사-IT 간 자동 연동 통제 구축 및 즉시 권한 회수 프로세스 개선을 요구합니다.", "rootcause": ["퇴직자의 계정이 퇴직 후에도 수개월간 살아있거나 실제 접근 이력이 발견된 원인은 무엇입니까?", "퇴직 처리 체크리스트 절차 자체가 없거나, 퇴직 후 비밀유지 서약서를 징구하지 않는 이유는 무엇입니까?"], "rootcauseEnd": "퇴직자 권한 관리 치명적 결함으로 확정하고, 미회수 계정 즉시 차단 및 퇴직자 보안 통제 절차 재설계를 요구합니다.", "na": ["점검 대상 기간 동안 퇴직자가 단 한 명도 발생하지 않았습니까?"], "naEnd": "인사발령 대장 상 퇴직 이력이 전혀 없음이 입증된 경우 해당없음 처리하되, 퇴직 통제 절차서 보유 여부는 확인합니다."}, "05-6": {"decisionQ": "부서 이동 등 인사이동 발생 시 이전 직무 권한의 회수와 신규 직무 최소 권한 부여가 정해진 기한 내 처리되고 정기 점검이 수행됩니까?", "verify": ["인사이동 시 IT/보안 부서로 전달되는 자동 알림 프로세스 및 권한 변경 처리 기한(예: 3일 이내) 규정을 보여주시겠습니까?", "최근 인사이동자 중 감사역이 지정한 2명의 '권한 변경 신청서(결재건)'와 실제 IAM/권한관리 시스템의 '이전 권한 회수 및 신규 권한 부여 로그'를 대조해 주시겠습니까?", "분기별로 실시한 '권한 정기 점검 결과 보고서' 및 불필요 권한 잔존자 적발/회수 조치 내역을 보여주시겠습니까?"], "verifyEnd": "인사이동 처리 기한 준수, 이전 직무 권한 삭제 및 신규 최소권한 부여 로그 일치, 정기 점검 이력이 검증되면 양호 확정합니다.", "partial": ["신규 부서 권한은 즉시 부여되었으나 이전 부서 권한 회수가 인사이동 후 수주 간 누락되어 겸직 상태로 권한이 유지된 이유는 무엇입니까?", "분기별 권한 정기 점검은 실시하나, 점검 결과 적발된 불필요 권한에 대한 회수 조치가 지연되는 이유는 무엇입니까?"], "partialEnd": "이전 권한 즉시 자동 회수 로직 구현 및 정기 점검 후속 조치 강화를 조치 요구합니다.", "rootcause": ["인사이동 후에도 이전 부서 권한을 삭제하지 않고 계속 누적하여 부여하는 관행이 존재하는 원인은 무엇입니까?", "권한 변경에 대한 결재 절차 없이 구두 요청 등으로 권한이 변경되고 있습니까?"], "rootcauseEnd": "권한 관리 및 최소 권한 부여 원칙 위반으로 결함 확정하며, 과다 권한 전수 조사 및 회수를 명합니다.", "na": ["점검 대상 기간 동안 부서 간 인사이동 사례가 전혀 발생하지 않았습니까?"], "naEnd": "인사발령 대장 상 부서 이동자가 없음이 입증되면 해당없음 처리하되, 권한 변경 통제 절차 및 정기점검 이력은 확인합니다."}, "05-7": {"decisionQ": "신규 입사자 및 외부 용역업체 인력 전체에 대해 법적 조치 조항이 포함된 비밀유지 서약서(NDA)가 적시에 징구되고 원본이 안전하게 보관되고 있습니까?", "verify": ["신규 입사자 및 외부 용역 계약 체결 시 사용하는 '비밀유지 서약서(NDA) 표준 양식'에 위반 시 손해배상 등 법적 조치 조항이 포함되어 있는지 보여주시겠습니까?", "현재 상주 중인 외부 용역업체 직원 명단과 이들의 'NDA 징구 현황 대장'을 조회해 주시겠습니까?", "감사역이 지정한 외부 용역 직원 2명의 NDA 원본(또는 공인전자문서) 보관 상태를 확인해 주시겠습니까?"], "verifyEnd": "NDA 표준 양식 내 법적 조치 문구 명시, 용역 인력 전원 NDA 징구 대장 관리, 원본/전자문서 안전 보관이 확인되면 양호 확정합니다.", "partial": ["신규 입사자 NDA는 완비되었으나, 외부 용역업체 인력의 경우 투입 일자보다 수주일 늦게 NDA가 징구된 이유는 무엇입니까?", "NDA 서약서는 받았으나 스캔본만 존재하고 원본 문서 보관 위치나 전자서명 관리 이력이 불투명한 이유는 무엇입니까?"], "partialEnd": "용역 인력 투입 전 NDA 징구 의무화 통제 및 NDA 원본 관리 체계 보완을 요청합니다.", "rootcause": ["외부 용역업체 계약 시 NDA를 별도로 징구하지 않거나, 일부 인원에 대해 NDA가 완전히 누락된 원인은 무엇입니까?", "NDA 미징구에 대한 정보보호 부서의 검증 절차(Gatekeeping)가 부재한 상태입니까?"], "rootcauseEnd": "비밀유지 서약 통제 미비로 결함 확정하며, 미징구 인력 전체 대상 NDA 즉시 징구 및 외주 보안 통제 절차 수립을 요구합니다.", "na": ["신규 입사자가 없고, 외주 용역업체 직원이나 외부 개발 인력을 단 한 명도 활용하지 않는 상태입니까?"], "naEnd": "외부 용역 및 신규 입사가 전혀 없음이 입증된 경우 N/A 처리 가능하나, 표준 NDA 양식 보유 여부는 점검합니다."}, "01-1": {"decisionQ": "설문에서 CISO를 지정하고 금융감독원에 신고를 완료했으며, CISO가 법정 자격요건을 충족한다고 응답하셨습니다. 관련 서류를 지금 함께 확인해 주실 수 있습니까?", "verify": ["CISO 임명장 또는 인사발령서 원본(또는 스캔본)을 보여주시겠습니까?", "금융감독원에 제출한 CISO 신고 접수확인증을 조회해 보여주시겠습니까? 접수일자와 임명일자가 일치합니까?", "CISO의 이력서와 경력증명서를 함께 보여주시겠습니까? 전자금융감독규정상 요구하는 경력·학력 요건을 충족하는지 지금 대조해 보겠습니다.", "최근 CISO 명의로 작성된 보고서나 지시사항 문서를 하나 보여주시겠습니까?"], "verifyEnd": "임명 서류·신고 접수증·자격요건·실적 문서가 모두 확인되고 상호 일자·내용이 일치하면 양호로 확정합니다.", "partial": ["임명은 되어 있으나 금감원 신고가 지연되었거나, 신고는 됐으나 자격요건 일부만 충족하는 등 어느 부분이 미흡한지 구체적으로 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이 상태가 얼마나 지속되었습니까? 전년도 감사나 금감원 검사에서도 지적된 사항입니까?", "완전한 요건 충족을 위한 조치 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분(신고 지연 또는 자격요건 미충족 등)을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["CISO가 지정되지 않았거나 신고가 이루어지지 않은 이유는 무엇입니까?", "현재 CISO 역할을 실질적으로 수행하는 사람이 있습니까? 있다면 그 사람의 자격과 직위는 무엇입니까?", "이 상태를 언제부터 인지하고 계셨습니까? 경영진에게 보고되었습니까?", "즉시 취할 임시조치와 CISO 지정·신고를 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, CISO 지정·신고 완료 계획서와 조치기한을 서면으로 요청합니다. 01-2(CIO 역할)·01-3(CIO·CISO 겸직 통제)과 연계되므로 해당 항목 응답도 함께 재확인합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: 법령상 CISO 지정 의무 적용 제외 규모에 해당)", "귀사가 CISO 지정 의무 적용 기준(자산총액 등)에 해당하지 않는다는 근거 자료를 보여주시겠습니까?", "조직 규모가 확대되어 의무 적용 대상이 될 경우 이를 인지하고 대응할 절차가 있습니까?"], "naEnd": "적용 제외 근거가 명확하면 확인을 종료하고, 규모 변경 시 재점검이 필요함을 안내합니다."}, "01-2": {"decisionQ": "설문에서 CIO가 지정되어 있고 IT 의사결정 권한이 문서화되어 있으며, 이사회·경영진 보고체계도 갖춰져 있다고 응답하셨습니다. 이를 문서로 바로 확인해 주실 수 있습니까?", "verify": ["CIO 직무기술서를 보여주시겠습니까? IT 의사결정 권한 범위가 구체적으로 명시되어 있습니까?", "이사회·경영진 IT 보고체계도를 보여주시겠습니까? CIO가 어떤 경로로 누구에게 보고하는지 확인하겠습니다.", "최근 IT운영위원회(또는 유사 회의체) 회의록을 하나 보여주시겠습니까? CIO가 실제로 주재하거나 참석해 의사결정한 내역이 있습니까?", "CIO 부재 시 업무를 대행할 사람이 지정되어 있습니까? 관련 규정이나 지정 문서를 보여주시겠습니까?"], "verifyEnd": "직무기술서·보고체계도·회의록·대행자 지정 문서가 모두 확인되고 실제 운영 내역과 일치하면 양호로 확정합니다.", "partial": ["직무기술서는 있으나 권한 범위가 모호하거나, 보고체계는 있으나 실제 운영되지 않는 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이 상태가 이전 점검에서도 지적된 적이 있습니까?", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["CIO가 지정되지 않았거나 권한이 문서화되어 있지 않은 이유는 무엇입니까?", "현재 IT 관련 의사결정은 누가, 어떤 절차로 하고 있습니까?", "이 상태를 언제부터 인지하고 계셨습니까? 스스로 발견한 것입니까, 외부 지적으로 알게 된 것입니까?", "즉시 취할 임시조치와 CIO 역할·권한 정립을 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다. 01-3(CIO·CISO 겸직 통제)과 직접 연계되므로 함께 재확인합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "조직 규모상 별도 CIO 지정이 필요 없다고 보신다면, IT 의사결정이 이루어지는 대체 체계는 무엇입니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 조직 확대 시 재점검이 필요함을 안내합니다."}, "01-3": {"decisionQ": "설문에서 CIO와 CISO를 1인이 겸직하고 있으며, 이해충돌 방지를 위한 보완 통제(상호검토·위원회승인)를 운영하고 있다고 응답하셨습니다. 이를 문서와 실제 운영 실적으로 확인해 주실 수 있습니까?", "verify": ["조직도와 인사발령서를 보여주시겠습니까? CIO·CISO 겸직 사실이 공식적으로 확인됩니까?", "이해충돌 방지 보완 통제 절차서를 보여주시겠습니까? 구체적으로 어떤 상호검토·승인 절차가 규정되어 있습니까?", "정보보호위원회 회의록 중 보완 통제 안건이 논의된 최근 사례를 보여주시겠습니까? 실제로 이중승인이나 위원회 검토가 이루어졌습니까?", "감독기관 검사에서 이 겸직 관련 이슈가 제기된 적이 있습니까? 있다면 그 결과 공문을 보여주시겠습니까?"], "verifyEnd": "겸직 사실 확인·보완 통제 절차서·실제 이행 실적·감독기관 이슈 이력이 모두 확인되고 서로 일치하면 양호로 확정합니다.", "partial": ["겸직 사실은 확인되나 보완 통제 절차서가 미비하거나, 절차서는 있으나 실제 이행 실적이 부족한 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이 상태가 이전 점검에서도 지적된 적이 있습니까? 반복 지적이라면 실질적 개선 의지 부재로 볼 수 있습니다.", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["겸직 상태에서 보완 통제가 전혀 운영되지 않고 있는 이유는 무엇입니까?", "현재 CIO·CISO 겸직자의 의사결정에 대한 견제 장치는 실질적으로 무엇이 있습니까?", "이 상태를 언제부터 인지하고 계셨습니까? 경영진 또는 이사회에 보고되었습니까?", "즉시 취할 임시조치(예: 특정 업무에 대한 임시 위원회 승인 등)와 근본적인 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다. 01-1(CISO 지정)·01-2(CIO 역할)와 정확히 맞닿아 있는 사안이니 함께 재확인합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: CIO·CISO가 별도 인원으로 지정되어 겸직 자체가 없음)", "향후 조직 개편으로 겸직이 발생할 가능성이 있습니까? 있다면 사전 대비된 보완 통제 방안이 있습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "겸직이 없음이 확인되면 확인을 종료하고, 향후 겸직 발생 시 보완 통제 체계 마련이 필요함을 안내합니다."}, "01-4": {"decisionQ": "설문에서 정보보호위원회를 연간 계획대로 개최하고, 안건과 의결사항을 관리하며 후속조치까지 추적하고 있다고 응답하셨습니다. 이를 회의록과 이행 자료로 확인해 주실 수 있습니까?", "verify": ["올해 정보보호위원회 연간 개최 계획서와 실제 회의록을 함께 보여주시겠습니까? 계획 대비 실제 개최 횟수가 일치합니까?", "최근 회의의 안건목록을 보여주시겠습니까? 정보보호 핵심 이슈(예: 주요 사고, 규정 개정, 예산)가 포함되어 있습니까?", "의결사항 이행 현황 추적 자료를 보여주시겠습니까? 지난 회의에서 의결된 사항이 실제로 이행되었는지 확인하겠습니다.", "위원 명단과 위촉장을 보여주시겠습니까? IT·보안·경영진이 고루 포함되어 있습니까?"], "verifyEnd": "개최 계획 대비 실적·안건 적정성·의결사항 이행·위원 구성이 모두 확인되면 양호로 확정합니다.", "partial": ["개최 횟수는 충족되나 안건이 형식적이거나, 의결사항 이행 추적이 일부만 되는 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이전 점검에서도 같은 부분이 지적된 적이 있습니까?", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["연간 계획 대비 개최 횟수가 크게 미달하거나 위원회가 사실상 운영되지 않는 이유는 무엇입니까?", "정보보호 관련 중요 의사결정은 현재 어떤 경로로 이루어지고 있습니까?", "이 상태를 언제부터 인지하고 계셨습니까?", "즉시 취할 임시조치와 위원회 정상화를 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "정보보호위원회를 별도로 두지 않는다면, 관련 의사결정은 어떤 대체 기구에서 이루어집니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "대체 체계가 타당하면 확인을 종료하고, 조직 변화 시 재점검이 필요함을 안내합니다."}, "01-5": {"decisionQ": "설문에서 연간 IT 예산을 계획대로 수립하고, 정보보호 예산을 별도 편성하여 집행하고 있다고 응답하셨습니다. 이를 예산 문서로 확인해 주실 수 있습니까?", "verify": ["연간 IT 예산 계획서를 보여주시겠습니까? 수립 시기가 회계연도 시작 전 적절한 시점이었습니까?", "정보보호 예산 세부 내역을 보여주시겠습니까? 전체 IT 예산 대비 비율이 얼마입니까?", "예산 집행 실적 보고서를 보여주시겠습니까? 계획 대비 달성률은 얼마입니까?", "미집행 예산이 있다면 그 사유와 이월 여부를 설명해 주시겠습니까? 이사회·경영진 승인 서류도 함께 보여주시겠습니까?"], "verifyEnd": "예산 계획서·정보보호 예산 비율·집행 실적·미집행 사유가 모두 확인되고 승인 절차도 적정하면 양호로 확정합니다.", "partial": ["예산 계획은 수립되었으나 정보보호 예산이 별도 구분되지 않거나, 집행률이 현저히 낮은 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이전 점검에서도 지적된 사항입니까?", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["IT 예산 계획 자체가 수립되지 않거나 정보보호 예산이 전혀 구분되지 않는 이유는 무엇입니까?", "현재 IT·보안 관련 지출은 어떤 절차로 승인·집행되고 있습니까?", "이 상태를 언제부터 인지하고 계셨습니까?", "즉시 취할 임시조치와 예산 체계 정립을 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "별도의 IT 예산 편성 체계가 없다면, IT 관련 지출은 어떻게 통제되고 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "대체 통제 체계가 타당하면 확인을 종료하고, 규모 확대 시 재점검이 필요함을 안내합니다."}, "01-6": {"decisionQ": "설문에서 전담 정보보호 인력이 법정 최소 기준을 충족하고, 필수 자격증과 교육 이수도 완료되어 있다고 응답하셨습니다. 이를 인력 현황 자료로 확인해 주실 수 있습니까?", "verify": ["정보보호 인력 현황표(성명·직급·담당업무)를 보여주시겠습니까?", "전자금융감독규정상 최소 인력 기준과 대조했을 때 현재 인원이 충족됩니까? 함께 계산해 보겠습니다.", "필수 자격증(정보보안기사·CISA·CISSP 등) 사본을 보여주시겠습니까? 유효기간이 남아있습니까?", "정보보호 교육·훈련 이수 확인서를 보여주시겠습니까? 전 인력이 최근 1년 내 이수했습니까?"], "verifyEnd": "인력 현황표·최소 기준 충족·자격증 유효성·교육 이수 이력이 모두 확인되면 양호로 확정합니다.", "partial": ["인력 수는 충족되나 자격증 유효기간이 만료됐거나, 일부 인력만 교육을 이수하는 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이전 점검에서도 지적된 사항입니까?", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["전담 인력이 최소 기준에 미달하는 이유는 무엇입니까?", "현재 부족한 인력으로 어떻게 정보보호 업무를 수행하고 있습니까? 겸직이나 외주 의존도는 어느 정도입니까?", "이 상태를 언제부터 인지하고 계셨습니까? 경영진에게 인력 충원을 요청한 적이 있습니까?", "즉시 취할 임시조치와 인력 충원을 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 인력 충원 계획서와 조치기한을 서면으로 요청합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "조직 규모상 별도 최소 인력 기준 적용을 받지 않는다면, 그 근거 규정을 보여주시겠습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "적용 제외 근거가 타당하면 확인을 종료하고, 규모 확대 시 재점검이 필요함을 안내합니다."}, "01-7": {"decisionQ": "설문에서 IT 조직도가 최신 상태로 관리되고, 주요 직위별 직무기술서가 작성·배포되어 R&R이 명확하다고 응답하셨습니다. 이를 문서로 확인해 주실 수 있습니까?", "verify": ["IT 조직도 최신본과 개정 이력을 보여주시겠습니까? 최근 조직 변경 사항이 반영되어 있습니까?", "주요 직위별 직무기술서를 보여주시겠습니까? 실제 배포되어 담당자가 인지하고 있습니까?", "업무분장표를 보여주시겠습니까? 직무 간 중복되거나 공백이 있는 부분은 없습니까?", "핵심 직위(예: DB관리자, 보안담당자)의 후임자가 지정되어 있습니까? 관련 문서를 보여주시겠습니까?"], "verifyEnd": "조직도 최신화·직무기술서 배포·R&R 명확성·후임자 지정이 모두 확인되면 양호로 확정합니다.", "partial": ["조직도는 최신이나 직무기술서 배포가 일부 누락되거나, R&R에 일부 공백이 있는 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이전 점검에서도 지적된 사항입니까?", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["조직도가 오래 갱신되지 않았거나 직무기술서 자체가 없는 이유는 무엇입니까?", "현재 직무 간 R&R은 실제로 어떻게 구분되어 운영되고 있습니까? 구두 관행에 의존하고 있습니까?", "이 상태를 언제부터 인지하고 계셨습니까?", "즉시 취할 임시조치와 조직도·직무기술서 정비를 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "조직 규모상 별도 직무기술서 체계가 필요 없다고 보신다면, R&R은 어떻게 관리되고 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "대체 관리 체계가 타당하면 확인을 종료하고, 조직 확대 시 재점검이 필요함을 안내합니다."}, "01-8": {"decisionQ": "설문에서 CISO→경영진→이사회로 이어지는 보고 체계가 정의되어 있고, 정기 보고와 긴급 보고가 모두 실제로 이행되고 있다고 응답하셨습니다. 이를 문서와 실적으로 확인해 주실 수 있습니까?", "verify": ["경영진 보고 절차서를 보여주시겠습니까? 보고 주기와 양식이 구체적으로 정의되어 있습니까?", "최근 이사회·경영진 보안 보고서를 보여주시겠습니까? 보고 수신 확인(메일 또는 서명)도 함께 확인하겠습니다.", "최근 1년 내 중요 보안사고가 있었다면, 그 즉시 보고 이력을 보여주시겠습니까? 사고 발생 시점과 보고 시점의 간격을 확인하겠습니다.", "보고가 누락되거나 지연된 사례가 있었습니까? 있었다면 그 경위를 설명해 주시겠습니까?"], "verifyEnd": "보고 절차서·정기 보고 실적·긴급 보고 이력·보고 누락 여부가 모두 확인되고 보고 체계가 실제로 작동하고 있으면 양호로 확정합니다.", "partial": ["보고 절차서는 있으나 수신 확인이 되지 않거나, 긴급 보고가 일부 지연된 등 어느 부분이 미흡한지 짚어 주시겠습니까?", "그 미흡한 부분이 발생한 경위는 무엇입니까?", "이전 점검에서도 지적된 사항입니까?", "완전한 이행을 위한 개선 계획과 시한은 무엇입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 재확인합니다.", "rootcause": ["보고 체계가 문서화되어 있지 않거나 실제로 보고가 이루어지지 않는 이유는 무엇입니까?", "최근 보안 관련 중요 사안이 경영진·이사회에 실제로 전달된 사례가 있습니까?", "이 상태를 언제부터 인지하고 계셨습니까?", "즉시 취할 임시조치와 보고 체계 정립을 위한 구체적 일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다. 01-2(CIO 역할)·01-4(정보보호위원회 운영)와 연계되므로 함께 재확인합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까?", "별도의 공식 보고 체계 없이도 경영진이 보안 현황을 파악하는 대체 경로가 있습니까?", "이 판단을 마지막으로 재확인한 시점은 언제입니까?"], "naEnd": "대체 경로가 타당하면 확인을 종료하고, 조직 변화 시 재점검이 필요함을 안내합니다."}, "25-1": {"decisionQ": "설문에서 외주인력의 원장 변경·암호화정보 해독 권한이 없고, 이용자 금융정보도 무단 보관하지 않는다고 응답하셨습니다. 이를 로그·검사 이력으로 바로 확인해 주실 수 있습니까?", "verify": ["외주인력 계정 기준 DBSAFER 쿼리 발송 내역을 함께 조회해 주시겠습니까? (최근 6개월)", "그 목록에서 감사역이 이 자리에서 무작위로 2개 계정을 지정할 테니, 해당 계정의 전체 쿼리 이력을 다른 화면(감사역 요청 계정 기준)으로 다시 조회해 보여주시겠습니까?", "외주인력 보유 PC에 대한 DLP 검사에서 금융정보 보유 이력이 있었습니까?", "예외적으로 원장 조회·변경이 필요했던 사례가 있었다면, 그 승인 절차를 설명해 주시겠습니까?"], "verifyEnd": "제시된 로그·검사 이력이 응답과 일치하고, 감사역이 임의로 지정한 계정을 다시 조회했을 때도 같은 결과가 나오며, 예외 승인 절차도 확인되면 양호로 확정합니다. 담당자가 먼저 제시한 자료와 감사역 지정 계정의 결과가 다르면(예: 미리 준비된 요약본과 실제 원장 조회 결과 불일치), 그 자체를 미흡 사유로 봅니다.", "rootcause": ["그렇다면 현재 외주인력의 DB 접근 권한은 어느 수준까지 부여되어 있습니까?", "원장 변경 권한이 부여된 경위와 시점을 설명해 주시겠습니까?", "이 상태를 언제부터 인지하고 계셨습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "지금 즉시 취할 수 있는 임시 조치와, 권한 회수를 포함한 근본적인 개선 계획·일정은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 개선계획서와 조치기한을 서면으로 요청합니다. D-09-3(DB 직접접속 통제)·D-06-5(상주 외주개발자 통제)와 정확히 맞닿아 있는 사안이니, 그쪽 항목의 응답도 함께 재확인하는 것이 좋습니다.", "partial": ["원장 변경 금지, 금융정보 무단보관 금지 두 가지 중 어느 부분은 지켜지고 어느 부분은 미흡한지 구분해 주시겠습니까?", "부분적으로만 지켜지고 있는 이유는 무엇입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "완전한 이행을 위해 언제까지 어떤 조치를 취하실 계획입니까?"], "partialEnd": "미흡한 부분을 특정하여 개선계획을 요청하고, 다음 점검에서 완전 이행 여부를 재확인합니다.", "na": ["이 항목을 '해당없음'으로 판단하신 근거는 무엇입니까? (예: 외주인력에게 DB 접근 권한 자체가 부여되지 않음)", "향후 외주인력에게 관련 권한이 부여될 가능성이 있습니까? 있다면 사전 통제 방안이 준비되어 있습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "해당없음 판단이 타당하면 확인을 종료하고, 향후 권한 부여 시 재점검이 필요함을 안내합니다."}, "25-2": {"decisionQ": "접근매체 보안대책, 서비스 중단 대비 비상대책, 소스코드를 포함한 백업체계가 모두 수립·운영되고 있다고 응답하셨습니다. 최근 실제 발동·점검 사례를 보여주실 수 있습니까?", "verify": ["최근 접근매체 위·변조 관련 보안대책이 실제로 작동한 사례(탐지·차단 로그)가 있습니까?", "외부주문 업체 도산 등 비상상황을 가정한 매뉴얼을 마지막으로 검토·갱신한 시점은 언제입니까?", "형상관리시스템 외 소스코드 백업·소산이 실제로 정기 수행되고 있음을 백업 이력으로 확인해 주시겠습니까?", "백업이 '존재'하는 것과 '복원 가능'한 것은 다릅니다 — 감사역이 지정하는 임의의 백업본 하나를 지금 실제로 복원(또는 무결성 검증)해서 보여주실 수 있습니까?"], "verifyEnd": "실사례·최신 갱신 이력·백업 로그가 모두 확인되고, 감사역이 지정한 백업본의 실제 복원·검증까지 성공하면 양호로 확정합니다. 백업 파일은 존재하지만 복원 테스트를 한 번도 해본 적이 없다면, 그 자체를 잠재적 결함으로 기록합니다.", "rootcause": ["세 가지(보안대책/비상대책/백업체계) 중 실제로 미흡한 부분은 구체적으로 무엇입니까?", "소스코드 백업·소산이 누락된 이유는 무엇이며, 언제부터 이런 상태였습니까?", "비상대책 매뉴얼이 최신화되지 않은 경우, 마지막 개정 이후 조직·계약 변경 사항이 반영되지 않은 리스크는 무엇입니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "개선을 위한 담당자 지정 및 완료 목표일은 언제입니까?"], "rootcauseEnd": "결함으로 확정하고, 특히 소스코드 소산 미흡은 위험도 '상' 사안으로 상향하여 별도 보고합니다. D-11-5(형상관리)·D-12-4(백업 복원테스트)와 함께 짚으면 원인을 더 명확히 볼 수 있습니다.", "partial": ["보안대책·비상대책·백업체계 세 가지 중 구체적으로 어느 것이 미흡합니까?", "가장 시급한 보완이 필요한 영역은 무엇이며, 왜 그렇게 판단하십니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "우선순위와 조치 일정을 말씀해 주시겠습니까?"], "partialEnd": "미흡 영역을 특정하고, 위험도가 높은 영역(특히 소스코드 백업)부터 우선 개선을 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: 외부주문 계약 자체가 없거나 소스코드를 다루지 않음)", "현재 운영 중인 외부주문 계약이 실제로 이 항목과 무관한 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "해당없음 판단의 근거가 명확하면 종료하고, 그렇지 않다면 재분류합니다."}, "25-3": {"decisionQ": "외부주문 개발·운영에 대한 내부통제방안이 문서화되어 있고, 자체 보안성검토·정기 보안점검도 실제 수행되고 있다고 응답하셨습니다. 최근 점검 결과를 확인해 주실 수 있습니까?", "verify": ["가장 최근 정기 보안점검 실시 보고서를 함께 보여주실 수 있습니까?", "가장 최근 것 말고, 1년 전(또는 그 이전) 점검 보고서도 함께 보여주시겠습니까? 최근 것만이 아니라 점검이 실제로 '정기적으로' 이루어져 왔는지 확인하기 위함입니다.", "그 점검에서 지적된 사항이 있었다면 어떻게 조치되었습니까?", "내부통제 가이드 문서가 현재 조직·계약 구조와 실제로 일치합니까?"], "verifyEnd": "최근 점검 실적뿐 아니라 과거 점검 이력도 일정한 주기로 존재하고, 지적사항 조치 이력이 확인되면 양호로 확정합니다. 최근 것만 있고 과거 이력이 없다면(최근에 급조된 정황), 미흡 경로로 전환합니다.", "rootcause": ["정기 보안점검이 실제로는 어느 주기로, 언제 마지막에 수행되었습니까?", "내부통제 가이드가 문서화되지 않았다면, 현재 외부주문 통제는 어떤 기준으로 이루어지고 있습니까?", "점검 미실시의 원인은 인력 부족입니까, 절차 미비입니까, 아니면 인지하지 못하고 있었습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "향후 점검 주기와 첫 점검 실시 예정일을 말씀해 주시겠습니까?"], "rootcauseEnd": "결함으로 확정하고, 재발방지 차원에서 점검 주기를 규정화하도록 권고합니다. D-03-4(내부 정보보호 감사)와 같은 원리이니, 그 항목의 감사 독립성·주기 이행 현황과 비교해 보는 것도 좋습니다.", "partial": ["내부통제방안과 자체 보안점검 중 어느 쪽이 미흡합니까?", "부분적으로만 이루어지고 있는 원인은 인력 부족입니까, 절차 미비입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "보완 계획과 일정은 어떻게 되십니까?"], "partialEnd": "미흡 원인을 특정하고 보완 계획의 실행 가능성을 확인합니다.", "na": ["이 항목을 해당없음으로 판단하신 근거는 무엇입니까?", "외부주문이 전혀 없어 통제 대상 자체가 없는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "외부주문이 실제로 없음이 확인되면 종료합니다."}, "25-4": {"decisionQ": "전자금융보조업자의 재무건전성·서비스품질(SLA)을 연 1회 이상 평가하고 금감원에 보고하고 있다고 응답하셨습니다. 최근 평가·보고 자료를 확인해 주실 수 있습니까?", "verify": ["가장 최근 재무건전성 평가 결과와 결재문서를 보여주실 수 있습니까?", "외부주문 업체가 둘 이상이라면, 감사역이 임의로 지정하는 서로 다른 두 업체의 평가서를 나란히 비교해 보여주시겠습니까? 평가 항목별 실제 점수·코멘트가 업체마다 실질적으로 다른지 확인하기 위함입니다(양식만 다르고 내용이 판박이인 형식적 평가 여부 확인).", "SLA 평가 기준과 최근 평가 결과는 어떠했습니까?", "기준 미달로 평가된 업체가 있었다면 사후관리는 어떻게 이루어졌습니까?"], "verifyEnd": "평가·보고 자료가 모두 존재하고, 업체별 평가 내용이 실질적으로 차별화되어 있으며, 기준 미달 업체에 대한 사후관리도 확인되면 양호로 확정합니다. 여러 업체의 평가서 코멘트가 문구까지 거의 동일하다면 형식적 평가로 의심하고 미흡 경로로 전환합니다.", "rootcause": ["평가가 이루어지지 않았거나 지연된 이유는 무엇입니까?", "금융감독원장 보고 대상임을 인지하고 계셨습니까?", "기준 미달 계약이 있다면 지금까지 어떤 조치도 없었던 이유는 무엇입니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "향후 평가·보고 일정을 어떻게 재정비하실 계획입니까?"], "rootcauseEnd": "결함으로 확정하고, 금감원 보고 누락 여부는 별도로 확인하여 심각도를 재평가합니다. D-06-3(수탁사 선정·정기 재평가)과 평가 주기·방식이 같은 축이니 함께 짚으면 좋습니다.", "partial": ["재무건전성 평가와 SLA 평가 중 어느 쪽이 미흡하거나 지연되고 있습니까?", "부분적으로만 수행된 이유는 무엇입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "남은 평가를 언제까지 완료하실 계획입니까?"], "partialEnd": "미완료 평가 항목을 특정하고 완료 기한을 확인합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: 전자금융보조업자에 해당하는 계약이 없음)", "현재 외부주문 업체들이 전자금융보조업자 정의에 해당하지 않는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "적용대상 자체가 없음이 확인되면 종료합니다."}, "25-5": {"decisionQ": "재위탁은 사전 동의 없이 이루어지지 않고, 업무수행인력에 대한 신원조회·인수인계 관리방안도 운영되고 있다고 응답하셨습니다. 관련 증적을 확인해 주실 수 있습니까?", "verify": ["최근 재위탁이 발생한 사례가 있었다면, 사전 동의 및 계약서 반영 절차를 보여주시겠습니까?", "재위탁 사례가 '없었다'고 하셨다면, 이를 어떻게 확인할 수 있습니까? 현재 투입된 인력 전원이 원 계약업체 소속임을 인사기록·사원증·건강보험 자격득실 확인서 등으로 교차 확인해 주실 수 있습니까? (재위탁 여부를 담당자 진술이 아닌 제3의 자료로 검증)", "신원보증서 또는 신원조회 결과를 징구한 이력이 있습니까?", "외주인력 교체 시 인수인계가 실제로 어떻게 이루어졌는지 최근 사례로 설명해 주시겠습니까?"], "verifyEnd": "재위탁 동의 이력(또는 재위탁이 없다는 사실을 뒷받침하는 제3의 자료)과 신원조회·인수인계 증적이 확인되면 양호로 확정합니다. '재위탁 없음'이라는 진술뿐 소속을 뒷받침할 자료를 제시하지 못하면 미흡 경로로 전환합니다.", "rootcause": ["재위탁이 사전 동의 없이 이루어진 사례가 있었습니까? 있었다면 언제, 어떤 경위였습니까?", "신원조회나 신원보증서 징구가 이루어지지 않은 인력이 있습니까?", "인수인계 없이 인력이 교체된 사례가 있었다면 어떤 문제가 발생했거나 발생할 수 있었습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "재발 방지를 위해 계약서·업무 절차에 어떤 통제를 추가하실 계획입니까?"], "rootcauseEnd": "결함으로 확정하고, 재위탁 미승인 건은 금감원 제재 사례와 유사한 고위험 사안으로 상향 보고합니다. D-06-8(재위탁 사전승인)과 동일한 통제이니, 두 항목의 응답이 서로 일치하는지도 대조해 보십시오.", "partial": ["재위탁 통제와 인력관리(신원조회·인수인계) 중 어느 부분이 미흡합니까?", "부분적으로만 관리되고 있는 이유는 무엇입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "보완 계획은 무엇입니까?"], "partialEnd": "미흡 영역을 특정하고, 재위탁 관련이면 위험도를 상향하여 별도 확인합니다.", "na": ["이 항목을 해당없음으로 판단하신 근거는 무엇입니까? (예: 재위탁 발생 이력이 전혀 없음)", "현재 계약 구조상 재위탁이 원천적으로 불가능한 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "재위탁 가능성 자체가 없음이 확인되면 종료합니다."}, "25-6": {"decisionQ": "이용자 정보 조회·출력 통제 및 테스트 시 이용자 정보 사용금지 원칙이 매일 실제로 지켜지고 있다고 응답하셨습니다. 이를 로그로 확인해 주실 수 있습니까?", "verify": ["이용자 정보 조회·출력 로그(사용자·일시·방법 기록)를 최근 며칠 치 보여주실 수 있습니까?", "부하 테스트 등에서 이용자 정보를 사용해야 했던 최근 사례가 있다면, 변환·삭제 처리 내역을 확인해 주시겠습니까?", "이 매일 점검이 실제로 '매일' 수행되고 있음을 증빙(월 단위가 아닌)으로 보여주실 수 있습니까?", "그 점검 로그가 사후에 수정되지 않았다는 것을 어떻게 보증할 수 있습니까? (예: 로그 자체에 대한 접근권한 통제, 수정이력 관리 여부)"], "verifyEnd": "일자별 점검 증적이 실제로 매일 존재하고, 그 로그 자체가 임의 수정될 수 없는 방식으로 보호되고 있으면 양호로 확정합니다. 월 단위 결재만 존재하거나, 로그를 담당자가 직접 수정할 수 있는 구조라면(신뢰성 담보 안 됨) 미흡 경로로 전환합니다.", "rootcause": ["현재 점검이 매일이 아니라 어느 주기로 이루어지고 있습니까?", "테스트 데이터에 실제 이용자 정보를 그대로 사용한 사례가 있습니까?", "이 문제를 인지하고도 개선하지 않은 이유가 있습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "매일 점검 체계로 전환하기 위한 구체적인 계획(자동화 여부 포함)은 무엇입니까?"], "rootcauseEnd": "결함으로 확정합니다. 전자금융감독규정시행세칙상 '매일' 수행 의무 위반 가능성이 있어 위험도를 '상'으로 조정합니다. D-11-8(테스트 데이터 비식별화)·D-09-4(개인정보처리시스템 접근통제)와 겹치는 사안이니 그쪽 응답과 대조해 보면 실제 이행 여부를 더 정확히 판단할 수 있습니다.", "partial": ["이용자정보 조회통제와 테스트 데이터 사용금지 중 어느 쪽이 부분적으로만 지켜지고 있습니까?", "매일 점검이 일부 항목만 이루어지고 있다면, 어떤 항목이 누락됩니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "전체 항목을 매일 점검 체계로 전환할 계획은 무엇입니까?"], "partialEnd": "부분 이행 항목을 특정하고, 매일 점검 의무 규정에 따라 조속한 전면 이행을 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: IT개발팀이 이용자 정보 조회 권한 자체가 없음)", "실제로 개발 업무에서 이용자 정보에 접근할 필요가 전혀 없는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "접근 자체가 없음이 확인되면 종료하되, 향후 업무 범위 변경 시 재점검을 안내합니다."}, "25-7": {"decisionQ": "운영시스템 접속통제, 인터넷·USB 등 매체 통제, 전산실 출입기록, 백신 최신화 등 시스템·매체·출입 통제가 매일 점검되고 있다고 응답하셨습니다. 실제 점검 기록을 확인해 주실 수 있습니까?", "verify": ["전산실 출입자 관리기록부를 최근 기간으로 보여주실 수 있습니까?", "감사역이 임의로 지정하는 특정 날짜(예: 지난달 중 하루) 하루치 출입기록을 그 자리에서 다시 뽑아 보여주시겠습니까? 그 날 출입한 외주인력과 실제 근태·작업 내역이 서로 맞는지 함께 확인해 주십시오.", "USB 등 보조기억매체 통제 설정 화면과 최근 위반 시도 차단 이력이 있습니까?", "백신·운영체제가 실제로 최신 상태로 유지되고 있음을 확인할 수 있습니까?"], "verifyEnd": "출입기록·매체통제·패치현황이 모두 최신이고, 감사역이 임의로 지정한 날짜의 기록도 즉시 제시되며 실제 근태와 부합하면 양호로 확정합니다. 특정 날짜를 요청했을 때 시간이 오래 걸리거나 내용이 어긋나면 기록의 신뢰성 자체를 의심하고 미흡 경로로 전환합니다.", "rootcause": ["여러 항목 중 실제로 누락되거나 형식적으로만 수행되고 있는 항목은 무엇입니까?", "전산자료·장비 반출입 통제가 미흡하다면, 그 원인은 통제장치 부재입니까 절차 미준수입니까?", "이 상태가 얼마나 지속되었습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "우선순위를 정해 어떤 항목부터 언제까지 개선하실 계획입니까?"], "rootcauseEnd": "미흡 항목별로 개선 담당자와 기한을 확인하여 결함으로 확정합니다. D-07-1(전산실 출입통제)·D-13-6(EDR 단말 설치) 각각의 항목에서 외주인력 단말·출입이 빠짐없이 포함되어 있는지 함께 확인하십시오.", "partial": ["여러 통제 항목(접속통제·매체통제·출입기록·백신 등) 중 구체적으로 어느 항목이 부분적으로만 지켜지고 있습니까?", "일부만 점검되고 나머지는 누락되는 이유는 무엇입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "전체 항목을 매일 점검 체계로 통합할 계획은 무엇입니까?"], "partialEnd": "부분 이행 항목을 특정하여 우선순위를 정하고, 매일 점검 체계로의 통합을 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까?", "외주인력이 전산실 출입이나 매체 반출입 자체를 하지 않는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "해당 통제 대상 자체가 없음이 확인되면 종료합니다."}, "25-8": {"decisionQ": "용역 참여인원의 보안서약서 징구, 수행 전 보안교육, 수행 중 보안점검이 모두 이루어지고 있다고 응답하셨습니다. 증빙을 확인해 주실 수 있습니까?", "verify": ["현재 투입된 외주인력 전원의 자필서명 보안서약서를 확인할 수 있습니까?", "지금 말씀하신 투입 인원수를, 서약서 매수가 아니라 독립적인 다른 자료(예: 최근 1개월 전산실 출입기록에 찍힌 서로 다른 외주인력 수, 또는 발급된 시스템 계정 수)와 대조했을 때도 정확히 일치합니까?", "수행 전 보안교육 자료와 참석자 서명부를 보여주시겠습니까?", "수행 중 보안점검에서 실제로 지적된 사례와 조치 내역이 있습니까?"], "verifyEnd": "서약서·교육·점검 이력이 인원별로 빠짐없이 확인되고, 서약서 인원수가 출입기록·계정 수 등 독립 자료와도 일치하면 양호로 확정합니다. 서약서상 인원과 실제 출입·계정 인원이 다르면(미신고 투입 인력 의심) 미흡 경로로 전환합니다.", "rootcause": ["서약서나 교육 이력이 없는 인력이 있습니까? 몇 명이며 언제부터 투입되었습니까?", "보안교육이 형식적으로만 이루어진다면, 실제 내용 이해도를 어떻게 확인하고 계십니까?", "이 공백을 인지하고 계셨습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "신규·기존 인력 모두에 대한 소급 조치 계획은 무엇입니까?"], "rootcauseEnd": "결함으로 확정하고, 서약서 미징구 인력에 대해 즉시 징구를 요구합니다. D-06-5(상주 외주개발자 보안서약서)와 대상 인력이 겹치니, 두 항목의 인력 명단이 서로 일치하는지 대조해 보십시오.", "partial": ["보안서약서·교육·점검 중 어느 것이 일부 인력에게만 적용되고 있습니까?", "몇 명의 인력이 누락되어 있으며, 언제 투입된 인력입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "누락된 인력에 대한 소급 조치 일정은 무엇입니까?"], "partialEnd": "누락 인원을 특정하고 즉시 소급 조치(서약서 징구·교육)를 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: 현재 투입된 외주인력이 전혀 없음)", "정말 현재 시점에 참여 중인 용역인력이 없는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "인력 투입이 없음이 확인되면 종료하고, 향후 투입 시 사전 절차 이행을 안내합니다."}, "25-9": {"decisionQ": "용역 관련 자료·산출물이 자료관리대장을 통해 관리되고, 지정된 서버·PC에만 저장되며, 웹하드·개인메일 사용이 금지되고 있다고 응답하셨습니다. 이를 확인해 주실 수 있습니까?", "verify": ["최근 자료관리대장 기록과 인계자·인수자 서명을 보여주시겠습니까?", "담당자가 골라서 보여주시는 것 외에, 최근 3개월 메일 발송함에서 용역업체 담당자 이메일 주소로 '자료', '파일', 'zip' 등 키워드 전수 검색을 지금 함께 실행해서 그 결과를 그대로 보여주시겠습니까? (미리 준비된 사례가 아니라 실시간 전수 검색으로 확인)", "유출금지 대상 자료의 퇴근 시 시건장치 보관 여부를 현장에서 확인할 수 있습니까?"], "verifyEnd": "자료관리대장·시건장치 보관이 확인되고, 실시간 전수 메일 검색에서도 개인메일·비암호화 전송 사례가 나오지 않으면 양호로 확정합니다. 검색 결과 사전에 언급되지 않은 전송 사례가 발견되면, 그 자체로 미흡 경로로 전환하고 사안의 중대성을 재평가합니다.", "rootcause": ["자료관리대장이 작성되지 않거나 미흡한 부분은 무엇입니까?", "개인메일이나 웹하드로 자료가 오간 사례가 있습니까?", "시건장치 없이 자료가 방치된 사례를 인지하고 계셨습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "재발 방지를 위한 자료 관리 프로세스 개선 계획은 무엇입니까?"], "rootcauseEnd": "결함으로 확정합니다. 개인신용정보 포함 자료 유출 가능성이 있는 경우 위험도를 '상'으로 조정합니다. D-13-7(DLP)·D-04-4(이동식매체 통제)와 같은 유출경로를 다루는 항목이니 함께 확인하면 좋습니다.", "partial": ["자료관리대장, 저장위치 통제, 메일 통제, 시건장치 보관 중 어느 부분이 부분적으로만 지켜지고 있습니까?", "관리가 안 되는 자료의 범위는 어느 정도입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "전체 자료 관리 프로세스를 표준화할 계획은 무엇입니까?"], "partialEnd": "미흡 범위를 특정하고, 개인신용정보 포함 여부에 따라 위험도를 재평가합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까?", "현재 외부주문 업무에서 자료·산출물 이관 자체가 발생하지 않는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "자료 이관이 없음이 확인되면 종료합니다."}, "25-10": {"decisionQ": "용역 수행 공간에 대한 정기 보안점검, 외부 반입장비 악성코드·반출 확인, 비인가 휴대용 저장매체 통제가 이루어지고 있다고 응답하셨습니다. 실사로 확인 가능합니까?", "verify": ["용역 수행 공간을 지금 함께 둘러볼 수 있습니까? (시건장치·물리적 분리 확인)", "실사 중에, 사전에 말씀해주신 인원·장비 목록에 없는 인력이나 장비가 눈에 띄면 그 자리에서 바로 여쭤봐도 되겠습니까? (사전 안내되지 않은 항목을 실사 중 우연히 발견하는 것이 서류 점검보다 신뢰도가 높습니다)", "최근 노트북 등 반입장비의 악성코드 검사·반출 시 자료 확인 이력이 있습니까?", "휴대용 저장매체 사용이 필요했던 사례가 있다면, 승인 절차를 설명해 주시겠습니까?"], "verifyEnd": "현장 실사와 반입·반출 이력이 응답과 일치하고, 실사 중 사전 안내와 다른 인원·장비가 발견되지 않으면 양호로 확정합니다. 사전에 언급되지 않은 인력·장비가 현장에서 발견되면 그 자체를 미흡 사유로 기록합니다.", "rootcause": ["정기 보안점검이 실제로는 이루어지지 않았거나 형식적이었던 이유는 무엇입니까?", "승인 없이 사용된 휴대용 저장매체가 있었습니까?", "물리적 보안(시건장치, 공간 분리)의 공백을 인지하고 계셨습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "즉시 조치 가능한 부분과, 시설·정책 개선이 필요한 부분을 구분해 설명해 주시겠습니까?"], "rootcauseEnd": "결함으로 확정하고, 물리적 보안 공백은 즉시 시정을 요구합니다. D-07-5(장비 반출입 대장)·D-07-1(전산실 출입통제)와 같은 축이니 함께 짚으십시오.", "partial": ["공간 보안점검, 반입장비 검사, 저장매체 통제 중 어느 부분이 미흡합니까?", "정기점검이 일부만 이루어지는 이유는 무엇입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "보완 계획과 다음 점검 예정일은 언제입니까?"], "partialEnd": "미흡 항목을 특정하고 물리보안 공백에 대한 즉시 조치를 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: 용역 수행 전용 공간이 별도로 없음)", "외주인력이 당행 시설 내에서 전혀 작업하지 않는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "전용 작업 공간 자체가 없음이 확인되면 종료합니다."}, "25-11": {"decisionQ": "개발·운영시스템이 분리되어 있고, 용역업체는 필요한 서버에만 제한적으로 접근하며, 인터넷 연결·P2P·웹하드가 차단되어 있다고 응답하셨습니다. 설정 화면으로 확인해 주실 수 있습니까?", "verify": ["용역업체 계정의 서버별 접근권한 목록을 함께 확인해 주시겠습니까?", "그 목록이 신청서·결재 문서 기준이 아니라, 실제 서버·시스템(AD, DB 등)에서 지금 이 자리에서 직접 조회한 결과와 일치합니까? 신청 당시와 현재 실제 권한이 시간이 지나며 달라져 있는 경우가 많습니다.", "용역업체 PC의 인터넷 연결 차단(또는 통제된 예외 허용) 설정을 보여주시겠습니까?", "불필요해진 계정·권한이 즉시 해지되고 있음을 최근 이력으로 확인할 수 있습니까?"], "verifyEnd": "접근권한 범위·인터넷 통제·계정 해지 이력이 모두 확인되고, 신청서 기준 권한과 시스템상 실제 권한이 일치하면 양호로 확정합니다. 신청서보다 실제 권한 범위가 넓다면(권한 확대가 기록 없이 이루어진 정황) 미흡 경로로 전환합니다.", "rootcause": ["용역업체가 실제로 필요 이상의 서버·시스템에 접근 가능한 상태입니까?", "인터넷 연결이나 P2P·웹하드 접속이 차단되지 않은 사례가 있습니까?", "불필요한 계정·권한이 방치된 기간은 얼마나 됩니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "접근권한 재설계와 정기 점검 체계를 어떻게 구축하실 계획입니까?"], "rootcauseEnd": "결함으로 확정합니다. 과도한 접근권한은 개인신용정보 유출과 직결되므로 위험도 '상'으로 조정합니다. D-11-2(개발·운영 환경분리)·D-09-7(개발자 운영DB 접근차단)·D-08-8(권한 정기검토)과 정확히 같은 통제를 다루는 항목이니, 응답이 서로 일치하는지 꼭 대조하십시오.", "partial": ["환경분리, 접근권한, 인터넷 통제, 계정관리 중 어느 부분이 부분적으로만 지켜지고 있습니까?", "일부 예외가 승인 없이 존재하는 것은 아닙니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "전체 접근통제 체계를 재정비할 계획은 무엇입니까?"], "partialEnd": "미흡 영역을 특정하고, 개인신용정보 접근 가능성이 있는 경우 위험도를 상향합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까?", "외주인력이 내부망이나 시스템에 전혀 접속하지 않는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "접속 자체가 없음이 확인되면 종료합니다."}, "25-12": {"decisionQ": "완료 산출물의 대외비 관리·폐기, 제공 자료·장비의 전량 회수, 저장매체 완전삭제, 미보유 확약서 징구가 모두 이루어지고 있다고 응답하셨습니다. 최근 완료 사업 사례로 확인해 주실 수 있습니까?", "verify": ["최근 완료된 용역 건의 자료·장비 회수 확인서를 보여주시겠습니까?", "그 건 말고, 감사역이 완료 용역 목록에서 임의로 지정하는 다른 한 건(가급적 6개월 이상 지난 건)도 같은 방식으로 회수·삭제 증빙을 보여주시겠습니까?", "업체 소유 저장매체의 완전삭제(또는 물리파괴) 증빙이 있습니까?", "자료 미보유 확약서를 대표자 명의로 징구한 이력이 있습니까?"], "verifyEnd": "최근 건뿐 아니라 감사역이 임의로 지정한 과거 완료 건에서도 회수·삭제·확약서가 동일하게 확인되면 양호로 확정합니다. 최근 건만 잘 갖춰져 있고 과거 건은 미비하다면(최근 들어서야 절차를 갖춘 정황), 결함으로 봅니다.", "rootcause": ["최근 완료된 용역 중 회수·삭제·확약서 중 누락된 절차가 있습니까?", "업체가 자료 사본을 보유하고 있을 가능성을 배제할 수 있습니까?", "이 절차가 계약서나 내부 체크리스트에 명시되어 있지 않은 것은 아닙니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "향후 모든 완료 건에 대해 이 절차를 표준화할 계획이 있습니까?"], "rootcauseEnd": "결함으로 확정하고, 과거 완료 건에 대한 소급 확인을 권고합니다. D-04-5(하드웨어 폐기 시 데이터 완전삭제)와 같은 원리이니 함께 확인하면 좋습니다.", "partial": ["회수·삭제·확약서 중 어느 절차가 일부 완료 건에서만 이루어졌습니까?", "누락된 완료 건은 몇 건이며, 어떤 자료가 미회수 상태입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "소급 조치 계획은 무엇입니까?"], "partialEnd": "누락 건을 특정하고 즉시 소급 회수·삭제 조치를 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: 최근 완료된 외부주문 사업이 없음)", "점검기간 중 실제로 완료된 용역 사업이 전혀 없는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "완료 사업이 없음이 확인되면 종료합니다."}, "25-13": {"decisionQ": "개인(신용)정보 처리위탁 계약에 보안관리대책이 반영되어 있고, 비밀유지계약서 작성, 정보보안 방안 마련, 외부전송 사전승인이 모두 이루어지고 있다고 응답하셨습니다. 계약서로 확인해 주실 수 있습니까?", "verify": ["개인신용정보 보안관리대책이 반영된 계약서 조항을 보여주시겠습니까?", "계약서에 조항이 있다는 것과 실제로 그 조항대로 운영되는 것은 별개입니다 — 최근 실제로 개인신용정보가 외부로 전송된 로그(메일·파일전송시스템 등)를 계약서 조항과 대조해, 승인 절차가 실제로 지켜졌는지 확인해 주시겠습니까?", "비밀유지계약서가 사업수행 계약과 별도로 작성되어 있습니까?", "개인신용정보 외부 전송이 필요했던 사례가 있다면, 관리책임자 사전 승인 이력을 확인해 주시겠습니까?"], "verifyEnd": "계약서 조항·비밀유지계약·전송 승인 이력이 모두 확인되고, 실제 전송 로그를 대조했을 때도 계약서 조항대로 사전 승인이 지켜졌으면 양호로 확정합니다. 계약서 조항은 있지만 실제 전송 로그와 대조했을 때 승인 없이 전송된 사례가 나오면(계약서는 형식, 실제 운영과 괴리) 미흡 경로로 전환합니다.", "rootcause": ["계약서에 개인신용정보 보안관리대책이 반영되지 않은 이유는 무엇입니까?", "비밀유지계약서 없이 진행된 사업이 있습니까?", "사전 승인 없이 개인신용정보가 외부로 전송된 사례가 있습니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "기존 계약에 대한 소급 보완과, 향후 표준계약서 개정 계획은 무엇입니까?"], "rootcauseEnd": "결함으로 확정합니다. 신용정보업감독규정 위반 소지가 있어 위험도 '상' 사안으로 별도 보고합니다. D-06-2(외부자 계약 보안요건)·D-17-7(개인정보 처리위탁 계약)과 같은 계약서를 다루는 항목이니 조항이 서로 일치하는지 대조하십시오.", "partial": ["계약 반영, 비밀유지계약, 정보보안 방안, 전송승인 중 어느 부분이 미흡합니까?", "일부 계약에서만 누락된 것입니까, 전체 계약 양식의 문제입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "표준계약서 개정 및 소급 보완 계획은 무엇입니까?"], "partialEnd": "미흡 계약을 특정하고, 표준계약서 개정을 통한 재발방지를 권고합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까? (예: 개인신용정보 처리위탁에 해당하는 계약이 없음)", "현재 외부주문 중 개인신용정보를 다루는 계약이 전혀 없는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "개인신용정보 처리위탁 계약이 없음이 확인되면 종료합니다."}, "25-14": {"decisionQ": "위탁 산출물이 지정 서버·PC에만 저장되고, 용역업체 계정·비밀번호가 관리되며, 최종 산출물이 대외비 이상으로 관리·회수된다고 응답하셨습니다. 증빙을 확인해 주실 수 있습니까?", "verify": ["산출물 저장 위치와 접근권한을 함께 확인해 주시겠습니까?", "회수 이력 기록과는 별개로, 현재 시스템에 등록된 용역업체 관련 계정을 지금 전수 조회해 주시겠습니까? 이미 종료된 용역의 계정이 기록상 회수 처리되었음에도 시스템에는 여전히 활성 상태로 남아있는 경우가 실무에서 흔합니다.", "용역업체에 부여된 계정의 비밀번호 변경·권한 회수 이력이 있습니까?", "최종 산출물의 문서등급 분류와 회수 이력을 보여주시겠습니까?"], "verifyEnd": "저장위치·계정관리·회수 이력이 모두 확인되고, 전수 조회 결과 종료된 용역의 계정이 실제로 비활성 상태이면 양호로 확정합니다. 회수 처리 '기록'은 있지만 전수 조회에서 여전히 활성 상태인 계정이 발견되면(회수가 형식적으로만 이루어진 정황) 미흡 경로로 전환합니다.", "rootcause": ["산출물이 지정되지 않은 위치(개인메일·웹하드 등)에 저장된 사례가 있습니까?", "용역업체 계정의 비밀번호 변경이나 권한 회수가 누락된 사례가 있습니까?", "최종 산출물의 문서등급 관리 기준이 없다면, 현재 어떻게 대외보안 필요자료를 구분하고 계십니까?", "이 문제를 스스로 발견하신 겁니까, 아니면 외부 지적(감사·검사 등)이나 사고를 계기로 알게 되신 겁니까? 스스로 발견하셨다면 그 사실을 경영진 또는 상급자에게 실제로 보고하셨습니까?", "이 항목들에 대한 표준 절차를 마련할 계획이 있습니까?"], "rootcauseEnd": "결함으로 확정하고, 계정 미회수 사례는 즉시 조치를 요구합니다. D-08-2(퇴직·계약종료 시 계정 즉시 회수)와 동일한 통제이니, 외주업체 계약종료 건도 그 항목 기준으로 같이 확인하십시오.", "partial": ["산출물 저장위치, 계정관리, 문서등급 관리 중 어느 부분이 부분적으로만 지켜지고 있습니까?", "일부 계정만 회수되지 않은 것입니까, 관리 체계 자체가 없는 것입니까?", "이 부분적 이행 상태가 언제부터 지속되어 왔습니까? 지난 점검(또는 전년도 감사)에서도 같은 '부분 이행'으로 지적된 적이 있습니까? (같은 상태가 반복 지적되는 것이라면 실질적 개선 의지가 없는 것일 수 있습니다)", "전체 계정·산출물 관리 체계를 표준화할 계획은 무엇입니까?"], "partialEnd": "미흡 부분을 특정하고, 계정 미회수 건은 즉시 조치를 요청합니다.", "na": ["이 항목이 해당없음이라고 판단하신 근거는 무엇입니까?", "용역업체에 별도 시스템 계정이 발급된 적이 전혀 없는 것이 맞습니까?", "이 '해당없음' 판단을 마지막으로 재확인한 시점은 언제입니까? 조직 규모나 서비스 범위가 바뀌면 예외 대상에서 벗어날 수 있는데, 그런 변화가 있을 때 이 판단을 다시 검토하는 절차가 있습니까?"], "naEnd": "계정 발급 이력이 없음이 확인되면 종료합니다."}, "26-1": {"decisionQ": "당행의 서버 및 네트워크 장비 등 전산장비 패치 작업 시, 사전 영향도 분석과 테스트를 거쳐 작업 전 백업 및 사후 롤백 프로토콜이 정상적으로 실행되고 있습니까?", "verify": ["최근 6개월 이내에 발행된 정기 및 긴급 패치 모니터링 대장과 적시 전파 이력을 보여주시겠습니까?", "가장 최근에 수행한 OS 또는 DB 패치 작업의 '패치 영향도 분석서'와 '테스트 환경 검증 결과서'를 화면에 띄워주시겠습니까?", "해당 패치 작업 직전에 수행된 백업 이력을 백업솔루션 콘솔 화면에서 즉석조회해 보여주시겠습니까?", "패치 작업이 실패했을 경우를 대비한 긴급 롤백(Rollback) 절차서와 실제 과거 롤백 수행 기록이 존재합니까?", "ITO 수탁사(외주 업체)가 수행한 패치 작업에 대해 당행 내부 결재(ITSM)를 득한 승인 및 결과 검증 보고서 이력을 대조해 주시겠습니까?"], "verifyEnd": "공급사 공지 모니터링부터 영향도 분석, 테스트 검증, 사전 백업, 사후 결과 보고 및 ITO 수탁사 작업에 대한 당행 승인 이력의 정합성이 모두 현장 시연을 통해 확인되면 양호로 확정합니다.", "partial": ["패치 자체는 수행되고 있으나 사전 영향도 분석서가 누락되었거나 테스트 장비가 아닌 운영 장비에 바로 적용하는 예외가 빈번히 발생하는 이유는 무엇입니까?", "ITO 수탁사가 패치 작업을 수행한 후 당행에 통보만 하고, 당행 담당자의 사전 승인이나 사후 상호검증 절차가 일부 누락되는 상태가 지속되고 있습니까?", "패치 작업 전 수동 백업은 수행하나 실제 장애 발생 시 작동할 구체적인 롤백 시나리오가 문서화되어 있지 않은 상태입니까?"], "partialEnd": "패치 절차 중 일부 단계(테스트 부족, ITO 통제 미흡 등)의 보완이 요구되므로, 부분 이행으로 판정하고 개선계획 제출을 요구합니다.", "rootcause": ["패치 전 필수적으로 수행해야 하는 시스템 백업을 생략하거나, 공용 계정을 사용하여 작업 기록의 식별이 불가능한 원인은 무엇입니까?", "긴급 패치 적용 시 영향도 평가나 사후 검증 없이 즉시 운영계에 적용하도록 방치된 체계적인 원인이 인력 부족 때문입니까, 아니면 내부 절차 부재 때문입니까?", "ITO 위수탁 계약서상 패치 관련 통제 조항이 누락되어 있거나 실제 통제권을 위탁사에 전부 일임하고 모니터링을 전혀 하지 않는 상태를 언제부터 방치해 온 것입니까?"], "rootcauseEnd": "중대한 패치 관리 통제 공백으로 판단하여 결함으로 확정하고, 전자금융감독규정 제13조 및 제23조 위반 가능성에 따른 긴급 조치와 책임 추궁 절차를 진행합니다.", "na": ["전산장비 패치 관리체계 점검 항목이 당행 IT 환경에 적용되지 않는다고 판단하신 구체적인 근거는 무엇입니까?", "당행이 직접 관리하는 전산 인프라가 전혀 없고 모든 시스템이 클라우드 SaaS 형태로만 제공되어 인프라 수준의 패치 권한이 아예 차단되어 있는 구조입니까?"], "naEnd": "직접적인 인프라 관리 책임이 존재하지 않는 특수한 서비스 형태임이 계약서 및 아키텍처 상으로 입증되어 N/A 타당성이 확인되면 종료합니다."}, "26-2": {"decisionQ": "외부 노출 자산을 포함한 주요 전산자산에 대해 신규 도입 단계부터 정기 점검, 중요 취약점 적시 조치 및 미조치 취약점 대체통제가 체계적으로 관리되고 있습니까?", "verify": ["당행이 보유한 외부 노출 서버 목록이 명시된 최신 '전산자산 목록'과 현행화 날짜를 바로 보여주시겠습니까?", "최근 1년 이내에 도입된 신규 시스템 중 감사역이 지정하는 자산의 '도입 전 취약점 점검 결과서'와 승인서를 보여주시겠습니까?", "가장 최근 금보원(F-ISAC)에서 수신한 긴급 보안취약점 공지 메일과 관련하여 당행이 식별, 조치, 재검증 후 내부 보고한 전체 이력 대장을 열어주시겠습니까?", "올해 수행한 정기 취약점 점검 결과 보고서에서 발견된 취약점 중 미조치 상태로 남아 있는 건들에 대한 '위험수용 및 대체통제 승인서'가 구비되어 있는지 조회해 주시겠습니까?"], "verifyEnd": "자산 현행화, 신규 도입 시 사전 통제, 긴급 취약점 즉시 대응 및 정기 취약점 점검 결과상 미조치 건에 대한 공식 대체통제 승인서가 실시간 시연으로 모두 검증되면 양호로 판정합니다.", "partial": ["정기 취약점 점검은 매년 실시하고 있으나, 신규 시스템 도입 시 취약점 점검을 생략하고 운영계에 먼저 배포하는 우회 절차가 빈번합니까?", "발견된 취약점에 대해 조치는 수행하고 있으나, 조치 완료 후 재검증(재스캔)을 통한 실효성 판단 단계를 누락하고 구두 보고로만 종결하고 있습니까?", "미조치 취약점에 대해 위험수용 보고서는 존재하나 구체적인 대체통제(망분리, 접근제한 강화 등)의 기술적 적용이 실제 방화벽이나 시스템 설정 상에 미반영되어 있습니까?"], "partialEnd": "점검 절차는 존재하나 사전/사후 통제의 불완전 이행 및 재검증 미흡이 식별되어 개선요구(부분이행) 조치합니다.", "rootcause": ["외부로 노출된 중요 웹서버가 내부 전산자산 목록에서 누락되어 취약점 점검 대상에서 통째로 제외되어 있던 근본적인 원인은 무엇입니까?", "금보원 등의 긴급 조치 권고를 수신하고도 수개월간 조치 및 검증을 지연하거나 방치한 보안 담당자 및 관리자의 업무 소홀 원인은 무엇입니까?", "반복 발견되는 고위험 취약점이 예산 부족이나 경영진 무관심으로 인해 조치되지 않고 장기 미이행 상태로 방치되고 있는 환경적 제약이 존재합니까?"], "rootcauseEnd": "보안 통제의 핵심 영역인 취약점 관리의 심각한 미흡으로 결함 확정 처리하고, 전자금융감독규정 제37조의4에 의거하여 취약점 조치 프로세스의 재설계 및 경영진 경고 절차를 진행합니다.", "na": ["당행 환경에서 보안 취약점 점검을 직접 수행할 대상 자산이 존재하지 않는다고 판단한 상세 근거는 무엇입니까?", "모든 금융 인프라와 단말기를 그룹사 또는 외부 전문기관에서 100% 위탁 관리하여 당행 내부에는 스캔하거나 취약점을 조치할 자산 자체가 완전히 배제되어 있는 구조입니까?"], "naEnd": "내부 자산이 전무하고 조치 주체가 타 기관에 귀속되어 있음이 정합성 있게 증명될 경우 N/A 종결합니다."}, "26-3": {"decisionQ": "당행 전산장비 및 S/W 자산에 대한 제조사 기술지원 종료(EoS) 도래 일정을 선제적으로 파악하여 예산 반영, 교체 계획 수립 및 임시 대체통제를 적정하게 수행하고 있습니까?", "verify": ["자산별 제조사 공식 EoS(End of Support) 일자가 명시된 'EoS 일정 관리대장'의 최신 갱신 이력을 열어주시겠습니까?", "기술지원 종료가 6개월 이하로 임박한 장비들에 대해 담당 부서 및 담당자에게 자동 또는 정기 알림이 전송된 최근 발송 로그를 메일함이나 시스템상에서 확인해 주시겠습니까?", "EoS 대상 장비들의 실질적 교체를 위해 작성된 '장비 교체 계획서'와 관련 예산이 반영된 경영진(IT운영위원회 등) 보고 안건 문서를 제시해 주시겠습니까?", "교체가 불가능하여 EoS 상태로 유지 중인 불가피한 자산에 대해 망분리 및 접근권한 최소화 설정이 적용된 방화벽 룰 화면을 이 자리에서 조회해 주시겠습니까?"], "verifyEnd": "EoS 자산 현황 식별, 사전 경고 전파 체계, 경영진 보고/예산 편성 확인 및 유지 자산에 대한 철저한 격리 통제가 일관되게 확인되면 양호로 판정합니다.", "partial": ["EoS 일자는 목록화하여 관리하고 있으나, 예산 부족 등으로 인해 교체 일정이 지속 지연되고 있으며 이에 대한 한시적 대체통제(망분리 등)마저 수립되지 않은 상태입니까?", "임박 알림은 비정기적으로 담당자 메모 수준으로만 공유되고 있고, 공식적인 전사 교체 계획서나 예산 배정 프로세스에 연동되어 있지 않습니까?"], "partialEnd": "EoS 목록 및 식별은 정상이나, 실질적인 위험 경감 조치(대체통제)와 실제 예산 반영 등 교체 이행 프로세스의 속도가 미흡하여 개선을 권고합니다.", "rootcause": ["제조사 기술지원이 이미 종료된 운영 서버가 EoS 대장에서 완벽히 누락된 채 방치되고 있었던 원인은 자산 관리 시스템의 동기화 실패 때문입니까?", "EoS 장비 교체 지연에 대해 보안 위험성을 사전에 검토하거나 경영진에게 심각성을 보고하는 절차가 전무했던 의사결정 체계의 결함 원인은 무엇입니까?", "EoS 유지 자산에 대한 접근통제(ACL)를 전혀 설정하지 않고 일반 운영 장비와 동일한 네트워크 대역에 섞어두어 위협 확산 가능성을 방치한 기술적 원인은 무엇입니까?"], "rootcauseEnd": "보안 패치가 공급되지 않는 무방비 전산자산의 실질적 격리 및 관리 누락으로 결함 확정하고, 중대한 인프라 리스크로 분류하여 특별 대책 수립을 강제합니다.", "na": ["당행 인프라 내에 제조사 기술지원 일정(EoS)의 영향을 받는 하드웨어 및 상용 소프트웨어(S/W) 자산이 전혀 없는 상태입니까?", "자체 구축 장비 없이 완전히 표준화된 퍼블릭 클라우드 PaaS/SaaS 서비스만을 활용하여 공급사가 EoS 및 업그레이드 전권을 자동 처리하는 구조입니까?"], "naEnd": "당행 관리하의 물리/논리 인프라 자산이 전무하여 자산별 EoS 위험 관리 대상에서 제외됨이 명확히 고증되면 N/A 판정합니다."}, "26-4": {"decisionQ": "정보처리시스템 접속기록 항목의 완전성을 보장하고 있으며, 로그 서버가 물리·논리적으로 완전히 분리되어 관리자 단독 삭제 방지와 백업 이중화가 실행되고 있습니까?", "verify": ["핵심 정보처리시스템 중 임의 시스템 1개의 실시간 접속 로그 샘플을 출력하여, [접속계정, 일시, 단말 IP, 원격/콘솔 구분, 수행 행위] 항목이 모두 빈칸 없이 수집되고 있는지 확인해 주시겠습니까?", "로그 서버가 운영 서버망과 별도로 분리된 구성도와, 로그 삭제 기능 자체를 원천 차단한 권한 제어 설정 화면을 직접 보여주시겠습니까?", "로그 데이터의 위·변조 방지를 위해 적용된 무결성 검증 기법(해시값 대조 결과 등)의 최근 일일 검증 이력을 열어주시겠습니까?", "접속 로그의 이중 저장 저장소 현황과, 백업 스케줄러를 통해 이기종 스토리지로 원본 백업이 매일 수행되는 설정을 확인해 주시겠습니까?"], "verifyEnd": "로그 필수 항목의 완전 수집, 관리자 단독 로그 훼손 차단 장치 확인, 로그 무결성 일일 검증 작동 및 이중화 백업 콘솔 시연이 모두 완벽하면 양호로 처리합니다.", "partial": ["로그는 수집하고 있으나 필수 항목 중 일부(예: 원격/콘솔 접속 경로 구분 또는 수행 행위의 쿼리 원문 등)가 누락되어 식별이 불가한 항목이 존재합니까?", "로그 서버 분리는 되어 있으나 최고 관리자(root, Administrator) 계정을 공유 사용하여 관리자가 단독으로 본인의 접속 기록 로그를 삭제할 수 있는 여지가 남아 있습니까?", "로그 백업은 수행하나 무결성 검증(Hash 값 생성 및 비교) 절차가 자동화되어 있지 않고 매월 형식적으로 대조하는 수준에 머물러 있습니까?"], "partialEnd": "접속기록 수집 및 보존 프로세스가 완벽하지 않아 사후 추적이 제한되므로 부분이행으로 판정하고, 즉각적인 구성 변경을 지도합니다.", "rootcause": ["로그 서버 내 접속 기록을 관리자가 임의로 삭제할 수 있는 쓰기/삭제 권한이 통제되지 않고 완전 개방되어 있었던 설계 오류 원인은 무엇입니까?", "접속 로그 백업이 용량 부족 등의 이유로 수개월째 에러 상태로 정지되어 있었음에도 이를 아무도 체크하지 않은 백업 통제 누락 원인은 무엇입니까?", "주요 정보처리시스템 중 일부 신규 시스템이 통합로그관리시스템 수집 대상에서 누락되어 감시 체계 밖에 존재하게 된 근본적 사유는 무엇입니까?"], "rootcauseEnd": "로그 삭제 권한 미통제 및 유실 방치 등 심각한 추적성 상실로 결함 확정하고, 전자금융감독규정 제22조 및 제35조 위반으로 강력 조치 및 즉각 시정을 명령합니다.", "na": ["당행 내부에서 로그를 직접 수집, 보존해야 할 정보처리시스템을 전혀 운영하지 않고 있는 타당한 기술적 근거가 있습니까?", "모든 개인신용정보와 거래 처리가 완벽히 아웃소싱되거나 외부 에이전시 시스템에서 처리되며, 당행 직원들은 해당 시스템에 접속조차 하지 않는 독립된 환경입니까?"], "naEnd": "당행 정보처리 주체가 없어 로그 관리 의무 대상에서 법적으로 제외됨이 검증되면 N/A 처리합니다."}, "26-5": {"decisionQ": "인사이동, 퇴직 시 계정 권한이 즉시 회수되고 있으며, 장기 미사용 계정 잠금 및 특권계정에 대한 로그인 이중인증(2FA) 등 계정 생애주기 통제 정책이 실효성 있게 가동 중입니까?", "verify": ["최근 3개월 이내 퇴직 및 부서 이동 임직원 명단 중 감사역이 무작위 지정하는 3명에 대해, 인사 발령 당일 계정 권한이 즉시 회수 및 잠금 처리된 Active Directory/계정관리시스템 승인 로그를 확인해 주시겠습니까?", "현재 설정된 Active Directory의 '장기 미사용 계정 자동 잠금(예: 30일)' 정책 값 화면과 실제 잠금 처리된 휴면 계정 목록을 출력해 주시겠습니까?", "외주개발자 및 ITO 수탁사 인력의 계정 유효기간이 계약 기간에 연동되어 자동 만료되도록 설정된 계정 상세 속성창을 조회해 주시겠습니까?", "서버(OS) 및 데이터베이스(DBA) 특권계정 로그인 시, ID/PW 외에 추가적으로 적용된 이중인증(MFA/2FA) 솔루션 연동 화면과 실제 차단 룰을 이 자리에서 직접 보여주시겠습니까?"], "verifyEnd": "퇴사자 계정의 당일 완벽 회수, 장기 미사용 계정 잠금 처리, 외주 계약 연동 자동 만료제 시행 및 특권 계정 MFA 실제 구현이 검증되면 양호로 확정합니다.", "partial": ["퇴직자 계정은 즉시 회수되고 있으나, 부서 내부 이동자(인사이동)의 경우 과거 권한이 정리가 되지 않고 계속 누적되어 과다 권한을 보유하는 관행이 지속되고 있습니까?", "장기 미사용 계정을 잠금 처리하는 규정은 존재하나, 자동화 시스템 설정 없이 담당자가 매월 수동으로 파악하여 잠금 처리하는 과정에서 일부 지연이 발생하고 있습니까?", "특권계정의 일부 세션(예: 내부망 내 직접 접속)에 대해서는 편의상 2FA 적용이 예외 처리되어 일차적 인증만으로 통과되고 있습니까?"], "partialEnd": "권한 회수 지연 및 특권계정 이중인증 범위 제한 등 계정 라이프사이클 일부 단계에 보안 허점이 식별되어 부분이행 판정 및 개선을 권고합니다.", "rootcause": ["퇴사한 지 수개월이 경과한 외주인력의 AD 계정이 여전히 '활성화(Active)' 상태로 방치되어 있었던 프로세스적 원인은 인사부서와 IT부서 간 통보 누락 때문입니까?", "시스템 유지 보수 편의를 위해 만료일이 설정되지 않은 불법 임시 공용 계정을 임의 발급하여 장기간 방치한 내부 직무 방임의 원인은 무엇입니까?", "특권 계정에 대해 이중인증을 우회할 수 있는 백도어 또는 예외 IP 대역을 임의로 과다 허용해 둔 보안 정책 형상 관리의 실패 사유는 무엇입니까?"], "rootcauseEnd": "인가되지 않은 외부 유입 위험 및 계정 통제 관리 주권의 상실 상태로 보아 즉시 결함 확정하고, 책임자 문책 및 즉각 계정 정리를 강력히 명령합니다.", "na": ["당행은 사내 직원 및 외부 인력의 계정을 직접 생성, 제어, 관리하는 독립된 도메인 및 계정 디렉토리를 전혀 가동하지 않고 있습니까?", "모든 업무 인프라 계정 관리가 전적으로 상위 그룹사 AD에 완벽 종속되어 있으며 당행 전담 관리자는 계정 권한 핸들링 권한 자체가 존재하지 않는 환경입니까?"], "naEnd": "계정 발급 및 통제의 귀속 권한이 타 기관에 전적으로 묶여 있어 당행 측 관리 항목에서 배제됨이 고증되면 N/A 종결합니다."}, "26-6": {"decisionQ": "전산 자료 및 시스템 백업이 소산 지침에 따라 안전하게 물리·논리적으로 분리 보관되고 있으며, 랜섬웨어 방지 에어갭 구성 및 정기 복구 테스트(RTO·RPO 측정)를 실행하고 있습니까?", "verify": ["당행의 원장 데이터와 설정값, 로그가 빠짐없이 포함된 최신 '백업 수행 보고서 및 백업 대상 범위 명세서'를 보여주시겠습니까?", "소산 백업 매체(VTL/테이프 등)가 보관된 원격지의 물리 소산대장 및 내화금고 입고 현황, 그리고 망이 완전히 절연된 에어갭(Air-Gap) 소산 설정 화면을 이 자리에서 확인해 주시겠습니까?", "백업 데이터 자체의 무결성 손상 여부를 매일 점검하여 기록한 '백업 정합성 점검 결과서' 최근 일주일 분을 열어주시겠습니까?", "최근 1년 이내에 실제 운영 원장 백업 데이터를 가상 환경에 밀어 넣어 목표 RTO(복구목표시간)와 RPO(복구목표시점) 달성 여부를 정량 측정한 '정기 복구 테스트 결과 보고서'를 보여주시겠습니까?"], "verifyEnd": "소산 격리성 보장, 백업 정합성 자동 점검, 랜섬웨어 대비 오프라인 단절 백업 가동, 실질적 모의 복구 훈련을 통한 RTO/RPO 지표 달성이 직접 입증되면 양호로 확정합니다.", "partial": ["백업은 주기적으로 수행하고 원격지로 전송(소산)하고 있으나, 백업 스토리지와 운영 서버망 간의 접근 차단(절연) 통제가 미흡하여 운영자 PC 감염 시 백업 데이터까지 동시 암호화될 우려가 존재합니까?", "정기 복구 테스트를 실시하고는 있으나, 실제 시나리오 기반 복구가 아닌 단순히 특정 파일 1~2개 단위의 복구 성공 여부만을 체크하여 실효성(원장 일괄 복구 등)을 담보할 수 없는 수준입니까?", "백업 대상 범위에 핵심 업무의 일부 서버 설정 파일이나 이기종 데이터베이스의 트랜잭션 로그 백업이 누락된 상태로 운영되고 있습니까?"], "partialEnd": "백업 및 소산은 수행되고 있으나 랜섬웨어 복원 안전성이나 복구 훈련의 실효성이 크게 떨어지므로 부분이행으로 판정하고 개선 대책을 구체적으로 요청합니다.", "rootcause": ["백업 데이터를 보존하는 백업 서버와 운영망 전체에 수평 이동(Lateral Movement) 방지를 위한 보안 필터링이나 관리자 계정 분리가 전혀 되어 있지 않았던 기본 아키텍처 결함 원인은 무엇입니까?", "최근 수년간 대고객 서비스 중단을 가정한 종합 재해복구(DR) 및 데이터 복구 테스트를 단 한 차례도 실시하지 않고 형식적 문서로만 대체한 부서 내부의 매너리즘 원인은 무엇입니까?", "소산 매체 배송 및 입고 처리를 임의로 누락하거나 전송 회선 차단 에러를 발견하고도 무조치로 장기간 무시해 온 일상 관리 부실 원인은 무엇입니까?"], "rootcauseEnd": "재해 발생 시 금융 원장 소실 및 대고객 서비스 복구 불능 사태를 촉발하는 초고위험 관리 부실로 간주하여 즉각 결함으로 확정하고, 최고 수준의 경영진 보고서에 등재합니다.", "na": ["당행이 보유한 직접 소산 및 직접 백업을 이행해야 할 대상 원장이나 금융 데이터 인프라 자체가 존재하지 않습니까?", "모든 업무 시스템이 중앙회 또는 모행의 전산망을 완벽히 임차 공유하여 사용 중이므로, 백업/DR 의무와 인프라 주권이 전적으로 위탁 기관에 귀속된 상태입니까?"], "naEnd": "자체적인 데이터 소산 및 백업 제어 권한이 원천적으로 면제된 비즈니스 구조임이 검증되면 N/A 종결합니다."}, "26-7": {"decisionQ": "전산 자료의 목적 외 노출 및 유출을 방지하기 위해 마스킹 처리, 매체 차단(DLP), 대량 조회 임계치 탐지 및 관리자 이중 모니터링이 설계되어 작동하고 있습니까?", "verify": ["당행의 개인신용정보 조회 화면(이기종 시스템 포함) 중 임의의 화면을 조회하여, 주민등록번호([KOREA_RRN]), 휴대폰번호([PHONE_NUMBER]), 계좌번호([FINANCIAL_ACCOUNT_NUMBER])가 규정대로 마스킹 처리되어 노출되는지 시연해 주시겠습니까?", "DLP(데이터유출방지) 솔루션 설정 화면에서 이메일, USB, 클라우드로의 전산 자료 전송이 원천 차단되거나 사전 결재 완료 건만 허용되는 화이트리스트 차단 룰을 확인해 주시겠습니까?", "한 번에 많은 고객 정보를 열람할 때 경보를 발생시키는 '대량 자료 조회/다운로드 탐지 임계치 설정(예: 1회 100건)' 정책과 이에 대응한 실제 이상 탐지 이벤트를 보여주시겠습니까?", "데이터베이스 관리자(DBA)가 DB에 직접 접속하여 실행하는 SQL 쿼리 및 자료 추출 행위에 대해 상급자가 이중 확인하고 모니터링한 이력 보고서를 확인해 주시겠습니까?"], "verifyEnd": "개인 정보 화면 마스킹, 매체 통제 DLP 룰 작동, 대량 다운로드 실시간 차단 경보 및 관리자 행위 이중 통제 이력이 실효성 있게 시연되면 양호로 판정합니다.", "partial": ["핵심 홈페이지 및 주요 거래 화면은 마스킹되나, 통계 분석용 이기종 시스템 화면이나 내부 백오피스 화면에서는 임직원이 고객 정보 원본을 마스킹 없이 전체 열람 가능한 사각지대가 존재합니까?", "DLP 솔루션이 가동되고 있으나, 일부 예외 단말이나 예외 사용자 그룹을 대폭 설정하여 기술적인 통제를 건너뛸 수 있는 우회 경로가 불필요하게 넓게 형성되어 있습니까?", "대량 다운로드 탐지는 수행되나 사후 소명 절차가 형식화되어 담당자가 사유를 상세히 검증하지 않고 일괄 '업무용'으로 수용 처리하고 있습니까?"], "partialEnd": "유출 방지 및 오남용 감시 프레임은 존재하나, 마스킹 누락 구간이 존재하고 사후 검증 절차의 형식화가 식별되어 부분이행 판정 및 시정을 지도합니다.", "rootcause": ["DBA 등의 특권 사용자가 사내 DB의 대량 데이터를 로컬 PC로 자유롭게 다운로드하고 외부로 전송할 수 있도록 통제가 완벽히 해제되어 있었던 근본적인 원인은 무엇입니까?", "중요 금융정보 전산자료의 전송 경로(예: 비인가 웹 메일, 개인 NAS 등)가 차단 필터에서 완전히 제외된 채 방치된 보안 정책 부실의 사유는 무엇입니까?", "정당한 업무 범위를 벗어난 비정상 대량 조회가 탐지되었음에도 이에 대한 보안 부서의 추적 조사나 사용자 대상 소명 프로세스가 아예 정지되어 있던 원인은 무엇입니까?"], "rootcauseEnd": "개인신용정보 대량 유출 사고 발생 가능성에 직면한 고위험 미흡 상태로 판단하고 즉시 결함 확정하며, 신용정보법 및 전자금융감독규정에 따른 긴급 감사 보고를 상신합니다.", "na": ["당행 비즈니스 상 개인신용정보를 포함한 외부 전산 자료를 보유하거나 임직원이 조회, 유출할 수 있는 권한 및 채널이 원천 차단된 환경입니까?", "모든 전산 단말기가 화면 캡처가 불가능한 완전 VDI 제로클라이언트 기반이며 외부 전송 가능한 수단이 논리적/물리적으로 100% 제거되어 예외 처리가 아예 무의미합니까?"], "naEnd": "자료의 생성, 보관, 조회, 전송 채널 자체가 존재하지 않음이 객관적으로 증빙될 경우 N/A 판정합니다."}, "26-8": {"decisionQ": "암호화 키의 생애주기 관리 절차가 이행되고 있으며, 소스코드 내 키 하드코딩 방지 점검(SAST) 및 키 생성·관리의 내부 직원 직무 전담 통제가 구비되어 있습니까?", "verify": ["암호키의 생성, 주입, 갱신, 폐기 등의 상세 단계가 정의된 '암호키 관리 절차서'와 실제 이행 내역 대장을 보여주시겠습니까?", "HSM(하드웨어보안모듈)의 물리적 보관 환경과 함께 마스터키 및 루트키가 별도 매체로 분리되어 안전하게 시건장치 내에 이중 통제 보관되고 있는지 보여주시겠습니까?", "가장 최근 가동한 정적 소스코드 분석 솔루션(SAST) 결과보고서 중 '하드코딩(Hardcoded Cryptographic Key)' 항목 검색 결과를 열어 평문 키 노출 건이 제로인지 대조해 주시겠습니까?", "암호키 생성 및 제어 권한을 획득한 직원이 전원 내부 정직원으로만 한정되어 있으며, 최근 인사이동에 따른 즉각적인 마스터 키 재발급(변경) 이력을 조회해 주시겠습니까?"], "verifyEnd": "HSM 기반 마스터키 보관, 소스코드 내 하드코딩 완전 제거(정적 스캔 검증), 키 관리 업무의 내부 직원 배타적 전담이 입증되면 양호로 확정합니다.", "partial": ["키 관리 절차는 있으나, 소스코드 검사(SAST)를 개발 마무리 단계가 아닌 일회성으로 수행하여 일부 최신 배포 소스코드 내에 중요 인증 키나 API 암호 토큰이 평문 하드코딩된 상태로 잔존합니까?", "키 관리를 내부 정직원이 담당하고는 있으나, 실제 주입 및 갱신 행위에 외주 수탁사 직원이 상시 동행하거나 사실상 대행하고 있는 직무 위임 정황이 관찰됩니까?"], "partialEnd": "소스코드 내 하드코딩 방지 일상 점검 체계가 불완전하고, 키 관리 직무분리가 외주 인력에 의해 희석되어 있으므로 부분이행으로 판정하고 조치를 권고합니다.", "rootcause": ["운영 DB 접속용 대칭 암호화 키를 소스코드 리포지토리에 그대로 하드코딩하여 모든 내부 개발자가 열람할 수 있도록 완전 노출 방치한 원인은 무엇입니까?", "HSM 모듈을 사용하지 않고 일반 서버 드라이브 내 텍스트 파일(*.txt) 형태로 마스터키를 저장 및 방치한 설계 무지의 사유는 무엇입니까?", "암호키 생성 권한 및 관리 역할을 외주 수탁사 엔지니어에게 완전히 일임하고 내부 직원은 승인 단추만 형식적으로 누른 실질적 보안 권한 양도의 원인은 무엇입니까?"], "rootcauseEnd": "암호화 정보의 해독 권한 상실 및 중요 키 유출 위험으로 인해 결함 확정하고, 전자금융감독규정 제17조 및 제37조 의거 조치 계획 강제를 명합니다.", "na": ["당행 비즈니스 상 직접 소유 및 주입, 갱신 관리해야 할 자체 대칭/비대칭 암호키 및 HSM 전용 보안 키 구조가 전혀 없는 환경입니까?", "모든 암호화 모듈과 서비스가 가상화된 클라우드 KMS(Key Management Service)에 이식되어 있고, 암호키의 통제권이 완벽히 인프라 솔루션 자동 제어하에 존재합니까?"], "naEnd": "물리적 HSM 관리 및 소스 레벨의 독자 암호키 제어 영역이 없음이 공식 증명되면 N/A 종결합니다."}, "26-9": {"decisionQ": "장비유형별 표준 보안설정 기준이 수립되어 신규 장비에 적용되고 있으며, 미사용 방화벽 룰 등 불필요 정책이 주기적으로 점검·정리되고 있습니까?", "verify": ["서버, DB, 네트워크, 보안장비별 공식적으로 승인된 '표준 보안설정 기준서' 최신본을 보여주시겠습니까?", "최근 6개월 내 신규 도입된 서버 장비 1대의 초기 설정값 체크리스트와, 디폴트 계정(e.g., guest, test) 및 불필요 기본 정책이 폐기/변경 완료되었는지 장비 설정창에서 확인해 주시겠습니까?", "방화벽 장비 콘솔을 열어, 최근 6개월간 사용 이력이 없는 미사용 정책 및 불필요 허용 규칙을 정기 점검하여 삭제 처리한 '방화벽 룰 클리닝 보고서'를 열어주시겠습니까?", "긴급 장애 대응 등을 이유로 적용한 임시 예외 보안정책에 대해 승인 사유, 한시 기한 명기 및 기한 경과 시 원상 복구 처리된 내역을 변경이력시스템에서 조회해 주시겠습니까?"], "verifyEnd": "유형별 표준 설정 준수, 디폴트 정책 변경 완료, 미사용 규칙 자동/정기 삭제 작동, 임시 정책의 엄격한 기한 관리 승인이 증명되면 양호로 판정합니다.", "partial": ["표준 보안설정 기준서는 있으나, 실제 신규 장비 도입 시 담당자 자율에 맡겨 체크리스트 점검이 일부 누락되거나 기본 관리자 패스워드를 그대로 유지하는 사례가 일부 발견됩니까?", "방화벽 룰 정리는 하고 있으나, 실질적인 트래픽 분석을 통한 자동화된 정리가 아니며, 담당자의 수동 판단 과정에서 예외 룰이 무기한 연장되고 있습니까?"], "partialEnd": "보안 설정 통제 체계는 유지되나, 실제 신규 배포 장비의 형상 제어 및 방화벽 예외 정책 기한 관리가 부실하므로 부분이행으로 판정하고 개선을 지시합니다.", "rootcause": ["방화벽 룰 중 애니 애니(Any-Any) 오픈 형태의 위험한 허용 규칙이 사전 영향 검토나 상급자 승인 없이 무단 등록되어 방치되어 온 근본 사유는 무엇입니까?", "도입된 시스템 장비의 제조사 디폴트 패스워드나 원격 접속 기본 활성화 옵션이 그대로 노출된 상태로 운영계에 즉시 배포된 기술 관리상의 원인은 무엇입니까?", "임시 예외 정책의 기한 관리 기준 자체가 부재하여, 한 번 열어둔 임시 포트 허용 규칙이 3년 이상 방치된 보안 불감증의 원인은 무엇입니까?"], "rootcauseEnd": "내부 정보시스템 보호 장벽의 형상 붕괴로 보아 결함으로 판정하고, 전자금융감독규정 제18조 및 제19조 위반에 따른 침투 취약 가능성이 높아 즉시 시정 조치를 시행합니다.", "na": ["당행이 독자적으로 인프라 표준 설정을 강제하거나 네트워크 방화벽 룰을 직접 추가/삭제 변경할 수 있는 제어 장치 자체가 없는 아웃소싱 환경입니까?"], "naEnd": "네트워크 및 장비 보안 정책 제어 수리가 당사의 책임 영역에 전무함이 법적 위수탁 계약서상 고증될 시 N/A 종결합니다."}, "26-10": {"decisionQ": "비인가 원격제어 및 개인 클라우드 파일공유 프로그램을 기술적(NAC/보안 솔루션)으로 자동 통제하고 있으며 단말 관리자 권한을 엄격히 제한합니까?", "verify": ["당행 업무 단말기(PC) 자산 전수에 대해 비인가 소프트웨어 설치 현황을 모니터링하여 실시간 격리 조치하는 'NAC/자산관리 콘솔의 탐지 룰 설정 화면'을 보여주시겠습니까?", "P2P, 원격제어(e.g., TeamViewer, AnyDesk), 개인 클라우드 파일공유 사이트의 접근과 실행을 차단하도록 설정된 통합 보안 에이전트 정책 화면을 이 자리에서 조회해 주시겠습니까?", "임의의 임직원 PC 1대를 무작위 선정하여, 해당 PC의 로컬 사용자 계정이 '관리자(Administrator)' 그룹에서 배제되어 프로그램 임의 설치 권한이 정상 차단되는지 시연해 주시겠습니까?", "백신 및 NAC 솔루션과 연동되어 취약한 패치 미적용 프로그램이 설치된 PC의 사내망 네트워크 접속을 물리적으로 격리(VLAN 분리 등)하는 자동 탐지/조치 이력을 보여주시겠습니까?"], "verifyEnd": "비인가 소프트웨어 실행 제어, 매체 및 사이트 통제 작동, 로컬 관리자 권한 완전 회수 시연, 패치 미적용 단말 실시간 차단 이력이 확인되면 양호로 확정합니다.", "partial": ["비인가 프로그램 설치 차단 솔루션은 가동되고 있으나, 편의상 일부 사용자에 대해 예외 권한을 상시 부여하여 원격제어 툴이 백그라운드에서 구동 가능한 상태가 존재합니까?", "로컬 PC 관리자 권한은 제한하고 있으나, 특정 임무(예: 내부 테스트)를 핑계로 임시 관리자 권한을 발급해 준 후 이를 회수하지 않아 사실상 영구 관리자 권한화되어 있습니까?"], "partialEnd": "단말 보안 솔루션은 구축되어 있으나 예외 관리와 우회 권한 발급 이력 추적 통제가 부실하므로 부분이행으로 판단하여 개선 대책 조치를 지시합니다.", "rootcause": ["금융 보안 규정상 금지된 개인 클라우드 업로드 툴 및 비인가 메신저가 직원의 PC에서 상시 구동되고 파일 전송까지 허용된 보안 홀의 발생 원인은 무엇입니까?", "PC 단말 관리자 권한을 전 직원에게 일괄 완전 개방하여 임의의 파일 공유 프로그램을 사용자가 마음대로 설치할 수 있도록 통제력을 해제해 준 정책 방임의 원인은 무엇입니까?", "보안 패치가 누락된 극히 취약한 미인가 웹 브라우저나 도구가 시스템 내에 장기간 설치되어 방치되었음에도 탐지 경보나 차단 조치가 없었던 관리 누락 사유는 무엇입니까?"], "rootcauseEnd": "단말 정보 자산의 통제 완전 상실로 판단하여 결함 처리하며, 정보 유출 사고 방지를 위한 NAC 및 PC 권한 즉각 회수를 행정 조치합니다.", "na": ["당행 임직원이 사용하는 개별 전산 단말(PC) 및 업무용 디바이스 자산이 사내망에 단 1대도 설치되어 구동되지 않는 가상화 전용 환경입니까?"], "naEnd": "클라이언트 로컬 OS 및 소프트웨어 구동 영역이 부재하여 단말 레벨 제어 관리 의무에서 자유로움이 고증되면 N/A 판정합니다."}, "26-11": {"decisionQ": "당행 주요 보호 구간에 정보보호시스템(방화벽, IPS, EDR, 무선차단 등)이 누락 없이 가동되고 있으며, 24시간 보안관제 및 최신 패턴 업데이트가 상시 수행 중입니까?", "verify": ["전체 네트워크 구성도와 보안시스템 배치 현황 구성도를 바탕으로, DMZ망 및 중요 DB망의 경계 구간에 침입차단 및 침입탐지시스템 구축이 누락된 경로가 전혀 없는지 크로스체크해 주시겠습니까?", "방화벽, IPS 등의 모든 핵심 정보보호시스템의 로그가 누락 없이 중앙 통합로그관리시스템(SIEM)으로 실시간 수집 연동되고 있는 로그 수신 현황 콘솔을 이 자리에서 직접 보여주시겠습니까?", "주요 정보보호시스템(IPS/WAF 등)의 차단 룰 및 EDR 백신 패턴이 제조사의 최신 릴리즈 버전으로 일일 단위 자동 업데이트 적용되는 주기 설정값 화면을 보여주시겠습니까?", "24시간 보안관제 전문 인력의 3교대 근무 편성표와 실제 야간 시간대에 수신된 실시간 보안 이벤트 경보 및 규정 시간 내 에스컬레이션(보고) 대응 이력 로그를 보여주시겠습니까?"], "verifyEnd": "경계 구간 정보보호시스템 완전 구축, 보안 로그 중앙 통합SIEM 유입, 최신 시그니처 상시 반영, 24시간 철저한 모니터링 경보 대응 이력이 모두 정합성이 검증되면 양호로 확정합니다.", "partial": ["정보보호시스템은 대부분 갖춰져 있으나, 최근 증설된 특정 개발망 또는 지점 통신망 연동 구간의 경계 방화벽 로그 수집이 SIEM 장비에서 장시간 누락되어 방치되었습니까?", "침입차단/침입탐지 정책은 가동 중이나, 편의상 또는 오탐 관리가 어렵다는 이유로 화이트리스트(탐지 무시 정책)에 주요 도메인 및 미검증된 광범위 IP 대역을 과도하게 포함하여 경보 차단 효력이 희석되어 있습니까?"], "partialEnd": "전체적인 시스템 인프라 구축은 확인되나 로그 수집의 부분적 누락 및 차단 룰 무력화 예외 오남용이 우려되어 부분이행 판정하고 조속한 정책 정리를 요구합니다.", "rootcause": ["중요 DB망 및 내부 운영 서버의 관문 방화벽 자체가 누락되어 대역 전체가 내부 비인가망에 활짝 열려있던 원인은 개발 완료 후 정식 검수가 결여된 사유 때문입니까?", "보안 장비의 침입 차단 기능이 오탐으로 인한 서비스 지연 클레임을 피하기 위해 단지 탐지 모드(Detection only)로만 무기한 작동하고 상시 방치된 무책임의 원인은 무엇입니까?", "24시간 보안관제를 위탁하고도 수탁사의 경보 발생 시 당행 담당자에 대한 즉각 통보 및 내부 보고 체계가 수년 동안 작동 불능 상태로 정지되어 있던 업무 방치 사유는 무엇입니까?"], "rootcauseEnd": "보안 감시망 및 대응 능력의 근본적 붕괴 상태로 결함 판정하고, 신속히 전사 관제 체계를 상시 정합 상태로 복구하도록 엄중 조치 및 경영진 특별 권고를 발송합니다.", "na": ["당행은 직접 통제 및 모니터링해야 하는 독자적인 물리적/논리적 관문 네트워크 회선이 아예 없는 폐쇄적 간이 인프라 구조입니까?"], "naEnd": "당사가 직접 통신 및 경계망에 관여하지 않고 모든 보초 통제 의무가 전적으로 위탁 상위 기관에 전가되어 있음을 법리 검증할 시 N/A 종결합니다."}, "26-12": {"decisionQ": "침해사고 대응 매뉴얼이 구비되어 정기 개정되고 있으며, 관계기관 규정 기한 내 보고 정합성을 만족하고 연 1회 이상 모의훈련을 실효성 있게 이행합니까?", "verify": ["당행의 침해사고 대응 매뉴얼 최종 승인본을 열어, 개정 일자가 최근 1년 이내인지와 관계기관(금융감독원 3시간, 개인정보보호위원회 72시간 등) 신고 보고 기준 및 비상 연락망이 정비되어 있는지 대조해 주시겠습니까?", "침해사고 발생 시 대고객 서비스 전면 불가 상황을 대비하여 수립된 대체 서비스 수단 제공 지침과 보상금 산정 프로세스가 매뉴얼 내 명문화되어 작동 중인지 확인해 주시겠습니까?", "고객 데이터 유출 시 신속 정확한 범위 식별을 위해 마련된 '데이터 유출 범위 산출 기준 및 쿼리 기법 방법론 문서'를 제시해 주시겠습니까?", "최근 1년 이내에 전 임직원 및 외주 개발자까지 포함하여 실질적인 해킹 공격 시나리오(e.g., APT, 랜섬웨어 유포)로 수행한 '침해사고 모의훈련 계획서 및 최종 결과 보고서'를 보여주시겠습니까?"], "verifyEnd": "최신 규정 반영 매뉴얼 구축, 대고객 보상 기준 수립, 유출 범위 정밀 산출 기준 존재, 전사적 연 1회 이상 리얼 시나리오 모의훈련 이수가 직접 검증되면 양호로 판정합니다.", "partial": ["매뉴얼은 있으나 오래전 개정되어 과거의 개인정보보호법상 구 보고 기준이 기재되어 있어, 개정 법률상 엄격한 3시간/72시간 신고 기준이 비상 절차서에 미반영되어 있습니까?", "모의훈련은 실시하고 있으나, 보안 부서 단독의 도상 훈련 수준에 그치고 있어 실제 비즈니스 유관 부서나 현업 직원들이 침투 상황 발생 시 비상연락망에 따라 실전 대응 조치를 시연하지 못하는 수준입니까?"], "partialEnd": "훈련과 규정 정비 노력은 관찰되나 규정 정합성 누락과 훈련 실효성 결여가 식별되어 부분이행 판정 및 매뉴얼 리뉴얼을 명령합니다.", "rootcause": ["침해사고 대응 매뉴얼 자체가 존재하지 않거나, 과거 사고 발생 시 실제 규정 기한 내에 금감원 보고를 전혀 수행하지 않고 의도적 누락 은폐를 지속해 온 사유는 무엇입니까?", "고객 정보가 유출된 사태 직후, 정확히 어떠한 개인정보 범위와 몇 명의 데이터가 빠져나갔는지 산출할 수 있는 데이터 추적 기법과 기준이 전무하여 우왕좌왕 방치한 원인은 무엇입니까?", "연간 필수적인 모의 대응 훈련을 단 한 차례도 실시하지 않은 채 훈련 일지 및 임직원 참석 서명부를 허위 조작하여 감사인에게 속여 제출한 위조의 경위는 무엇입니까?"], "rootcauseEnd": "전자금융거래법 및 전자금융감독규정 제40조 위반과 고의적 보안 의무 불이행으로 결함 확정하고, 최고경영진 대상 긴급 경고 보고 및 엄중 징계 조치를 추진합니다.", "na": ["당행이 법적으로 직접적인 금융 침해사고 대응의 비상 조치나 대고객 통지, 당국 보고 의무의 독자 주권을 가지지 않는 조직입니까?"], "naEnd": "모든 법적 정보 주체 보호 의무와 규제 준수 대상 지위가 완벽히 타 기관에 귀속되어 직접 수행 의무가 면제됨이 서면 입증되면 N/A 종결합니다."}, "26-13": {"decisionQ": "당행 내부 시스템 원격접속에 대해 임시 계정 운영 등 사용 대상자를 사전에 통제하고 승인, MFA, IP 제한, 세션 타임아웃 및 전체 명령어 로그가 누락 없이 저장을 실행 중입니까?", "verify": ["현재 외부에서 원격으로 접속 가능한 시스템 목록과 원격접속 권한이 사전 인가된 전용 사용자(정직원 및 ITO 외주인력) 목록 대장을 열어주시겠습니까?", "임의 원격접속 승인 건에 대해 2차 승인(결재), 다중인증(MFA/2FA) 가동 상세 이력 및 10분 내 미작동 시 자동 끊김이 작동하는 '세션 타임아웃 정책 설정 화면'을 보여주시겠습니까?", "원격 접속 허용 IP 및 등록된 특정 전산 단말 Mac 화이트리스트 정책 설정 테이블과 실제 접속 시도 시 파일 전송 및 클립보드 복사 차단이 강제 적용되는 프로파일 설정값을 보여주시겠습니까?", "원격 세션 중에 수행된 모든 입력 커맨드가 자동 레코딩되는 '세션 녹화 파일 저장소'와 '입력 명령어 명령어 로그(Audit Log)' 실시간 수집 내역을 임의 조회해 주시겠습니까?"], "verifyEnd": "사전 개별 임시 승인, MFA 연동, 엄격한 단말 및 IP 통제, 파일 공유 봉쇄, 세션 전체 녹화 및 이력 상시 점검이 시연을 통해 전수 검증되면 양호로 판정합니다.", "partial": ["원격접속 시 MFA 및 IP 제한은 정상 구비되어 있으나, 접속 기한 설정이 누락되어 한번 부여된 원격 승인 권한이 계약이 끝난 뒤에도 장기간 비활성화되지 않고 상시 열려있는 상태가 발견됩니까?", "원격 접속 세션 제어 시 파일 전송은 차단되나 클립보드 텍스트 복사(Copy&Paste) 통제가 무력화되어 주요 원본 소스코드나 고객 원장 문자열이 유출될 수 있는 허점이 존재합니까?"], "partialEnd": "원격접속의 일차 차단막은 튼튼하나, 세션 기한 자동 통제 및 디테일한 복사 유출 방지선이 불충분하여 부분이행으로 판단하고 해당 기능을 즉각 강화 조치하도록 요청합니다.", "rootcause": ["다중인증(MFA) 우회가 가능한 불법 원격접속 VPN 계정을 임의 발급하여 장비 보수 엔지니어에게 항시 개방 제공해 온 근본 보안 유기 사유는 무엇입니까?", "원격 접속 세션 전체 녹화 서버 및 명령어 로깅 기능 자체를 디스크 공간 부족 등의 핑계로 수개월째 꺼둔 채 방치하여 원격 작업자의 유출 행위를 원천 추적 불가하게 방치한 원인은 무엇입니까?", "사내 보안 위원회 승인을 득하지 않은 우회 가설 무선 AP망이나 개인 테더링 장비를 통한 비인가 무선 원격접속이 사내 서버룸 내부망까지 침투하도록 방치된 보안 모니터링 누락 원인은 무엇입니까?"], "rootcauseEnd": "금융 전산망의 논리적 망분리 의무 위반 및 외부 불법 침입 경로의 인위적 과다 방치로 판단하고 즉각 결함 확정하며, 감사 조치 요구 및 관련자 고발 조치를 실시합니다.", "na": ["당행 비즈니스 상 어떠한 사유로도 임직원이나 외주 인력이 외부에서 사내 시스템으로 원격 접속할 수 있는 게이트웨이(VPN, 재택근무 시스템 등) 인프라 자체가 존재하지 않는 물리적 단절망입니까?"], "naEnd": "원격 외부 유입 통로가 논리적으로 원천 완전 삭제되어 있어 원격 통제 자체가 아예 무의미함이 아키텍처 상 증명될 시 N/A 종결합니다."}, "26-14": {"decisionQ": "인터넷 노출 자산의 식별·스캔을 정례화하고 있으며, 운영 종료 서버의 신속한 리소스 제거 및 노출 웹서버 접근계정에 MFA 통제를 구현하고 있습니까?", "verify": ["당행이 가동하는 전체 인터넷 노출 도메인과 IP 정보가 수록된 '공격표면 자산목록'의 최종 업데이트 날짜를 대조해 주시겠습니까?", "서비스 운영이 완전 공식 종료된 과거 서버의 DNS 레코드 삭제 이력과, 해당 서버에 바인딩되어 있던 공인 IP 및 가상 하이퍼바이저 할당 자원이 완벽 회수 처리된 증빙을 보여주시겠습니까?", "최근 수행 완료된 외부 취약 스캔 보고서상 검출된 오픈 포트 중 비필수 포트(e.g., 21, 23, 445 등)가 원천 비활성화/폐쇄 처리되었음을 보여주는 방화벽 실제 룰 체크 결과를 확인해 주시겠습니까?", "인터넷에 오픈된 공개용 웹서버의 관리자 콘솔 페이지가 외부 대역에서 원천 접속 차단되어 있으며, 필수 관리 목적 접속 시 2FA(이중인증) 통제가 무조건 개입되는지 화면 시연을 요청해도 되겠습니까?"], "verifyEnd": "스캔 자동화 가동, EoS 장비 리소스 당일 제거, 비필수 포트 완벽 폐쇄, 관리자 콘솔 외부 노출 원천 차단 및 MFA 탑재가 확인되면 양호 처리합니다.", "partial": ["인터넷 노출 자산 스캔은 정기적으로 이행하고 있으나, 신규 생성된 일시적 프로모션 사이트나 임시 마케팅용 외부 웹서버가 스캔 대상 목록에서 한시 누락된 채 방치되고 있습니까?", "운영 종료된 서버의 DNS는 지웠으나, 클라우드 가상화 플랫폼 내 공인 IP 리소스를 깜빡하고 장시간 반납 제거하지 않아 좀비 자산 형태로 보안 침투 허점을 발생시키고 있습니까?"], "partialEnd": "인터넷 노출 자산 통제 활동은 수행되나, 잔여 리소스의 종결 회수 절차 누락 및 사각지대 자산이 관측되어 부분이행으로 분류하고 시정을 지도합니다.", "rootcause": ["내부 중요 업무용 개발/테스트 서버 관리자 접속 페이지가 외부 인터넷 대역 전체에 아무런 방화벽 접근 필터 없이 100% 개방 노출되어 있던 인프라 설계 방치의 사유는 무엇입니까?", "공개용 웹서버 내에 소스 분석용 백도어 파일이나 데이터베이스 평문 연결 정보가 담긴 임시 파일(*.bak, *.swp)을 무단 생성해 둔 뒤 방치하여 외부 크롤링에 무기한 방치한 원인은 무엇입니까?", "보안 부서에 미승인된 인가받지 않은 신규 웹 도메인이 사내 인프라망을 우회하여 몰래 외부로 개통되어 운용되고 있던 유령 자산의 출처 원인은 무엇입니까?"], "rootcauseEnd": "최악의 공격 접점 무방비 노출로 결함 판정하고 즉시 DNS 격리, 비인가 외부 공인 IP 차단 및 공격 유입 경로 전면 봉쇄 통제를 명령합니다.", "na": ["당행은 대고객 인터넷 웹 서비스, 모바일 앱, 그리고 공인 IP를 직접 부여하여 구동하는 인터넷 관문 노출 포트 자체를 단 1개도 보유하지 않는 100% 내부 폐쇄형 인프라입니까?"], "naEnd": "외부 인터넷 접점 공격 접촉 표면 자체가 원천 성립 불가능한 격리 아키텍처임이 통신사 회선 증빙 등을 통해 입증되면 N/A 종결합니다."}, "26-15": {"decisionQ": "DMZ망이 물리·논리적으로 철저히 내부망과 분리 구성되어 있으며, 웹로그 중앙 수집 및 WAF를 통한 탐지, 웹쉘 상시 탐지 및 무결성 검증 체계가 가동 중입니까?", "verify": ["DMZ 구간과 내부망 구간 사이에 위치한 방화벽 접근통제 정책 설정값을 열어, 웹서버가 내부 DB서버의 지정 포트 외에 불필요한 대역에 직접 접근하는 경로가 완전히 격리되어 있는지 확인해 주시겠습니까?", "웹서버의 액세스 로그 및 WAF(웹방화벽) 로그가 통합로그관리시스템(SIEM)으로 실시간 중앙 수집되고 있는 상태창을 보여주시겠습니까?", "DMZ 내 전 웹서버의 소스 디렉토리를 대상으로 매일 실행되는 '웹쉘(Webshell) 실시간 탐지 솔루션'의 일일 점검 로그 및 탐지 제외 예외 폴더 설정을 보여주시겠습니까?", "해킹 공격으로 인한 웹 소스 코드의 인위적 개조를 감시하는 '웹 소스 무결성 검증 시스템'의 해시 변동 경보 내역 최근 1개월 분을 열어주시겠습니까?"], "verifyEnd": "DMZ 독립 구성 준수, 웹서버-내부망 간 허용 최소화, WAF 실시간 오탐 방지 차단 작동, 웹쉘 검사 및 소스코드 무결성 자동 감시가 대조 확인되면 양호로 판정합니다.", "partial": ["DMZ 분리 구성은 되어 있으나, 특정 연계 모듈의 편의성을 위해 DMZ 웹서버에서 내부 운영 서버의 광범위한 대역으로 자유롭게 통신할 수 있는 과다 포트 허용 정책이 잔존하고 있습니까?", "웹쉘 탐지 솔루션은 도입했으나, 사이트 로딩 속도 저하를 이유로 중요 소스 디렉토리의 절반 이상을 검사 대상 제외(Exception) 처리해 둔 꼼수가 관찰됩니까?"], "partialEnd": "네트워크 경계는 있으나 실질적인 침해 확산 차단망 및 웹쉘 진단 범위에 심각한 구멍이 존재하므로 부분이행으로 판정하고 조속한 정책 정리를 요구합니다.", "rootcause": ["DMZ 격리망 설계를 무력화하고 내부망에 웹서버를 혼용 배치하거나 망 분리 스위치 설정을 오접속하여 단일 백본에 혼합 구동한 보안 유기 원인은 무엇입니까?", "웹서버 침투의 주범인 웹쉘 스크립트가 수개월째 백업 폴더에 업로드되어 실시간 동작 중이었음에도 탐지 경보가 일절 작동하지 않았던 시스템상 원인은 무엇입니까?", "외부 침입자가 침투하여 내부 데이터베이스를 모두 털어갈 수 있도록 웹서버에서 DB 직접 쿼리 조회를 아무런 제약 없이 승인해 둔 개발 및 운영 설계의 붕괴 사유는 무엇입니까?"], "rootcauseEnd": "내부 금융 원장망 직접 피격 위험 상태로 판단하여 결함 확정하고, 전자금융감독규정 제18조 및 제19조 위반에 따른 강력한 징계 및 망분리 재구성을 집행합니다.", "na": ["당행은 대고객 웹 서비스 등 DMZ(독립 경계망) 구간을 형성하여 가동해야 할 물리적/논리적 접점망 자체가 전혀 없는 폐쇄형 아키텍처입니까?"], "naEnd": "내부 독립 단일망으로만 금융 통신망이 마감되어 외부 접점 DMZ 통제 의무가 성립 불가능함이 확인될 시 N/A 종결합니다."}, "26-16": {"decisionQ": "홈페이지 등 공개 게시판에 자료 등록 시 내부 승인 결재를 거치며, 첨부파일 내 개인정보 노출 차단 점검 및 위·변조 방지 기술 대책을 가동합니까?", "verify": ["당행 홈페이지에 신규 안내장이나 게시물을 업로드할 때 거쳐야 하는 '사전 게시 승인 절차서'와 실제 결재 완료 문서 1건을 조회해 주시겠습니까?", "게시판에 첨부되는 PDF, HWP, DOCX 파일 내에 주민등록번호([KOREA_RRN])나 휴대폰번호([PHONE_NUMBER]) 등 개인정보가 포함되었을 때 자동으로 필터링 및 차단하는 '개인정보 노출 진단 시스템 점검 이력'을 열어주시겠습니까?", "홈페이지 파일의 무단 위·변조를 실시간 모니터링하여 공격 발생 시 원본으로 자동 강제 복원하는 '웹 위변조 방지 솔루션'의 가동 룰 및 설정 상태를 보여주시겠습니까?", "최근 3개월간 당행 게시물 전체를 대상으로 개인정보 수동 및 자동 전수 스캔 점검을 시행한 결과 보고서를 보여주시겠습니까?"], "verifyEnd": "사전 결재 득한 게시물만 업로드 가용, 파일 내 개인정보 실시간 차단 에이전트 구비, 위변조 탐지 즉시 복원 가동이 입증되면 양호로 확정합니다.", "partial": ["자료 게시 시 결재는 받으나, 첨부파일 내의 보이지 않는 개인정보(예: 문서 속성 내 작성자 실명 또는 메타데이터 개인정보 등)까지 차단해 주는 필터 기술의 범위가 좁아 완벽한 제어가 안 됩니까?", "위변조 방지 툴은 가동 중이나, 일부 서브도메인이나 홍보용 마이크로사이트 게시판은 적용 범위에서 빠져 있어 허점이 노출되어 있습니까?"], "partialEnd": "기본 통제는 설계되었으나 일부 공개용 페이지 및 첨부 속성 제어의 완전성이 결여되어 부분이행으로 보고 개선을 통보합니다.", "rootcause": ["홈페이지 관리자가 결재라인을 완전히 무시하고 비인가 홍보 자료나 임의의 파일을 인터넷 공개 게시판에 직접 직권 업로드할 수 있도록 열어둔 통제 구멍의 원인은 무엇입니까?", "첨부 파일 내에 수천 명의 대량 정보주체 금융정보 및 계좌 목록이 버젓이 포함되어 업로드되었음에도 개인정보 필터링 솔루션의 시그니처 미등록으로 인해 외부 유출 다운로드를 방치한 기술적 사유는 무엇입니까?", "홈페이지 화면이 완전히 변조되어 외부 악성 사이트 유도 통로로 수일간 변해있었음에도 위변조 알림 및 자동 복구 장치가 통째로 다운되어 아무런 경보가 울리지 않은 방치 원인은 무엇입니까?"], "rootcauseEnd": "대고객 금융 사기 유도 피싱 경로 제공 및 민감 신용정보 유출 결함으로 확정하고 엄격한 특별 제재 프로세스를 개시합니다.", "na": ["당행이 직접 독자 운영하는 인터넷 홈페이지, 오픈 웹 포털 및 불특정 다수가 자유롭게 게시물을 열람/작성하는 게시 공간 자체가 전무합니까?"], "naEnd": "대고객 공개용 자료게시 채널 및 홈페이지 도메인을 자체 운영하지 않음이 확인될 시 N/A 종결합니다."}, "26-17": {"decisionQ": "테스트 환경이 운영망과 논리·물리적으로 완벽히 격리되어 있으며, 실 고객 정보가 아닌 가명·합성데이터를 사용하며 SAST·DAST 보안성 테스트를 필수로 적용합니까?", "verify": ["개발망 및 테스트망 구성도를 검토하여 테스트 장비가 운영 데이터베이스에 직접 접근하는 경로가 방화벽 상에서 완벽히 영구 거부(Drop) 처리되어 있는지 확인해 주시겠습니까?", "테스트망에 존재하는 데이터베이스 중 임의의 테이블 1개를 조회하여, 실 고객의 주민등록번호나 전화번호가 아닌 비식별화(가명처리/난독화) 혹은 가상의 합성데이터(Synthetic Data)가 적재되어 작동 중인지 직접 보여주시겠습니까?", "신규 프로그램 배포 시나리오를 검토하고, 충분한 검증 기간과 배포 인력 확보를 증빙하는 최근 변경 요청(RFC) 상세 타임라인 기록을 띄워주시겠습니까?", "배포 최종 단계 승인 전 수행 완료해야 하는 소스코드 정적 분석(SAST) 및 웹 애플리케이션 동적 취약점 분석(DAST) 최종 검출 결함 조치 결과 보고서를 확인해 주시겠습니까?"], "verifyEnd": "테스트-운영망 영구 격리, 가명 데이터 사용 100% 이행, 소스코드 및 구동 보안 테스트(SAST/DAST) 통과 증적이 명확히 대조되면 양호로 확정합니다.", "partial": ["테스트망 격리는 되어 있으나, 특정 고질적 에러 분석을 위해 운영계 실 고객 원본 데이터의 일부를 승인서 없이 로컬 개발 단말기로 직접 복사해 와서 분석하는 우회 관행이 남아 있습니까?", "SAST는 필수 적용하나, 개발 일정 단축을 이유로 DAST(동적 스캔) 검사는 생략하거나 배포 완료 후에 사후적으로 형식적 검사를 구색 맞추기로 밀어 넣고 있습니까?"], "partialEnd": "원장 정보 변환 사용의 사각지대 존재 및 보안 취약점 동적 진단의 실효성 결여가 식별되므로 부분이행으로 판정하고 개선 대책을 요청합니다.", "rootcause": ["테스트 데이터 변환 장치나 프로세스가 귀찮다는 이유로 운영계 실제 고객 DB 전체를 아무런 마스킹 없이 개발 테스트 DB망에 통째로 밀어 넣어 복사해 두고 수개월간 방치한 보안 참사의 사유는 무엇입니까?", "테스트 서버가 어떠한 인가 필터도 없이 공인 인터넷 전역에 완벽 개방 노출되어 공격자들의 놀이터로 전락하도록 방치한 인프라 관리 방치 원인은 무엇입니까?", "SAST/DAST 결과 다수의 심각한 고위험 취약점이 검출되었음에도 무단 묵인하고 배포 담당자가 수동 강제 승인 처리하여 무단 상용 배포를 강행한 고의적 프로세스 우회의 원인은 무엇입니까?"], "rootcauseEnd": "보안성 검증을 전면 배제한 위험 프로그램의 운영계 무단 이식 행위로 보아 즉각 결함 확정하고, 전자금융감독규정 제23조 위반으로 강력한 특별 제재를 실시합니다.", "na": ["당행은 독자적으로 프로그램을 변경, 테스트, 배포 관리하는 행위 자체를 하지 않으며 상위 중앙 전산 장치를 있는 그대로 터미널 뷰어로만 임차하여 소스 제어 영역이 원천 부재합니까?"], "naEnd": "당사가 직접 관여 및 소유한 프로그램 개발/테스트 라이프사이클이 아예 부재함이 서면 입증될 시 N/A 종결합니다."}, "26-18": {"decisionQ": "긴급작업 판단 기준이 세분화·최소화되어 관리되고 있으며, 긴급 승인권자 사전 지정, 작업 전 백업 및 야간 긴급작업 시 강화된 모니터링 통제를 가동 중입니까?", "verify": ["당행 변경관리지침 내 '긴급작업의 구체적인 정의 및 제한적 성립 요건'이 명시된 기준서 문구를 보여주시겠습니까?", "사전에 공식 지정된 '긴급 승인권자 목록'과 함께, 최근 발생한 긴급작업 1건의 긴급 사전 승인 문서(또는 선 구두승인 후 24시간 내 사후 시스템 등록 이력)를 확인해 주시겠습니까?", "긴급작업 실행 직전에 안전장치로 수행된 '대상 시스템 설정/데이터 백업 기록'과 원상 복구용 실제 롤백 절차가 변경 지시서 내에 기재되어 있었는지 보여주시겠습니까?", "야간 및 휴일 비업무시간에 수행된 긴급작업에 대해, 보안관리자가 작업 시간대에 마스킹 우회 및 불필요 변경 행위를 모니터링하고 가동한 '야간작업 강화 통제 및 접속 감사 로그 보고서'를 확인해 주시겠습니까?"], "verifyEnd": "정당한 긴급 요건 충족, 승인권자 사전 지칭, 사전 백업 및 복구 체계 구비, 비업무 시간 작업 시 보안의 추가 모니터링 이력이 검증되면 양호로 확정합니다.", "partial": ["긴급작업은 절차대로 승인을 받으나, 사후 정식 영향도 평가 및 완료 보고 절차를 '긴급'이라는 핑계로 매번 생략하거나 수 주 이상 방치하는 미흡 사항이 관찰됩니까?", "구두 승인 후 사후 문서화는 하고 있으나, 구체적인 세부 작업 사유나 실제 적용된 명령어 목록의 투명한 기입이 생략되고 단순히 '긴급 조치 완료'로만 요약 기재하고 있습니까?"], "partialEnd": "긴급 대응 체계는 구동되나 사후 관리 및 문서화 추적 수준의 완전성이 상당히 불량하므로 부분이행으로 판정하고 보완을 명령합니다.", "rootcause": ["일반 정기 업무 및 계획된 프로그램 패치 작업임에도 정식 영향도 검토와 사전 테스트 단계를 생략 우회하고자 고의로 '긴급작업' 코드를 남발하여 상용 배포를 일상화한 꼼수의 근본 원인은 무엇입니까?", "긴급작업 시 사전 백업 절차를 전면 생략하여 긴급 조치 실패 시 운영 인프라 전체가 셧다운되는 최악의 리스크를 감수하도록 방치한 인프라 관리 소홀 사유는 무엇입니까?", "사후 문서화나 검증 결재 없이 임의의 소스코드 등록 행위를 '긴급'으로 우회해 두고 영구 미승인 좀비 프로그램 형태로 무단 운영해 온 내부 통제 상실의 원인은 무엇입니까?"], "rootcauseEnd": "정상적 내부 통제 검증 프레임워크를 고의 회피하는 비정상 배포 관행으로 보아 결함 확정하고, 긴급 작업 통계 분석 보고를 경영진에게 강제 발송 조치합니다.", "na": ["당행 전산 변경 관리 정책 상 어떠한 예외적인 상황에서도 '긴급작업'이라는 특수 사전 승인 우회 코드 자체가 아예 허용되지 않는 철저한 표준 변경 전용 구조입니까?"], "naEnd": "긴급작업이라는 업무 유형 분류 및 예외 우회 트랙이 제도적으로 존재하지 않음이 확인될 시 N/A 종결합니다."}, "26-19": {"decisionQ": "운영서버 소스코드 직접 수정이 금지되고 자동 배포 도구를 통한 사전 승인 배포가 유지되며, 형상관리(버전 관리) 및 개발-배포 담당자 간의 직무분리가 철저히 이행되고 있습니까?", "verify": ["외주 개발자를 포함한 전체 개발 인력의 운영 서버(OS/DB) 직접 쓰기 및 수정 권한이 완전히 차단되어 있는 실제 시스템 권한 제약 화면을 보여주시겠습니까?", "배포 사전 승인 결재 완료 정보가 배포 서버 자동 제어 도구(e.g., Jenkins, 변경관리 시스템)와 동기화되어 승인되지 않은 배포 파일은 이식이 아예 거부되는 자동화 제어 연결을 보여주시겠습니까?", "배포 파일의 해시값 검증을 통한 무결성 체크 및 악성코드 백신 사전 정밀 스캔 결과 로그를 이 자리에서 바로 열어주시겠습니까?", "실제 상용 실행파일 생성 및 운영서버 이식 작업의 주체가 '개발 담당자'와 완벽하게 다른 '독립 배포 전담자'로 직무 분리되어 있는 인사 직무분리 대장 및 계정 목록을 대조해 주시겠습니까?"], "verifyEnd": "운영서버 직접 수정 불가 물리 통제, 자동화 결재 연동 배포 제어, 배포파일 해시 검증 및 개발-배포 직무 분리가 시연으로 확인되면 양호로 판정합니다.", "partial": ["자동 배포 도구는 사용 중이나, 비상 배포나 마이너 패치 시에는 개발자가 형상관리시스템을 우회하여 운영서버 특정 디렉토리에 소스코드를 수동 FTP로 밀어 넣을 수 있는 예외 허용 폴더가 잔존합니까?", "개발자와 배포자가 문서상으로는 분리되어 있으나, 배포 전담자의 부재 시 개발자가 배포자의 계정과 OTP 토큰을 수령하여 대행 배포하는 편법적 구두 위임 관행이 지속되고 있습니까?"], "partialEnd": "배포 통제 프레임은 양호하나 우회 가능 폴더의 존재 및 실질적 직무분리의 구두 위반 소지가 발견되므로 부분이행으로 판정하고 철저한 감시 강화를 지도합니다.", "rootcause": ["개발자 및 외주 인력이 운영중인 메인 웹서버의 소스코드를 실시간 편집기로 직접 접속하여 즉석 수정하고 무단 저장할 수 있도록 권한을 통째로 허용 방치한 근본 원인은 무엇입니까?", "배포 파일의 무결성 손상이나 악성코드 오염 여부를 파악하는 해시 검증 및 악성코드 사전 검사 단계가 형상 관리 빌드 프로세스 내에 완전히 누락되어 방치된 원인은 무엇입니까?", "개발에서 배포까지 동일 인물 1인이 단독으로 소스 수정, 빌드, 승인, 배포 전 권한을 일괄 거머쥐고 독단 구동할 수 있도록 통제권 전체가 집중된 조직 관리 실패의 사유는 무엇입니까?"], "rootcauseEnd": "소스코드 오염 및 비인가 불법 코드 상용 이식이라는 최고 수준의 전산 사고 위험에 직면한 결함 상태로 판단하고, 즉각 직무 분리 조치 및 수동 FTP 경로 차단을 집행합니다.", "na": ["당행은 독자적으로 빌드, 형상관리, 배포 가동해야 할 소스코드나 프로그램 아티팩트 자산 자체가 존재하지 않고 100% 기성 외부 솔루션 패키지만을 무변경 운용합니까?"], "naEnd": "소스코드 변경 및 직접 배포 트랜잭션 주권 자체가 존재하지 않음이 공증될 시 N/A 종결합니다."}, "26-20": {"decisionQ": "용도 폐기 전산 프로그램의 식별 및 사전 영향도 분석을 적정 수행하며, 관련 DB계정·방화벽 정책의 일괄 정리 및 보존·파기 정책을 준수합니까?", "verify": ["당행의 최신 프로그램 운영 현황 목록과 함께, 최근 폐기 완료된 프로그램의 폐기 이력 대장을 열어주시겠습니까?", "특정 프로그램 폐기 시 연계된 타 대내외 연동 시스템에 미치는 오류 영향을 선제 평가한 '사전 폐기 영향도 분석서'를 보여주시겠습니까?", "폐기가 승인 완료된 프로그램과 연계되었던 사내 DB 계정, 전용 API 통신 키 및 방화벽 허용 포트 정책이 실시간 일괄 삭제 처리된 실제 방화벽 비활성화 로그를 보여주시겠습니까?", "폐기된 소스코드의 안전 보관 정책 준수 상태와 더불어, 스케줄러(배치) 등록 해제 및 관련 테스트/백업 가상 서버 내의 데이터 파기 처리 이행 완료 보고서를 확인해 주시겠습니까?"], "verifyEnd": "영향도 검토 후 공식 폐기 결재 진행, 연동 접근권한 및 통신 정책 전수 비활성화, 잔존 좀비 서버 내 가공 데이터 영구 파기가 증명되면 양호로 판정합니다.", "partial": ["프로그램 본체는 운영 서버에서 내렸으나, 과거 등록해 둔 자동 배치 스케줄러(Cron 등)나 예외 방화벽 포트 룰을 깜빡하고 정리하지 않고 계속 열어둔 채 방치하는 미흡 건이 다수 존재합니까?", "폐기 조치는 완료했으나 테스트 서버에 설치되어 구동 중이던 과거 소스코드 및 구형 데이터베이스 보존 데이터가 별도의 파기 기준 적용 없이 무기한 하드디스크에 잔존해 있습니까?"], "partialEnd": "메인 릴리즈 폐기는 확인되나 잔존 쓰레기 리소스(좀비 프로세스/방화벽 예외 정책 등)의 후속 청소 통제가 불량하므로 부분이행으로 보고 완전 제거를 요구합니다.", "rootcause": ["정식 프로그램 폐기 승인 절차를 생략하고, 시스템 엔지니어가 임의로 운영 서버의 실행 바이너리를 무단 삭제하여 사후 타 연계 프로그램의 전면 마비 장애를 촉발한 무계획성 폐기 원인은 무엇입니까?", "폐기된 프로그램이 이용하던 중요 DB 계정과 접속 패스워드를 회수 삭제하지 않아, 공격자가 구형 계정을 도용해 사내 망 내부로 침투하는 백도어로 악용하도록 방치한 보안 불감증의 원인은 무엇입니까?", "테스트 및 백업 서버에 남아있는 과거 실제 고객 개인신용정보 원본 보존 영역을 파기 및 덮어쓰기 소거하지 않고 개발 인력들에게 완전 개방 방치한 근본 사유는 무엇입니까?"], "rootcauseEnd": "폐기 잔존물 방치로 인한 심각한 백도어 취약성 노출로 결함 판정하고 즉각 미사용 계정 및 방화벽 룰 회수 명령을 단행합니다.", "na": ["당행 비즈니스 상 자체 폐기 및 생애주기를 핸들링해야 할 전산 프로그램 자산 자체가 원천 부재하여 폐기 라이프사이클이 미존재하는 구조입니까?"], "naEnd": "운영 자산 중 프로그램 단위의 수명 관리가 물리적/논리적으로 불필요함이 확인될 시 N/A 종결합니다."}};
